window.QUESTIONS = [{"id":"R7-1","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":1,"stem":"医薬品の本質に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品は、一般の生活者が自ら選択し、使用するものであり、添付文書や製品表示に記載された内容を見れば、効能効果や副作用等について誤解や認識不足を生じることはない。"},{"label":"b","text":"一般用医薬品の販売に従事する専門家は、随時新たに付加される医薬品の有効性、安全性等に関する情報の把握に努める必要がある。"},{"label":"c","text":"医薬品は、人の生命や健康に密接に関連するものであるため、高い水準で均一な品質が保証されなければならない。"},{"label":"d","text":"一般用医薬品として販売される製品は、製造物責任法（ＰＬ法）の対象ではない。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":3,"explanation":"bとcが正しい。一般用医薬品は添付文書や製品表示を見ても、効能効果や副作用について誤解や認識不足が生じることがあるため専門家の関与が必要で、aは誤り。医薬品は生命や健康に直結するので高い水準で均一な品質が求められ、専門家は新しい有効性・安全性情報の把握に努める必要がある。一般用医薬品として販売される製品も製造物責任法（PL法）の対象であり、dは誤り。","tags":["医薬品の本質","PL法"]},{"id":"R7-2","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":2,"stem":"医薬品のリスク評価に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。\n\n　新規に開発される医薬品のリスク評価は、医薬品開発の国際的な標準化（ハーモナイゼーション）制定の流れのなかで、個々の医薬品の用量-反応関係に基づいて、医薬品の安全性に関する非臨床試験の基準である（　a　）が制定されている。また、ヒトを対象とした臨床試験の実施の基準には、国際的に（　b　）が制定されている。さらに、製造販売後の調査及び試験の実施の基準として（　c　）が制定されている。","statements":[],"options":[{"n":1,"text":"a GLP / b GCP / c GPSP"},{"n":2,"text":"a GLP / b GCP / c GVP"},{"n":3,"text":"a GCP / b GLP / c GVP"},{"n":4,"text":"a GVP / b GLP / c GPSP"},{"n":5,"text":"a GVP / b GCP / c GPSP"}],"answer":1,"explanation":"非臨床試験の基準はGLP（Good Laboratory Practice）、ヒトを対象とする臨床試験の基準はGCP（Good Clinical Practice）、製造販売後の調査・試験の基準はGPSP（Good Post-marketing Study Practice）である。GVPは製造販売後の安全管理（副作用情報の収集等）の基準で、試験の実施基準とは区別される。略称と対象の段階をセットで覚えるとよい。","tags":["リスク評価","GLP・GCP・GPSP"]},{"id":"R7-3","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":3,"stem":"健康食品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"健康食品は、医薬品との相互作用で薬物治療の妨げになることはない。"},{"label":"b","text":"錠剤やカプセル等の医薬品に類似した形状で健康食品を販売することは、禁止されている。"},{"label":"c","text":"機能性表示食品は、事業者の責任で科学的根拠をもとに疾病に罹患していない者の健康維持及び増進に役立つ機能を商品のパッケージに表示するものとして、国の個別の許可を受けたものである。"},{"label":"d","text":"特定保健用食品は、身体の生理機能などに影響を与える保健機能成分を含むもので、個別に（一部は規格基準に従って）特定の保健機能を示す有効性や安全性などに関する国の審査を受け、許可されたものである。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":5,"explanation":"正しいのはdのみ。健康食品は医薬品との相互作用で薬物治療の妨げになることがあり、aは誤り。医薬品に類似した形状の健康食品は誤用の懸念があるが、販売が一律に禁止されているわけではなく、bは誤り。機能性表示食品は事業者の責任で表示する届出制の制度で、国の個別の許可を受けたものではないため、cは誤り。国の審査を受けて許可されるのは特定保健用食品である。","tags":["健康食品","機能性表示食品","特定保健用食品"]},{"id":"R7-4","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":4,"stem":"セルフメディケーションに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"セルフメディケーションの推進は、医療費の増加やその国民負担の増大を解決する重要な活動のひとつである。"},{"label":"b","text":"地域住民の健康相談を受け、一般用医薬品の販売等や必要に応じて医療機関の受診を勧める（受診勧奨）という登録販売者の業務は、セルフメディケーションの推進に欠かせないものである。"},{"label":"c","text":"平成２９年１月からは、条件を満たした場合にスイッチＯＴＣ医薬品の購入の対価について、一定の金額をその年分の総所得金額等から控除するセルフメディケーション税制が導入された。"},{"label":"d","text":"セルフメディケーション税制は、令和４年１月の見直しにより、全ての一般用医薬品が対象となった。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"a、b、cは正しく、dが誤り。セルフメディケーション税制は、条件を満たした場合にスイッチOTC医薬品の購入費用の一定額をその年分の総所得金額等から控除する制度で、平成29年1月に導入された。令和4年1月からはスイッチOTC医薬品以外にも、腰痛や肩こり、風邪やアレルギーの諸症状に対応する一般用医薬品が対象に加わったが、対象は全ての一般用医薬品ではないためdは誤り。なお令和8年4月改訂の手引きでは、令和9年1月から消化器官用薬や一般用検査薬も対象となると記載されており、今後も範囲は見直されうる。","tags":["セルフメディケーション","セルフメディケーション税制"]},{"id":"R7-6","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":6,"stem":"医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"眠気や口渇等の比較的よく見られる症状は、副作用に含まれない。"},{"label":"b","text":"一般用医薬品は、通常、重大な副作用を回避することよりも、その使用を中断することによる不利益を回避することが優先される。"},{"label":"c","text":"副作用は、容易に異変を自覚できるものばかりでなく、明確な自覚症状として現れないこともある。"},{"label":"d","text":"一般用医薬品の販売等に従事する専門家は、購入者等から副作用の発生の経過を十分に聴き、副作用の状況次第では、購入者等に対して、速やかに適切な医療機関を受診するよう勧奨する必要がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"cとdが正しい。眠気や口渇などの比較的よく見られる症状も副作用に含まれ、aは誤り。一般用医薬品では、使用中断による不利益よりも重大な副作用を回避することが優先され、bは誤り。副作用は自覚しにくい場合もあり、専門家は発生の経過を聴いたうえで、状況次第で速やかに医療機関の受診を勧める必要がある。","tags":["副作用"]},{"id":"R7-7","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":7,"stem":"医薬品の適正使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品の販売等に従事する専門家は、一般用医薬品の適正な使用を図るため、購入者等の理解力や医薬品を使用する状況等に即して説明をすべきである。"},{"label":"b","text":"医薬品は、その目的とする効果に対して副作用が生じる危険性が最小限になるよう、使用する量や使い方が定められている。"},{"label":"c","text":"一般用医薬品を使用して症状が一時的に緩和するなら、疾病の根本的な治療や生活習慣の改善等は行わず、使用し続けることが推奨される。"},{"label":"d","text":"医薬品の販売等に従事する専門家は、必要以上の大量購入や頻回購入などを試みる者であっても、販売を差し控えるなどの対応をする必要はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":1,"explanation":"aとbが正しい。専門家は購入者の理解力や使用状況に合わせて説明し、医薬品は副作用の危険性が最小限になるよう用量・用法が定められている。症状が一時的に緩和しても、根本的な治療や生活習慣の改善を行わず使い続けることは望ましくなく、cは誤り。大量購入や頻回購入を試みる者には販売を差し控えるなどの対応が必要で、dも誤り。","tags":["適正使用","医薬品の乱用"]},{"id":"R7-8","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":8,"stem":"複数の医薬品や食品による相互作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品の相互作用は、医薬品が吸収、分布、代謝又は排泄される過程でのみ起こる。"},{"label":"b","text":"相互作用を回避するには、ある医薬品を使用している期間やその前後を通じて、通常、その医薬品との相互作用を生じるおそれのある医薬品や食品の摂取を控えなければならない。"},{"label":"c","text":"外用薬であっても、食品によって医薬品の作用や代謝に影響を受ける可能性がある。"},{"label":"d","text":"購入者等が医療機関・薬局から交付された薬剤を使用している場合には、一般用医薬品の販売等に従事する専門家が、一般用医薬品を併用しても問題ないか判断すべきである。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"aとdが誤り、bとcが正しい。相互作用は吸収・分布・代謝・排泄の過程だけでなく、作用部位などでも起こるため、aは誤り。外用薬でも食品の影響を受けることがあり、cは正しい。医療機関・薬局から交付された薬剤との併用の可否は、一般用医薬品の専門家が判断するのではなく、医師や薬剤師に確認するよう案内すべきで、dは誤り。","tags":["相互作用","食品との相互作用"]},{"id":"R7-9","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":9,"stem":"医薬品とアルコールの相互作用に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。\n\n　アルコールは、主として肝臓で代謝されるため、酒類（アルコール）をよく摂取する者では、肝臓の代謝機能が高まっていることが多い。その結果、肝臓で代謝されるアセトアミノフェンなどでは、通常よりも（　a　）なり、薬効が（　b　）ことがある。また、代謝によって産生する物質（代謝産物）が人体に悪影響を及ぼす医薬品の場合には、副作用が（　c　）なる。","statements":[],"options":[{"n":1,"text":"a 代謝されにくく / b 十分に得られなくなる / c 現れにくく"},{"n":2,"text":"a 代謝されにくく / b 強く現れる / c 現れやすく"},{"n":3,"text":"a 代謝されやすく / b 強く現れる / c 現れにくく"},{"n":4,"text":"a 代謝されやすく / b 十分に得られなくなる / c 現れやすく"},{"n":5,"text":"a 代謝されやすく / b 十分に得られなくなる / c 現れにくく"}],"answer":4,"explanation":"アルコールを常用すると肝臓の代謝機能が高まり、肝臓で代謝されるアセトアミノフェンなどは通常より代謝されやすくなって、薬効が十分に得られなくなることがある。一方、代謝産物が人体に悪影響を及ぼす医薬品では、代謝が進むことで副作用が現れやすくなる。よって(a)代謝されやすく、(b)十分に得られなくなる、(c)現れやすく、の組合せが正しい。","tags":["相互作用","アルコール"]},{"id":"R7-11","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":11,"stem":"高齢者への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般に生理機能が衰えつつあり、特に、肝臓や腎臓の機能が低下していると若年時と比較して副作用を生じるリスクが低くなる。"},{"label":"b","text":"持病（基礎疾患）を抱えていることが多いが、一般用医薬品の使用によって基礎疾患の症状が悪化することはない。"},{"label":"c","text":"喉の筋肉が衰えて飲食物を飲み込む力が弱まっている（嚥下障害）場合があり、内服薬を使用する際に喉に詰まらせやすい。"},{"label":"d","text":"細かい文字が見えづらく、添付文書や製品表示の記載を読み取るのが難しい場合等があり、情報提供や相談対応において特段の配慮が必要となる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"cとdが正しい。高齢者は生理機能が衰え、特に肝臓や腎臓の機能低下があると若年時より副作用を生じるリスクが高くなり、aは誤り。持病を抱えることが多く、一般用医薬品の使用で基礎疾患が悪化することもあるため、bも誤り。嚥下障害により内服薬が喉に詰まりやすいこと、細かい文字が見えにくく情報提供に配慮が必要なことは正しい。","tags":["高齢者","副作用"]},{"id":"R7-12","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":12,"stem":"妊婦又は妊娠していると思われる女性及び母乳を与える女性（授乳婦）への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"妊娠の有無やその可能性については、購入者等にとって他人に知られたくない場合もあることから、一般用医薬品の販売等において専門家が情報提供や相談対応を行う際には、十分配慮することが必要である。"},{"label":"b","text":"妊婦が一般用医薬品を使用する際には、妊婦の状態を通じて胎児に影響を及ぼすことがないよう配慮する必要がある。"},{"label":"c","text":"便秘薬には、配合成分やその用量によっては、流産や早産を誘発するおそれがあるものがある。"},{"label":"d","text":"医薬品の種類によっては、授乳婦が使用した医薬品の成分の一部が乳汁中に移行することが知られている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"a、b、c、dいずれも正しい。妊娠の有無は他人に知られたくない場合があり配慮が必要で、妊婦が使う医薬品は胎児への影響も考える必要がある。便秘薬には成分や用量によって流産・早産を誘発するおそれがあるものがあり、授乳婦の使用した医薬品の成分が乳汁中に移行することもある。","tags":["妊婦・授乳婦"]},{"id":"R7-13","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":13,"stem":"プラセボ効果に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品を使用したとき、結果的又は偶発的に薬理作用によらない作用を生じることをプラセボ効果という。"},{"label":"b","text":"プラセボ効果によってもたらされる反応や変化は、望ましいもの（効果）だけであり、不都合なもの（副作用）はない。"},{"label":"c","text":"プラセボ効果は、条件付けによる生体反応は関与していないと考えられている。"},{"label":"d","text":"一般用医薬品の使用によりもたらされた望ましい反応や変化が、プラセボ効果と思われるときは、その効果を目的として医薬品を使用するべきである。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"aのみ正しい。プラセボ効果とは、薬理作用によらず結果的又は偶発的に生じる反応や変化のことである。望ましい効果だけでなく不都合な反応（副作用）も生じ得るためbは誤り。条件付けによる生体反応や暗示効果、自然緩解なども関与すると考えられ、cは誤り。プラセボ効果を目的に医薬品を使用すべきではなく、dも誤り。","tags":["プラセボ効果"]},{"id":"R7-14","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":14,"stem":"医薬品の品質に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品は、適切な保管・陳列がなされていれば、経時変化による品質の劣化を避けることができる。"},{"label":"b","text":"医薬品の品質が劣化した場合、人体に好ましくない作用をもたらす物質が生じることはあるが、医薬品の効き目が低下することはない。"},{"label":"c","text":"医薬品に配合されている添加物成分は、高温や多湿、紫外線等によって品質が劣化することはない。"},{"label":"d","text":"医薬品が保管・陳列される場所は、清潔性が保たれるとともに、その品質が十分保持される環境となるよう留意する必要がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":5,"explanation":"dのみ正しい。医薬品は適切に保管・陳列しても経時変化による品質劣化は避けられず、aは誤り。品質が劣化すると有害な物質が生じることがあるほか、効き目が低下することもあり、bは誤り。添加物成分も高温・多湿・紫外線などで劣化するため、cも誤り。保管・陳列場所は清潔性と品質保持に配慮する必要がある。","tags":["医薬品の品質","保管・陳列"]},{"id":"R7-16","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":16,"stem":"登録販売者の一般用医薬品を販売する際の姿勢に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"購入者側に情報提供を受けようとする意識が乏しい場合であっても、購入者側から医薬品の使用状況に係る情報をできる限り引き出し、可能な情報提供を行っていくためのコミュニケーション技術を身につけるべきである。"},{"label":"b","text":"全ての一般用医薬品の販売、情報提供等を担う観点から、一般の生活者のセルフメディケーションに対して支援していくという姿勢で臨むことが基本となる。"},{"label":"c","text":"一般用医薬品は、家庭における常備薬として購入されることも多いことから、その医薬品によって対処しようとする症状等が現にあるか把握するよう努めることが望ましい。"},{"label":"d","text":"購入者等が、宣伝広告や販売価格等に基づいて漠然と製品を選択することがあることに留意しなければならない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"a、c、dが正しく、bが誤り。購入者に情報提供を受ける意識が乏しくても、使用状況を引き出すコミュニケーション技術が必要で、家庭の常備薬として購入される場合も症状の有無の把握に努める。購入者が広告や価格で漠然と選ぶことがある点にも留意する。登録販売者が担うのは第二類・第三類医薬品であり、「全ての一般用医薬品」を担うとする点でbは誤り。","tags":["登録販売者の姿勢","情報提供"]},{"id":"R7-18","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":18,"stem":"サリドマイド及びサリドマイド訴訟に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"サリドマイド訴訟は、サリドマイド製剤を妊娠している女性が使用したことにより、出生児に四肢欠損、耳の障害等の先天異常が発生したことに対する損害賠償訴訟である。"},{"label":"b","text":"サリドマイドは、催眠鎮静成分として承認され、その鎮静作用を目的として、胃腸薬にも配合された。"},{"label":"c","text":"サリドマイドは副作用として血管新生を促進する作用があったため、胎児に先天異常が発生した。"},{"label":"d","text":"サリドマイドによる薬害事件は、日本のみならず世界的にも問題となったため、世界保健機関（WHO）加盟国を中心に、各国における副作用情報の収集体制の整備が図られた。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"a、b、dが正しく、cが誤り。サリドマイド訴訟は妊娠中の使用による先天異常（四肢欠損・耳の障害等）に対する訴訟で、催眠鎮静成分として承認され、胃腸薬にも配合された。サリドマイドの作用は血管新生を「促進」ではなく「妨げる」もので、そのために胎児の器官形成が阻害された。この薬害は世界的問題となり、副作用情報の収集体制の整備が図られた。","tags":["薬害","サリドマイド"]},{"id":"R7-19","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":19,"stem":"スモン訴訟に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。\n\n　（　a　）として販売されていたキノホルム製剤を使用したことにより、（　b　）に罹患したことに対する損害賠償訴訟である。キノホルム製剤は、１９５８年頃から（　c　）症状を伴う特異な神経症状が報告されるようになり、米国では１９６０年にアメーバ赤痢への使用に限ることが勧告されたが、日本で販売が停止されたのは１９７０年であった。","statements":[],"options":[{"n":1,"text":"a 解熱鎮痛剤 / b 亜急性脊髄視神経症 / c 呼吸器"},{"n":2,"text":"a 解熱鎮痛剤 / b 中毒性表皮壊死融解症 / c 呼吸器"},{"n":3,"text":"a 整腸剤 / b 中毒性表皮壊死融解症 / c 消化器"},{"n":4,"text":"a 整腸剤 / b 亜急性脊髄視神経症 / c 消化器"},{"n":5,"text":"a 整腸剤 / b 亜急性脊髄視神経症 / c 呼吸器"}],"answer":4,"explanation":"スモン訴訟は、整腸剤として販売されていたキノホルム製剤の使用により、亜急性脊髄視神経症（スモン）に罹患したことに対する損害賠償訴訟である。キノホルム製剤は消化器症状を伴う特異な神経症状が報告されるようになったとされ、日本での販売停止は1970年であった。よって(a)整腸剤、(b)亜急性脊髄視神経症、(c)消化器が正しい。中毒性表皮壊死融解症は別の重篤な皮膚障害である。","tags":["薬害","スモン"]},{"id":"R8-1","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":1,"stem":"医薬品の本質に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品は、人の疾病の診断、治療若しくは予防に使用されること、又は人の身体の構造や機能に影響を及ぼすことを目的とする生命関連製品である。"},{"label":"b","text":"医薬品は、多くの場合、人体に取り込まれて作用し、効果を発現させるものである。"},{"label":"c","text":"法では、健康被害の発生の可能性がある場合のみ、異物等の混入、変質等がある医薬品を販売等してはならない旨を定めている。"},{"label":"d","text":"一般用医薬品の販売に従事する専門家は、有効性、安全性等に関する新たな医薬品情報に円滑に対応できるよう、常に情報の把握に努める必要がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"a、b、dが正しく、cが誤り。医薬品は疾病の診断・治療・予防や身体の構造・機能への影響を目的とする生命関連製品で、人体に取り込まれて作用する。法は、健康被害の発生のおそれの有無にかかわらず、異物の混入や変質などがある医薬品の販売等を禁じており、「可能性がある場合のみ」とするcは誤り。専門家は新たな情報の把握に努める必要がある。","tags":["医薬品の本質","医薬品の定義"]},{"id":"R8-2","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":2,"stem":"医薬品の本質に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品も医療用医薬品と同様、科学的な根拠に基づく適切な理解や判断によって適正な使用が図られる必要がある。"},{"label":"b","text":"医薬品は、人の生命や健康に密接に関連するものであるため、高い水準で均一な品質が保証されていなければならない。"},{"label":"c","text":"購入者等が、一般用医薬品を適切に選択し、適正に使用するためには、その販売に専門家が関与し、専門用語を分かりやすい表現で伝えるなどの適切な情報提供を行うことが不可欠である。"},{"label":"d","text":"一般用医薬品として販売される製品は、製造物責任法（ＰＬ法）の対象外である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"a、b、cが正しく、dが誤り。一般用医薬品も医療用医薬品と同様に科学的根拠に基づく適正使用が求められ、高い水準で均一な品質が必要である。適切な選択と使用のため、専門家が専門用語を分かりやすく伝えるなど情報提供することが不可欠となる。一般用医薬品として販売される製品も製造物責任法（PL法）の対象であり、dは誤り。","tags":["医薬品の本質","PL法"]},{"id":"R8-3","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":3,"stem":"医薬品の効果とリスク評価に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品の投与量と効果の関係は、薬物用量の増加に伴い、効果の発現が検出されない「無作用量」から、最小有効量を経て「治療量」に至る。"},{"label":"b","text":"医薬品は、少量の投与であれば、長期投与されたとしても慢性的な毒性が発現することはない。"},{"label":"c","text":"医薬品の安全性に関する非臨床試験の基準として、Good Vigilance Practice（ＧＶＰ）が制定されている。"},{"label":"d","text":"ヒトを対象とした臨床試験の実施の基準には、国際的に Good Clinical Practice（ＧＣＰ）が制定されている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"aとdが正しい。投与量と効果の関係は、無作用量から最小有効量を経て治療量に至る。少量でも長期投与により慢性的な毒性が現れることがあり、bは誤り。非臨床試験の基準はGLPで、GVPは製造販売後の安全管理の基準であるため、cは誤り。ヒトを対象とする臨床試験の基準は国際的にGCPが制定されている。","tags":["リスク評価","用量-反応関係","GLP・GCP"]},{"id":"R8-5","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":5,"stem":"セルフメディケーションへの積極的な貢献に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"世界保健機関（ＷＨＯ）によれば、セルフメディケーションとは、「自分自身の健康に責任を持ち、軽度な身体の不調は自分で手当てすること」とされている。"},{"label":"b","text":"セルフメディケーションの主役は、一般用医薬品の販売等に従事する専門家であり、購入者等に対して常に科学的な根拠に基づいた正確な情報提供を行い、セルフメディケーションを適切に支援していくことが期待されている。"},{"label":"c","text":"地域住民の健康相談を受け、一般用医薬品の販売や必要な時は医療機関の受診を勧める業務は、セルフメディケーションの推進に欠かせない。"},{"label":"d","text":"一般用医薬品の販売等を行う登録販売者は、地域医療を支える医療スタッフあるいは行政などとも連携をとって、地域住民の健康維持・増進、生活の質（ＱＯＬ）の改善・向上などに携わることが望まれる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"a、c、dが正しく、bが誤り。WHOはセルフメディケーションを、自分自身の健康に責任を持ち軽度な身体の不調は自分で手当てすることと位置づけている。主役はあくまで購入者等（生活者）であり、専門家はそれを適切に支援する立場のため、「主役は専門家」とするbは誤り。健康相談や受診勧奨、他職種・行政との連携による地域住民の健康維持・増進への関与が期待される。","tags":["セルフメディケーション","登録販売者の役割"]},{"id":"R8-6","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":6,"stem":"医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"副作用は、発生原因の観点から、薬理作用によるものとアレルギーによるものに大別することができる。"},{"label":"b","text":"複数の疾病を有する人の場合、ある疾病のために使用された医薬品の作用が、別の疾病の症状を悪化させることもある。"},{"label":"c","text":"医薬品を十分注意して適正に使用すれば、副作用が生じることはない。"},{"label":"d","text":"副作用は、明確な自覚症状として現れ、容易に異変を自覚できるものばかりである。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"aとbが正しい。副作用は発生原因から、薬理作用によるものとアレルギー（過敏反応）によるものに大別され、複数の疾病を持つ人では、ある疾病のための医薬品が別の疾病を悪化させることもある。適正に使用しても副作用が生じることはあり、cは誤り。副作用には明確な自覚症状として現れないものもあり、dも誤り。","tags":["副作用","アレルギー"]},{"id":"R8-7","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":7,"stem":"アレルギーに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"アレルギーとは、免疫機構が過敏に反応して、好ましくない症状が引き起こされることである。"},{"label":"b","text":"医薬品の添加物は、アレルギーを引き起こす原因物質（アレルゲン）となり得ない。"},{"label":"c","text":"病気等に対する抵抗力が低下している状態などの場合、普段は医薬品にアレルギーを起こしたことがない人でも、思わぬアレルギーを生じることがある。"},{"label":"d","text":"外用薬では、アレルギーが起こることはない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"aとcが正しい。アレルギーは免疫機構が過敏に反応して好ましくない症状を引き起こすことで、抵抗力が低下している場合などは、普段問題のない人でも思わぬアレルギーを生じることがある。医薬品の添加物もアレルゲンとなり得るためbは誤り。外用薬でもアレルギーは起こり得るため、dも誤り。","tags":["アレルギー","副作用"]},{"id":"R8-9","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":9,"stem":"複数の医薬品による相互作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品は、一つの医薬品の中に作用の異なる複数の成分を組み合わせて含んでいることが多く、他の医薬品と併用した場合に、作用が強く出過ぎたり、副作用を招く危険性が増すことがある。"},{"label":"b","text":"複数の疾病を有する人では、疾病ごとに医薬品が使用されるため、相互作用の注意をする必要はない。"},{"label":"c","text":"医薬品の相互作用は、医薬品の作用が増強する場合だけでなく、逆に減弱する場合もある。"},{"label":"d","text":"相互作用による副作用のリスクを減らす観点から、緩和を図りたい症状が明確な場合には、なるべくその症状に合った成分のみを含む医薬品を選ぶことが望ましい。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"a、c、dが正しく、bが誤り。一般用医薬品は複数成分を含むものが多く、併用すると作用が強く出過ぎたり副作用の危険性が増したりする。相互作用は作用の増強だけでなく減弱もあり、リスクを減らすには症状に合った成分のみを含む医薬品を選ぶのが望ましい。複数の疾病を持つ人こそ、疾病ごとの医薬品の併用による相互作用に注意が必要で、bは誤り。","tags":["相互作用","併用"]},{"id":"R8-10","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":10,"stem":"医薬品と食品の相互作用に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"酒類（アルコール）は、医薬品の代謝に影響を与えるが、吸収には影響を与えない。"},{"label":"b","text":"カフェインのように、食品中に医薬品の成分と同じ物質が存在する場合、それらを含む医薬品と食品を一緒に摂取すると過剰摂取となるものもある。"},{"label":"c","text":"生薬成分等が配合された医薬品と、ハーブ等の食品を合わせて摂取すると、その医薬品の効き目や副作用を増強させることがある。"},{"label":"d","text":"食品との相互作用は内服薬で起こるものであり、外用薬では考慮する必要はない。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":3,"explanation":"bとcが正しい。カフェインのように食品と医薬品に同じ成分が含まれると過剰摂取になることがあり、生薬成分を含む医薬品とハーブ等の食品を一緒に摂ると、効き目や副作用が強まることがある。酒類は医薬品の代謝だけでなく吸収にも影響し得るため、aは誤り。外用薬でも食品の影響を受ける可能性があり、dも誤り。","tags":["相互作用","食品との相互作用"]},{"id":"R8-11","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":11,"stem":"小児等への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"「医療用医薬品の添付文書等の記載要領の留意事項」において、おおよその目安として１歳未満を「新生児」としている。"},{"label":"b","text":"５歳未満の幼児に使用される錠剤やカプセル剤などの医薬品では、服用時に喉につかえやすいので注意するよう添付文書に記載されている。"},{"label":"c","text":"医薬品が喉につかえると、大事に至らなくても咳きこんで吐き出し苦しむことになり、その体験から乳幼児に医薬品の服用に対する拒否意識を生じさせることがある。"},{"label":"d","text":"一般に乳幼児は、容態が変化した場合に、自分の体調を適切に伝えることが難しいため、医薬品を使用した後は、保護者等が乳幼児の状態をよく観察することが重要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":4,"explanation":"b、c、dが正しく、aが誤り。「医療用医薬品の添付文書等の記載要領の留意事項」では、おおよその目安として、1歳未満を「乳児」、新生児は生後4週未満としており、「1歳未満を新生児」とするaは誤り。5歳未満の幼児の錠剤やカプセル剤は喉につかえやすい旨の注意があり、喉につかえた体験が服用への拒否意識につながることがある。乳幼児は体調を伝えにくいため、使用後の観察が重要である。","tags":["小児","乳幼児"]},{"id":"R8-13","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":13,"stem":"妊婦又は妊娠していると思われる女性及び母乳を与える女性（授乳婦）への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品においては、多くの場合、妊婦が使用した場合における安全性に関する評価が確立している。"},{"label":"b","text":"妊娠の有無やその可能性については、購入者等にとって他人に知られたくない場合もあることから、一般用医薬品の販売等において専門家が情報提供や相談対応を行う際には、十分配慮することが必要である。"},{"label":"c","text":"便秘薬は、配合成分やその用量にかかわらず、流産や早産を誘発することはない。"},{"label":"d","text":"乳汁中に移行することが知られている医薬品の中には、通常の使用の範囲では具体的な悪影響が判明していないものもある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"bとdが正しい。妊娠の有無は他人に知られたくない場合があり、配慮して対応する必要がある。乳汁中に移行する医薬品の中には、通常の使用の範囲では具体的な悪影響が判明していないものもある。一般用医薬品では妊婦が使用した場合の安全性評価が確立しているものは多くなく、aは誤り。便秘薬には成分や用量によって流産・早産を誘発するおそれがあるものがあり、cも誤り。","tags":["妊婦・授乳婦"]},{"id":"R8-14","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":14,"stem":"プラセボ効果に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品を使用したときにもたらされる反応や変化には、薬理作用によるもののほか、プラセボ効果によるものも含まれている。"},{"label":"b","text":"プラセボ効果によってもたらされる反応や変化は、望ましいもの（効果）だけであり、不都合なもの（副作用）はない。"},{"label":"c","text":"プラセボ効果には、時間経過による自然発生的な変化（自然緩解など）等は関与していないと考えられている。"},{"label":"d","text":"プラセボ効果は、主観的な変化だけでなく、客観的に測定可能な変化として現れることもあるため、その変化を目的として医薬品を使用することが推奨される。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"aのみ正しい。医薬品を使用したときの反応や変化には、薬理作用に加えてプラセボ効果によるものも含まれる。プラセボ効果には不都合な反応（副作用）もあり、bは誤り。時間経過による自然発生的な変化（自然緩解など）も関与すると考えられ、cは誤り。その変化を目的に医薬品を使用すべきではなく、dも誤り。","tags":["プラセボ効果"]},{"id":"R8-15","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":15,"stem":"医薬品の品質に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品に配合されている成分は、光（紫外線）等によって品質の劣化を起こしやすいものが多いが、高温や多湿によって品質の劣化を引き起こすことはない。"},{"label":"b","text":"一般用医薬品は、購入された後、すぐに使用されるとは限らないため、外箱等に記載されている使用期限から十分な余裕をもって販売することが重要である。"},{"label":"c","text":"医薬品の外箱等に記載されている「使用期限」は、開封状態で保管された場合でも品質が保持される期限である。"},{"label":"d","text":"医薬品が保管・陳列される場所については、清潔性が保たれるとともに、その品質が十分保持される環境となるよう留意する必要がある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"bとdが正しい。医薬品の成分は光だけでなく高温・多湿によっても劣化するため、aは誤り。購入後すぐ使われるとは限らないので、使用期限から十分な余裕をもって販売することが重要である。使用期限は未開封の状態で適切に保管された場合に品質が保持される期限で、開封後を保証するものではなく、cは誤り。保管・陳列場所は清潔性と品質保持に配慮する。","tags":["医薬品の品質","使用期限"]},{"id":"R8-17","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":17,"stem":"サリドマイドに関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。\nサリドマイドは催眠鎮静成分として承認されたが、副作用として血管新生を妨げる作用もあった。妊娠又は妊娠していると思われる女性が服用した場合、（　a　）関門を通過して胎児へ移行し、胎児の器官形成に必要な血管の発達が阻害されたことで、四肢欠損などの（　b　）異常が発生した。\nサリドマイドによる薬害事件は、日本のみならず世界的にも問題となったため、ＷＨＯ加盟国を中心に（　c　）の副作用情報の収集の重要性が改めて認識され、各国における副作用情報の収集体制の整備が図られることとなった。","statements":[],"options":[{"n":1,"text":"a 血液－胎盤 / b 先天 / c 市販前"},{"n":2,"text":"a 血液－胎盤 / b 先天 / c 市販後"},{"n":3,"text":"a 血液－胎盤 / b 後天 / c 市販後"},{"n":4,"text":"a 血液－脳 / b 後天 / c 市販前"},{"n":5,"text":"a 血液－脳 / b 先天 / c 市販後"}],"answer":2,"explanation":"サリドマイドは血液-胎盤関門を通過して胎児に移行し、血管の発達が阻害されて四肢欠損などの先天異常が生じた。血液-脳関門は脳への移行に関するものである。この薬害を契機に、WHO加盟国を中心に市販後の副作用情報収集の重要性が認識され、各国で収集体制が整備された。よって血液-胎盤、先天、市販後の組合せが正しい。","tags":["薬害","サリドマイド"]},{"id":"R8-18","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":18,"stem":"亜急性脊髄視神経症（スモン）及びスモン訴訟に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"スモン訴訟は、整腸剤として販売されていたキノホルム製剤を使用したことにより、亜急性脊髄視神経症に罹患したことに対する損害賠償訴訟である。"},{"label":"b","text":"スモンの症状は、初期には腹部の膨満感から激しい腹痛を伴う下痢を生じ、次第に下半身の痺れや脱力、歩行困難等が現れる。"},{"label":"c","text":"スモン訴訟により、緊急に必要とされる医薬品を迅速に供給するための「緊急輸入」制度が創設された。"},{"label":"d","text":"スモン訴訟等を契機として、医薬品の副作用による健康被害の迅速な救済を図るため、医薬品副作用被害救済制度が創設された。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"a、b、dが正しく、cが誤り。スモン訴訟は整腸剤として販売されたキノホルム製剤の使用による亜急性脊髄視神経症への損害賠償訴訟で、症状は腹部の膨満感や激しい腹痛を伴う下痢に始まり、次第に下半身の痺れや脱力、歩行困難が現れる。スモン訴訟等を契機に、1980年に医薬品副作用被害救済制度が創設された。一方「緊急輸入」制度は、HIV訴訟の和解後に成立した1996年の改正薬事法（感染症報告の義務づけ等とともに）で創設されたもので、スモン訴訟によるものではないためcは誤り。","tags":["薬害","スモン","副作用被害救済制度"]},{"id":"R8-19","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":19,"stem":"ＨＩＶ訴訟に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。\nＨＩＶ訴訟は、血友病患者が、ヒト免疫不全ウイルス（ＨＩＶ）が混入した原料（　a　）から製造された血液凝固因子製剤の投与を受けたことにより、ＨＩＶに感染したことに対する損害賠償訴訟である。\n和解後、国は感染者に対する恒久対策として（　b　）を行うとともに、製薬企業に対し従来の副作用報告に加えて（　c　）を義務づけるなどの改正薬事法が１９９６年に成立し、翌年施行された。","statements":[],"options":[{"n":1,"text":"a 血漿 / b エイズ治療・研究開発センターの整備 / c 感染症報告"},{"n":2,"text":"a 血漿 / b 医薬品副作用被害救済制度の拡充 / c 製造販売後の安全性に関する調査"},{"n":3,"text":"a 血漿 / b 血液製剤の全面使用禁止 / c 感染症報告"},{"n":4,"text":"a 血球 / b エイズ治療・研究開発センターの整備 / c 感染症報告"},{"n":5,"text":"a 血球 / b 医薬品副作用被害救済制度の拡充 / c 製造販売後の安全性に関する調査"}],"answer":1,"explanation":"HIV訴訟は、血友病患者がHIVの混入した原料血漿から製造された血液凝固因子製剤の投与を受けて感染した訴訟である。和解後、国は恒久対策としてエイズ治療・研究開発センターの整備などを行い、製薬企業に感染症報告を義務づける改正薬事法が1996年に成立、翌年施行された。血液製剤の全面使用禁止は行われていない。","tags":["薬害","HIV訴訟"]},{"id":"R7-61","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":61,"stem":"消化管に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"胃の内壁にある胃腺からは、塩酸（胃酸）やペプシノーゲンなどが分泌される。"},{"label":"b","text":"胃粘液に含まれる成分は、小腸におけるビタミンB１２の吸収に重要な役割を果たしている。"},{"label":"c","text":"小腸のうち十二指腸に続く部分の、概ね上部４０％が回腸、残り約６０％が空腸である。"},{"label":"d","text":"大腸の粘膜は、絨毛で覆われてビロード状になっている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"胃腺からは胃酸やペプシノーゲンが分泌され、胃粘液に含まれる内因子はビタミンB12の吸収に関わるため、aとbは正しい。空腸と回腸の割合は、十二指腸に続く上部約40%が空腸、残り約60%が回腸であり、cは逆になっているため誤り。絨毛で覆われてビロード状になっているのは小腸の粘膜であり、大腸の粘膜には絨毛がないため、dは誤り。","tags":["消化器","胃","小腸・大腸"]},{"id":"R7-62","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":62,"stem":"消化器系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"膵臓は、弱酸性の膵液を十二指腸へ分泌する。"},{"label":"b","text":"胆嚢は、胆汁を産生して蓄える器官である。"},{"label":"c","text":"摂取されたアルコールは、胃や小腸で吸収され、肝臓へと運ばれてアセトアルデヒドに代謝されたのち、さらに代謝されて酢酸となる。"},{"label":"d","text":"アミノ酸が分解された場合等に生成するアンモニアは、肝臓において尿素へと代謝される。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"膵液は弱アルカリ性で、胃で酸性になった内容物を中和する働きがあるため、aは誤り。胆汁を産生するのは肝臓で、胆嚢は胆汁を濃縮して蓄える器官なので、bも誤り。アルコールは胃や小腸で吸収され、肝臓でアセトアルデヒドを経て酢酸に代謝されるためcは正しく、アミノ酸の分解などで生じたアンモニアが肝臓で尿素に代謝されることもdは正しい。","tags":["消化器","膵臓・胆嚢","肝臓"]},{"id":"R7-63","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":63,"stem":"呼吸器系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"呼吸器系は鼻腔、咽頭、喉頭、気管、気管支、肺からなり、そのうち、鼻腔から咽頭・喉頭までの部分を上気道という。"},{"label":"b","text":"鼻汁にはリゾチームが含まれ、気道の防御機構の一つとなっている。"},{"label":"c","text":"喉頭の大部分と気管から気管支までの粘膜は、線毛上皮で覆われている。"},{"label":"d","text":"肺の筋組織が拡張・収縮することで、呼吸運動が行われている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"呼吸器系は鼻腔から咽頭・喉頭までを上気道、気管から肺までを下気道と区分するため、aは正しい。鼻汁には殺菌作用のあるリゾチームが含まれ、気道の防御に役立つのでbも正しい。喉頭の大部分と気管から気管支までの粘膜は線毛上皮で覆われておりcは正しい。肺自体には筋組織がなく、呼吸運動は横隔膜や肋間筋の働きで胸郭内の容積が変わることで行われるため、dは誤り。","tags":["呼吸器","気道"]},{"id":"R7-65","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":65,"stem":"脾臓及びリンパ系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"脾臓は、胃の後方の右下腹部に位置する。"},{"label":"b","text":"脾臓は、古くなった赤血球を濾し取って処理したり、血流中の細菌やウイルス等の異物に対する免疫応答に関与する。"},{"label":"c","text":"リンパ管には逆流防止のための弁がある。"},{"label":"d","text":"リンパ管は互いに合流して次第に太くなり、最終的に門脈に合流する。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":2,"explanation":"脾臓は胃の後方の左上腹部にあり、右下腹部ではないため、aは誤り。古い赤血球の処理や免疫応答への関与はbのとおりで正しい。リンパ管には逆流を防ぐ弁があり、cは正しい。リンパ管は合流して太くなり、最終的に鎖骨下静脈で静脈に合流するもので、門脈ではないため、dは誤り。","tags":["脾臓","リンパ系"]},{"id":"R7-66","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":66,"stem":"泌尿器系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"左右の腎臓と膀胱は、尿管でつながっている。"},{"label":"b","text":"尿は血液が濾過されて作られるため、糞便とは異なり、健康な状態であれば細菌等の微生物は存在しない。"},{"label":"c","text":"尿の排泄において、膀胱の出口にある排尿筋が緩むと、同時に膀胱壁の膀胱括約筋が収縮し、尿が尿道へと押し出される。"},{"label":"d","text":"男性では、加齢とともに前立腺が肥大し、尿道を圧迫して排尿困難等を生じることがある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"腎臓と膀胱をつなぐのは尿管であり、aは正しい。尿は血液が濾過されて作られ、健康な状態では細菌等の微生物は含まれないため、bも正しい。排尿時は、膀胱の出口にある膀胱括約筋が緩み、同時に膀胱壁の排尿筋が収縮して尿が押し出されるので、筋の名称が逆になっているcは誤り。男性では加齢で前立腺が肥大し排尿困難等が生じることがあり、dは正しい。","tags":["泌尿器","排尿"]},{"id":"R7-67","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":67,"stem":"目に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"目を使う作業を続けると、眼筋の疲労のほか、遠近の焦点調節を行っている硝子体の疲労などが起こる。"},{"label":"b","text":"雪眼炎は、眼球が紫外線を含む光に長時間曝されることにより、網膜の上皮が損傷を起こした状態である。"},{"label":"c","text":"視細胞が光を感じる反応にはビタミンAが不可欠であるため、不足すると夜間視力の低下が生じる。"},{"label":"d","text":"睡眠中は涙液分泌が多いため、滞留した老廃物に粘液や脂分が混じって眼脂（目やに）となる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"目の遠近の焦点調節を行うのは毛様体とその筋であり、硝子体ではないため、aは誤り。雪眼炎は紫外線などによって損傷を受けるのが角膜の上皮であり、網膜ではないため、bも誤り。視細胞の光を感じる反応にはビタミンAが必要で、不足すると夜間視力が低下するのでcは正しい。眼脂は、睡眠中は涙液の分泌が少なく老廃物が滞留して生じるため、分泌が多いとするdは誤り。","tags":["目","ビタミンA"]},{"id":"R7-69","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":69,"stem":"外皮系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"外皮系とは、皮膚、汗腺等の皮膚腺、爪等の角質の総称である。"},{"label":"b","text":"皮膚のバリア機能を担っている角質層は、セラミドでできた角質細胞と、ケラチンを主成分とする細胞間脂質で構成されている。"},{"label":"c","text":"立毛筋は、気温や感情の変化などの刺激により収縮し、毛穴が隆起する立毛反射（いわゆる「鳥肌」）が生じる。"},{"label":"d","text":"メラニン色素は、真皮の最下層にあるメラニン産生細胞で産生され、太陽光に含まれる紫外線から皮膚組織を防護する役割がある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":2,"explanation":"外皮系は皮膚、皮膚腺、角質(爪・毛など)の総称であり、aは正しい。角質層は、ケラチンを主成分とする角質細胞と、セラミドを主成分とする細胞間脂質で構成されるため、両者が入れ替わっているbは誤り。立毛筋の収縮による立毛反射はcのとおり正しい。メラニン色素を産生するメラニン産生細胞は真皮ではなく表皮の最下層にあるので、dは誤り。","tags":["外皮系","皮膚"]},{"id":"R7-70","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":70,"stem":"筋組織に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。\n\n（　a　）は、筋線維を顕微鏡で観察すると横縞模様が見える横紋筋であり、随意筋である。一方、（　b　）系に支配されている（　c　）は、血管壁や膀胱等に分布する意識的にコントロールできない筋で、比較的弱い力で持続的に収縮する特徴がある。","statements":[],"options":[{"n":1,"text":"a 平滑筋 / b 自律神経 / c 心筋"},{"n":2,"text":"a 骨格筋 / b 自律神経 / c 平滑筋"},{"n":3,"text":"a 骨格筋 / b 体性神経 / c 心筋"},{"n":4,"text":"a 心筋 / b 体性神経 / c 骨格筋"},{"n":5,"text":"a 心筋 / b 自律神経 / c 平滑筋"}],"answer":2,"explanation":"横紋筋で意識的に動かせる随意筋は骨格筋であり、aは骨格筋。血管壁や膀胱などに分布し意識的にコントロールできない筋は平滑筋で、自律神経系に支配されるため、bは自律神経、cは平滑筋となる。心筋も横紋筋だが不随意筋で、自律神経系の支配を受けるので、この文の条件には当てはまらない。","tags":["筋組織","自律神経"]},{"id":"R7-71","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":71,"stem":"脳や神経系の働きに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"視床下部は、自律神経系、ホルモン分泌等の様々な調節機能を担っている。"},{"label":"b","text":"脳の血管は、末梢の血管に比べて物質の透過に関する選択性が低く、タンパク質などの大分子やイオン化した物質は、血液中から脳の組織へ移行しやすい。"},{"label":"c","text":"脳は脊髄と、延髄でつながっており、脊髄には、心臓中枢や呼吸中枢等がある。"},{"label":"d","text":"末梢神経系は、体性神経系と自律神経系に分類される。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"視床下部は自律神経系やホルモン分泌などの調節を担うため、aは正しい。脳の血管は末梢の血管に比べて物質の透過性の選択性が高く(血液脳関門)、大分子やイオン化した物質は脳に移行しにくいので、bは誤り。心臓中枢や呼吸中枢があるのは延髄であり、脊髄ではないため、cは誤り。末梢神経系は体性神経系と自律神経系に分類されるので、dは正しい。","tags":["脳・神経","血液脳関門"]},{"id":"R7-73","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":73,"stem":"薬の代謝、排泄に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"経口投与後、消化管で吸収された有効成分は、全身循環に入る前にリンパ管を経由して肝臓を通過する。"},{"label":"b","text":"血漿タンパク質と結合した有効成分は、腎臓で濾過されないため、長く循環血液中に留まることとなり、作用が持続する原因となる。"},{"label":"c","text":"肝初回通過効果とは、全身循環に移行する有効成分の量が、消化管で吸収された量よりも、肝臓で代謝を受けた分だけ少なくなることをいう。"},{"label":"d","text":"有効成分は、未変化体のままで、あるいは代謝物として体外へ排出されるが、肺から呼気中へ排出されることはない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"消化管で吸収された有効成分は、リンパ管ではなく門脈を経由して肝臓に運ばれ、そこで酵素の働きによる代謝を受けるため、aは誤り。血漿タンパク質と結合した有効成分は腎臓で濾過されないため、長く血液中にとどまって作用が持続する原因となり、bは正しい。肝初回通過効果の説明であるcも正しい。有効成分は未変化体や代謝物として尿中や胆汁中に排泄されるほか、肺から呼気中へ排出されることもあり、汗中や母乳中への排出経路もあるので、呼気中へは排出されないとするdは誤り。","tags":["薬の代謝","肝初回通過効果","排泄"]},{"id":"R7-74","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":74,"stem":"医薬品の剤形及びその一般的な特徴に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"口腔内崩壊錠は、適切な量の水とともに服用する必要がある剤形のため、水分摂取が制限されている患者には適さない。"},{"label":"b","text":"トローチ剤は、口の中で噛み砕いて服用する。"},{"label":"c","text":"経口液剤は、服用後、固形製剤よりも比較的速やかに消化管から吸収されるため、有効成分の血中濃度が上昇しやすい。"},{"label":"d","text":"軟膏剤は、油性基剤に水分を加えたもので、皮膚への刺激が強く、傷等への使用を避ける必要がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":5,"explanation":"口腔内崩壊錠は口の中の唾液で速やかに溶けるよう工夫されており、水なしで服用できて水分摂取が制限されている人にも適するため、aは誤り。トローチ剤は噛み砕かず、飲み込まずに口の中で舐めて徐々に溶かして使うので、bも誤り。経口液剤は固形製剤より飲み込みやすく、服用後比較的速やかに吸収されて血中濃度が上昇しやすいので、cは正しい。軟膏剤は油性基剤で皮膚への刺激が弱いのに対し、油性基剤に水分を加えたクリーム剤は刺激が強く傷等への使用を避けるとされるため、dは誤り。","tags":["剤形","経口液剤","軟膏剤"]},{"id":"R7-75","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":75,"stem":"点眼薬又は点鼻薬を使用する上での注意事項に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"点眼薬により、ショック（アナフィラキシー）等のアレルギー性の副作用を生じることがある。"},{"label":"b","text":"点眼薬は、鼻涙管を通って鼻粘膜から吸収されることがあるため、眼以外の部位に到達して起こる副作用を軽減するためには、点眼後に目頭の鼻涙管の部分を押さえることが有効である。"},{"label":"c","text":"点鼻後に鼻腔粘膜で吸収された点鼻薬の有効成分は、初めに肝臓で代謝を受けて全身に分布する。"},{"label":"d","text":"一般用医薬品に分類される点鼻薬には、全身作用を目的とするものもある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":4,"explanation":"点眼薬でもアレルギー性の副作用(ショック等)が起こりうるため、aは正しい。点眼後に目頭を押さえると、鼻涙管を通った鼻粘膜からの吸収を減らせるので、bも正しい。鼻粘膜から吸収された成分は、初めに肝臓で代謝を受けずに全身に分布するため、cは誤り。一般用医薬品の点鼻薬は局所作用を目的とするものであり、全身作用を目的とするものはないので、dも誤り。","tags":["点眼薬・点鼻薬","薬の吸収"]},{"id":"R7-77","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":77,"stem":"医薬品の副作用として現れる偽アルドステロン症に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"体内にカリウムが貯留し、体から塩分（ナトリウム）と水が失われることによって生じる病態である。"},{"label":"b","text":"副腎皮質からのアルドステロン分泌が増加していることが特徴である。"},{"label":"c","text":"主な症状として、手足の脱力、血圧上昇、筋肉痛、喉の渇き、吐きけ・嘔吐等がある。"},{"label":"d","text":"複数の医薬品や、医薬品と食品との間の相互作用によって起きることがある。"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":5,"explanation":"偽アルドステロン症は、体内にナトリウムと水が貯留し、カリウムが失われることで起こるため、aは逆で誤り。副腎皮質からのアルドステロン分泌が増加しているわけではなく、増加していないのに同様の症状を示す病態なので、bも誤り。手足の脱力、血圧上昇、筋肉痛、喉の渇き、吐きけ等の症状はcのとおりで、複数の医薬品や食品との相互作用で起こることもあるためdも正しい。","tags":["偽アルドステロン症","副作用"]},{"id":"R7-78","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":78,"stem":"消化器系及び呼吸器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"消化性潰瘍になると、消化管出血に伴って糞便が黒くなるなどの症状が現れることがある。"},{"label":"b","text":"イレウス様症状（腸閉塞様症状）は、小児や高齢者のほか、普段から下痢傾向のある人の発症リスクが高い。"},{"label":"c","text":"間質性肺炎は、一般的に、原因となる医薬品の使用開始から短時間（１時間以内）のうちに起きることが多い。"},{"label":"d","text":"喘息は、合併症の有無にかかわらず、原因となった医薬品の有効成分が体内から消失しても症状は寛解しない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"消化性潰瘍で消化管出血が生じると、糞便が黒くなることがあるため、aは正しい。イレウス様症状は、小児や高齢者のほか、普段から便秘傾向のある人でリスクが高いとされており、下痢傾向とするbは誤り。間質性肺炎は一般に、使用開始から1～2週間程度で起きることが多く、1時間以内ではないためcは誤り。喘息は、合併症がない場合、原因となった医薬品の有効成分が体内から消失すれば寛解するのが一般的で、dは誤り。","tags":["消化性潰瘍","イレウス","間質性肺炎"]},{"id":"R7-79","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":79,"stem":"循環器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"うっ血性心不全とは、全身が必要とする量の血液を心臓が送り出すことができなくなり、肺に血液が貯留して、種々の症状を示す疾患である。"},{"label":"b","text":"心不全の既往がある人は、薬剤による心不全を起こしやすい。"},{"label":"c","text":"不整脈の種類によっては失神することもあり、その場合には自動体外式除細動器（ＡＥＤ）の使用を考慮する。"},{"label":"d","text":"高血圧や心臓病等、循環器系疾患の診断を受けている人は、心臓や血管に悪影響を及ぼす可能性が高い医薬品を使用してはならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"うっ血性心不全は、心臓が必要な血液量を送り出せず、肺に血液が貯留するなどして種々の症状を示す疾患で、aは正しい。心不全の既往がある人は薬剤性の心不全を起こしやすく(b)、不整脈で失神した場合にAEDの使用を考慮すること(c)、循環器系疾患のある人は心臓や血管に悪影響を及ぼす可能性が高い医薬品を使ってはならないこと(d)も、手引きに沿った記述で正しい。したがってすべて正しい。","tags":["循環器系副作用","心不全","不整脈"]},{"id":"R8-61","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":61,"stem":"消化器系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"唾液には、デンプンをデキストリンや麦芽糖に分解する消化酵素であるリゾチームが含まれる。"},{"label":"b","text":"食道の上端と下端には括約筋がある。"},{"label":"c","text":"胃腺からは塩酸（胃酸）のほか、トリプシノーゲンなどが分泌されている。"},{"label":"d","text":"小腸は全長６～７ｍの臓器で、空腸、回腸、結腸の３部分に分かれる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"唾液中にデンプンを分解する酵素はアミラーゼ(プチアリン)で、リゾチームは殺菌作用のある成分なので、aは誤り。食道の上端と下端には括約筋があり、bは正しい。胃腺から分泌されるのはペプシノーゲンであり、トリプシノーゲンは膵液に含まれるため、cは誤り。小腸は十二指腸、空腸、回腸に分かれ、結腸は大腸の一部なので、dも誤り。","tags":["消化器","唾液・胃液","小腸"]},{"id":"R8-62","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":62,"stem":"呼吸器系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"喉頭は、鼻腔と口腔につながっており、消化管と気道の両方に属する。"},{"label":"b","text":"咽頭は、発声器としての役割もあり、呼気で咽頭上部にある声帯を振動させて声が発せられる。"},{"label":"c","text":"呼吸運動は、肺を構成する筋組織の拡張・収縮により行われる。"},{"label":"d","text":"気管支が細かく枝分れした末端は、ブドウの房のような構造となっており、その球状の袋部分を肺胞という。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"喉頭は気道にのみ属し、消化管と気道の両方に属するのは咽頭なので、aは誤り。声帯があるのは咽頭ではなく喉頭であり、bも誤り。肺自体には筋組織がなく、呼吸運動は横隔膜や肋間筋の働きで行われるため、cは誤り。気管支の末端が房状に終わり、その球状の袋部分が肺胞であるという記述dは正しい。","tags":["呼吸器","喉頭・咽頭","肺胞"]},{"id":"R8-63","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":63,"stem":"循環器系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"心臓の心室には、血液を取り込む側と送り出す側にそれぞれ弁がある。"},{"label":"b","text":"肺でガス交換が行われた血液は、心臓の左側部分（左心房・左心室）に入り、そこから全身に送り出される。"},{"label":"c","text":"動脈は皮膚表面近くを通っている部分が多く、静脈の多くは体の深部を通っている。"},{"label":"d","text":"毛細血管には、一定の間隔で弁があり、血液の逆流を防いでいる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"心室には、血液を取り込む側(房室弁)と送り出す側(動脈弁)にそれぞれ弁があり、aは正しい。肺でガス交換された血液は左心房・左心室に入り、全身へ送り出されるのでbも正しい。動脈は体の深部を通るものが多く、静脈は皮膚表面近くを通る部分が多いので、cは逆で誤り。逆流を防ぐ弁があるのは静脈であり、毛細血管ではないため、dも誤り。","tags":["循環器","心臓・血管"]},{"id":"R8-65","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":65,"stem":"腎臓及び副腎に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"腎小体と尿細管とで腎臓の基本的な機能単位（ネフロン）を構成している。"},{"label":"b","text":"腎小体では、肝臓でアミノ酸が分解されて生成する尿素など、血液中の老廃物が濾過され、原尿として尿細管に入る。"},{"label":"c","text":"腎臓では、赤血球の産生を促進するホルモンが分泌される。"},{"label":"d","text":"副腎髄質では、アルドステロンが産生・分泌される。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"腎小体と尿細管でネフロンを構成し、aは正しい。腎小体では尿素などの老廃物が濾過されて原尿となるため、bも正しい。腎臓は赤血球の産生を促すホルモン(エリスロポエチン)を分泌するので、cも正しい。アルドステロンは副腎髄質ではなく副腎皮質で産生・分泌されるため、dは誤り。","tags":["腎臓","副腎","ホルモン"]},{"id":"R8-66","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":66,"stem":"尿路に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"左右の腎臓と膀胱は尿道でつながっている。"},{"label":"b","text":"尿の排泄においては、膀胱の出口にある膀胱括約筋が緩むと、同時に膀胱壁の排尿筋が収縮し、尿が押し出される。"},{"label":"c","text":"女性は尿道が短いため、細菌などが侵入したとき膀胱まで感染を生じやすい。"},{"label":"d","text":"高齢者は、膀胱や尿道の括約筋の働きによって排尿を制御する機能が低下し、また、膀胱の容量が小さくなるため、尿失禁を起こしやすくなる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"腎臓と膀胱をつなぐのは尿管で、尿道ではないため、aは誤り。排尿時は膀胱括約筋が緩み、膀胱壁の排尿筋が収縮して尿が押し出されるので、bは正しい。女性は尿道が短く、膀胱まで感染が及びやすいためcは正しい。高齢者は排尿を制御する機能の低下や膀胱容量の減少から尿失禁を起こしやすく、dも正しい。","tags":["泌尿器","排尿","尿路感染"]},{"id":"R8-67","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":67,"stem":"目に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"涙腺は上眼瞼の裏側にある分泌腺で、リンパ液から涙液を産生する。"},{"label":"b","text":"涙液には、角膜に酸素や栄養分を供給する働きはない。"},{"label":"c","text":"眼瞼（まぶた）は、素早くまばたき運動ができるよう、皮下組織が少なく薄くできているため、内出血や裂傷を生じやすい。"},{"label":"d","text":"神経性の疲労、睡眠不足、栄養不良等が要因となって、慢性的な目の疲れに肩こり、頭痛等の全身症状を伴う場合を眼精疲労という。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"涙腺は血漿から涙液を産生するため、リンパ液からとするaは誤り。涙液には角膜に酸素や栄養分を供給する働きがあり、ないとするbも誤り。眼瞼は皮下組織が少なく薄いため、内出血や裂傷を生じやすく、cは正しい。慢性的な目の疲れに肩こり・頭痛などの全身症状を伴う場合を眼精疲労といい、dも正しい。","tags":["目","涙液","眼精疲労"]},{"id":"R8-69","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":69,"stem":"皮膚に関する記述について、（　）の中に入れるべき字句の正しい組合せを選べ。\n\n皮膚は、体温を一定に保つため重要な役割を担っている。体温が（　a　）始めると、皮膚を通っている毛細血管を流れる血液量が（　b　）ことで、体外へより多くの熱を排出する。また、全身に分布する（　c　）から汗を分泌して、その蒸発時の気化熱を利用して体温を下げる。","statements":[],"options":[{"n":1,"text":"a 下がり / b 減る / c アポクリン腺"},{"n":2,"text":"a 下がり / b 増える / c エクリン腺"},{"n":3,"text":"a 上がり / b 増える / c アポクリン腺"},{"n":4,"text":"a 上がり / b 増える / c エクリン腺"},{"n":5,"text":"a 上がり / b 減る / c アポクリン腺"}],"answer":4,"explanation":"体温が上がり始めると、皮膚の毛細血管を流れる血液量が増えて体外へ熱を放出しやすくなる。また、全身に分布して汗を分泌するのはエクリン腺であり、その気化熱で体温を下げる。アポクリン腺は腋窩などの限られた部位に分布する腺なので、当てはまらない。","tags":["外皮系","体温調節","汗腺"]},{"id":"R8-70","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":70,"stem":"骨格系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"骨の基本構造は、骨質、骨髄、関節軟骨の三組織からなっている。"},{"label":"b","text":"赤血球、白血球、血小板は、骨髄で産生される造血幹細胞から分化することにより、体内に供給される。"},{"label":"c","text":"骨組織を構成する無機質は骨の強靭さを保ち、有機質（タンパク質及び多糖体）は骨に硬さを与える。"},{"label":"d","text":"骨の関節面は、弾力性に富む柔らかな軟骨層に覆われ、これが衝撃を和らげ、関節の動きを滑らかにしている。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"骨の基本構造は骨質、骨髄、骨膜、関節軟骨の四組織からなるため、三組織とするaは誤り。血液の細胞は骨髄の造血幹細胞から分化して供給されるので、bは正しい。骨の無機質(リン酸カルシウム等)は硬さを与え、有機質は強靭さを与えるため、逆に書かれているcは誤り。関節面を軟骨層が覆って衝撃を和らげる記述dは正しい。","tags":["骨格系","骨の構造","造血"]},{"id":"R8-71","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":71,"stem":"脳や神経系の働きに関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"脳において、ブドウ糖の消費量は全身の約２５％、酸素の消費量は全身の約５０％を占める。"},{"label":"b","text":"血液脳関門とは、脳の毛細血管が中枢神経の間質液環境を血液内の組成変動から保護するように働く機能のことをいう。"},{"label":"c","text":"末梢神経系は、体性神経系と自律神経系に分類され、自律神経系は、交感神経系と副交感神経系からなる。"},{"label":"d","text":"副交感神経の節後線維の末端から放出される神経伝達物質は、ノルアドレナリンである。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":3,"explanation":"脳の消費量は、ブドウ糖が全身の約25%であるのに対し、酸素は約20%とされるため、aは誤り。血液脳関門の説明bは正しい。末梢神経系は体性神経系と自律神経系に分類され、自律神経系は交感神経系と副交感神経系からなるので、cも正しい。副交感神経の節後線維の末端から放出される伝達物質はアセチルコリンで、ノルアドレナリンは交感神経の節後線維のものなので、dは誤り。","tags":["脳・神経","血液脳関門","自律神経"]},{"id":"R8-73","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":73,"stem":"薬の代謝、排泄に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"経口投与後、消化管で吸収された有効成分は、門脈を経由して肝臓に運ばれ、肝臓に存在する酵素の働きにより代謝を受ける。"},{"label":"b","text":"肝初回通過効果とは、全身循環に移行する有効成分の量が、消化管で吸収された量よりも、肝臓で代謝を受けた分だけ少なくなることをいう。"},{"label":"c","text":"医薬品の有効成分が代謝を受けると、作用を失ったり（不活性化）、作用が現れたり（代謝的活性化）、あるいは体外へ排泄されやすい脂溶性の物質に変化したりする。"},{"label":"d","text":"腎機能が低下した人では、正常な人に比べて有効成分の尿中への排泄が早まるため、医薬品の効き目が十分に現れず、副作用も生じにくい。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":1,"explanation":"吸収された有効成分は門脈を経て肝臓に運ばれ、酵素で代謝を受けるため、aは正しい。肝初回通過効果の説明bも正しい。代謝を受けた成分は、体外へ排泄されやすい水溶性の物質に変化するため、脂溶性とするcは誤り。腎機能が低下すると排泄が遅れ、効き目が過剰に現れたり副作用が生じやすくなるので、dは誤り。","tags":["薬の代謝","肝初回通過効果","腎機能"]},{"id":"R8-74","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":74,"stem":"薬の体内での働きに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品が効果を発揮するためには、有効成分がその作用の対象である器官や組織の細胞外液中あるいは細胞内液中に、一定以上の濃度で分布する必要がある。"},{"label":"b","text":"全身作用を目的とする医薬品の多くは、使用後の一定期間、その有効成分の血中濃度が有効域に維持されるよう、使用量及び使用間隔が定められている。"},{"label":"c","text":"医薬品を摂取すると、血中濃度はある時点で最高血中濃度に達し、その後は低下していくが、これは医薬品の有効成分の代謝・排泄の速度が吸収・分布の速度を上回るためである。"},{"label":"d","text":"一度に大量の医薬品を摂取して血中濃度を高くしても、ある濃度以上になるとより強い薬効は得られなくなる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"有効成分が作用部位の細胞外液・細胞内液中に一定以上の濃度で分布する必要があること(a)、全身作用を目的とする医薬品は血中濃度が有効域に維持されるよう使用量・間隔が定められていること(b)は、いずれも正しい。血中濃度が最高に達したあと低下するのは、代謝・排泄の速度が吸収・分布の速度を上回るためであり(c)、濃度を高くしても一定以上では薬効が頭打ちになる(d)。したがってすべて正しい。","tags":["薬の体内での働き","血中濃度"]},{"id":"R8-75","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":75,"stem":"医薬品の剤形及びその一般的な特徴に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"クリーム剤は、油性基剤に水分を加えたもので、皮膚への刺激が強いため、傷等への使用は避ける必要がある。"},{"label":"b","text":"外用液剤は、軟膏剤やクリーム剤に比べて、患部が乾きにくいという特徴がある。"},{"label":"c","text":"貼付剤は、適用部位に有効成分が一定時間留まるため、薬効の持続が期待できる。"},{"label":"d","text":"スプレー剤は、手指等では塗りにくい部位や、広範囲に適用する場合に適している。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"クリーム剤は油性基剤に水分を加えたもので、皮膚への刺激が強いため傷等への使用は避けるとされ、aは正しい。外用液剤は軟膏剤やクリーム剤に比べて患部が乾きやすいので、乾きにくいとするbは誤り。貼付剤は有効成分が留まり薬効の持続が期待でき(c)、スプレー剤は塗りにくい部位や広範囲に適する(d)ので、いずれも正しい。","tags":["剤形","外用剤"]},{"id":"R8-77","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":77,"stem":"全身的に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ショック（アナフィラキシー）は、生体異物に対する即時型のアレルギー反応の一種で、一旦発症すると急速に悪化することが多い。"},{"label":"b","text":"肝機能障害が疑われても原因と考えられる医薬品を漫然と使用し続けると、不可逆的な病変（肝不全）を生じ、死に至ることもある。"},{"label":"c","text":"皮膚粘膜眼症候群は、最初に報告した医師の名前にちなんでライエル症候群とも呼ばれる。"},{"label":"d","text":"皮膚粘膜眼症候群及び中毒性表皮壊死融解症のいずれも発生は非常にまれであるが、一旦発症すると多臓器障害の合併症等により致命的な転帰をたどることがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"ショック(アナフィラキシー)は即時型のアレルギー反応で急速に悪化することが多く、aは正しい。肝機能障害を漫然と放置すると肝不全に至り死亡することもあり、bも正しい。ライエル症候群と呼ばれるのは中毒性表皮壊死融解症(TEN)であり、皮膚粘膜眼症候群の別名はスティーブンス・ジョンソン症候群なので、cは誤り。両疾患とも発生はまれだが重篤で致命的になりうるので、dは正しい。","tags":["重篤な副作用","ショック","皮膚粘膜眼症候群"]},{"id":"R8-78","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":78,"stem":"精神神経系に現れる医薬品の副作用に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"副作用として現れる精神神経症状は、医薬品を大量服用した時に限って発生する。"},{"label":"b","text":"医薬品の副作用と疑われる精神神経症状が現れた場合、原因と考えられる医薬品を中止せずに、医師の診察を受けるなどの対応が必要である。"},{"label":"c","text":"医薬品の副作用と疑われる無菌性髄膜炎の症状が現れた場合、早期に原因医薬品の使用を中止すれば、速やかに回復し、予後は比較的良好であることがほとんどであるが、重篤な中枢神経系の後遺症が残った例も報告されている。"},{"label":"d","text":"医薬品の不適正な使用によって、倦怠感や虚脱感等を生じることがあるので、医薬品の販売等に従事する専門家は、販売する医薬品の使用状況にも留意する必要がある。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"精神神経症状は大量服用時に限らず、通常の用法・用量でも現れることがあるため、aは誤り。疑われる場合は原因と考えられる医薬品の使用を中止し、医師の診察を受ける必要があるので、中止せずとするbは誤り。無菌性髄膜炎は早期に使用を中止すれば速やかに回復することがほとんどだが、後遺症が残った例も報告されており、cは正しい。不適正な使用によって倦怠感や虚脱感などが生じることがあり、dも正しい。","tags":["精神神経系副作用","無菌性髄膜炎"]},{"id":"R8-79","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":79,"stem":"医薬品の副作用として現れる間質性肺炎に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"間質性肺炎とは、気管支又は肺胞が細菌に感染して炎症を生じたものである。"},{"label":"b","text":"一般的に、医薬品の使用開始から１～２時間程度で起きることが多い。"},{"label":"c","text":"発症すると、体内は低酸素状態となり、呼吸困難、空咳（痰の出ない咳）、発熱等の症状を呈する。"},{"label":"d","text":"症状は一過性に現れ、自然と回復することもあるが、悪化すると肺線維症に移行することがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":3,"explanation":"間質性肺炎は、肺胞と毛細血管を取り囲んで支える間質が炎症を起こしたものであり、気管支や肺胞が細菌に感染して起こる通常の肺炎とは異なるため、aは誤り。発症時期は一般に使用開始から1～2週間程度が多く、1～2時間とするbも誤り。低酸素状態となり、呼吸困難、空咳、発熱などが現れるのでcは正しく、一過性のこともあるが悪化すると肺線維症に移行する場合があるためdも正しい。","tags":["間質性肺炎","呼吸器副作用"]},{"id":"R7-21","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":21,"stem":"かぜ（感冒）及びかぜ薬（総合感冒薬）に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"上気道の急性炎症であるかぜは、単一の疾患であり、予後は良好である。"},{"label":"b","text":"かぜによく似た症状の疾患は、喘息、肺結核、関節リウマチなど多数ある。"},{"label":"c","text":"インフルエンザ（流行性感冒）は、細菌の呼吸器感染によるものであり、感染力が強く、また重症化しやすいため、かぜとは区別して扱われる。"},{"label":"d","text":"かぜは様々な症状が組み合わさって現れるため、かぜであれば、どのような場合でも総合感冒薬を選択すべきである。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"かぜは単一の疾患ではなく、主にウイルスの感染による上気道の急性炎症の総称（症候群）なので、aは誤りです。喘息・肺結核・関節リウマチなどかぜに似た症状を示す疾患は多く、bは正しい記述です。インフルエンザは細菌ではなくインフルエンザウイルスによる感染症のため、cは誤りです。かぜでも症状や状況により総合感冒薬が最適とは限らないため、dの「どのような場合でも選択すべき」も誤りです。","tags":["かぜ薬","感冒"]},{"id":"R7-24","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":24,"stem":"化学的に合成された解熱鎮痛成分に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。なお、同じアルファベットの（　　）の中には、同じ字句が入る。\n\n　解熱に関しては、中枢神経系におけるプロスタグランジンの産生（　a　）作用のほか、腎臓における水分の再吸収を促して循環血流量を（　b　）させ、発汗を促進する作用も寄与している。\n　また、末梢におけるプロスタグランジンの産生（　a　）は、腎血流量を（　c　）させる。よって、心臓に障害がある場合や腎機能に障害がある場合には、その症状を悪化させるおそれがある。","statements":[],"options":[{"n":1,"text":"a 抑制 / b 増加 / c 減少"},{"n":2,"text":"a 抑制 / b 増加 / c 増加"},{"n":3,"text":"a 抑制 / b 減少 / c 増加"},{"n":4,"text":"a 促進 / b 減少 / c 増加"},{"n":5,"text":"a 促進 / b 増加 / c 減少"}],"answer":1,"explanation":"解熱鎮痛成分は、中枢神経系でのプロスタグランジン産生を抑制して解熱・鎮痛に働くほか、腎臓での水分再吸収を促して循環血流量を増加させ、発汗を促します。一方、末梢でのプロスタグランジン産生の抑制は腎血流量を減少させるため、心臓や腎臓に障害がある人では症状を悪化させるおそれがあります。したがって a=抑制、b=増加、c=減少 の組合せが正解です。","tags":["解熱鎮痛薬","プロスタグランジン"]},{"id":"R7-26","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":26,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを選べ。\n\n　体力中等度で、慢性に経過する頭痛、めまい、肩こりなどがあるものの慢性頭痛、神経症、高血圧の傾向のあるものに適すとされる。","statements":[],"options":[{"n":1,"text":"呉茱萸湯"},{"n":2,"text":"香蘇散"},{"n":3,"text":"麻黄湯"},{"n":4,"text":"釣藤散"},{"n":5,"text":"芍薬甘草湯"}],"answer":4,"explanation":"慢性に経過する頭痛・めまい・肩こりがあり、慢性頭痛、神経症、高血圧の傾向のある人（体力中等度）に用いられるのは釣藤散です。呉茱萸湯は主に頭痛・しゃっくり等、香蘇散は虚弱な人のかぜの初期や神経過敏、麻黄湯は体力充実したかぜのひきはじめ、芍薬甘草湯は筋肉のけいれんを伴う痛みに用いる処方で、記述の内容とは合いません。","tags":["漢方","釣藤散","頭痛"]},{"id":"R7-31","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":31,"stem":"口腔咽喉薬及び含嗽薬とその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"口腔咽喉薬には、鎮咳成分や気管支拡張成分、去痰成分は配合されていない。"},{"label":"b","text":"含嗽薬の殺菌消毒効果は、含嗽薬の使用後すぐに食事を摂った場合でも影響はない。"},{"label":"c","text":"グリチルリチン酸二カリウムは、喉の粘膜を刺激から保護する成分として配合されている。"},{"label":"d","text":"バセドウ病や橋本病の甲状腺疾患の診断を受けた人が、ヨウ素系殺菌消毒成分が配合された含嗽薬を使用する場合、その適否について、治療を行っている医師等に相談する必要がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"口腔咽喉薬には鎮咳・気管支拡張・去痰成分は配合されないとされ、aは正しい記述です。含嗽薬は使用後すぐに飲食すると殺菌消毒成分が薄まり効果が十分に得られないおそれがあるため、bは誤りです。グリチルリチン酸二カリウムは粘膜保護ではなく抗炎症成分として配合されるので、cは誤りです。ヨウ素系殺菌消毒成分は甲状腺疾患のある人では、治療中の医師等に相談する必要があり、dは正しい記述です。","tags":["口腔咽喉薬","含嗽薬","ヨウ素"]},{"id":"R7-33","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":33,"stem":"寝冷えによる下痢の症状を訴えて、「ロペラミド塩酸塩」が配合された一般用医薬品の止瀉薬を購入しようとする者への登録販売者の説明について、適切なものの組合せを選べ。","statements":[{"label":"a","text":"発熱がある場合には、薬により症状の悪化を招くおそれがあるため、使用できない可能性があると説明した。"},{"label":"b","text":"腹部に痛みがある場合には、胃腸鎮痛鎮痙薬を併用してもよいと説明した。"},{"label":"c","text":"副作用としてめまいや眠気が現れることがあるため、服用後は乗物又は機械類の運転操作をしないように説明した。"},{"label":"d","text":"１～２週間使用しても症状の改善がみられない場合には、服用を中止し、医師の診療を受けるよう説明した。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":2,"explanation":"ロペラミド塩酸塩は腸管運動を抑えて下痢を止める成分で、発熱を伴う下痢や血便など感染性が疑われる場合は症状を悪化させるおそれがあり、使用できない可能性があるため、aは適切です。副作用としてめまいや眠気が現れることがあり、服用後の乗物・機械類の運転操作を避けるよう説明するcも適切です。腹痛があるときに胃腸鎮痛鎮痙薬を併用するというbは適切ではありません。止瀉薬は下痢の対症療法として短期間の使用が前提で、数日使用しても改善しなければ受診を勧めるのが基本のため、「1～2週間」も使用を続けるよう促すdは適切ではありません。","tags":["止瀉薬","ロペラミド"]},{"id":"R7-35","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":35,"stem":"胃腸の不調を改善する目的で用いられる漢方処方製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"安中散は、体力中等度以下で、腹部は力がなくて、胃痛又は腹痛があって、ときに胸やけや、げっぷ、胃もたれ、食欲不振、吐きけ、嘔吐などを伴うものの神経性胃炎、慢性胃炎、胃腸虚弱に適すとされる。"},{"label":"b","text":"麻子仁丸は、体力虚弱で、疲れやすくて手足などが冷えやすいものの胃腸虚弱、下痢、嘔吐、胃痛、腹痛、急・慢性胃炎に適すとされる。"},{"label":"c","text":"桂枝加芍薬湯は、体力中等度以上で、胃がもたれて消化が悪く、ときに吐きけ、食後に腹が鳴って下痢の傾向があるものの食べ過ぎによる胃のもたれ、急・慢性胃炎、消化不良、食欲不振に適すとされる。"},{"label":"d","text":"六君子湯は、体力中等度以下で、胃腸が弱く、食欲がなく、みぞおちがつかえ、疲れやすく、貧血性で手足が冷えやすいものの胃炎、胃腸虚弱、胃下垂、消化不良、食欲不振、胃痛、嘔吐に適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"安中散は記述どおり、体力中等度以下で腹部に力がなく胃痛・胸やけなどのある人に用いられるので、aは正しい記述です。bの記述は虚弱で手足が冷えやすい人の胃腸虚弱などを示す内容で、便秘に用いる麻子仁丸の説明ではないため誤りです。cの「胃がもたれて消化が悪く、食後に腹が鳴って下痢の傾向」は桂枝加芍薬湯ではなく別の処方の説明であり誤りです。六君子湯の説明であるdは正しい記述です。","tags":["漢方","胃腸薬"]},{"id":"R7-38","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":38,"stem":"一般用医薬品の強心薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"センソは比較的有効域が狭いため、一般用医薬品では１日用量が５ｍｇ以下となるよう用法・用量が定められている。"},{"label":"b","text":"ジャコウは、強心作用のほか、呼吸中枢を刺激して呼吸機能を高めたり、意識をはっきりさせる等の作用がある。"},{"label":"c","text":"ロクジョウは、強心作用のほか、末梢血管の拡張による血圧降下、興奮を静める等の作用がある。"},{"label":"d","text":"リュウノウは、鎮静作用等を期待して用いられる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"センソは有効域が比較的狭く、一般用医薬品では1日用量が5mg以下とされているため、aは正しい記述です。ジャコウは強心作用のほか呼吸中枢を刺激して意識をはっきりさせる作用があるとされ、bも正しい記述です。cの末梢血管拡張による血圧降下や興奮を静める作用は別の生薬の説明で、ロクジョウは強壮・血行促進の目的で配合される生薬とされるため誤りです。リュウノウは鎮静ではなく中枢神経系の刺激による気つけ等を期待して用いられるため、dも誤りです。","tags":["強心薬","生薬"]},{"id":"R7-40","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":40,"stem":"痔及び一般用医薬品の痔疾用薬とその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"痔は、肛門部に過度の負担をかけることやストレス等により生じる。"},{"label":"b","text":"痔核は、肛門に存在する細かい血管群が部分的に拡張し、肛門内にいぼ状の腫れが生じたものである。"},{"label":"c","text":"痔による肛門部の創傷の治癒を促す効果を期待して、組織修復成分であるイソプロピルメチルフェノールが配合されている。"},{"label":"d","text":"リドカインは、局所への穏やかな熱感刺激によって痒みを抑える効果を期待して配合される。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"痔は肛門部への過度の負担やストレス等で生じ、痔核は肛門の血管群が部分的に拡張して生じるいぼ状の腫れであるため、a・bは正しい記述です。イソプロピルメチルフェノールは殺菌消毒成分であり、組織修復成分ではないため、cは誤りです。リドカインは局所麻酔成分で、痛みや痒みを抑える目的で配合されるものであり、熱感刺激によるものではないため、dも誤りです。","tags":["痔疾用薬","痔"]},{"id":"R7-42","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":42,"stem":"女性の月経や更年期障害に伴う諸症状の緩和に用いられる漢方処方製剤のうち、体力虚弱な人に用いるものの組合せを選べ。","statements":[{"label":"a","text":"桂枝茯苓丸"},{"label":"b","text":"四物湯"},{"label":"c","text":"桃核承気湯"},{"label":"d","text":"当帰芍薬散"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":4,"explanation":"月経や更年期障害に伴う諸症状に用いる漢方処方のうち、体力虚弱な人を対象とするのは四物湯（冷え症で皮膚が乾燥し色つやの悪い人）と当帰芍薬散（冷え症で貧血の傾向があり疲れやすい人）です。桂枝茯苓丸と桃核承気湯は、いずれも虚弱な人向けの処方ではなく、比較的体力のある人（桃核承気湯は便秘しがちでのぼせる人）を対象とします。したがって（b、d）が正解です。","tags":["漢方","婦人薬"]},{"id":"R7-46","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":46,"stem":"鼻炎用点鼻薬及びその配合成分に関する記述について、誤っているものを選べ。","statements":[],"options":[{"n":1,"text":"鼻炎用点鼻薬は、急性鼻炎、アレルギー性鼻炎又は副鼻腔炎による諸症状のうち、鼻づまり、鼻みず、くしゃみ、頭重の緩和を目的として、鼻腔内に適用される外用液剤である。"},{"n":2,"text":"スプレー式鼻炎用点鼻薬は、噴霧後に鼻汁とともに逆流する場合があるので、使用前に鼻をよくかむ。"},{"n":3,"text":"点鼻薬の成分は、鼻粘膜を通っている血管から吸収されて循環血液中に入りやすく、全身的な影響を生じることがある。"},{"n":4,"text":"ナファゾリン塩酸塩が配合された点鼻薬は、過度に使用すると鼻粘膜の血管が反応しなくなり、逆に血管が拡張して二次充血を招き、鼻づまりがひどくなりやすい。"},{"n":5,"text":"クロモグリク酸ナトリウムは、アレルギー性でない鼻炎や副鼻腔炎にも有効である。"}],"answer":5,"explanation":"クロモグリク酸ナトリウムはマスト細胞からのヒスタミン遊離を抑える抗アレルギー成分で、アレルギー性の鼻炎にのみ用いられ、アレルギー性でない鼻炎や副鼻腔炎への効果は期待できないため、5が誤りです。他の選択肢は、鼻炎用点鼻薬の目的、使用前に鼻をかむこと、全身作用の可能性、ナファゾリンによる二次充血といった一般的な注意点として正しい記述です。","tags":["鼻炎用点鼻薬","抗アレルギー成分"]},{"id":"R7-48","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":48,"stem":"外皮用薬に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"外皮用薬は、表皮の角質層が柔らかくなることで有効成分が浸透しやすくなることから、入浴後に用いるのが効果的とされる。"},{"label":"b","text":"貼付剤は、同じ部位に連続して貼付すると、かぶれを生じやすい。"},{"label":"c","text":"スプレー剤は患部から十分離して、１０秒以上同じ部位に連続して噴霧することが望ましい。"},{"label":"d","text":"火傷や化膿した創傷面の消毒、口腔内の殺菌・消毒を目的とする製品は、医薬部外品として製造販売されている。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":1,"explanation":"外皮用薬は、角質層が柔らかくなっている入浴後に用いると有効成分が浸透しやすいとされ、aは正しい記述です。貼付剤は同じ部位に連続して貼るとかぶれを生じやすいため、bも正しい記述です。スプレー剤は患部から十分離して噴霧し、同じ部位への連続噴霧は3秒以内にとどめるのが望ましく、凍傷を避けるためにも「10秒以上」とするcは誤りです。火傷や化膿した創傷面の消毒、口腔内の殺菌・消毒を目的とする製品は医薬品として販売され、医薬部外品としては扱われないため、dも誤りです。","tags":["外皮用薬","使用上の注意"]},{"id":"R7-50","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":50,"stem":"痒み、腫れ、痛み等を抑える配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"デキサメタゾンは、ステロイド骨格を持つ抗炎症成分の一つである。"},{"label":"b","text":"ステロイド性抗炎症成分は、末梢組織の免疫機能を増強させる作用を示すため、みずむし、たむし、にきび等に用いられる。"},{"label":"c","text":"ケトプロフェンを主薬とする外皮用薬では、紫外線により、使用中又は使用後しばらくしてから重篤な光線過敏症が現れることがある。"},{"label":"d","text":"ジクロフェナクナトリウムを主薬とする外皮用薬は、皮膚感染症に対して効果がなく、痛みや腫れを鎮めることでかえって皮膚感染が自覚されにくくなるおそれがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"デキサメタゾンはステロイド骨格を持つ抗炎症成分で、aは正しい記述です。ステロイド性抗炎症成分は末梢組織の免疫機能を「抑制」する作用により抗炎症作用を示すため、増強するとするbは誤りです。ケトプロフェンは紫外線により重篤な光線過敏症が現れることがあり、cは正しい記述です。ジクロフェナクナトリウムは皮膚感染症に効果がなく、症状の自覚を妨げるおそれがあるとされ、dも正しい記述です。","tags":["外皮用薬","ステロイド","NSAIDs"]},{"id":"R7-54","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":54,"stem":"医薬品として扱われる保健薬に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。\n\n　滋養強壮保健薬は、（　a　）を生じやすい状態や体質の改善、特定の（　b　）の不足による症状の（　c　）等を目的として、ビタミン成分、カルシウム、アミノ酸、生薬成分等が配合された医薬品である。","statements":[],"options":[{"n":1,"text":"a 消化不良 / b 栄養素 / c 改善又は予防"},{"n":2,"text":"a 消化不良 / b エネルギー源 / c 治療又は予防"},{"n":3,"text":"a 体調不良 / b 栄養素 / c 改善又は予防"},{"n":4,"text":"a 体調不良 / b 栄養素 / c 治療又は予防"},{"n":5,"text":"a 体調不良 / b エネルギー源 / c 治療又は予防"}],"answer":3,"explanation":"滋養強壮保健薬は、体調不良を生じやすい状態や体質の改善、特定の栄養素の不足による症状の改善又は予防等を目的とする医薬品です。「治療」は目的に含まれず、また消化不良やエネルギー源といった語も手引きの説明とは異なるため、a=体調不良、b=栄養素、c=改善又は予防の組合せが正解です。","tags":["滋養強壮保健薬","ビタミン"]},{"id":"R7-56","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":56,"stem":"次の漢方処方製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"清上防風湯は、体力中等度以上で、赤ら顔で、ときにのぼせがあるもののにきび、顔面・頭部の湿疹・皮膚炎、赤鼻に適すとされる。"},{"label":"b","text":"防風通聖散は、体力が充実して、脇腹からみぞおちあたりにかけて苦しく、便秘の傾向があるものの胃炎、常習便秘、高血圧や肥満に伴う肩こり・頭痛・便秘、神経症、肥満症に適すとされる。"},{"label":"c","text":"大柴胡湯は、体力中等度以下で、疲れやすく、汗のかきやすい傾向があるものの肥満に伴う関節の腫れや痛み、むくみ、多汗症、肥満症（筋肉にしまりのない、いわゆる水ぶとり）に適すとされる。"},{"label":"d","text":"防已黄耆湯は、体力充実して、腹部に皮下脂肪が多く、便秘がちなものの高血圧や肥満に伴う動悸・肩こり・のぼせ・むくみ・便秘、蓄膿症、湿疹・皮膚炎、ふきでもの、肥満症に適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"清上防風湯は、体力中等度以上で赤ら顔・にきび等に用いられるとする記述で、aは正しい内容です。bの記述は大柴胡湯の特徴、cの記述は防已黄耆湯の特徴、dの記述は防風通聖散の特徴にあたり、それぞれ処方名と説明が入れ替わっているため誤りです。肥満に用いる処方は名称が似ていても対象とする体力や症状が異なるため、区別が必要です。","tags":["漢方","肥満","防風通聖散"]},{"id":"R7-58","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":58,"stem":"感染症及び食中毒に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"感染症は、病原性のある細菌、寄生虫やウイルスなどが体に侵入することによって起こる望ましくない反応である。"},{"label":"b","text":"日常生活で問題となる感染症は、飛沫感染するものや経口感染するものが多い。"},{"label":"c","text":"一般に、夏はウイルスによる食中毒が、冬は細菌による食中毒が発生することが多いと言われている。"},{"label":"d","text":"食中毒の集団感染を防止するためには、器具等の消毒に適切な化学薬剤（消毒薬）を用いた処置を行うことが重要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"感染症は病原性のある細菌・寄生虫・ウイルス等の侵入によって起こる望ましくない反応であり、aは正しい記述です。日常生活で問題となる感染症は飛沫感染や経口感染するものが多く、bも正しい記述です。一般に夏は細菌性、冬はウイルス性の食中毒が多いとされているため、cは逆になっていて誤りです。食中毒の集団感染防止には、器具等の消毒に適切な消毒薬を用いることが重要で、dは正しい記述です。","tags":["感染症","食中毒","消毒薬"]},{"id":"R8-21","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":21,"stem":"かぜ（感冒）及びかぜ薬（総合感冒薬）に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"かぜの約８割は、細菌の感染が原因である。"},{"label":"b","text":"かぜは、下気道の急性炎症の総称である。"},{"label":"c","text":"かぜ薬は、かぜの諸症状の緩和を図る対症療法薬である。"},{"label":"d","text":"かぜであるからといって、必ずしもかぜ薬（総合感冒薬）を選択することが最適とは限らない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"かぜの原因の大部分はウイルスで、細菌が約8割を占めるわけではないため、aは誤りです。かぜは下気道ではなく上気道の急性炎症の総称なので、bも誤りです。かぜ薬はかぜの諸症状の緩和を図る対症療法薬で、原因そのものを治すものではないため、cは正しい記述です。かぜに似た症状でも、症状に応じ総合感冒薬以外の薬が適する場合があるため、dも正しい記述です。","tags":["かぜ薬","感冒"]},{"id":"R8-23","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":23,"stem":"かぜの症状緩和に用いられる漢方処方製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"葛根湯は、体力充実して、かぜのひきはじめで、寒気がして発熱、頭痛があり、咳が出て身体のふしぶしが痛く汗が出ていないものの感冒、鼻かぜ、気管支炎、鼻づまりに適すとされる。"},{"label":"b","text":"柴胡桂枝湯は、体力中等度以下で、痰が切れにくく、ときに強く咳こみ、又は咽頭の乾燥感があるもののから咳、気管支炎、気管支喘息、咽頭炎、しわがれ声に適すとされる。"},{"label":"c","text":"小青竜湯は、体力中等度又はやや虚弱で、うすい水様の痰を伴う咳や鼻水が出るものの気管支炎、気管支喘息、鼻炎、アレルギー性鼻炎、むくみ、感冒、花粉症に適すとされる。"},{"label":"d","text":"桂枝湯は、体力虚弱で、汗が出るもののかぜの初期に適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"葛根湯は体力中等度以上の人を対象とする処方で、「体力充実して」とするaは誤りです。bの、痰が切れにくく咳こむ、咽頭の乾燥感といった特徴は麦門冬湯の説明であり、柴胡桂枝湯の説明ではないため誤りです。小青竜湯は、うすい水様の痰を伴う咳や鼻水が出る人に用いられ、cは正しい記述です。桂枝湯は体力虚弱で汗が出るかぜの初期に用いられ、dも正しい記述です。","tags":["漢方","かぜ薬","小青竜湯"]},{"id":"R8-26","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":26,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを選べ。\n体力に関わらず使用でき、筋肉の急激な痙攣を伴う痛みのあるもののこむらがえり、筋肉の痙攣、腹痛、腰痛に適すとされる。ただし、症状があるときのみの服用にとどめ、連用は避ける。","statements":[],"options":[{"n":1,"text":"釣藤散"},{"n":2,"text":"疎経活血湯"},{"n":3,"text":"麻杏薏甘湯"},{"n":4,"text":"桂枝加朮附湯"},{"n":5,"text":"芍薬甘草湯"}],"answer":5,"explanation":"筋肉の急激なけいれんを伴う痛み（こむらがえり、腹痛、腰痛など）に体力に関わらず用いられ、症状があるときのみの服用にとどめ連用を避けるとされる処方は芍薬甘草湯です。カンゾウを多く含むため、長期連用による偽アルドステロン症等に注意が必要な処方でもあります。釣藤散は慢性頭痛、疎経活血湯は関節痛・神経痛等、麻杏薏甘湯は関節痛・神経痛・筋肉痛、桂枝加朮附湯は関節痛・神経痛に用いられる処方です。","tags":["漢方","芍薬甘草湯","筋肉痛"]},{"id":"R8-29","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":29,"stem":"神経質、精神不安、不眠等の症状の改善を目的とした漢方処方製剤のうち、小児の夜泣きに用いるものの組合せを選べ。","statements":[{"label":"a","text":"酸棗仁湯"},{"label":"b","text":"桂枝加竜骨牡蛎湯"},{"label":"c","text":"加味帰脾湯"},{"label":"d","text":"抑肝散"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":4,"explanation":"小児の夜泣きに用いられる処方は、桂枝加竜骨牡蛎湯と抑肝散です。酸棗仁湯は心身が疲れて不眠がある人、加味帰脾湯は貧血・不眠・精神不安等がある人向けの処方で、小児の夜泣きを効能に含みません。したがって（b、d）が正解です。","tags":["漢方","不眠","夜泣き"]},{"id":"R8-31","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":31,"stem":"比較的穏やかな鎮咳去痰作用を期待して、配合されている場合がある生薬成分の組合せを選べ。","statements":[{"label":"a","text":"キキョウ"},{"label":"b","text":"センブリ"},{"label":"c","text":"キョウニン"},{"label":"d","text":"センキュウ"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":2,"explanation":"キキョウは痰を伴う咳などに、キョウニンは穏やかな鎮咳去痰作用を期待して配合される生薬です。センブリは苦味による健胃作用、センキュウは血行促進・鎮痛等を期待する生薬で、鎮咳去痰目的ではありません。したがって（a、c）が正解です。","tags":["鎮咳去痰薬","生薬"]},{"id":"R8-34","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":34,"stem":"胃腸に作用する薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"アルジオキサは、透析を受けている人では使用を避ける必要がある。"},{"label":"b","text":"テプレノンは、胃粘膜を保護し、荒れた胃粘膜の修復を促すことを期待して配合されている。"},{"label":"c","text":"ピレンゼピン塩酸塩は、排尿困難、動悸、目のかすみの副作用を生じることがある。"},{"label":"d","text":"ウルソデオキシコール酸は、胆汁の分泌を促す作用があるとされ、消化を助ける効果を期待して用いられる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"アルジオキサはアルミニウムを含み、透析を受けている人では使用を避ける必要があるとされ、aは正しい記述です。テプレノンは胃粘膜の保護と修復促進を目的に配合され、bも正しい記述です。ピレンゼピン塩酸塩は抗コリン作用により排尿困難・動悸・目のかすみ等が現れることがあり、cも正しい記述です。ウルソデオキシコール酸は胆汁分泌を促して消化を助けるとされ、dも正しい記述です。すべて正しいため、3が正解です。","tags":["胃腸薬","配合成分"]},{"id":"R8-37","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":37,"stem":"浣腸薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"浣腸薬は一般に、直腸の急激な動きに刺激されて流産・早産を誘発するおそれがあるため、妊婦又は妊娠していると思われる女性では使用を避けるべきである。"},{"label":"b","text":"注入剤を使用する場合は、薬液の放出部を肛門に差し込み、薬液だまりの部分を絞って、薬液を押し込むように注入する。"},{"label":"c","text":"グリセリンは、浸透圧の差によって腸管壁から水分を取り込んで直腸粘膜を刺激し排便を促す。"},{"label":"d","text":"炭酸水素ナトリウムが配合された坐剤を、痔出血の症状がある場合に使用すると、傷口から血管内に入り溶血を引き起こすおそれがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":1,"explanation":"浣腸薬は直腸の急激な動きが流産・早産を誘発するおそれがあるため妊婦等では使用を避けるとされ、aは正しい記述です。注入剤は薬液放出部を肛門に差し込み、薬液だまりを絞って薬液を押し込むように注入するため、bも正しい記述です。グリセリンは浸透圧の差で腸管壁から水分を取り込んで直腸粘膜を刺激し排便を促すため、cも正しい記述です。痔出血のある人で傷口から血管内に入り溶血を起こすおそれがあるのはグリセリンであり、炭酸水素ナトリウムの坐剤ではないためdは誤りです。","tags":["浣腸薬","グリセリン","瀉下薬"]},{"id":"R8-39","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":39,"stem":"血中コレステロール及び高コレステロール改善薬とその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"低密度リポタンパク質（ＬＤＬ）は、コレステロールを肝臓から末梢組織へと運ぶリポタンパク質である。"},{"label":"b","text":"心臓病や肥満、動脈硬化症等の生活習慣病の危険性は、血液中のＬＤＬが少なく、高密度リポタンパク質（ＨＤＬ）が多い場合に高くなる。"},{"label":"c","text":"大豆油不けん化物（ソイステロール）は、腸管におけるコレステロールの吸収を抑える。"},{"label":"d","text":"高コレステロール改善薬は、ウエスト周囲径（腹囲）を減少させるなどの痩身効果を目的として使用される。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":1,"explanation":"LDLはコレステロールを肝臓から末梢組織へ運ぶリポタンパク質で、aは正しい記述です。生活習慣病の危険性は、LDLが多くHDLが少ない場合に高まるため、「LDLが少なくHDLが多い」とするbは誤りです。大豆油不けん化物（ソイステロール）は腸管でのコレステロール吸収を抑えるため、cは正しい記述です。高コレステロール改善薬は血中コレステロールの改善を目的とし、腹囲を減らすなどの痩身効果を目的とするものではないため、dは誤りです。","tags":["高コレステロール改善薬","コレステロール"]},{"id":"R8-42","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":42,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを選べ。\n体力に関わらず使用でき、排尿異常があり、ときに口が渇くものの排尿困難、排尿痛、残尿感、頻尿、むくみに適すとされる。","statements":[],"options":[{"n":1,"text":"牛車腎気丸"},{"n":2,"text":"猪苓湯"},{"n":3,"text":"六味丸"},{"n":4,"text":"乙字湯"},{"n":5,"text":"苓桂朮甘湯"}],"answer":2,"explanation":"体力に関わらず使用でき、排尿異常があり、ときに口が渇くものの排尿困難・排尿痛・残尿感・頻尿・むくみに用いられるのは猪苓湯です。牛車腎気丸と六味丸は主に体力中等度以下～虚弱で疲れやすい人の下肢痛・むくみ・排尿困難等、乙字湯は痔核・便秘等、苓桂朮甘湯はめまい・立ちくらみ等に用いられる処方で、記述とは異なります。","tags":["漢方","猪苓湯","泌尿器"]},{"id":"R8-45","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":45,"stem":"アレルギー、蕁麻疹及び一般用医薬品の内服アレルギー用薬に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"体内に侵入したアレルゲンにより肥満細胞から遊離されたヒスタミンは、周囲の器管や組織表面の受容体と反応することで、血管収縮、血管透過性低下等の作用を示す。"},{"label":"b","text":"蕁麻疹には、アレルゲンとの接触以外に、皮膚への物理的な刺激等によってヒスタミンが肥満細胞から遊離して生じるものもある。"},{"label":"c","text":"内服アレルギー用薬は、蕁麻疹や湿疹、かぶれ及びそれらに伴う皮膚の痒み又は鼻炎等に用いられる内服薬の総称で、抗ヒスタミン成分を主体として配合されている。"},{"label":"d","text":"一般用医薬品には、アトピー性皮膚炎による慢性湿疹等の治療に用いることを目的とするものがある。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":3,"explanation":"アレルゲンにより肥満細胞から遊離したヒスタミンは、血管拡張や血管透過性亢進などの作用を示すため、「血管収縮、血管透過性低下」とするaは誤りです。蕁麻疹にはアレルゲン以外に、皮膚への物理的な刺激でヒスタミンが遊離して起こるものもあり、bは正しい記述です。内服アレルギー用薬は抗ヒスタミン成分を主体とする内服薬の総称で、cも正しい記述です。アトピー性皮膚炎の慢性湿疹などの治療を目的とする一般用医薬品は認められておらず、dは誤りです。","tags":["アレルギー用薬","蕁麻疹","抗ヒスタミン成分"]},{"id":"R8-47","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":47,"stem":"一般用医薬品の鼻炎用点鼻薬に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"鼻炎用点鼻薬は、鼻炎等の原因そのものを取り除くことにより、症状の緩和を図るものである。"},{"label":"b","text":"副鼻腔炎のうち慢性のものである蓄膿症は、一般用医薬品の鼻炎用点鼻薬で対処することが推奨される。"},{"label":"c","text":"鼻粘膜が腫れてポリープ（鼻茸）となっている場合にも、一般用医薬品の点鼻薬の使用が適切である。"},{"label":"d","text":"アドレナリン作動成分が配合された鼻炎用点鼻薬は、鼻以外の器官や臓器に影響を及ぼすおそれがあり、長期連用を避けることとされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"鼻炎用点鼻薬は原因そのものを取り除くものではなく、症状の緩和を図る薬なので、aは誤りです。蓄膿症（慢性の副鼻腔炎）は一般用医薬品の鼻炎用点鼻薬での対処が推奨されず、bは誤りです。鼻茸（ポリープ）がある場合も一般用点鼻薬の使用は適切ではなく、cは誤りです。アドレナリン作動成分は鼻以外にも影響するおそれがあり、長期連用を避けるとされ、dは正しい記述です。","tags":["鼻炎用点鼻薬","アドレナリン作動成分"]},{"id":"R8-50","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":50,"stem":"次の成分の一般用医薬品の外用鎮痛消炎薬（貼付剤）に関する記述の正誤について、正しい組合せを選べ。\n１００ｇ中：\n成分 / 分量\nサリチル酸グリコール / 2.0g\nグリチルレチン酸 / 0.05g\nトウガラシエキス / 0.02g\nトコフェロール酢酸エステル / 0.3g","statements":[{"label":"a","text":"サリチル酸グリコールは、局所刺激により患部の血行を促し、また、末梢の知覚神経に軽い麻痺を起こすことにより、鎮痛作用をもたらす。"},{"label":"b","text":"トウガラシ（トウガラシエキス）は、皮膚に温感刺激を与え、末梢血管を拡張させて患部の血行を促すことを期待して配合されている。"},{"label":"c","text":"トコフェロール酢酸エステルは、患部局所の血行を促す目的で配合されている。"},{"label":"d","text":"本剤は、打撲や捻挫などの急性の腫れや熱感を伴う症状に適している。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"サリチル酸グリコールは局所刺激による血行促進と、末梢の知覚神経の軽い麻痺による鎮痛作用を示す成分で、aは正しい記述です。トウガラシは温感刺激により血行を促す目的で配合され、bも正しい記述です。トコフェロール酢酸エステルは患部局所の血行促進を目的に配合され、cも正しい記述です。トウガラシエキスを含む温感タイプの貼付剤は、打撲や捻挫の急性の腫れや熱感を伴う症状には適さないため、dは誤りです。","tags":["外用鎮痛消炎薬","貼付剤","温感刺激"]},{"id":"R8-55","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":55,"stem":"禁煙補助剤（咀嚼剤）に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。なお、同じアルファベットの（　　）の中には、同じ字句が入る。\n口腔内が（　a　）になるとニコチンの吸収が低下するため、コーヒーや炭酸飲料など口腔内を（　a　）にする食品を摂取した後、しばらくは使用を避けることとされている。また、ニコチンは（　b　）系を興奮させる作用を示し、アドレナリン作動成分が配合された医薬品（鎮咳去痰薬、鼻炎用薬、痔疾用薬等）との併用により、その作用を（　c　）させるおそれがある。","statements":[],"options":[{"n":1,"text":"a 酸性 / b 交感神経 / c 増強"},{"n":2,"text":"a 酸性 / b 交感神経 / c 減弱"},{"n":3,"text":"a 酸性 / b 副交感神経 / c 増強"},{"n":4,"text":"a アルカリ性 / b 交感神経 / c 減弱"},{"n":5,"text":"a アルカリ性 / b 副交感神経 / c 減弱"}],"answer":1,"explanation":"禁煙補助剤（咀嚼剤）では、口腔内が酸性になるとニコチンの吸収が低下するため、コーヒーや炭酸飲料等の摂取後しばらくは使用を避けます。また、ニコチンは交感神経系を興奮させる作用があり、アドレナリン作動成分を含む医薬品との併用でその作用を増強させるおそれがあります。したがって a=酸性、b=交感神経、c=増強 が正解です。","tags":["禁煙補助剤","ニコチン"]},{"id":"R8-58","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":58,"stem":"エタノール及びイソプロパノールの殺菌消毒作用等に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"アルコール分が微生物のタンパク質を変性させることによって、殺菌消毒作用を示す。"},{"label":"b","text":"結核菌に対して殺菌消毒作用を示すが、真菌類に対しては殺菌消毒作用を示さない。"},{"label":"c","text":"エタノールのウイルスに対する不活性効果は、イソプロパノールよりも低い。"},{"label":"d","text":"脱脂による肌荒れを起こしやすく、皮膚へ繰り返して使用する場合には、適さない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"エタノールやイソプロパノールは、微生物のタンパク質を変性させて殺菌消毒作用を示すため、aは正しい記述です。結核菌や真菌類にも殺菌消毒作用を示すため、「真菌類には示さない」とするbは誤りです。ウイルスに対する不活性効果は、イソプロパノールよりもエタノールのほうが高いとされるため、「エタノールのほうが低い」とするcは誤りです。脱脂による肌荒れを起こしやすく、繰り返し皮膚に使用する場合には適さないため、dは正しい記述です。","tags":["消毒薬","エタノール","イソプロパノール"]},{"id":"R7-81","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":81,"stem":"登録販売者に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"登録販売者試験に合格した者であって、医薬品の販売又は授与に従事しようとするものは、都道府県知事の登録を受けなければならない。"},{"label":"b","text":"登録販売者名簿の登録事項に変更を生じたときは、居住地の都道府県知事にその旨を届け出なければならない。"},{"label":"c","text":"都道府県知事は、登録販売者が不正の手段により販売従事登録を受けたことが判明したときは、その登録を消除しなければならない。"},{"label":"d","text":"登録販売者として店舗販売業に従事している者が、他の都道府県の店舗で従事する場合、新たに当該都道府県知事の販売従事登録を重複して受ける必要がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":1,"explanation":"a正：試験に合格した者で医薬品の販売・授与に従事しようとする者は、都道府県知事の登録を受けなければなりません（法第36条の8第2項）。b誤：登録事項に変更が生じたときは、30日以内に、居住地ではなく登録を受けた都道府県知事へ変更届を提出します（規則第159条の9）。c正：偽りその他不正の手段により販売従事登録を受けたことが判明したときは、都道府県知事は登録を消除しなければなりません（規則第159条の10第5項）。d誤：二以上の都道府県で販売従事登録を受けることはできず、いずれか一つの登録のみとされています（規則第159条の7第3項）。","tags":["登録販売者","販売従事登録"]},{"id":"R7-82","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":82,"stem":"医薬品の定義に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"日本薬局方に収載されている物は、全て法で規定される医薬品である。"},{"label":"b","text":"日本薬局方に収載されている医薬品の中に、一般用医薬品として販売されているものはない。"},{"label":"c","text":"法で規定される医薬品には、検査薬や殺虫剤、器具用消毒薬のように、人の身体に直接使用されないものも含まれる。"},{"label":"d","text":"「やせ薬」を標榜したもの等、「無承認無許可医薬品」も法で規定されている医薬品に含まれる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"a正：日本薬局方に収載されている物は、すべて医薬品医療機器等法上の医薬品です。b誤：局方収載品目には一般用医薬品として販売されているものが多くあります。c正：検査薬や殺虫剤、器具用消毒薬のように、人の身体に直接使用しないものでも、法の医薬品の定義に該当するものがあります。d正：やせ薬などを標榜して販売される無承認無許可医薬品も、医薬品として法の規制対象になります。","tags":["医薬品の定義","日本薬局方"]},{"id":"R7-83","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":83,"stem":"要指導医薬品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"要指導医薬品で劇薬に該当するものはない。"},{"label":"b","text":"検体の採取に身体への直接のリスクを伴う検査薬は、要指導医薬品としては認められていない。"},{"label":"c","text":"医師等の診療によらなければ一般に治癒が期待できない心臓病に対する効能効果は、要指導医薬品において認められていない。"},{"label":"d","text":"要指導医薬品は、法に定める期間を経過し、薬事審議会において一般用医薬品として取り扱うことが適切と認められたものについては、一般用医薬品に分類される。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"a誤：要指導医薬品には劇薬に該当するものがあります。b正：検体の採取に身体への直接のリスクを伴う検査薬は、要指導医薬品として認められていません。c正：医師等の診療によらなければ一般に治癒が期待できない疾患（心臓病など）に対する効能効果は、要指導医薬品では認められません。d正：所定の期間を経過し、薬事審議会で一般用医薬品として取り扱うことが適切とされたものは、一般用医薬品に分類されます。","tags":["要指導医薬品","医薬品の販売区分"]},{"id":"R7-85","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":85,"stem":"一般用医薬品のリスク区分に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"第三類医薬品は、法で「その副作用等により日常生活に支障を来す程度の健康被害が生ずるおそれがある医薬品であって厚生労働大臣が指定するもの」とされている。"},{"label":"b","text":"第二類医薬品のうち、「特別の注意を要するものとして厚生労働大臣が指定するもの」を指定第二類医薬品としている。"},{"label":"c","text":"第三類医薬品に分類されている医薬品について、第一類医薬品又は第二類医薬品に分類が変更されることもある。"},{"label":"d","text":"既存の医薬品と明らかに異なる有効成分が配合されたもの（いわゆるダイレクトＯＴＣ）は、承認を受けてから一定期間は第三類医薬品に分類される。"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":3,"explanation":"b正：第二類医薬品のうち、特別の注意を要するものとして厚生労働大臣が指定するものが指定第二類医薬品です。c正：リスクの評価や使用状況により、第三類から第一類・第二類へ分類が変更されることもあります。a誤：第三類医薬品は、第一類医薬品及び第二類医薬品以外の一般用医薬品と定義されており、記述は第二類医薬品の定義に近い内容です。d誤：新有効成分含有医薬品（ダイレクトOTC）は、承認後一定期間は第三類ではなく第一類医薬品に分類されます。","tags":["一般用医薬品のリスク区分"]},{"id":"R7-86","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":86,"stem":"法第５０条に基づき、一般用医薬品及び要指導医薬品の直接の容器又は直接の被包に記載されていなければならない事項について、正しいものの組合せを選べ。ただし、厚生労働省令で定める表示の特例に関する規定は考慮しなくてよい。","statements":[{"label":"a","text":"製造業者の氏名又は名称及び住所"},{"label":"b","text":"日本薬局方に収載されている医薬品については、「日本薬局方」の文字"},{"label":"c","text":"指定第二類医薬品にあっては、「第二類医薬品」の文字に下線"},{"label":"d","text":"配置販売品目以外の一般用医薬品にあっては、「店舗専用」の文字"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":4,"explanation":"法第50条に基づく記載事項のうち、b：日本薬局方に収められている医薬品は「日本薬局方」の文字（同条第5号）、d：配置販売品目基準に適合するもの以外の一般用医薬品は「店舗専用」の文字（規則第210条第1項第5号）を記載します。a誤：記載するのは製造業者ではなく製造販売業者の氏名又は名称及び住所です（法第50条第1号）。c誤：指定第二類医薬品は、規則第210条第1項第6号により「枠の中に『2』の数字」を記載する定めで、「第二類医薬品」の文字に下線を付す規定ではありません。","tags":["法定表示","容器・被包の記載"]},{"id":"R7-87","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":87,"stem":"医薬部外品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬部外品を販売する場合は、販売業の許可を取得する必要がある。"},{"label":"b","text":"医薬部外品を製造販売する場合は、厚生労働大臣が基準を定めて指定するものを除き、品目ごとに承認を得る必要がある。"},{"label":"c","text":"医薬部外品は、医薬品的な効能効果を表示・標榜することは認められていない。"},{"label":"d","text":"指定医薬部外品は、用法用量や使用上の注意を守って適正に使用することが他の医薬部外品と比べてより重要であるため、各製品の容器や包装等に識別表示をしなければならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"a誤：医薬部外品は販売業の許可が不要で、一般小売店でも販売できます。b正：製造販売には、厚生労働大臣が基準を定めて指定するものを除き、品目ごとの承認が必要です。c誤：医薬部外品は、承認された範囲で効能効果を表示・標榜できます（医薬品的な効能効果の標榜が認められないのは化粧品などです）。d正：指定医薬部外品は、容器や包装等に識別表示が義務付けられています。","tags":["医薬部外品"]},{"id":"R7-89","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":89,"stem":"保健機能食品等の食品に関する記述について、誤っているものを選べ。","statements":[],"options":[{"n":1,"text":"特定保健用食品、栄養機能食品、機能性表示食品を総称して「保健機能食品」という。"},{"n":2,"text":"特定保健用食品の特定の保健の用途を表示するには、個別に生理的機能や特定の保健機能を示す有効性や安全性等に関する審査を受け、許可又は承認を取得することが必要である。"},{"n":3,"text":"栄養機能食品として、食品表示基準の規定に基づき特定の栄養成分の機能を表示するには、消費者庁長官の個別の審査を受けなければならない。"},{"n":4,"text":"機能性表示食品は、事業者の責任において、科学的根拠に基づいた機能性を表示し、販売前に安全性及び機能性の根拠に関する情報などを消費者庁長官へ届け出る必要がある。"},{"n":5,"text":"健康食品の中には医薬品成分が検出される場合があり、無承認無許可医薬品として、法に基づく取締りの対象となる。"}],"answer":3,"explanation":"1正：特定保健用食品、栄養機能食品、機能性表示食品を総称して保健機能食品といいます。2正：特定保健用食品は個別に審査を受け、許可又は承認を得る必要があります。3誤：栄養機能食品は、国が定める規格基準に適合すれば、個別の審査や届出なしに機能を表示できます（自己認証）。4正：機能性表示食品は、事業者の責任で表示し、販売前に消費者庁長官へ届け出ます。5正：医薬品成分が検出された健康食品は、無承認無許可医薬品として取締りの対象になります。","tags":["保健機能食品","健康食品"]},{"id":"R7-90","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":90,"stem":"法第２４条及び第２５条に規定されている医薬品の販売業に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。\n\n医薬品を、業として販売、授与又は販売若しくは授与の目的での貯蔵、若しくは陳列（以下「販売等」という。）を行うには、薬局の開設又は医薬品の販売業の許可を受ける必要がある。医薬品の販売業の許可については、店舗販売業の許可、配置販売業の許可又は（　a　）の許可に分けられており、このうち、一般の生活者に対して医薬品を販売等することができるのは、（　b　）の許可を受けた者である。\nまた、これらの許可は、（　c　）年ごとに、その更新を受けなければ、その期間の経過によって、その効力を失う。","statements":[],"options":[{"n":1,"text":"a 卸売販売業 / b 店舗販売業及び配置販売業 / c 5"},{"n":2,"text":"a 卸売販売業 / b 店舗販売業及び配置販売業 / c 6"},{"n":3,"text":"a 卸売販売業 / b 店舗販売業、配置販売業及び卸売販売業 / c 5"},{"n":4,"text":"a 製造販売業 / b 店舗販売業、配置販売業及び製造販売業 / c 5"},{"n":5,"text":"a 製造販売業 / b 店舗販売業、配置販売業及び製造販売業 / c 6"}],"answer":2,"explanation":"医薬品の販売業の許可は、店舗販売業、配置販売業、卸売販売業の3種類です（法第25条）。このうち一般の生活者に販売等できるのは店舗販売業と配置販売業で、卸売販売業は薬局開設者や販売業者等に対する販売に限られます。製造販売業は販売業の種類ではありません。これらの許可は6年ごとに更新を受けなければ、その期間の経過によって効力を失います（法第24条第2項）。","tags":["医薬品販売業の許可","許可の更新"]},{"id":"R7-91","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":91,"stem":"薬局に関する記述について、正しいものを選べ。","statements":[],"options":[{"n":1,"text":"薬局で取り扱うことができる医薬品は、医療用医薬品と一般用医薬品のみである。"},{"n":2,"text":"医薬品を取り扱う場所であって、薬局として開設の許可を受けていないものはすべて、薬局の名称を付してはならない。"},{"n":3,"text":"薬局は、その薬局開設者が薬剤師でないときは、その薬局で薬事に関する実務に従事する薬剤師のうちから管理者を指定して実地に管理させなければならない。"},{"n":4,"text":"医師若しくは歯科医師又は薬剤師が診療又は調剤に従事する他の医療提供施設と連携し、薬剤の適正な使用の確保のために専門的な薬学的知見に基づく指導を実施するために必要な機能を有する薬局は、傷病の区分ごとに、その所在地の都道府県知事の認定を受けて地域連携薬局と称することができる。"},{"n":5,"text":"薬局開設者は、薬剤師不在時間に係る掲示事項を当該薬局に掲示すれば、その間は調剤室を閉鎖する必要はない。"}],"answer":3,"explanation":"3が正しい：薬局開設者が薬剤師でないときは、その薬局で薬事に関する実務に従事する薬剤師のうちから管理者を指定して実地に管理させなければなりません（法第7条第2項）。1誤：薬局では、医療用医薬品のほか、要指導医薬品及び一般用医薬品も取り扱えます。2誤：薬局として開設の許可を受けていない場所は薬局の名称を付せませんが、病院又は診療所の調剤所は例外です（法第6条）。4誤：傷病の区分ごとに都道府県知事の認定を受けるのは専門医療機関連携薬局で、地域連携薬局ではありません（法第6条の2・第6条の3）。5誤：薬剤師不在時間内は、調剤室を閉鎖しなければなりません（規則第14条の3第3項）。","tags":["薬局","薬局開設者・管理者"]},{"id":"R7-93","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":93,"stem":"配置販売業に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"配置販売業の許可は、一般用医薬品を、配置により販売又は授与する業務について、配置しようとする区域をその区域に含む都道府県ごとに、その都道府県知事が与える。"},{"label":"b","text":"配置販売業は、一般用医薬品のうち経年変化が起こりにくいこと等の基準（配置販売品目基準）に適合するもの以外の医薬品を販売等してはならない。"},{"label":"c","text":"配置販売業者又はその配置員は、その住所地の都道府県知事が発行する身分証明書の交付を受け、かつ、これを携帯しなければ、医薬品の配置販売に従事してはならない。"},{"label":"d","text":"配置販売業者は、配置以外の方法によっても医薬品を販売することができる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"a正：配置販売業の許可は、配置しようとする区域を含む都道府県ごとに、その都道府県知事が与えます。b正：配置販売できるのは、経年変化が起こりにくい等の基準（配置販売品目基準）に適合する一般用医薬品に限られます。c正：配置員は、都道府県知事が発行する身分証明書の交付を受けて携帯していなければ配置販売に従事できません。d誤：配置販売業者は、配置以外の方法で販売してはなりません。","tags":["配置販売業"]},{"id":"R7-94","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":94,"stem":"要指導医薬品及び一般用医薬品のリスク区分に応じた情報提供等に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"要指導医薬品を販売する場合には、薬局開設者はその薬局において医薬品の販売に従事する薬剤師に、あらかじめ購入者等から他の医薬品の使用状況を確認させなければならない。"},{"label":"b","text":"第一類医薬品を販売する場合、店舗販売業者は情報提供を行った薬剤師の氏名を購入者等へ伝えさせなければならない。"},{"label":"c","text":"第二類医薬品を配置販売業者が配置する場合、配置販売に従事する登録販売者に、必ず書面を用いて必要な情報を提供させなければならない。"},{"label":"d","text":"第三類医薬品を購入した者から店舗販売業者に相談があり、その店舗において医薬品の販売に従事する薬剤師又は登録販売者が不在の場合には、別の店舗において医薬品の販売に従事する薬剤師又は登録販売者に必要な情報を提供させることができる。"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":1,"explanation":"a正：要指導医薬品の販売では、薬剤師にあらかじめ購入者等の他の医薬品の使用状況等を確認させる必要があります。b正：第一類医薬品を販売する場合、情報提供を行った薬剤師の氏名を購入者等に伝えさせる必要があります。c誤：第二類医薬品の情報提供は努力義務で、配置の場合も書面を必ず用いなければならないわけではありません。d誤：相談に応じるのはその店舗で販売に従事する薬剤師又は登録販売者で、不在時に別の店舗の者が代わる扱いは認められていません。","tags":["情報提供","リスク区分"]},{"id":"R7-95","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":95,"stem":"薬局開設者が第一類医薬品を販売する場合に、購入者にその薬局において医薬品の販売に従事する薬剤師に提供させなければならない事項について、誤っているものを選べ。","statements":[],"options":[{"n":1,"text":"当該医薬品の名称"},{"n":2,"text":"当該医薬品の有効成分の名称及びその分量"},{"n":3,"text":"当該医薬品の用法及び用量"},{"n":4,"text":"当該医薬品の効能又は効果"},{"n":5,"text":"当該医薬品の製造販売業者の氏名又は名称及び住所"}],"answer":5,"explanation":"第一類医薬品を販売する場合に薬剤師が提供する事項は、医薬品の名称、有効成分の名称及び分量、用法及び用量、効能又は効果、使用上の注意など（施行規則第159条の15）です。5誤：製造販売業者の氏名又は名称及び住所は、この情報提供事項に含まれません。","tags":["第一類医薬品","情報提供事項"]},{"id":"R7-97","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":97,"stem":"店舗販売業者が、法第２９条の４の規定に基づき、当該店舗の見やすい場所に掲示しなければならない事項の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"店舗に勤務する者の名札等による区別に関する説明"},{"label":"b","text":"勤務する登録販売者の販売従事登録証"},{"label":"c","text":"要指導医薬品、第一類医薬品、第二類医薬品及び第三類医薬品の定義並びにこれらに関する解説"},{"label":"d","text":"医薬品による健康被害の救済制度に関する解説"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"法第29条の4に基づく店舗の掲示事項には、a（勤務する者の名札等による区別に関する説明）、c（要指導医薬品及び各類の一般用医薬品の定義と解説）、d（医薬品による健康被害の救済制度に関する解説）が含まれます。b誤：勤務する登録販売者の販売従事登録証そのものの掲示は求められていません（掲示するのは勤務者の氏名・担当業務などの勤務状況や許可の内容等です）。","tags":["店舗販売業","掲示事項"]},{"id":"R7-98","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":98,"stem":"特定販売に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"店舗販売業者は、店舗に貯蔵又は陳列していない一般用医薬品でも、購入しようとする者の求めに応じて、特定販売にて販売することができる。"},{"label":"b","text":"特定販売を行うことについてインターネットを利用して広告するときは、ホームページに相談時及び緊急時の電話番号その他連絡先を見やすく表示する必要がある。"},{"label":"c","text":"店舗販売業者は、一般用医薬品を購入しようとする者から、対面又は電話により相談応需の希望があった場合、その店舗において医薬品の販売又は授与に従事する薬剤師又は登録販売者に、対面又は電話により情報提供を行わせなければならない。"},{"label":"d","text":"薬局開設者は、特定販売により薬局製造販売医薬品（毒薬及び劇薬であるものを除く。）を販売することができる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"a誤：特定販売は、その店舗に貯蔵又は陳列している医薬品に限って行えます。b正：インターネットでの広告には、相談時・緊急時の連絡先などを見やすく表示する必要があります。c正：購入者から対面又は電話による相談応需の希望があった場合、薬剤師又は登録販売者が対面又は電話で情報提供を行います。d正：薬局製造販売医薬品（毒薬・劇薬を除く）は特定販売が可能です。","tags":["特定販売"]},{"id":"R7-99","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":99,"stem":"医薬品の広告に関する記述の正誤について、正しい組合せを選べ。なお、キョウニンはアンズ等の種子を基原とする生薬であり、アンズは果実を可食部とする食品である。","statements":[{"label":"a","text":"アンズやアンズを加工して製造された食品の記事に、キョウニンの効能効果を説明し、広告してよい。"},{"label":"b","text":"キョウニンが漢方処方製剤の構成生薬のひとつであるとき、キョウニンの効能効果のみをもって、この漢方処方製剤の効能効果を説明してはならない。"},{"label":"c","text":"一般用医薬品と同じ有効成分を含有する医療用医薬品の効能効果をそのまま標榜する広告は、承認されている内容を正確に反映した広告とはいえない。"},{"label":"d","text":"チラシやパンフレット等の同一紙面に、医薬品と、食品、化粧品、雑貨類等の医薬品ではない製品を併せて掲載することは認められていない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"a誤：食品の広告に、医薬品の成分の効能効果を結び付けて説明することは認められません。b正：漢方処方製剤は、構成生薬の作用を個別に挙げて効能効果を説明しないのが原則です。c正：医療用医薬品の効能効果をそのまま標榜すると、承認内容を正確に反映した広告とはいえません。d誤：医薬品と食品等を同一紙面に併載することは、混同されないよう区別すれば認められます。","tags":["広告規制","医薬品等適正広告基準"]},{"id":"R8-81","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":81,"stem":"次の記述は、法第１条の条文である。（　）の中に入れるべき字句の正しい組合せを選べ。なお、同じアルファベットの（　）の中には、同じ字句が入る。\n\nこの法律は、医薬品、医薬部外品、化粧品、医療機器及び再生医療等製品の品質、有効性及び安全性の確保並びにこれらの使用による（　a　）上の危害の発生及び拡大の防止のために必要な規制を行うとともに、（　b　）の規制に関する措置を講ずるほか、医療上特にその必要性が高い医薬品、医療機器及び再生医療等製品の（　c　）の促進のために必要な措置を講ずることにより、（　a　）の向上を図ることを目的とする。","statements":[],"options":[{"n":1,"text":"a 保健衛生 / b 指定薬物 / c 適正使用"},{"n":2,"text":"a 保健衛生 / b 指定薬物 / c 研究開発"},{"n":3,"text":"a 保健衛生 / b 麻薬及び向精神薬 / c 研究開発"},{"n":4,"text":"a 公衆衛生 / b 指定薬物 / c 適正使用"},{"n":5,"text":"a 公衆衛生 / b 麻薬及び向精神薬 / c 適正使用"}],"answer":2,"explanation":"法第1条は、医薬品等の品質・有効性・安全性の確保と、これらの使用による保健衛生上の危害の発生・拡大の防止のための規制、指定薬物の規制に関する措置、医療上特に必要性が高い医薬品等の研究開発の促進を定め、保健衛生の向上を図ることを目的としています。よって、a保健衛生、b指定薬物、c研究開発の組合せである2が正解です。","tags":["法の目的","医薬品医療機器等法"]},{"id":"R8-82","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":82,"stem":"登録販売者に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"販売従事登録を受けようとする者は、販売従事登録申請書を、販売従事登録を受けようとする者の本籍地の都道府県知事に提出しなければならない。"},{"label":"b","text":"都道府県知事は、販売従事登録を行ったときは、当該販売従事登録を受けた者に対して、登録証を交付しなければならない。"},{"label":"c","text":"登録販売者は、一般用医薬品の販売又は授与に従事しようとしなくなったときは、６０日以内に、登録販売者名簿の登録の消除を申請しなければならない。"},{"label":"d","text":"店舗販売業者は、その店舗において業務に従事する登録販売者に対し、都道府県知事に届出を行った者（研修実施機関）が行う研修を毎年度受講させなければならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"b正：都道府県知事は販売従事登録を行ったときは、登録を受けた者に登録証を交付しなければなりません（規則第159条の8第2項）。a誤：申請書の提出先は本籍地ではなく、医薬品の販売・授与に従事する薬局又は店舗の所在地（配置販売業は配置しようとする区域を含む都道府県）の都道府県知事です（規則第159条の7第1項）。c誤：一般用医薬品の販売・授与に従事しようとしなくなったときは、60日ではなく30日以内に登録の消除を申請します（規則第159条の10第1項）。d誤：継続的研修は毎年度受講させる必要がありますが、実施機関が届出をする相手は都道府県知事ではなく厚生労働大臣です（規則第147条の11の3）。","tags":["登録販売者","販売従事登録"]},{"id":"R8-83","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":83,"stem":"医薬品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品は、厚生労働大臣により「製造業」の許可を受けた者でなければ製造販売をしてはならない。"},{"label":"b","text":"製造販売しようとする医薬品は、品目ごとに、厚生労働大臣に届け出たものでなければならない。"},{"label":"c","text":"日本薬局方とは、都道府県知事が、保健医療上重要な医薬品について、必要な規格・基準及び標準的試験法等を定めたものである。"},{"label":"d","text":"医薬品の販売業者は、不正表示医薬品及び不良医薬品を販売の目的で陳列してはならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"a誤：医薬品を製造販売するには、「製造業」ではなく「製造販売業」の許可が必要です。b誤：品目ごとに必要なのは、届出ではなく承認です。c誤：日本薬局方は、都道府県知事ではなく厚生労働大臣が、薬事審議会の意見を聴いて定めます。d正：販売業者は、不正表示医薬品や不良医薬品を販売目的で陳列してはなりません。","tags":["医薬品の製造販売","日本薬局方"]},{"id":"R8-85","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":85,"stem":"毒薬及び劇薬に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"毒薬及び劇薬は、単に毒性、劇性が強いものだけでなく、薬効が期待される摂取量（薬用量）と中毒のおそれがある摂取量（中毒量）が接近しており安全域が狭いため、その取扱いに注意を要するもの等が指定される。"},{"label":"b","text":"劇薬を貯蔵、陳列する場所には、かぎを施さなければならない。"},{"label":"c","text":"毒薬を、１８歳未満の者その他安全な取扱いに不安のある者に交付することは禁止されている。"},{"label":"d","text":"劇薬を一般の生活者に対して対面販売又は譲渡する際に、当該医薬品を譲り受ける者から交付を受ける文書には、当該譲受人の職業の記載は不要である。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"a正：毒薬・劇薬は、毒性の強さだけでなく、薬用量と中毒量が近く安全域が狭いものも指定されます。b誤：かぎを施す義務があるのは毒薬を貯蔵・陳列する場所で、劇薬にはありません。c誤：交付が禁止されているのは14歳未満の者その他安全な取扱いに不安のある者で、18歳未満ではありません。d誤：毒薬・劇薬を一般の生活者に譲渡する際に受け取る文書には、譲受人の職業の記載も必要です。","tags":["毒薬・劇薬"]},{"id":"R8-86","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":86,"stem":"法第２条第１０項に規定される生物由来製品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"生物由来製品の中には、医療機器は含まれない。"},{"label":"b","text":"生物由来製品は、製品の使用による感染症の発生リスクに着目して指定される。"},{"label":"c","text":"生物由来製品には、植物に由来するもののみを原料又は材料として製造されるものもある。"},{"label":"d","text":"一般用医薬品である漢方処方製剤の中には、生物由来製品に指定されているものがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"a誤：生物由来製品には医療機器も含まれます。b正：生物由来製品は、製品の使用による感染症の発生リスクに着目して指定されます。c誤：植物に由来するもののみを原料又は材料とするものは、生物由来製品から除かれます。d誤：一般用医薬品の漢方処方製剤には、生物由来製品に指定されているものはありません。","tags":["生物由来製品"]},{"id":"R8-87","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":87,"stem":"次の成分（その水和物及びそれらの塩類を含む。）を有効成分として含有する製剤のうち、法第３６条の１１第１項の規定に基づき厚生労働大臣が指定する指定濫用防止医薬品（外用剤を除く。）に該当するものについて、正しいものの組合せを選べ。","statements":[{"label":"a","text":"ジフェンヒドラミン"},{"label":"b","text":"ジヒドロコデイン"},{"label":"c","text":"アスピリン"},{"label":"d","text":"アセトアミノフェン"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":1,"explanation":"指定濫用防止医薬品（法第36条の11）は、濫用のおそれのある成分を含む医薬品として厚生労働大臣が指定するもので、外用剤を除く製剤のうち、ジフェンヒドラミンやジヒドロコデインを有効成分とするものが指定の対象に含まれます。アスピリンやアセトアミノフェンは指定成分に含まれません。","tags":["指定濫用防止医薬品","濫用等のおそれのある医薬品"]},{"id":"R8-89","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":89,"stem":"医薬部外品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬部外品を製造販売する場合は、厚生労働大臣が基準を定めて指定するものを除き、品目ごとに承認を得る必要がある。"},{"label":"b","text":"医薬部外品の直接の容器又は直接の被包には、「医薬部外品」の文字の表示が義務付けられている。"},{"label":"c","text":"衛生害虫類（ねずみ、はえ、蚊、のみその他これらに類する生物）の防除のため使用される製品群は、「指定医薬部外品」の表示が義務付けられている。"},{"label":"d","text":"医薬部外品は、医薬品のような販売業の許可は必要なく、一般小売店において販売することができる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"a正：医薬部外品の製造販売は、厚生労働大臣が基準を定めて指定するものを除き、品目ごとに承認が必要です。b正：直接の容器又は直接の被包に「医薬部外品」の文字を表示することが義務付けられています。c誤：衛生害虫類の防除に使う製品群は防除用医薬部外品であり、「指定医薬部外品」の表示義務の対象として説明するのは誤りです。d正：医薬部外品は販売業の許可が不要で、一般小売店でも販売できます。","tags":["医薬部外品"]},{"id":"R8-90","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":90,"stem":"化粧品に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"化粧品の成分本質（原材料）について、いかなる場合であっても医薬品の成分を配合してはならない。"},{"label":"b","text":"化粧品は、医薬品的な効能効果の表示・標榜が認められていない。"},{"label":"c","text":"化粧品には、人の身体の構造又は機能に影響を及ぼすことを目的とするものがある。"},{"label":"d","text":"不良化粧品及び不正表示化粧品の販売は禁止されている。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"b正：化粧品では、医薬品的な効能効果の表示・標榜は認められていません。d正：不良化粧品・不正表示化粧品の販売は禁止されています。a誤：化粧品には、配合が認められている医薬品成分（一定の範囲内）があります。c誤：人の身体の構造又は機能に影響を及ぼすことを目的とするものは、化粧品の定義に当たらず、医薬品又は医薬部外品に該当します。","tags":["化粧品"]},{"id":"R8-91","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":91,"stem":"特別用途食品に関する記述について、（　）の中に入れるべき字句の正しい組合せを選べ。\n\n乳児、幼児、妊産婦又は病者の発育又は（　a　）若しくは回復の用に供することが適当な旨を医学的・栄養学的表現で記載し、かつ、用途を限定したもので、（　b　）に基づく許可又は承認を受け、「特別の用途に適する旨の表示」をする食品であり、（　c　）の許可等のマークが付されている。","statements":[],"options":[{"n":1,"text":"a 疾病の治療 / b 食品衛生法 / c 消費者庁"},{"n":2,"text":"a 疾病の治療 / b 食品衛生法 / c 厚生労働省"},{"n":3,"text":"a 疾病の治療 / b 健康増進法 / c 厚生労働省"},{"n":4,"text":"a 健康の保持 / b 健康増進法 / c 消費者庁"},{"n":5,"text":"a 健康の保持 / b 健康増進法 / c 厚生労働省"}],"answer":4,"explanation":"特別用途食品は、乳児・幼児・妊産婦・病者の発育又は健康の保持若しくは回復の用に供する旨を医学的・栄養学的に表示するもので、健康増進法に基づく許可又は承認を受けて表示されます。所管は消費者庁で、許可等のマークが付されています。よって、a健康の保持、b健康増進法、c消費者庁の4が正解です。","tags":["特別用途食品","保健機能食品等"]},{"id":"R8-93","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":93,"stem":"店舗販売業に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"店舗販売業者では、医薬品をあらかじめ小分けし、販売する行為は認められていない。"},{"label":"b","text":"店舗管理者が薬剤師であれば、その店舗において登録販売者に第一類医薬品を販売させることができる。"},{"label":"c","text":"店舗管理者は、保健衛生上支障を生ずるおそれがないよう、その店舗の業務につき、店舗販売業者に対して必要な意見を書面により述べなければならない。"},{"label":"d","text":"店舗販売業に従事している薬剤師は、その店舗で調剤を行うことができる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"a正：店舗販売業では、医薬品をあらかじめ小分けして販売することは認められていません。b誤：第一類医薬品の販売・情報提供は薬剤師が行い、店舗管理者が薬剤師であっても登録販売者に販売させることはできません。c正：店舗管理者は、保健衛生上支障を生じるおそれがないよう、店舗販売業者に対して必要な意見を書面により述べなければなりません。d誤：調剤は薬局でのみ行えるもので、店舗販売業の店舗では調剤できません。","tags":["店舗販売業","店舗管理者"]},{"id":"R8-94","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":94,"stem":"配置販売業に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品を配置により販売又は授与するときは、配置しようとする区域をその区域に含む都道府県ごとに、配置販売業の許可を受けなければならない。"},{"label":"b","text":"配置販売業者は、医薬品を開封して分割販売することができる。"},{"label":"c","text":"配置販売業者は、配置以外の方法により医薬品を販売してはならない。"},{"label":"d","text":"配置販売業者又はその配置員は、配置販売業者の氏名及び住所、配置販売に従事する者の氏名及び住所並びに区域及びその期間を、配置販売に従事した日から１５日以内に、配置販売に従事する区域の都道府県知事に届け出なければならない。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":2,"explanation":"a正：配置販売業の許可は、配置しようとする区域を含む都道府県ごとに受けます。c正：配置販売業者は、配置以外の方法で医薬品を販売してはなりません。b誤：配置販売業者は、医薬品を開封して分割販売してはなりません。d誤：配置販売に従事する者等の届出は、従事する前にあらかじめ行うものであり、従事した日から15日以内という定めではありません。","tags":["配置販売業"]},{"id":"R8-95","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":95,"stem":"法施行規則第１５９条の１８の５の規定に基づき、店舗販売業者が指定濫用防止医薬品であるプソイドエフェドリン塩酸塩を含有する一般用医薬品（かぜ薬としての効能又は効果を有する製剤）を店舗で販売するときに、その店舗で勤務する薬剤師又は登録販売者に確認させなければならない事項の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"年齢"},{"label":"b","text":"当該医薬品を購入しようとする者が１８歳未満の場合は、当該者の氏名"},{"label":"c","text":"当該医薬品を購入しようとする者又は使用しようとする者の当該医薬品及び当該医薬品以外の指定濫用防止医薬品の購入又は譲受けの状況"},{"label":"d","text":"当該医薬品をその店舗で購入しようとする者が、７日分を超えて当該医薬品を購入しようとする場合は、その理由"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"施行規則第159条の18の5により、指定濫用防止医薬品の販売時には、購入者の年齢、18歳未満の場合の氏名、当該医薬品及び他の指定濫用防止医薬品の購入又は譲受けの状況、多量に購入する場合の理由などを、薬剤師又は登録販売者に確認させる必要があります。設問のa～dはすべてこの確認事項に該当するため、3が正解です。","tags":["指定濫用防止医薬品","販売時の確認事項"]},{"id":"R8-97","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":97,"stem":"店舗販売業者が行う特定販売に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"特定販売を行うことについてインターネットを利用して広告をするときは、都道府県知事（その店舗の所在地が保健所を設置する市又は特別区の区域にある場合においては、市長又は区長。）及び厚生労働大臣が容易に閲覧することができるホームページで行わなければならない。"},{"label":"b","text":"特定販売を行うことについて広告をするときは、医薬品の薬効群ごとに表示しなければならない。"},{"label":"c","text":"特定販売を行うことについてインターネットを利用して広告をするときは、ホームページに特定販売を行う一般用医薬品の使用期限を見やすく表示しなければならない。"},{"label":"d","text":"特定販売を行う店舗に注文された医薬品がない場合、別の店舗から発送することができる。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":2,"explanation":"a正：インターネットでの特定販売の広告は、都道府県知事（保健所設置市・特別区の場合は市長又は区長）及び厚生労働大臣が容易に閲覧できるホームページで行います。c正：ホームページには、特定販売を行う一般用医薬品の使用期限を見やすく表示する必要があります。b誤：広告で表示を求められるのは薬効群ごとではなく、リスク区分ごとの表示などです。d誤：特定販売は、その店舗に貯蔵・陳列している医薬品に限られ、別の店舗から発送することはできません。","tags":["特定販売","広告規制"]},{"id":"R8-98","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":98,"stem":"医薬品等適正広告基準に関する記述について、誤っているものを選べ。","statements":[],"options":[{"n":1,"text":"漢方処方製剤の効能効果は、配合されている個々の生薬成分が相互に作用しているため、それらの構成生薬の作用を個別に挙げて説明することは不適当である。"},{"n":2,"text":"チラシやパンフレット等の同一紙面に、医薬品と、食品、化粧品、雑貨類等の医薬品ではない製品を併せて掲載することは認められていない。"},{"n":3,"text":"医師による診断・治療によらなければ一般に治癒が期待できない疾患について、自己治療が可能であるかのような広告表現は認められていない。"},{"n":4,"text":"医薬品の有効性又は安全性について、それが確実であることを保証するような表現がなされた広告は、明示的・暗示的を問わず、虚偽又は誇大な広告とみなされる。"},{"n":5,"text":"医薬関係者、医療機関、公的機関、団体等が、公認、推薦、選用等している旨の広告については、仮に事実であったとしても、原則として不適当とされている。"}],"answer":2,"explanation":"誤りは2。医薬品等適正広告基準では、医薬品と食品・化粧品・雑貨類等を同一紙面に併載すること自体は禁止されておらず、混同されないよう区別して掲載すれば認められます。1正：漢方処方製剤の効能効果は、構成生薬の作用を個別に挙げて説明することは不適当です。3正：医師の診断・治療が必要な疾患について、自己治療が可能であるかのような表現は認められません。4正：有効性・安全性の保証表現は、虚偽又は誇大な広告とみなされます。5正：医薬関係者・団体等の公認・推薦等の旨の広告は原則不適当です。","tags":["広告規制","医薬品等適正広告基準"]},{"id":"R8-99","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":99,"stem":"医薬品の販売方法に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"キャラクターグッズ等の景品類を提供して販売することに関しては、不当景品類及び不当表示防止法の限度内であれば認められる。"},{"label":"b","text":"医薬品の販売等に従事する専門家は、医薬品を多量に購入する者等に対して、プライバシーに配慮し、積極的に事情を尋ねることは避けるべきである。"},{"label":"c","text":"購入者の利便性のため、異なる複数の医薬品又は医薬品と他の物品を組み合わせて販売又は授与する場合は、購入者等に対して情報提供を十分に行える程度の種類の範囲内であって、かつ、組み合わせることに合理性が認められるものでなければならない。"},{"label":"d","text":"配置販売業において、医薬品を先用後利によらず現金売りすることは、配置による販売行為に当たる。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":2,"explanation":"a正：景品類の提供は、不当景品類及び不当表示防止法の限度内であれば認められます。c正：複数の医薬品又は医薬品と他の物品を組み合わせて販売する場合は、情報提供が十分に行える範囲で、組合せに合理性が必要です。b誤：多量購入者などには、必要に応じて事情を確認するべきで、尋ねることを避けるべきではありません。d誤：先用後利によらない現金売りは、配置による販売行為には当たりません。","tags":["販売方法","配置販売業"]},{"id":"R7-101","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":101,"stem":"医薬品の適正使用情報に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"要指導医薬品の添付文書等に記載されている適正使用情報は、一般の生活者には理解しにくい専門的な表現で記載されている。"},{"label":"b","text":"一般用医薬品は、薬剤師又は登録販売者の判断に従い、一般の生活者が使用するものである。"},{"label":"c","text":"一般用医薬品の添付文書は、開封時に一度目を通されれば十分というものではなく、必要なときにいつでも取り出して読むことができるように保管される必要がある。"},{"label":"d","text":"一般用医薬品の中には、添付文書の形でなく、法第５２条第２項の規定に基づく「用法、用量その他使用及び取扱い上の必要な注意」等の記載を外部の容器又は被包に行っている場合もある。"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":5,"explanation":"正解は5（c、d）。添付文書は購入後も必要なときに読み返せるよう保管すべきもので（c）、添付文書の形でなく外部の容器や被包に必要事項を記載する場合もある（d）。aは誤りで、要指導医薬品の情報は生活者が理解しやすい平易な表現で書かれる。bも誤りで、一般用医薬品は専門家の助言を参考にしつつも、生活者が自らの判断で選択・使用するものである。","tags":["適正使用情報","添付文書"]},{"id":"R7-102","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":102,"stem":"一般用医薬品（一般用検査薬を除く。）の添付文書等に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品の有効性・安全性等に係る新たな知見、使用に係る情報に基づき、２年に１回の定期的な改訂がなされている。"},{"label":"b","text":"販売名に薬効名が含まれている場合には、薬効名の記載は省略されることがある。"},{"label":"c","text":"病気の予防・症状の改善につながる事項（いわゆる「養生訓」）は、一般の生活者に分かりやすく示すため、必ず記載しなければならない。"},{"label":"d","text":"医療用医薬品では、紙の添付文書の同梱を廃止し、注意事項等情報は電子的な方法により提供されることとなったが、一般用医薬品は、引き続き紙の添付文書が同梱されている。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"正解は4。bは正しく、販売名に薬効名が含まれる場合は薬効名の記載が省略されることがある。dも正しく、一般用医薬品は引き続き紙の添付文書が同梱される。aは誤りで、添付文書は定期的ではなく、新たな知見に応じて必要なときに随時改訂される。cも誤りで、いわゆる養生訓は必須の記載事項ではなく、必要に応じて記載される。","tags":["添付文書","電子化"]},{"id":"R7-103","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":103,"stem":"一般用医薬品（一般用検査薬を含む。）の添付文書等における「使用上の注意」に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"使用上の注意は、枠囲い、文字の色やポイントを変えるなど他の記載事項と比べて目立つように記載されている。"},{"label":"b","text":"一般用検査薬では、検査結果が陰性であっても何らかの症状がある場合は、再検査するか又は医師に相談する旨等が記載されている。"},{"label":"c","text":"重篤な副作用として、ショック（アナフィラキシー）、皮膚粘膜眼症候群、中毒性表皮壊死融解症、喘息等が掲げられている医薬品では、「本剤又は本剤の成分によりアレルギー症状を起こしたことがある人は、長期連用しないこと」と記載されている。"},{"label":"d","text":"副作用については、まず、まれに発生する重篤な副作用について記載され、そのあとに続けて、一般的な副作用が記載される。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"正解は3。a（使用上の注意は枠囲みや文字の色などで目立たせる）とb（一般用検査薬は陰性でも症状があれば再検査か医師への相談）は正しい。cは誤りで、ショックなどを掲げる医薬品では「アレルギー症状を起こしたことがある人は、使用しないこと」と記載される。dも誤りで、副作用は、まず一般的なものを記載し、そのあとに続けてまれに発生する重篤なものを記載する順序である。","tags":["使用上の注意","一般用検査薬"]},{"id":"R7-104","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":104,"stem":"一般用医薬品の保管及び取扱い上の注意に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"取り出したときに室温との温度差で湿気を帯びる可能性があるため、カプセル剤を冷蔵庫内で保管することは不適当である。"},{"label":"b","text":"開封後、シロップ剤は変質しやすいため、冷蔵庫内で保管されるのが望ましい。"},{"label":"c","text":"点眼薬では、万一、使用に際して薬液に細菌汚染があった場合に、別の使用者に感染するおそれがあるため、添付文書に「家族以外の人とは共用しないこと」と記載されている。"},{"label":"d","text":"家庭内では、誤飲事故を防ぐため小児の手の届かないところに保管される必要がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"正解は2。カプセル剤は冷蔵庫から出した際の温度差で湿気を帯びるおそれがあり冷蔵庫保管は不適当（a）、開封後のシロップ剤は変質しやすいので冷蔵庫保管が望ましい（b）、小児の手の届かない所に保管する（d）はいずれも正しい。cは誤りで、点眼薬は細菌汚染による感染を防ぐため、家族であっても他の人と共用しないよう記載される。","tags":["保管・取扱い","点眼薬"]},{"id":"R7-105","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":105,"stem":"一般用医薬品の製品表示に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"アルコールを含有する内服液剤（滋養強壮を目的とするもの）には、アルコールを含有する旨が表示されているものがある。"},{"label":"b","text":"適切な保存条件下で製造後３年を超えて性状及び品質が安定であることが確認されている医薬品において、使用期限の法的な表示義務はない。"},{"label":"c","text":"購入者から開封後の医薬品の使用期限の問合せがあった場合、外箱等に記載されている使用期限を回答すればよい。"},{"label":"d","text":"危険物に該当する消毒用アルコールは、法の規定による法定表示事項に加え、「火気厳禁」等の表示が必要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"正解は2。アルコール含有の滋養強壮内服液にはその旨の表示がある製品がある（a）、製造後3年を超えて安定であることが確認されている医薬品は使用期限の法的表示義務がない（b）、危険物に該当する消毒用アルコールには火気厳禁などの表示が必要（d）は正しい。cは誤りで、外箱の使用期限は未開封で適切に保管した場合のものであり、開封後は期限より短い期間で使い切るよう案内すべきである。","tags":["製品表示","使用期限"]},{"id":"R7-107","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":107,"stem":"法第６８条の１０第１項の規定に基づき、医薬品の製造販売業者がその製造販売した医薬品について行う副作用等の報告において、１５日以内に厚生労働大臣に報告することとされている事項の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品によるものと疑われる副作用症例のうち、使用上の注意から予測できないもので、非重篤な国内事例"},{"label":"b","text":"医薬品によるものと疑われる感染症症例のうち、使用上の注意から予測できるもので、重篤（死亡を含む）な国内事例"},{"label":"c","text":"副作用症例・感染症の発生傾向が著しく変化したことを示す研究報告"},{"label":"d","text":"承認を受けた効能若しくは効果を有しないことを示す研究報告"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3。感染症症例のうち使用上の注意から予測できる重篤（死亡を含む）な国内事例は15日以内の報告対象である（b）。aの使用上の注意から予測できない非重篤の国内副作用症例は、15日ではなく定期報告の対象である。cの発生傾向が著しく変化したことを示す研究報告と、dの承認を受けた効能・効果を有しないことを示す研究報告は、いずれも30日以内の報告である。報告期限は「症例か研究報告か」「重篤度」「予測可否」で分けて整理するとよい。","tags":["副作用報告","製造販売業者"]},{"id":"R7-108","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":108,"stem":"法第６８条の１０第２項の規定に基づき、医薬関係者が行う医薬品の副作用等の報告に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品との因果関係が必ずしも明確でない場合であっても報告の対象となり得る。"},{"label":"b","text":"報告内容の正確性が必要ではあるが、報告様式の記入欄すべてに記入がなされる必要はない。"},{"label":"c","text":"保健衛生上の危害の発生や拡大防止の観点から、報告の必要性を認めた場合には、適宜速やかに報告する。"},{"label":"d","text":"安全対策上必要があると認める場合であっても、医薬品の過量使用によるものと思われる健康被害については報告する必要はない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"正解は2。医薬関係者からの報告は因果関係が明確でなくても対象になり得る（a）、報告様式の全欄記入は必須でない（b）、必要性を認めたら適宜速やかに報告する（c）は正しい。dは誤りで、安全対策上必要があると認める場合は、医薬品の過量使用や誤用によると思われる健康被害も報告の対象となる。","tags":["副作用報告","医薬関係者"]},{"id":"R7-109","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":109,"stem":"医薬品副作用被害救済制度に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品の副作用により一定の健康被害が生じた場合には、適正に使用したかどうかにかかわらず、医療費等の給付を行い、これにより被害者の迅速な救済を図る制度である。"},{"label":"b","text":"救済給付業務に必要な費用のうち、給付費については、製造販売業者から年度ごとに納付される拠出金が充てられる。"},{"label":"c","text":"健康被害が医薬品の副作用によると診断した医師が、独立行政法人医薬品医療機器総合機構（ＰＭＤＡ）に対して給付請求を行うことになっている。"},{"label":"d","text":"ＰＭＤＡは、（公財）友愛福祉財団からの委託を受けて、血液製剤によるヒト免疫不全ウイルス（ＨＩＶ）感染者・発症者に対する健康管理費用の支給等を行っている。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"正解は5。救済給付の給付費には製造販売業者から年度ごとに納付される拠出金が充てられ（b）、PMDAは友愛福祉財団の委託でHIV感染者・発症者の健康管理費用の支給等を行う（d）。aは誤りで、この制度は医薬品を適正に使用したにもかかわらず生じた副作用による被害が対象である。cも誤りで、請求は被害を受けた本人（または遺族）が行う。","tags":["医薬品副作用被害救済制度","PMDA"]},{"id":"R7-110","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":110,"stem":"医薬品副作用被害救済制度に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"人体に直接使用しない殺菌消毒剤は、本制度の対象とならない。"},{"label":"b","text":"医薬品の副作用であるかどうか判断がつきかねる場合は、給付請求を行うことはできない。"},{"label":"c","text":"副作用による疾病のため、入院治療が必要と認められるが、やむをえず自宅療養を行った場合についても、給付対象となる。"},{"label":"d","text":"いわゆる健康食品として販売された無承認無許可医薬品の使用による健康被害についても、本制度の対象となる。"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":2,"explanation":"正解は2（a、c）。人体に直接使用しない殺菌消毒剤などは救済制度の対象とならない（a）。入院が必要な程度でもやむを得ず自宅療養した場合は給付対象となる（c）。bは誤りで、副作用かどうか判断がつかない場合でも請求は可能で、因果関係は審議・判定される。dも誤りで、無承認無許可の健康食品による被害は対象外である。","tags":["医薬品副作用被害救済制度","給付対象"]},{"id":"R7-111","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":111,"stem":"一般用医薬品の安全対策に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"解熱鎮痛成分としてアミノピリン、スルピリンが配合されたアンプル入りかぜ薬の使用による重篤な副作用（ショック）で死亡例が発生し、１９６５年、厚生省（当時）より関係製薬企業に対し、製品の回収が要請された。"},{"label":"b","text":"１９７０年に、アンプル剤以外の一般用かぜ薬について、承認基準が制定され、成分・分量、効能・効果等が見直された。"},{"label":"c","text":"一般用かぜ薬の使用によると疑われる腎障害の発生事例が、２００３年５月までに複数報告されたことを受け、厚生労働省は一般用かぜ薬全般につき使用上の注意の改訂を指示した。"},{"label":"d","text":"２００３年８月までにプソイドエフェドリン塩酸塩が配合された一般用医薬品による脳出血等の副作用症例が複数報告されたことを受け、厚生労働省から関係製薬企業等に対して、使用上の注意の改訂、代替成分への切替え等について指示がなされた。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"正解は3。アンプル入りかぜ薬によるショック死を受けた1965年の製品回収要請（a）と、1970年のアンプル剤以外のかぜ薬の承認基準制定（b）は正しい。cは誤りで、2003年5月までに報告され使用上の注意が改訂されたのは腎障害ではなく間質性肺炎である。dも誤りで、脳出血等が問題となったのはプソイドエフェドリンではなくフェニルプロパノールアミン配合製品で、そのため代替成分に切り替えられた。","tags":["安全対策の経緯","かぜ薬"]},{"id":"R7-114","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":114,"stem":"一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に、「喘息を起こしたことがある人」と記載することとされている医薬品を選べ。","statements":[],"options":[{"n":1,"text":"フェルビナクが配合された外用鎮痛消炎薬"},{"n":2,"text":"タンニン酸アルブミンが配合された止瀉薬"},{"n":3,"text":"センノシドが配合された瀉下薬"},{"n":4,"text":"アルジオキサが配合された胃腸薬"},{"n":5,"text":"ピレンゼピン塩酸塩水和物が配合された胃腸薬"}],"answer":1,"explanation":"正解は1。フェルビナクなどの外用の非ステロイド性抗炎症成分（インドメタシン、ケトプロフェン、ピロキシカム等）は、アスピリン喘息を誘発するおそれがあるため、「喘息を起こしたことがある人」は使用しないこととされる。タンニン酸アルブミンは牛乳（カゼイン由来）アレルギーの人、アルジオキサは透析療法を受けている人への注意が中心で、喘息の記載はない。センノシドは授乳中や大量使用などに関する注意、ピレンゼピン塩酸塩水和物は目のかすみ・異常なまぶしさによる運転操作の注意や排尿困難に関する注意が中心である。","tags":["使用上の注意","外用鎮痛消炎薬"]},{"id":"R7-115","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":115,"stem":"一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に、「１５歳未満の小児」と記載することとされている内服薬の成分について、誤っているものを選べ。","statements":[],"options":[{"n":1,"text":"サザピリン"},{"n":2,"text":"ロペラミド"},{"n":3,"text":"オキセサゼイン"},{"n":4,"text":"プロメタジンメチレンジサリチル酸塩"},{"n":5,"text":"アセトアミノフェン"}],"answer":5,"explanation":"正解は5。アセトアミノフェンには15歳未満の小児を一律に使用不可とする記載はなく、用法・用量の年齢区分に従う。サザピリン、ロペラミド、オキセサゼイン、プロメタジンメチレンジサリチル酸塩は、いずれも「15歳未満の小児」が使用しないこととされる成分として整理されている。","tags":["使用上の注意","小児"]},{"id":"R7-116","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":116,"stem":"一般用医薬品の添付文書等において、心悸亢進、血圧上昇、糖代謝促進を起こしやすいため、「相談すること」の項目中に「高齢者」と記載することとされている内服薬の成分について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"トラネキサム酸"},{"label":"b","text":"トリメトキノール塩酸塩水和物"},{"label":"c","text":"水酸化アルミニウムゲル"},{"label":"d","text":"メチルエフェドリン塩酸塩"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":4,"explanation":"正解は4（b、d）。トリメトキノール塩酸塩水和物とメチルエフェドリン塩酸塩は交感神経刺激作用により心悸亢進・血圧上昇・糖代謝促進を起こしやすいため、高齢者は相談することとされる。トラネキサム酸と水酸化アルミニウムゲルは、この理由による高齢者の記載の対象ではない。","tags":["使用上の注意","高齢者"]},{"id":"R7-118","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":118,"stem":"一般用医薬品の添付文書等において、うっ血性心不全、心室頻拍の副作用が現れることがあるため、「症状があるときのみの服用にとどめ、連用しないこと」と記載することとされている漢方製剤の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"芍薬甘草湯"},{"label":"b","text":"抑肝散"},{"label":"c","text":"小建中湯"},{"label":"d","text":"加味帰脾湯"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"正解は4。うっ血性心不全と心室頻拍の副作用への注意から「症状があるときのみの服用にとどめ、連用しないこと」と記載されるのは芍薬甘草湯（a）のみである。抑肝散、小建中湯、加味帰脾湯はこの記載の対象ではない。芍薬甘草湯は甘草を含み偽アルドステロン症にも注意が必要である。","tags":["漢方製剤","芍薬甘草湯"]},{"id":"R7-119","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":119,"stem":"一般用医薬品の添付文書等の「相談すること」の項目中に、「次の診断を受けた人」として「甲状腺機能障害又は甲状腺機能亢進症」と記載することとされている内服薬の成分について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"フェニレフリン塩酸塩"},{"label":"b","text":"イブプロフェン"},{"label":"c","text":"ジプロフィリン"},{"label":"d","text":"クロルフェニラミンマレイン酸塩"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":2,"explanation":"正解は2（a、c）。フェニレフリン塩酸塩とジプロフィリンは、甲状腺機能障害または甲状腺機能亢進症の診断を受けた人が相談することとされる。イブプロフェンとクロルフェニラミンマレイン酸塩は、この項目での記載対象ではない。","tags":["使用上の注意","相談すること"]},{"id":"R8-101","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":101,"stem":"医薬品の適正使用情報と一般用医薬品の購入者等に対する情報提供に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品は、効能・効果、用法・用量、起こり得る副作用等、その適正な使用のために必要な情報（適正使用情報）を伴って初めて医薬品としての機能を発揮するものである。"},{"label":"b","text":"医薬品の販売等に従事する専門家が、購入者等へ情報提供を行う際は、個々の生活者の状況に関わらず、添付文書に記載された全ての項目を効率的に説明しなければならない。"},{"label":"c","text":"医薬品の販売等に従事する専門家は、購入者等が一般用医薬品の購入後、その医薬品を使い終わるまで、添付文書等は必要なときいつでも取り出して読むことができるよう大切に保存する必要性を説明することが重要である。"},{"label":"d","text":"一般用医薬品の添付文書や外箱表示の記載内容が改訂された場合、実際にそれが反映された製品が流通し、購入者等の目に触れるようになるまでには一定の期間を要する。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"正解は2。適正使用情報を伴って初めて医薬品としての機能を発揮する（a）、添付文書は使い終わるまで保管する必要がある（c）、改訂内容が製品に反映され流通するまで時間を要する（d）は正しい。bは誤りで、情報提供は個々の生活者の状況に合わせて必要な事項を選んで行うもので、全項目を画一的に説明するわけではない。","tags":["適正使用情報","情報提供"]},{"id":"R8-102","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":102,"stem":"一般用医薬品（一般用検査薬を除く。）の添付文書等に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"添付文書は、必要に応じて随時改訂がなされ、重要な内容が変更された場合には、改訂年月を記載するとともに、改訂された箇所を明示することとされている。"},{"label":"b","text":"医薬品を使用する人に、その製品の概要を分かりやすく説明することを目的として、製品の特徴が記載されている。"},{"label":"c","text":"誤りやすい使用方法の指摘、小児に使用させる場合の注意等、用法・用量に関連する使用上の注意事項がある場合には、用法及び用量の項目に続けて、これと区別して記載されている。"},{"label":"d","text":"医薬品を別の容器へ移し替えると、誤用の原因となるおそれや、医薬品として適切な品質が保持できなくなるおそれから、保管及び取扱い上の注意には、「他の容器に入れ替えないこと。」と記載されている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"正解は5（すべて正しい）。添付文書は必要に応じて随時改訂され、重要な変更は改訂年月と改訂箇所を明示する（a）。製品の概要を分かりやすく示す「製品の特徴」が記載される（b）。用法・用量に関連する使用上の注意は用法及び用量に続けて区別して記載される（c）。誤用や品質保持の観点から「他の容器に入れ替えないこと」と記載される（d）。","tags":["添付文書","記載項目"]},{"id":"R8-103","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":103,"stem":"一般用医薬品（一般用検査薬を除く。）の添付文書等における「使用上の注意」に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"「使用上の注意」、「してはいけないこと」及び「相談すること」の各項目の見出しには、それぞれ例示された標識的マークが付されていることが多い。"},{"label":"b","text":"「使用上の注意」として記載される内容は、その医薬品に配合されている成分等に由来することも多く、使用上の注意の内容について、配合成分等の記載からある程度読み取ることも可能である。"},{"label":"c","text":"医療用医薬品との併用について、医療機関で治療を受けている人が、治療のために処方された医薬品の使用を自己判断で控えることは適当でないため、「次の人は使用（服用）しないこと」の項目に、「医師（又は歯科医師）の治療を受けている人」等として記載されている。"},{"label":"d","text":"「相談すること」の項目に「妊娠又は妊娠していると思われる人」と記載されている医薬品は、ヒトにおける具体的な悪影響が判明しているものに限定されている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"正解は4（a、bが正、c、dが誤）。標識的マークが付されることが多く（a）、使用上の注意は配合成分から読み取れることも多い（b）。cは誤りで、医療機関で治療中の人の併用は自己判断で中止させず、「相談すること」の項目に記載される。dも誤りで、「妊娠又は妊娠していると思われる人」は、具体的な悪影響が判明していないものも含め、予防的観点から記載されている。","tags":["使用上の注意","妊婦"]},{"id":"R8-104","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":104,"stem":"一般用医薬品（一般用検査薬を除く。）の製品表示に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"外箱等には法の規定による表示事項のみを記載することとされ、他の法令に基づいた製品表示がなされていることはない。"},{"label":"b","text":"専門家への相談勧奨に関する事項について、記載スペースが狭小な場合には、「使用が適さない場合があるので、使用前には必ず医師、歯科医師、薬剤師又は登録販売者に相談してください」等と記載されている。"},{"label":"c","text":"購入者によっては、購入後すぐ開封せずにそのまま保管する場合や持ち歩く場合があるため、添付文書を見なくても適切な保管がなされるよう、その容器や包装にも、保管に関する注意事項が記載されている。"},{"label":"d","text":"使用期限の表示については、適切な保存条件下で製造後１年を超えて性状及び品質が安定であることが確認されている医薬品において、法的な表示義務はない。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":3,"explanation":"正解は3（b、c）。専門家への相談勧奨は、スペースが狭い場合は簡略な文言で記載される（b）。購入後すぐ開封しない場合や持ち歩く場合に備え、容器・包装にも保管上の注意が記載される（c）。aは誤りで、外箱には薬機法以外の法令（消防法など）に基づく表示がされることもある。dは誤りで、使用期限の法的表示義務がないのは製造後3年を超えて安定であることが確認されている場合である。","tags":["製品表示","使用期限"]},{"id":"R8-105","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":105,"stem":"安全性速報に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般的な使用上の注意の改訂情報よりも、迅速な注意喚起や適正使用のための対応の注意喚起が必要な状況にある場合に作成される。"},{"label":"b","text":"厚生労働省からの命令、指示、製造販売業者の自主決定等に基づいて作成される。"},{"label":"c","text":"製造販売業者から医療機関や薬局等へは、３か月以内に情報伝達される。"},{"label":"d","text":"イエローレターとも呼ばれている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3（aとbが正、cとdが誤）。安全性速報は、一般的な使用上の注意の改訂より迅速な注意喚起が必要な場合に、厚生労働省の命令・指示や製造販売業者の自主決定に基づき作成される。cは誤りで、製造販売業者から医療機関・薬局等へは1か月以内に情報伝達される。dは誤りで、安全性速報は青色地のブルーレターと呼ばれ、イエローレターは緊急安全性情報である。","tags":["安全性速報","ブルーレター"]},{"id":"R8-106","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":106,"stem":"医薬品等の安全性情報等に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"独立行政法人医薬品医療機器総合機構のホームページには、一般用医薬品に関連した情報として添付文書のほかに、医薬品等の製品回収に関する情報等が掲載されている。"},{"label":"b","text":"医薬品医療機器情報配信サービス（ＰＭＤＡメディナビ）は、医薬関係者のみが利用可能である。"},{"label":"c","text":"厚生労働省は、医薬品（一般用医薬品を含む）、医療機器等による重要な副作用、不具合等に関する情報をとりまとめ、「医薬品・医療機器等安全性情報」として情報提供を行っている。"},{"label":"d","text":"緊急安全性情報は、医療機関等への直接配布だけでなく、電子メールによる情報伝達も認められている。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"正解は3。PMDAのホームページには添付文書のほか製品回収情報等が掲載される（a）、厚生労働省は「医薬品・医療機器等安全性情報」を提供している（c）、緊急安全性情報は電子メールでの伝達も認められる（d）。bは誤りで、PMDAメディナビは医薬関係者に限らず、希望する人であれば利用できる。","tags":["安全性情報","PMDAメディナビ"]},{"id":"R8-107","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":107,"stem":"法第６８条の１０第２項の規定（医薬関係者からの副作用等報告制度）に基づく医薬品の副作用等の報告に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"医薬品等によるものと疑われる、身体の変調・不調、死亡を含む日常生活に支障を来す程度の健康被害について報告が求められている。"},{"label":"b","text":"登録販売者は、報告を行う医薬関係者として位置づけられている。"},{"label":"c","text":"医薬品との因果関係が明確でない場合は、報告の対象とはならない。"},{"label":"d","text":"報告の必要性を認めた場合には、保健衛生上の危害の発生又は拡大防止の観点から、報告する期限が定められている。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":1,"explanation":"正解は1（a、b）。医薬関係者からの報告は、身体の変調・不調や死亡を含む日常生活に支障を来す程度の健康被害が対象で（a）、登録販売者も報告を行う医薬関係者として位置づけられる（b）。cは誤りで、因果関係が明確でなくても報告の対象となる。dは誤りで、必要性を認めたら適宜速やかに報告することとされ、報告期限は定められていない。","tags":["副作用報告","医薬関係者"]},{"id":"R8-110","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":110,"stem":"医薬品副作用被害救済制度の給付に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医療手当の給付の請求期限は、医療費の支給の対象となる費用の支払いが行われたときから５年以内である。"},{"label":"b","text":"遺族年金の給付は、請求期限がない。"},{"label":"c","text":"医療費の給付の請求期限は、請求に係る医療が行われた日の属する月の翌月の初日から５年以内である。"},{"label":"d","text":"障害児養育年金の給付は、請求期限がない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"正解は3（dのみ正）。障害児養育年金は請求期限がない（d）。aは誤りで、医療手当の請求期限は医療が行われた日の属する月の翌月の初日から5年以内である。bは誤りで、遺族年金は死亡のときから5年以内という期限がある。cは誤りで、医療費の請求期限は費用の支払いが行われたときから5年以内であり、aとcの内容が入れ替わっている。","tags":["医薬品副作用被害救済制度","請求期限"]},{"id":"R8-111","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":111,"stem":"一般用医薬品の安全対策に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"小柴胡湯は、インターフェロン製剤の併用例による間質性肺炎が報告されたことから、１９９４年１月、インターフェロン製剤との併用を禁忌とする旨の使用上の注意の改訂がなされた。"},{"label":"b","text":"慢性肝炎患者が小柴胡湯を使用して、間質性肺炎を発症し、死亡を含む重篤な転帰に至った例もあったことから、１９９６年３月、厚生省（当時）より関係製薬企業に対して緊急安全性情報の配布が指示された。"},{"label":"c","text":"２００３年８月までに、塩酸フェニルプロパノールアミンが配合された一般用医薬品による脳出血等の副作用症例が複数報告されたことなどから、厚生労働省は関係製薬企業等に対し、プソイドエフェドリン塩酸塩等への速やかな切替えを指示した。"},{"label":"d","text":"一般用かぜ薬全般において、まれに間質性肺炎の重篤な症状が起きることがあり、その初期症状は、かぜの諸症状と区別が難しいため、症状が悪化した場合には服用を中止して医師の診療を受ける旨の注意喚起がなされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"正解は5（すべて正しい）。小柴胡湯はインターフェロン製剤との併用が1994年1月に禁忌とされ（a）、1996年3月に緊急安全性情報の配布が指示された（b）。2003年8月までのフェニルプロパノールアミン配合製品による脳出血等の報告を受け、プソイドエフェドリン塩酸塩等への切替えが指示された（c）。かぜ薬全般で間質性肺炎の注意喚起がなされている（d）。","tags":["安全対策の経緯","小柴胡湯"]},{"id":"R8-112","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":112,"stem":"医薬品の適正使用のための啓発活動に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品の持つ特質及びその使用・取扱い等について正しい知識を広く生活者に浸透させることにより、保健衛生の維持向上に貢献することを目的とし、毎年１０月１７日～１０月２３日の１週間を「薬と健康の週間」として、国、自治体、関係団体等による広報活動やイベント等が実施されている。"},{"label":"b","text":"薬物依存は、一般用医薬品によって生じることはない。"},{"label":"c","text":"医薬品の適正使用の重要性等に関して、小中学生のうちからの啓発が重要である。"},{"label":"d","text":"登録販売者には、適切なセルフメディケーションの普及定着、医薬品の適正使用の推進のため、啓発活動に積極的に参加、協力することが期待されている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"正解は2。「薬と健康の週間」は毎年10月17日～23日で正しい知識の浸透を目的とする（a）。小中学生のうちからの啓発が重要（c）、登録販売者は啓発活動への参加・協力が期待される（d）。bは誤りで、薬物依存は一般用医薬品の濫用によっても生じ得る。","tags":["薬と健康の週間","セルフメディケーション","濫用"]},{"id":"R8-113","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":113,"stem":"アスピリンが配合された一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に記載することとされている対象者について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"緑内障の診断を受けた人"},{"label":"b","text":"出産予定日１２週以内の妊婦"},{"label":"c","text":"本剤又は他のかぜ薬、解熱鎮痛薬を使用（服用）して、喘息を起こしたことがある人"},{"label":"d","text":"１８歳未満の人"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":3,"explanation":"正解は3（b、c）。アスピリンを含む製品は、出産予定日12週以内の妊婦（b）と、本剤や他のかぜ薬・解熱鎮痛薬で喘息を起こしたことがある人（c）は使用しないこととされる。aの緑内障の診断を受けた人は、この成分での「使用しないこと」には該当しない。dは誤りで、記載されるのは15歳未満の小児である。","tags":["アスピリン","使用しないこと"]},{"id":"R8-114","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":114,"stem":"一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に、「服用後、乗物又は機械類の運転操作をしないこと」と記載することとされている内服薬の成分の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ジフェンヒドラミン塩酸塩"},{"label":"b","text":"ロペラミド塩酸塩"},{"label":"c","text":"イブプロフェン"},{"label":"d","text":"ジヒドロコデインリン酸塩"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"正解は5。ジフェンヒドラミン塩酸塩（抗ヒスタミン成分）、ロペラミド塩酸塩、ジヒドロコデインリン酸塩は眠気やめまいのおそれから「服用後、乗物又は機械類の運転操作をしないこと」と記載される。イブプロフェンにはこの記載はない。","tags":["使用上の注意","運転操作"]},{"id":"R8-115","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":115,"stem":"一般用医薬品の胃腸薬の添付文書等において、アルミニウム脳症及びアルミニウム骨症を生じるおそれがあるため、「長期連用しないこと」と記載することとされている医薬品成分の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"アルジオキサ"},{"label":"b","text":"テプレノン"},{"label":"c","text":"合成ヒドロタルサイト"},{"label":"d","text":"スクラルファート"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"正解は2（a、c、d）。アルジオキサ、合成ヒドロタルサイト、スクラルファートはアルミニウムを含み、長期連用でアルミニウム脳症・骨症のおそれがある。テプレノンはアルミニウムを含まず、この注意の対象ではない。","tags":["胃腸薬","アルミニウム"]},{"id":"R8-117","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":117,"stem":"スコポラミン臭化水素酸塩水和物が配合された一般用医薬品の添付文書等において、「相談すること」の項目中に「緑内障の診断を受けた人」と記載されている理由について、（　）の中に入れるべき字句の正しい組合せを選べ。\n\nスコポラミン臭化水素酸塩水和物は、（　a　）作用によって、房水流出路が（　b　）なり、眼圧が（　c　）し、緑内障を悪化させるおそれがあるため、「緑内障の診断を受けた人」は、「相談すること」とされている。","statements":[],"options":[{"n":1,"text":"a 抗コリン / b 狭く / c 上昇"},{"n":2,"text":"a 抗コリン / b 狭く / c 低下"},{"n":3,"text":"a 抗コリン / b 広く / c 上昇"},{"n":4,"text":"a コリン / b 狭く / c 上昇"},{"n":5,"text":"a コリン / b 広く / c 低下"}],"answer":1,"explanation":"正解は1。スコポラミン臭化水素酸塩水和物は抗コリン作用により房水流出路が狭くなり、眼圧が上昇して緑内障を悪化させるおそれがある。したがって「緑内障の診断を受けた人」は相談することとされる。コリン作用や眼圧低下では説明できない。","tags":["抗コリン作用","緑内障"]},{"id":"R7-5","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":5,"stem":"免疫及びアレルギーに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"免疫とは、細菌やウイルスなどが人体に取り込まれたとき、人体を防御するために生じる反応である。"},{"label":"b","text":"アレルギーは、一般的にあらゆる物質によって起こり得るものである。"},{"label":"c","text":"アレルギー症状は、結膜炎症状や鼻炎症状、蕁麻疹や湿疹等の皮膚症状及び血管性浮腫のようなやや広い範囲にわたる腫れ等が生じることが多い。"},{"label":"d","text":"アレルギーには体質的・遺伝的な要素があり、アレルギーを起こしやすい体質の人や、近い親族にアレルギー体質の人がいる場合には、注意が必要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"a〜dはすべて正しく、正解は5。免疫は本来、細菌やウイルスなどが体内に入ったときに人体を守る反応だが、これが過敏に働いて好ましくない症状を起こしたものがアレルギーである。アレルギーは原因物質がほぼ何でもなり得て、結膜炎症状・鼻炎症状・じんましんや湿疹・血管性浮腫のような腫れが出やすい。また体質的・遺伝的な要素があり、本人がアレルギー体質の場合や近親者にアレルギー体質の人がいる場合は注意が必要とされる。","tags":["免疫","アレルギー"]},{"id":"R7-10","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":10,"stem":"小児等への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"「医療用医薬品の添付文書等の記載要領の留意事項」において、幼児とは、おおよその目安として、１歳以上７歳未満をいう。"},{"label":"b","text":"小児は、大人と比べて身体の大きさに対して腸が長いため、服用した医薬品の吸収率が相対的に高い。"},{"label":"c","text":"小児は、大人と比べて血液脳関門が発達しているため、中枢神経系に影響を与える医薬品で副作用を起こしにくい。"},{"label":"d","text":"乳児は状態が急変しやすく、一般用医薬品の使用の適否が見極めにくいため、基本的には医師の診療を受けることが優先される。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"正解は5（a正・b正・c誤・d正）。幼児は「医療用医薬品の添付文書等の記載要領の留意事項」で、おおよその目安として1歳以上7歳未満とされる。小児は体格に比べて腸が長く、飲んだ薬の吸収率が相対的に高い。cは誤りで、小児は血液脳関門が未発達なため、循環血液中の成分が脳へ入りやすく、中枢神経系に作用する薬で副作用が出やすい。乳児は状態が急変しやすく使用の可否も見極めにくいので、基本的には医師の診療を優先する。","tags":["小児","血液脳関門"]},{"id":"R7-15","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":15,"stem":"一般用医薬品で対処可能な症状等の範囲に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品は、医療機関での治療を受けるほどではない体調不良や疾病の初期段階、あるいは日常において、生活者が自らの疾病の治療、予防又は生活の質の改善・向上を図ることを目的として用いられる。"},{"label":"b","text":"一般用医薬品を一定期間若しくは一定回数使用しても症状の改善がみられない場合は、他の一般用医薬品に変更し症状の改善を図るのが適当である。"},{"label":"c","text":"一般用医薬品の販売等に従事する専門家による情報提供は、必ずしも医薬品の販売に結びつけるのでなく、医薬品の使用によらない対処を勧めることが適切な場合があることにも留意する必要がある。"},{"label":"d","text":"症状が重いとき（例えば、高熱や激しい腹痛がある場合等）に、一般用医薬品を使用することは、一般用医薬品の役割にかんがみて、適切な対処といえる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3（a正・b誤・c正・d誤）。一般用医薬品は、医療機関で治療を受けるほどではない体調不良や病気の初期段階、あるいは日常で、自分で治療・予防・生活の質の向上を図るために使われる。bは誤りで、一定期間・一定回数使っても改善しない、または悪化したときは、別の一般用医薬品へ変えるのではなく医療機関の受診が必要である。cのとおり、情報提供は販売に結びつけるとは限らず、受診勧奨や使用によらない対処を勧める場合もある。dも誤りで、高熱や激しい腹痛など症状が重いときに一般用医薬品で対処するのは、その役割から見て適切とはいえない。","tags":["一般用医薬品の役割","受診勧奨"]},{"id":"R7-20","chapter":1,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":20,"stem":"ＨＩＶ訴訟に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"血友病患者が、ヒト免疫不全ウイルス（ＨＩＶ）が混入した原料血漿から製造された血液凝固因子製剤の投与を受けたことにより、ＨＩＶに感染したことに対する損害賠償訴訟である。"},{"label":"b","text":"国及び製薬企業を被告として、大阪地裁、東京地裁で提訴され、現在も和解に向けた協議が進められている。"},{"label":"c","text":"ＨＩＶ感染者に対する恒久対策として、国はエイズ治療・研究開発センター及び拠点病院の整備などの取り組みを推進している。"},{"label":"d","text":"本訴訟を契機に、緊急に必要とされる医薬品を迅速に供給するための「緊急輸入」制度の創設等を内容とする改正薬事法が成立し、施行された。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"正解は2（a正・b誤・c正・d正）。HIV訴訟は、血友病患者がHIV混入の原料血漿から作られた血液凝固因子製剤で感染したことへの損害賠償訴訟である。bは誤りで、1989年に大阪地裁・東京地裁で提訴されたが、1996年3月に両地裁で和解が成立しており、現在も協議中ではない。和解後、国は恒久対策としてエイズ治療・研究開発センターや拠点病院の整備などを進めた。さらに1996年に、感染症報告の義務づけや緊急輸入制度の創設などを内容とする薬事法改正が成立し、翌1997年に施行された。","tags":["薬害","HIV訴訟"]},{"id":"R7-64","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":64,"stem":"血液に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"血液の粘稠性は、主として血漿の水分量や赤血球の量で決まり、血中脂質量はほとんど影響を与えない。"},{"label":"b","text":"赤血球は中央部がくぼんだ円盤状の細胞で、血液全体の約４０％を占める。"},{"label":"c","text":"アルブミンは鉄分と結合したタンパク質で、酸素量の多いところで酸素分子と結合し、酸素が少なく二酸化炭素が多いところで酸素分子を放出する性質がある。"},{"label":"d","text":"健常人の血液において、白血球のなかでリンパ球が最も数が多い。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"正解は3（a正・b正・c誤・d誤）。血液の粘稠性は主に血漿の水分量と赤血球の量で決まり、血中脂質量はほとんど影響しない。赤血球は中央がくぼんだ円盤状で、血液全体の約40%を占める。cは誤りで、鉄分と結合して酸素の運搬を担うタンパク質はヘモグロビンであり、アルブミンは血液の浸透圧の保持や成分の運搬にかかわる血漿タンパク質である。dも誤りで、白血球で最も多いのは好中球（約60%）で、リンパ球は約3分の1である。","tags":["血液","赤血球","白血球"]},{"id":"R7-68","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":68,"stem":"鼻及び耳に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"鼻腔の粘膜に炎症を起こして腫れた状態を鼻炎といい、鼻汁過多や鼻閉（鼻づまり）などの症状を生じる。"},{"label":"b","text":"副鼻腔に入った埃等の粒子は、粘液に捉えられて線毛の働きによって鼻腔内へ排出される。"},{"label":"c","text":"耳垢（耳あか）は、内耳にある耳垢腺（汗腺の一種）や皮脂腺からの分泌物に、埃や内耳上皮の老廃物などが混じったものである。"},{"label":"d","text":"乗物酔いは、鼓室で感知する平衡感覚が混乱して生じる身体の変調である。"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":1,"explanation":"正解は1（a、b）。aのとおり、鼻腔粘膜の炎症による腫れを鼻炎といい、鼻汁過多や鼻づまりが起こる。bのとおり、副鼻腔に入った埃などは粘液に捉えられ、線毛の働きで鼻腔へ排出される。cは誤りで、耳垢腺や皮脂腺があるのは内耳ではなく外耳道であり、耳垢は外耳道上皮の老廃物などが混ざったものである。dも誤りで、乗物酔いは内耳の前庭で感知する平衡感覚の混乱で生じる（鼓室は中耳）。","tags":["鼻","耳","内耳"]},{"id":"R7-72","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":72,"stem":"薬が働く仕組みに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"全身作用を目的とする医薬品では、その有効成分が吸収されて、循環血液中に移行することが不可欠である。"},{"label":"b","text":"有効成分が吸収されるにつれて、その血中濃度は上昇し、ある最小有効濃度（閾値）を超えたときに生体の反応としての薬効が現れる。"},{"label":"c","text":"有効成分の血中濃度は、ある時点でピーク（最高血中濃度）に達し、その後は低下していくが、これは代謝・排泄の速度が吸収・分布の速度を上回るためである。"},{"label":"d","text":"舌下錠は、有効成分を舌下で溶解させる剤形で、薬効を期待する部位は口の中や喉である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"正解は2（a正・b正・c正・d誤）。全身作用を目的とする医薬品は、有効成分が吸収されて循環血液中に移行することが不可欠である。吸収に伴い血中濃度が上がり、最小有効濃度（閾値）を超えると薬効が現れる。その後、代謝・排泄の速度が吸収・分布の速度を上回るため、ピークを過ぎて血中濃度は下がる。dは誤りで、舌下錠は有効成分を舌下で溶かして口腔粘膜から吸収させ全身作用を得るもので、薬効を期待する部位が口の中や喉なのはトローチ・ドロップなどである。","tags":["薬物動態","剤形"]},{"id":"R7-76","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":76,"stem":"医薬品の副作用として現れる皮膚粘膜眼症候群（スティーブンス・ジョンソン症候群）及び中毒性表皮壊死融解症に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"どちらも典型的な症状として、３８℃以上の高熱、目の充血、口唇のただれ、喉の痛み、広範囲の皮膚の発赤等が現れる。"},{"label":"b","text":"皮膚粘膜眼症候群の症例の多くが、中毒性表皮壊死融解症の進展型とみられる。"},{"label":"c","text":"どちらも原因医薬品の使用開始後、２週間以内で発症することは少なく、１か月以上経過してから発症することが多い。"},{"label":"d","text":"どちらも発症機序の詳細は不明である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":5,"explanation":"正解は5（a正・b誤・c誤・d正）。皮膚粘膜眼症候群（SJS）と中毒性表皮壊死融解症（TEN）は、38℃以上の高熱、目の充血、口唇のただれ、喉の痛み、広範囲の皮膚の発赤などが注意すべき症状である。bは誤りで、関係が逆であり、TENの症例の多くがSJSの進展型とみられる。cも誤りで、いずれも原因薬の使用開始後2週間以内の発症が多く、1か月以上経ってから起こることもあるにとどまる。dのとおり、どちらも発症機序の詳細は不明で、予測は困難とされる。","tags":["重篤な副作用","SJS","TEN"]},{"id":"R7-80","chapter":2,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":80,"stem":"皮膚に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"アレルギー性皮膚炎は、医薬品が接触した皮膚の部位にのみ生じる。"},{"label":"b","text":"光線過敏症は、医薬品が触れた部分だけでなく、全身へ広がって重篤化する場合がある。"},{"label":"c","text":"医薬品を使用した後に発疹・発赤等が現れた場合は、薬疹の可能性を考慮し、原因と考えられる医薬品の使用を直ちに中止する。"},{"label":"d","text":"接触性皮膚炎は、外用薬の副作用で生じることはない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"正解は2（a誤・b正・c正・d誤）。aは誤りで、接触皮膚炎は薬が触れた部位に限られるが、アレルギー性皮膚炎の発症部位は接触部位に限定されない。bのとおり、光線過敏症は薬が触れた部分にとどまらず全身へ広がって重篤化することがある。cのとおり、薬の使用後に発疹・発赤が出たら薬疹の可能性を考え、原因と考えられる薬の使用を直ちに中止する。dは誤りで、接触皮膚炎はいわゆる「かぶれ」であり、外用薬の副作用としても起こる。","tags":["皮膚の副作用","薬疹"]},{"id":"R8-4","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":4,"stem":"健康食品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"健康増進や維持の助けになることが期待されるいわゆる「健康食品」は、あくまで食品であり、医薬品とは法律上区別される。"},{"label":"b","text":"「特定保健用食品」は、身体の生理機能などに影響を与える保健機能成分を含むもので、個別に（一部は規格基準に従って）特定の保健機能を示す効果や安全性などに関する国の審査を受け、許可されたものである。"},{"label":"c","text":"「機能性表示食品」は、事業者の責任で科学的根拠をもとに機能性関与成分が有する健康維持及び増進に役立つ機能を商品のパッケージに表示するものとして、国の個別の許可を受けたものである。"},{"label":"d","text":"一般用医薬品の販売時には健康食品の摂取の有無について確認することは重要で、購入者等の健康に関する意識を尊重しつつも、必要があればそれらの摂取についての指導も行うべきである。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"正解は5（a正・b正・c誤・d正）。いわゆる健康食品は食品であり、医薬品とは法律上区別される。特定保健用食品は、身体の生理機能に影響を与える保健機能成分を含み、特定の保健機能を示す効果や安全性について国の審査を受けて許可されたものである。cは誤りで、機能性表示食品は事業者の責任で科学的根拠をもとに機能を表示し、国へ届け出た商品であって、国の個別の許可を受けたものではない。dのとおり、医薬品の販売時には健康食品の摂取の有無を確認することが重要で、必要なら摂取についての指導も行う。","tags":["健康食品","保健機能食品"]},{"id":"R8-8","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":8,"stem":"一般用医薬品の使用等に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"本来の目的以外の意図で、定められた用量を超えて服用しても短期間であれば問題ない。"},{"label":"b","text":"みだりに他の医薬品や酒類等と一緒に摂取するといった乱用がなされると、過量摂取による急性中毒等を生じる危険性が高くなる。"},{"label":"c","text":"一般用医薬品にも、習慣性・依存性がある成分を含むものがある。"},{"label":"d","text":"医薬品の乱用によって薬物依存が形成されても、使用を中止すれば、すぐに離脱できる。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":3,"explanation":"正解は3（b、c）。bのとおり、定められた用量を超える服用や、他の薬・酒類と一緒に摂取する乱用は、過量摂取による急性中毒の危険を高める。cのとおり、一般用医薬品にも習慣性・依存性のある成分を含むものがある。aは誤りで、本来の目的以外の意図で用量を超えて服用することは、短期間であっても乱用にあたり問題がある。dも誤りで、乱用で薬物依存が形成されると、そこから離脱することは容易ではない。","tags":["乱用","依存性"]},{"id":"R8-12","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":12,"stem":"高齢者への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"「医療用医薬品の添付文書等の記載要領の留意事項」において、おおよその目安として７５歳以上を「高齢者」としている。"},{"label":"b","text":"生理機能の衰えの度合いは個人差が小さいため、年齢から副作用を生じるリスクがどの程度増大しているか判断することができる。"},{"label":"c","text":"医薬品の副作用で口渇を生じることがあり、その場合、誤嚥を誘発しやすくなるので注意が必要である。"},{"label":"d","text":"医薬品の取り違えや飲み忘れを起こしやすいなどの傾向があり、家族等の理解や協力も含めた配慮が重要となることがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":3,"explanation":"正解は3（a誤・b誤・c正・d正）。aは誤りで、「医療用医薬品の添付文書等の記載要領の留意事項」が高齢者としているのは、おおよその目安として65歳以上である。bも誤りで、高齢者でも基礎体力や生理機能の衰えの度合いは個人差が大きく、年齢だけでは副作用のリスクの増大度を判断しにくい。cのとおり、副作用で口渇が生じると誤嚥を誘発しやすくなる。dのとおり、取り違えや飲み忘れを起こしやすい傾向があり、家族や介護者の理解・協力を含めた配慮が必要な場合がある。","tags":["高齢者","誤嚥"]},{"id":"R8-16","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":16,"stem":"一般用医薬品の販売時における、医薬品の販売に従事する専門家のコミュニケーションに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"購入者等が、自分自身や家族の健康に対する責任感を持ち、適切な医薬品を選択して、適正に使用するよう、働きかけていくことが重要である。"},{"label":"b","text":"購入者等が適切な医薬品を選択し、実際にその医薬品を使用する人が必要な注意を払って適正に使用していくためには、可能な限り購入者等の個々の状況の把握に努めることが重要となる。"},{"label":"c","text":"情報提供を受ける購入者等が医薬品を使用する本人で、かつ、現に症状等がある場合には、言葉によるコミュニケーションから得られる情報のみで、その人の状況が把握できるので、他の情報は不要である。"},{"label":"d","text":"購入者等が医薬品を使用する状況は随時変化する可能性があるため、販売数量は一時期に使用する必要量とする等、販売時のコミュニケーションの機会を継続的に確保するよう配慮することが重要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"正解は1（a正・b正・c誤・d正）。専門家は、購入者等が自分や家族の健康に責任感を持ち、適切な薬を選んで適正に使うよう働きかけることが重要である。適切な選択と使用のため、購入者等の個々の状況を可能な限り把握するよう努める。cは誤りで、使用する本人に現に症状がある場合でも、言葉から得られる情報だけでなく、その人の状態や様子全般から得られる情報も重要な手がかりになる。dのとおり、使用状況は変わりうるので、販売数量を一時期の必要量にとどめるなどして、継続的にコミュニケーションの機会を確保する。","tags":["販売時のコミュニケーション"]},{"id":"R8-20","chapter":1,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":20,"stem":"クロイツフェルト・ヤコブ病（ＣＪＤ）及びＣＪＤ訴訟に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ＣＪＤは、真菌の一種であるプリオンが原因とされる感染症である。"},{"label":"b","text":"ＣＪＤは、認知症に類似した症状が現れ、死に至る重篤な神経難病である。"},{"label":"c","text":"ＣＪＤ訴訟では、国、輸入販売業者及び製造業者が被告として提訴された。"},{"label":"d","text":"ＣＪＤ訴訟の和解後、国は生物由来製品による感染等被害救済制度を創設した。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3（a誤・b正・c正・d正）。aは誤りで、CJD（クロイツフェルト・ヤコブ病）の原因とされるプリオンは、細菌でもウイルスでもないタンパク質の一種であり、真菌ではない。bのとおり、CJDは認知症に似た症状が出て死に至る重篤な神経難病である。cのとおり、CJD訴訟（ヒト乾燥硬膜が原因）は国、輸入販売業者、製造業者を被告として提起された。dのとおり、和解後の2002年の薬事法改正などで、生物由来製品による感染等被害救済制度が創設された。","tags":["薬害","CJD訴訟"]},{"id":"R8-64","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":64,"stem":"血液に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"赤血球は、銅と結合したタンパク質であるヘモグロビンを含んでいる。"},{"label":"b","text":"白血球の中でリンパ球は最も数が多く、白血球の約６０％を占めている。"},{"label":"c","text":"血小板は、損傷した血管からの血液の流出を抑える仕組みにおいて重要な役割を担っている。"},{"label":"d","text":"血漿に含まれるアルブミンには、血液の浸透圧を保持する働きがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"正解は5（a誤・b誤・c正・d正）。aは誤りで、ヘモグロビンは銅ではなく鉄分と結合したタンパク質である。bも誤りで、白血球で最も多いのは好中球（約60%）であり、リンパ球は白血球の約3分の1にあたる。cのとおり、損傷した血管からの血液の流出を抑える仕組みでは、血小板が重要な役割を担う。dのとおり、血漿中のアルブミンは血液の浸透圧を保持し、血漿成分が血管外へ漏れ出るのを防ぐ。","tags":["血液","血小板","アルブミン"]},{"id":"R8-68","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":68,"stem":"鼻及び耳に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"鼻中隔の前部は、毛細血管が少ないことに加えて粘膜が厚いため、傷つきにくく鼻出血を起こしにくい。"},{"label":"b","text":"鼻腔上部の粘膜にある特殊な神経細胞（嗅細胞）を、においの元となる物質の分子（におい分子）が刺激すると、その刺激が脳の嗅覚中枢へ伝わる。"},{"label":"c","text":"小さな子供では、耳管が太く短くて、走行が水平に近いため、鼻腔からウイルスや細菌が侵入し、感染しやすい。"},{"label":"d","text":"乗物酔いは、前庭で感知する平衡感覚が混乱して生じる身体の変調である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"正解は4（a誤・b正・c正・d正）。aは誤りで、鼻中隔の前部は毛細血管が豊富なうえ粘膜が薄いため、傷つきやすく鼻出血を起こしやすい。bのとおり、鼻腔上部の嗅細胞をにおい分子が刺激すると、その刺激が脳の嗅覚中枢へ伝わる。cのとおり、小さな子供は耳管が太く短く水平に近いので、鼻腔から細菌やウイルスが入って中耳が感染しやすい。dのとおり、乗物酔いは内耳の前庭で感知する平衡感覚が混乱して生じる身体の変調である。","tags":["鼻","耳","鼻出血","乗物酔い"]},{"id":"R8-72","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":72,"stem":"薬の吸収に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"内服薬の有効成分によっては、消化管の粘膜に障害を起こすことがあるため、食事の時間と服用時期との関係が、各医薬品の用法に定められている。"},{"label":"b","text":"一般に、内服薬の有効成分の小腸からの吸収は、濃度の高い方から低い方へ受動的に拡散していく現象である。"},{"label":"c","text":"皮膚に適用する医薬品（塗り薬、貼り薬等）は、皮膚表面から循環血液中に移行する量が少ないため、適用部位以外にアレルギー性の副作用が現れることはない。"},{"label":"d","text":"坐剤は、有効成分が容易に循環血液中に入るため、内服の場合よりも全身作用が速やかに現れる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"正解は5（a正・b正・c誤・d正）。aのとおり、有効成分によっては消化管粘膜を傷めるため、食事の時間と服用時期の関係が各薬の用法に定められている。bのとおり、小腸などからの吸収は濃度の高い方から低い方へ受動的に拡散する現象である。cは誤りで、皮膚に塗る・貼る薬は皮膚から血中へ移る量が比較的少ないとはいえ、アレルギー性の副作用は適用部位以外にも現れることがある。dのとおり、坐剤は直腸粘膜から有効成分が容易に血中へ入るため、内服より全身作用が速やかに現れる。","tags":["薬の吸収","坐剤","経皮吸収"]},{"id":"R8-76","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":76,"stem":"医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般に、重篤な副作用は発生頻度が高く、医薬品の販売等に従事する専門家にとっても遭遇する機会が多いので自然と知識が身につく。"},{"label":"b","text":"「重篤副作用疾患別対応マニュアル（厚生労働省作成）」の対象に、一般用医薬品に起因する副作用は含まれていない。"},{"label":"c","text":"医薬品の販売等に従事する専門家は、購入者等に対して、一般用医薬品による副作用と疑われる症状について医療機関の受診を勧奨する際に、当該一般用医薬品の添付文書等を見せて説明するなどの対応をすることが望ましい。"},{"label":"d","text":"一般用医薬品による副作用は、医薬品服用時のアルコール飲用等が原因で起こる場合がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"正解は2（a誤・b誤・c正・d正）。aは誤りで、重篤な副作用は発生頻度が低く、専門家でも遭遇する機会は極めてまれなため、意識して知識を身に付ける必要がある。bも誤りで、厚生労働省の「重篤副作用疾患別対応マニュアル」の対象には、一般用医薬品によって起こる副作用も含まれている。cのとおり、副作用が疑われる症状で受診を勧めるときは、その薬の添付文書等を見せて説明するなどの対応が望ましい。dのとおり、一般用医薬品の副作用は、併用や服用時の飲酒などが原因で起こる場合もある。","tags":["副作用","重篤副作用疾患別対応マニュアル"]},{"id":"R8-80","chapter":2,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":80,"stem":"泌尿器系に現れる医薬品の副作用に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"副交感神経系の機能を亢進する作用がある成分が配合された医薬品を使用すると、膀胱の排尿筋の収縮が抑制され、尿が出にくい、尿が少ししか出ない、残尿感がある等の症状を生じることがある。"},{"label":"b","text":"医薬品による排尿困難が進行すると、尿閉や下腹部が膨満して激しい痛みを感じるようになるが、これらの症状は、前立腺肥大の基礎疾患がある男性にのみ現れる。"},{"label":"c","text":"排尿困難や尿閉の症状が現れたときには、原因となる医薬品の使用を中止することにより症状は速やかに改善することが多い。"},{"label":"d","text":"尿勢の低下等の兆候に留意することは、排尿困難の初期段階での適切な対応につながる。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"正解は5（c、d）。aは誤りで、排尿困難は副交感神経系の機能を「抑制」する作用のある成分（抗コリン成分など）で、膀胱の排尿筋の収縮が抑えられて起こる。「亢進」ではない。bも誤りで、尿閉や下腹部の激しい痛みは前立腺肥大などの基礎疾患がない人でも現れ、男性に限らず女性でも報告されている。cのとおり、原因の薬を中止すれば多くは速やかに改善する。dのとおり、尿勢の低下などの兆候に気を付けることが、初期段階での適切な対応につながる。","tags":["泌尿器系の副作用","排尿困難"]},{"id":"R7-22","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":22,"stem":"かぜの症状緩和に用いられる漢方処方製剤に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"葛根湯は、体力虚弱で、神経過敏で気分がすぐれず胃腸の弱いもののかぜの初期、血の道症に適すとされる。"},{"label":"b","text":"柴胡桂枝湯は、体力中等度又はやや虚弱で、多くは腹痛を伴い、ときに微熱・寒気・頭痛・吐きけなどのあるものの胃腸炎、かぜの中期から後期の症状に適すとされる。"},{"label":"c","text":"小青竜湯は、体力中等度又はやや虚弱で、うすい水様の痰を伴う咳や鼻水が出るものの気管支炎、気管支喘息、鼻炎、アレルギー性鼻炎、むくみ、感冒、花粉症に適すとされる。"},{"label":"d","text":"半夏厚朴湯は、体力中等度で、ときに脇腹からみぞおちあたりにかけて苦しく、食欲不振や口の苦味があり、舌に白苔がつくものの食欲不振、吐きけ、胃炎、胃痛、胃腸虚弱、疲労感、かぜの後期の諸症状に適すとされる。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":3,"explanation":"正解は3（b、c）。柴胡桂枝湯は腹痛を伴う胃腸炎やかぜの中期から後期に、小青竜湯は薄い水様の痰を伴う咳や鼻水に用いる、という記述はどちらも手引きの内容どおりである。aは、神経過敏で気分がすぐれず胃腸の弱い人のかぜの初期・血の道症という香蘇散の説明であり、葛根湯の説明としては誤り。dは、脇腹からみぞおちの苦しさ、口の苦味、舌の白苔といった小柴胡湯の説明であり、半夏厚朴湯ではない。処方名と適応の組合せを取り違えさせる問題である。","tags":["漢方処方製剤","かぜ薬"]},{"id":"R7-25","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":25,"stem":"かぜの症状緩和に用いられる漢方処方製剤のうち、マオウを含むものの組合せを選べ。","statements":[{"label":"a","text":"葛根湯"},{"label":"b","text":"小柴胡湯"},{"label":"c","text":"小青竜湯"},{"label":"d","text":"麦門冬湯"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":2,"explanation":"正解は2（a、c）。かぜに用いられる漢方処方製剤のうち、構成生薬にマオウを含むのは麻黄湯のほか葛根湯と小青竜湯である。小柴胡湯と麦門冬湯はマオウを含まない（ただしカンゾウは含む）。マオウは交感神経を刺激する成分で、心臓病・高血圧・甲状腺機能亢進症・排尿困難などの人では注意が必要とされるため、含有の有無は押さえておきたい。","tags":["マオウ","漢方処方製剤"]},{"id":"R7-27","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":27,"stem":"一般用医薬品の催眠鎮静薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"抗ヒスタミン成分を主薬とする催眠鎮静薬は、慢性的に不眠症状がある人や、医療機関において不眠症の診断を受けている人に使用される。"},{"label":"b","text":"妊娠中に生じる睡眠障害は、睡眠改善薬の適用対象である。"},{"label":"c","text":"アリルイソプロピルアセチル尿素は、脳の興奮を抑え、痛覚を鈍くする作用がある。"},{"label":"d","text":"小児及び若年者では、抗ヒスタミン成分により眠気とは反対の神経過敏や中枢興奮などが現れることがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"正解は5（a誤・b誤・c正・d正）。抗ヒスタミン成分を主薬とする睡眠改善薬は一時的な睡眠障害（寝つきが悪い、眠りが浅い）向けで、慢性的な不眠や医療機関で不眠症と診断された人は対象外なのでaは誤り。妊娠中の睡眠障害はホルモンバランスや体型変化が原因で睡眠改善薬の適用対象ではないため、bも誤り。アリルイソプロピルアセチル尿素は脳の興奮を抑え痛覚を鈍くする作用があり、小児や若年者では抗ヒスタミン成分で眠気と反対の神経過敏や中枢興奮が起こることがある、というc・dは正しい。","tags":["催眠鎮静薬","睡眠改善薬","抗ヒスタミン成分"]},{"id":"R7-28","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":28,"stem":"次の漢方処方製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"酸棗仁湯は、体力中等度以下で、心身が疲れ、精神不安、不眠などがあるものの不眠症、神経症に適すとされる。"},{"label":"b","text":"加味帰脾湯は、体力中等度をめやすとして、神経がたかぶり、怒りやすい、イライラなどがあるものの神経症、不眠症、小児夜なき、小児疳症、歯ぎしり、更年期障害、血の道症に適すとされる。"},{"label":"c","text":"柴胡加竜骨牡蛎湯は、体力中等度以上で、精神不安があって、動悸、不眠、便秘などを伴う高血圧の随伴症状、神経症、更年期神経症、小児夜なき、便秘に適すとされる。"},{"label":"d","text":"小建中湯は、体力虚弱で疲労しやすく腹痛があり、血色がすぐれず、ときに動悸、手足のほてり、冷え、ねあせ、鼻血、頻尿及び多尿などを伴うものの小児虚弱体質、疲労倦怠、慢性胃腸炎、腹痛、神経質、小児夜尿症、夜なきに適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":3,"explanation":"正解は3（a正・b誤・c正・d正）。酸棗仁湯、柴胡加竜骨牡蛎湯、小建中湯の説明は手引きの記載と一致している。bは、神経がたかぶり怒りやすい、小児夜なき、歯ぎしりなどに用いる抑肝散の説明であり、加味帰脾湯は、心身が疲れ血色が悪く、ときに熱感を伴う人の貧血・不眠症・精神不安・神経症に用いるものなので誤り。","tags":["漢方処方製剤","神経系"]},{"id":"R7-32","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":32,"stem":"胃腸に作用する薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ウルソデオキシコール酸は、肝臓病の診断を受けた人では、かえって症状を悪化させるおそれがある。"},{"label":"b","text":"テプレノンは、血栓のある人、血栓を起こすおそれのある人では、生じた血栓が分解されにくくなることが考えられる。"},{"label":"c","text":"スクラルファートは、透析を受けている人では、使用を避ける必要がある。"},{"label":"d","text":"ピレンゼピン塩酸塩は、排尿困難、動悸、目のかすみの副作用を生じることがある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"正解は3（a正・b誤・c正・d正）。ウルソデオキシコール酸は肝臓の働きを高める作用があるとされるが、肝臓病の診断を受けた人ではかえって症状を悪化させるおそれがある。スクラルファートはアルミニウムを含み、透析療法を受けている人では使用を避ける。ピレンゼピン塩酸塩は抗コリン作用による排尿困難・動悸・目のかすみが起こりうる。bの「生じた血栓が分解されにくくなる」注意はセトラキサート塩酸塩（体内でトラネキサム酸に代謝される）に関するもので、テプレノンの注意事項ではないため誤り。","tags":["胃腸薬","配合成分","使用上の注意"]},{"id":"R7-34","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":34,"stem":"瀉下成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"センノシドは、腸管内で水分を吸収して腸内容物に浸透し、糞便のかさを増やすとともに糞便を柔らかくする。"},{"label":"b","text":"ピコスルファートナトリウムは、大腸に生息する腸内細菌によって分解され、大腸への刺激作用を示すようになる。"},{"label":"c","text":"水酸化マグネシウムは、腸内容物の浸透圧を高めることで糞便中の水分量を増し、また大腸を刺激して排便を促す。"},{"label":"d","text":"ビサコジルは、主成分である麦芽糖が腸内細菌によって分解して生じるガスによって便通を促す。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"正解は1（a誤・b正・c正・d誤）。ピコスルファートナトリウムは、大腸の腸内細菌に分解されて大腸への刺激作用を示すようになる。水酸化マグネシウムなどのマグネシウム塩は、腸内容物の浸透圧を高めて糞便中の水分を増やし、大腸も刺激する。aは水分を吸収してかさを増やし便を柔らかくする膨潤性瀉下成分の説明で、大腸刺激性のセンノシドには当てはまらない。dは麦芽糖が発酵してガスを生じるマルツエキスの説明で、ビサコジルは大腸粘膜を刺激する成分なので誤り。","tags":["瀉下薬","大腸刺激性瀉下成分"]},{"id":"R7-36","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":36,"stem":"胃腸鎮痛鎮痙薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ブチルスコポラミン臭化物は、排尿困難の症状がある人、心臓病の診断を受けた人では症状の悪化を招くおそれがある。"},{"label":"b","text":"ロートエキスは、消化管の粘膜及び平滑筋に対する麻酔作用による鎮痛鎮痙効果を期待して配合されている。"},{"label":"c","text":"オキセサゼインは、妊婦又は妊娠していると思われる女性や１５歳未満の小児では使用を避ける。"},{"label":"d","text":"医療機関を受診するなどの対応が必要な痛みについては、医師の診療を受けるまでの当座の対処として一般用医薬品の胃腸鎮痛鎮痙薬を使用することが望ましい。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":2,"explanation":"正解は2（a正・b誤・c正・d誤）。ブチルスコポラミン臭化物は抗コリン成分で、排尿困難や心臓病・緑内障のある人では症状の悪化を招くおそれがある。オキセサゼインは妊婦または妊娠していると思われる女性と15歳未満の小児では使用を避ける。bの麻酔作用による鎮痛鎮痙は局所麻酔成分（アミノ安息香酸エチル、オキセサゼイン）の説明で、ロートエキスは抗コリン作用をもつ生薬成分なので誤り。dは、医療機関の受診が必要な痛みに当座しのぎで使うと痛みの部位が不明確になり原因の特定が難しくなるため、望ましくない。","tags":["胃腸鎮痛鎮痙薬","抗コリン成分"]},{"id":"R7-37","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":37,"stem":"胃腸に作用する薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"毎日の排便が滞るような便秘には、大腸刺激性瀉下成分が配合された瀉下薬の常用が望ましい。"},{"label":"b","text":"制酸成分を主体とする胃腸薬は、酸度の高い食品と一緒に使用すると胃酸に対する中和作用が低下することが考えられるため、炭酸飲料等での服用は適当でない。"},{"label":"c","text":"胃腸鎮痛鎮痙薬に配合されている局所麻酔成分は、痛みが感じにくくなることで重大な消化器疾患や状態の悪化等を見過ごすおそれがあり、長期間にわたって漫然と使用することは避けることとされている。"},{"label":"d","text":"腸内殺菌成分の入った止瀉薬は、下痢の予防にも有効である。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"正解は1（a誤・b正・c正・d誤）。制酸成分を主体とする胃腸薬は酸度の高い食品と一緒だと中和作用が下がるため炭酸飲料での服用は不適当である。局所麻酔成分は痛みを感じにくくして重大な疾患の見過ごしにつながるおそれがあり、長期間の漫然とした使用を避ける。aは、瀉下薬を繰り返し使うと腸管の感受性が低下し効果が弱くなるため常用を避けるとされており誤り。dも、腸内殺菌成分入りの止瀉薬を予防目的や症状が治まった後に飲むと腸内細菌のバランスを崩すことがあり、下痢の症状があるときだけの使用とされるため誤り。","tags":["胃腸薬","瀉下薬","止瀉薬"]},{"id":"R7-39","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":39,"stem":"貧血及び貧血用薬（鉄製剤）の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"貧血のうち鉄製剤で改善できるのは、鉄欠乏性貧血のみである。"},{"label":"b","text":"銅は、糖質・脂質・タンパク質の代謝をする際に働く酵素の構成物質であり、エネルギー合成を促進する目的で、硫酸銅が配合されている場合がある。"},{"label":"c","text":"ビタミン成分では、ヘモグロビン産生に必要なビタミンＢ６や、正常な赤血球の形成に働くビタミンＢ１２や葉酸などが配合されている場合がある。"},{"label":"d","text":"鉄製剤を服用すると便が黒くなることがあるが、服用前から便が黒い場合は、貧血の原因として消化管内で出血している場合もあるため、服用前の便の状況との対比が必要である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"正解は2（a正・b誤・c正・d正）。貧血のうち鉄製剤で改善できるのは鉄欠乏性貧血のみである。ヘモグロビン産生に必要なビタミンB6、赤血球の形成に働くビタミンB12や葉酸が配合されることがあるというcも正しい。鉄製剤で便が黒くなること自体は異常ではないが、服用前から黒い場合は消化管出血の可能性もあるため、服用前の状態との比較が必要である。bの「糖質・脂質・タンパク質の代謝酵素の構成物質でエネルギー合成を促進する」のはマンガン（硫酸マンガン）の説明で、銅は鉄の代謝や輸送に働きヘモグロビン産生を助ける金属なので誤り。","tags":["貧血用薬","鉄製剤"]},{"id":"R7-41","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":41,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを選べ。\n\n　体力中等度以下で、疲れやすくて、四肢が冷えやすく、尿量減少又は多尿でときに口渇があるものの下肢痛、腰痛、しびれ、高齢者のかすみ目、痒み、排尿困難、残尿感、夜間尿、頻尿、むくみ、高血圧に伴う随伴症状の改善（肩こり、頭重、耳鳴り）、軽い尿漏れに適すとされる。","statements":[],"options":[{"n":1,"text":"芎帰膠艾湯"},{"n":2,"text":"乙字湯"},{"n":3,"text":"竜胆瀉肝湯"},{"n":4,"text":"八味地黄丸"},{"n":5,"text":"苓桂朮甘湯"}],"answer":4,"explanation":"正解は4（八味地黄丸）。疲れやすく四肢が冷えやすい、尿量減少または多尿、下肢痛・腰痛・しびれ、高齢者のかすみ目、排尿困難・残尿感・夜間尿・頻尿、軽い尿漏れといった記述は、手引きの八味地黄丸の説明と一致する。これは泌尿器・老年期の症状に用いる処方に特徴的な内容で、他の選択肢（止血・痔・泌尿生殖器の炎症・めまいやむくみなど）とは適応の中心が異なる。","tags":["漢方処方製剤","八味地黄丸"]},{"id":"R7-43","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":43,"stem":"アレルギー及び蕁麻疹に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"体内に侵入したアレルゲンが直接、肥満細胞を刺激することによって、細胞間の刺激の伝達を担うヒスタミンやプロスタグランジン等が遊離される。"},{"label":"b","text":"肥満細胞から遊離されたヒスタミンは、周囲の器管や組織表面の受容体と反応することで血管拡張や血管透過性亢進等の作用を示す。"},{"label":"c","text":"皮膚症状が治まると喘息が現れるというように、種々のアレルギー症状が連鎖的に現れることがある。"},{"label":"d","text":"サバなどの生魚は、傷むとヒスタミンやヒスタミン様物質が生成することがあり、そうした食品を摂取することで蕁麻疹を生じることがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"正解は4（a誤・b正・c正・d正）。アレルゲンが皮膚や粘膜から体内に入ると、それを特異的に認識した抗体によって肥満細胞が刺激され、ヒスタミンやプロスタグランジンなどが遊離する。つまりアレルゲンが直接肥満細胞を刺激するわけではないので、aは誤り。遊離したヒスタミンが受容体と反応して血管拡張・血管透過性亢進などを起こすこと、皮膚症状が治まると喘息が現れるなどアレルギー症状が連鎖的に現れることがあること、傷んだサバなどでヒスタミン様物質により蕁麻疹が生じることがあること、はいずれも正しい。","tags":["アレルギー","蕁麻疹","ヒスタミン"]},{"id":"R7-45","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":45,"stem":"アレルギー症状の緩和を目的として用いる漢方処方製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"十味敗毒湯、消風散、当帰飲子は、鼻の症状を主とする人に適すとされる。"},{"label":"b","text":"茵蔯蒿湯は、体力中等度以下で、冷え症で、皮膚が乾燥するものの湿疹・皮膚炎（分泌物の少ないもの）、痒みに適すとされる。"},{"label":"c","text":"葛根湯加川芎辛夷は、比較的体力があるものの鼻づまり、蓄膿症（副鼻腔炎）、慢性鼻炎に適すとされる。"},{"label":"d","text":"辛夷清肺湯は、構成生薬としてカンゾウを含まない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"正解は2（a誤・b誤・c正・d正）。十味敗毒湯・消風散・当帰飲子は、鼻ではなく皮膚の症状を主とする人に適するとされる処方なのでaは誤り。bの「冷え症で皮膚が乾燥する、分泌物の少ない湿疹・皮膚炎、痒み」は当帰飲子の説明で、茵蔯蒿湯は口渇があり尿量が少なく便秘する人の蕁麻疹・口内炎・湿疹に用いるものである。葛根湯加川芎辛夷は比較的体力があるものの鼻づまり・蓄膿症・慢性鼻炎に適するとされ、辛夷清肺湯は茵蔯蒿湯とともにカンゾウを含まない処方である。","tags":["漢方処方製剤","アレルギー用薬","カンゾウ"]},{"id":"R7-47","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":47,"stem":"眼科用薬及びその配合成分に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"コンタクトレンズをしたままの点眼は、ソフトコンタクトレンズ、ハードコンタクトレンズに関わらず、すべての点眼薬で行うことはできない。"},{"label":"b","text":"点眼の際には、薬液に雑菌を混入させないために、容器の先端が眼瞼（まぶた）や睫毛（まつげ）に触れないようにする。"},{"label":"c","text":"点眼薬の１滴の薬液量は、結膜嚢の容積より少ないとされている。"},{"label":"d","text":"テトラヒドロゾリン塩酸塩が配合されている点眼薬は、緑内障を悪化させることがある。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":4,"explanation":"正解は4（b、d）。点眼の際は容器の先端がまぶたやまつげに触れないようにして雑菌の混入を防ぐ。テトラヒドロゾリンなどのアドレナリン作動成分は眼圧の上昇を招き、緑内障を悪化させるおそれがある。aは、コンタクトレンズ装着中の点眼は添付文書に使用可能と書かれていない限り避けるという扱いで、使い切りタイプなど装着したまま使える製品もあるため、「すべての点眼薬で行えない」は誤り。cは、1滴が約50μLなのに結膜嚢の容積は約30μLとされ、1滴のほうが多いので誤りである。","tags":["眼科用薬","点眼薬","アドレナリン作動成分"]},{"id":"R7-49","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":49,"stem":"きず口等の殺菌消毒成分に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"アクリノールは、真菌、結核菌、ウイルスに対して殺菌消毒作用を示す。"},{"label":"b","text":"オキシドールの作用は、過酸化水素の分解に伴って発生する活性酸素による酸化、及び発生する酸素の泡立ちによる物理的な洗浄効果による。"},{"label":"c","text":"レゾルシンは、細菌や真菌類のタンパク質を変性させることにより殺菌消毒作用を示し、にきび用薬などに配合されている場合がある。"},{"label":"d","text":"ポビドンヨードは、ヨウ素及びヨウ化カリウムをエタノールに溶解させたもので、皮膚刺激性が強く、粘膜や目の周りへ使用は避ける必要がある。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":3,"explanation":"正解は3（b、c）。オキシドールは過酸化水素の分解で生じる活性酸素による酸化と、発生する酸素の泡立ちによる洗浄効果で作用する。レゾルシンは細菌や真菌のタンパク質を変性させて殺菌消毒し、にきび用薬などに配合されることがある。aのアクリノールは一般細菌の一部には有効だが、真菌・結核菌・ウイルスには効果がない。dの「ヨウ素とヨウ化カリウムをエタノールに溶解」はヨードチンキの説明で、ポビドンヨードはヨウ素をポリビニルピロリドンに結合させ水溶性にしたものなので誤り。","tags":["殺菌消毒成分","外皮用薬"]},{"id":"R7-51","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":51,"stem":"外皮用薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ジフェンヒドラミンは、肥満細胞から遊離したヒスタミンとその受容体タンパク質との結合を促進することにより、湿疹、かぶれ、虫さされ等による一時的な皮膚症状（ほてり・腫れ・痒み等）を緩和する。"},{"label":"b","text":"カンフルは、皮膚表面に冷感刺激を与え、患部の血行を促す効果や、知覚神経を麻痺させることによる鎮痛・鎮痒の効果を期待して配合されている場合がある。"},{"label":"c","text":"温熱刺激成分を主薬とする貼付剤は、入浴後すぐに貼るのが効果的である。"},{"label":"d","text":"損傷皮膚の組織の修復を促す作用を期待して、アラントインが配合されている場合がある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"正解は4（a誤・b正・c誤・d正）。カンフルは冷感刺激により反射的に血行を促し、知覚神経を麻痺させて鎮痛・鎮痒を期待して配合される。アラントインは損傷皮膚の組織の修復を促す目的で配合されることがある。aのジフェンヒドラミンは、ヒスタミンと受容体の結合を促進するのではなく、妨げることでヒスタミンの働きを抑える抗ヒスタミン成分である。cの温熱刺激成分の貼付剤は、入浴前後の使用は適当でなく、入浴後は皮膚のほてりが鎮まってから貼るとされているので誤り。","tags":["外皮用薬","抗ヒスタミン成分","温感刺激成分"]},{"id":"R7-53","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":53,"stem":"一般用医薬品の禁煙補助剤に関する記述について、誤っているものを選べ。","statements":[],"options":[{"n":1,"text":"咀嚼剤は、噛むことにより口腔内でニコチンが放出されるため、唾液が多く分泌されるよう菓子のガムのように噛むこととされている。"},{"n":2,"text":"脳梗塞・脳出血等の急性期脳血管障害がある人は、使用を避ける。"},{"n":3,"text":"うつ病と診断されたことのある人では、禁煙時の離脱症状により、うつ症状を悪化させることがあるため、使用を避ける。"},{"n":4,"text":"ニコチンは交感神経系を興奮させる作用を示し、アドレナリン作動成分が配合された医薬品との併用により、その作用を増強させるおそれがある。"},{"n":5,"text":"禁煙補助剤は、喫煙を完全に止めたうえで使用することとされている。"}],"answer":1,"explanation":"誤っているものを選ぶ問題で、正解は1。咀嚼剤は、菓子のガムのように噛むと唾液が多く分泌されてニコチンが飲み込まれ、口腔粘膜から十分吸収されず吐きけや腹痛などが出やすくなるため、ゆっくり断続的に噛むこととされている。したがって「菓子のガムのように噛む」は誤り。急性期脳血管障害のある人、うつ病と診断されたことのある人は使用を避ける、ニコチンがアドレナリン作動成分の作用を増強するおそれがある、喫煙を完全に止めて使う、はいずれも正しい。","tags":["禁煙補助剤","ニコチン"]},{"id":"R7-55","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":55,"stem":"滋養強壮保健薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ビタミンＡやビタミンＤなどの水溶性ビタミンでは、過剰摂取により過剰症を生じるおそれがある。"},{"label":"b","text":"医薬部外品として製造販売されている製品の効能・効果の範囲は、しみ・そばかす等のような特定部位の症状に限定されている。"},{"label":"c","text":"生薬成分であるロクジョウは、医薬部外品においても配合することができる。"},{"label":"d","text":"ビタミン成分の１日最大量が既定値を超えるものであっても、医薬部外品として製造販売されている製品がある。"}],"options":[{"n":1,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"正解は5（すべて誤）。aは、ビタミンA・Dは水溶性ではなく脂溶性ビタミンで、過剰摂取により過剰症を生じるおそれがある。bは、しみ・そばかす等の特定部位の症状に対する効能・効果は医薬品でのみ認められ、医薬部外品の保健薬の効能は滋養強壮・虚弱体質の改善・病中病後の栄養補給などに限られる。cのロクジョウは医薬品においてのみ認められる生薬成分である。dの、ビタミン成分の1日最大量が規定値を超えるものも医薬品としてのみ認められる。","tags":["滋養強壮保健薬","医薬部外品","ビタミン"]},{"id":"R7-57","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":57,"stem":"漢方の特徴・漢方薬使用における基本的な考え方に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"漢方処方は、処方全体としての適用性等、その性質からみて処方自体が一つの有効成分として独立したものという見方をすべきものである。"},{"label":"b","text":"現代では、一般用医薬品の漢方処方製剤として、処方に基づく生薬混合物の浸出液を濃縮して調製された乾燥エキス製剤を散剤に加工したもののみが、市販されている。"},{"label":"c","text":"「口渇があり、尿量が減少するもの」という状態は、漢方の病態認識では水毒となる。"},{"label":"d","text":"一般用医薬品の漢方処方製剤に用いることが出来る漢方処方は、現在５０処方程度である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"正解は2（a正・b誤・c正・d誤）。漢方処方は処方全体の適用性からみて、処方自体が一つの有効成分として独立したものとみなす。「口渇があり尿量が減少する」状態は漢方の病態認識では水毒にあたる。bは、現代の漢方処方製剤の多くは乾燥エキス製剤を散剤などに加工したものだが、軟エキス剤・刻み生薬の混合物・丸剤なども存在するため「のみ」は誤り。dの、一般用に用いることができる漢方処方は現在300処方程度とされており、50処方程度は誤りである。","tags":["漢方","漢方処方製剤の基本"]},{"id":"R7-59","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":59,"stem":"忌避剤及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"忌避剤は、人体に直接使用されるが、虫さされによる痒みや腫れなどの症状を和らげる効果はない。"},{"label":"b","text":"スプレー剤となっている忌避剤を使用した場合、塗りむらがあると忌避効果が落ちるため、手で塗り拡げるなどして、必要以上に使用しないことが重要である。"},{"label":"c","text":"効果の持続性が高い忌避成分であるディートは、医薬品においてのみ配合が認められている。"},{"label":"d","text":"イカリジンは、生後６ヵ月未満の乳児への使用を避けることとされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"正解は1（a正・b正・c誤・d誤）。忌避剤は虫が取り付いて吸血するのを防ぐもので、虫さされによる痒みや腫れを和らげる効果はない。スプレー剤でも塗りむらがあると忌避効果が落ちるので手で塗り拡げるなどし、必要以上に使わないことが大切とされる。cのディートは医薬品と医薬部外品の両方に用いられる成分で、「医薬品においてのみ」は誤り。dは、生後6ヶ月未満の乳児への使用を避けるとされているのはディートを含む忌避剤であり、イカリジンは年齢による使用制限がない成分である。","tags":["忌避剤","ディート","イカリジン"]},{"id":"R7-60","chapter":3,"source":"関西広域連合 令和7年度 登録販売者試験 前半","no":60,"stem":"尿糖・尿タンパク検査薬に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"尿タンパクの検査の場合、原則として早朝尿（起床直後の尿）を検体とし、激しい運動の直後は避ける必要がある。"},{"label":"b","text":"出始めの尿では、尿道や外陰部等に付着した細菌や分泌物が混入することがあるため、中間尿を採取して検査することが望ましい。"},{"label":"c","text":"尿は通常、弱アルカリ性であるが、食事の影響で変わることがある。"},{"label":"d","text":"服用している医薬品が一般用医薬品であれば、尿糖・尿タンパクの検査結果に影響を与えることはない。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":1,"explanation":"正解は1（a、b）。尿タンパク検査は原則として早朝尿（起床直後の尿）を検体とし、激しい運動の直後は避ける。出始めの尿には尿道や外陰部の細菌・分泌物が混入することがあるため、中間尿を採取するのが望ましい。cは、尿は通常弱酸性で、食事などの影響で中性から弱アルカリ性に傾くと正確な結果が得られなくなることがあるので誤り。dも、医薬品の中には検査結果に影響を与える成分を含むものがあり、一般用医薬品でも影響しうるため誤りである。","tags":["検査薬","尿糖・尿タンパク"]},{"id":"R8-22","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":22,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを選べ。\n体力中等度で、ときに脇腹（腹）からみぞおちあたりにかけて苦しく、食欲不振や口の苦味があり、舌に白苔がつくものの食欲不振、吐きけ、胃炎、胃痛、胃腸虚弱、疲労感、かぜの後期の諸症状に適すとされる。","statements":[],"options":[{"n":1,"text":"香蘇散"},{"n":2,"text":"半夏厚朴湯"},{"n":3,"text":"安中散"},{"n":4,"text":"小柴胡湯"},{"n":5,"text":"桂枝加芍薬湯"}],"answer":4,"explanation":"正解は4（小柴胡湯）。体力中等度で、ときに脇腹からみぞおちあたりにかけて苦しく、食欲不振や口の苦味があり、舌に白苔がつく、食欲不振・吐きけ・胃炎・胃痛・胃腸虚弱・疲労感・かぜの後期の諸症状、という記述は手引きの小柴胡湯の説明そのものである。半夏厚朴湯は不安や咽喉の異物感、香蘇散は神経過敏で胃腸の弱い人のかぜの初期、桂枝加芍薬湯は腹部膨満感や腹痛に用いる処方で、この記述には合わない。","tags":["漢方処方製剤","小柴胡湯"]},{"id":"R8-24","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":24,"stem":"４５歳女性が、発熱や喉の痛み等のかぜの症状があるため、次の成分の一般用医薬品のかぜ薬を購入する目的で店舗を訪れ、登録販売者は以下のような相談を受けた。この女性に対する説明の正誤について、正しい組合せを選べ。\n＜相談内容＞\nこの薬を服用する際に気を付けることを教えてほしい。また、同じようなかぜの症状がある１３歳の中学生の息子に、この薬を服用させてよいか教えてほしい。\n６錠中：\n成分 / 分量\nトラネキサム酸 / 750mg\nイブプロフェン / 450mg\nクレマスチンフマル酸塩 / 1.34mg\nブロムヘキシン塩酸塩 / 12mg\ndl－メチルエフェドリン塩酸塩 / 60mg\nジヒドロコデインリン酸塩 / 24mg\nチアミン硝化物（ビタミンＢ１） / 25mg\nリボフラビン（ビタミンＢ２） / 12mg","statements":[{"label":"a","text":"心臓や脳の血管の病気（心筋梗塞・脳血栓など）で治療を受けている場合は、服用する前に治療を行っている医師等に相談してください。"},{"label":"b","text":"便秘を起こしやすい成分が含まれていますので、注意してください。"},{"label":"c","text":"眠気を促す成分が含まれているため、服用後は乗物や機械類の運転操作はしないでください。"},{"label":"d","text":"このかぜ薬は、１３歳の息子さんも服用できます。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":1,"explanation":"正解は1（a正・b正・c正・d誤）。トラネキサム酸は血液を溶けにくくする働きがあるため、心筋梗塞・脳血栓などの血栓のある人は医師等への相談が必要（a）。ジヒドロコデインリン酸塩は便秘を起こすことがある（b）。クレマスチンフマル酸塩は抗ヒスタミン成分で眠気を生じるため、運転操作は避ける（c）。dは、この薬にはイブプロフェンが含まれ、一般用医薬品では15歳未満の小児にはいかなる場合も使用できないため、13歳の子には服用させられず誤りである。","tags":["かぜ薬","事例問題","イブプロフェン"]},{"id":"R8-25","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":25,"stem":"次の成分の一般用医薬品の解熱鎮痛薬に関する記述の正誤について、正しい組合せを選べ。\n１錠中：\n成分 / 分量\nイソプロピルアンチピリン / 150mg\nイブプロフェン / 50mg\n無水カフェイン / 50mg","statements":[{"label":"a","text":"アスピリン喘息を誘発するおそれのある成分が含まれている。"},{"label":"b","text":"ピリン系解熱鎮痛成分が含まれている。"},{"label":"c","text":"イブプロフェンは、プロスタグランジンの産生を抑制することで消化管粘膜の防御機能を高める。"},{"label":"d","text":"無水カフェインは、解熱鎮痛成分の鎮痛作用を増強する効果が期待される。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"正解は1（a正・b正・c誤・d正）。イブプロフェンなど解熱鎮痛成分は、アスピリン喘息を誘発するおそれがある。イソプロピルアンチピリンは現在の一般用医薬品で唯一のピリン系解熱鎮痛成分である。無水カフェインは解熱鎮痛成分の鎮痛作用を増強する効果を期待して配合される。cは、イブプロフェンなどがプロスタグランジンの産生を抑えることで、消化管粘膜の防御機能が低下するのであり、防御機能を高めるという記述は逆で誤りである。","tags":["解熱鎮痛薬","イブプロフェン","ピリン系"]},{"id":"R8-27","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":27,"stem":"眠気防止薬の有効成分として配合されるカフェインに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"腎臓におけるナトリウムイオンの再吸収促進作用がある。"},{"label":"b","text":"胃液分泌抑制作用がある。"},{"label":"c","text":"乳汁中へ移行するため、乳児に影響を及ぼす可能性がある。"},{"label":"d","text":"脳に軽い興奮状態を引き起こし、一時的に眠気や倦怠感を抑える効果がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"カフェインは脳を軽く興奮させて眠気やだるさを一時的に抑えるため d は正しく、摂取分の一部が乳汁中へ移行し乳児に蓄積し得るので c も正しい。一方、腎臓ではナトリウムイオン（と水分）の再吸収を『抑制』して尿量を増やすので a は誤り。また胃液の分泌は『促進』するため、胃酸過多や胃潰瘍のある人は避ける必要があり、b も誤りである。","tags":["カフェイン","眠気防止薬"]},{"id":"R8-28","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":28,"stem":"次の成分を含有する医薬品の服用に際し、留意すべきことに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"アセトアミノフェンは、ライ症候群の発生が示唆されており、小児に対しては、いかなる場合も一般用医薬品として使用してはならない。"},{"label":"b","text":"ブロモバレリル尿素は、クローン病の既往歴がある人では、疾患の再発を招くおそれがある。"},{"label":"c","text":"イブプロフェンは、全身性エリテマトーデスの診断を受けた人において無菌性髄膜炎を生じやすい。"},{"label":"d","text":"ジフェニドール塩酸塩は、緑内障の症状を悪化させるおそれがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"イブプロフェンは全身性エリテマトーデスや混合性結合組織病のある人で無菌性髄膜炎を生じやすいので c は正しい。ジフェニドール塩酸塩は抗コリン様の副作用があり、排尿困難や緑内障の人では症状を悪化させるおそれがあるため d も正しい。ライ症候群を理由に15歳未満へ使用できないのはアスピリン等のサリチル酸系なので、アセトアミノフェンの a は誤り。消化管疾患（クローン病等）の再発はイブプロフェンの留意点で、ブロモバレリル尿素の b は誤りである。","tags":["解熱鎮痛成分","使用上の留意点"]},{"id":"R8-30","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":30,"stem":"乗物酔い防止薬の配合成分とその作用との関係について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"配合成分：アミノ安息香酸エチル／作用：脳に軽い興奮を起こさせて、平衡感覚の混乱によるめまいを軽減させる。"},{"label":"b","text":"配合成分：クロルフェニラミンマレイン酸塩／作用：延髄にある嘔吐中枢への刺激や内耳の前庭における自律神経反射を抑える。"},{"label":"c","text":"配合成分：スコポラミン臭化水素酸塩水和物／作用：中枢に作用して自律神経系の混乱を軽減させるとともに、末梢では消化管の緊張を低下させる。"},{"label":"d","text":"配合成分：ジプロフィリン／作用：胃粘膜への麻酔作用によって嘔吐刺激を和らげる。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":3,"explanation":"スコポラミン等の抗コリン成分は中枢で自律神経系の混乱を軽減し、末梢では消化管の緊張を低下させるので c は正しい。クロルフェニラミンなど抗ヒスタミン成分は嘔吐中枢への刺激や前庭の自律神経反射を抑えるので b も正しい。アミノ安息香酸エチルは胃粘膜への局所麻酔作用で吐きけを和らげる成分であり、a の説明は誤り。ジプロフィリンは脳を軽く興奮させるキサンチン系成分で、d の説明は誤りである。","tags":["乗物酔い防止薬","配合成分の作用"]},{"id":"R8-32","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":32,"stem":"咳止めや痰を出しやすくする目的で用いられる漢方処方製剤のうち、マオウを含むものの組合せを選べ。","statements":[{"label":"a","text":"麦門冬湯"},{"label":"b","text":"甘草湯"},{"label":"c","text":"五虎湯"},{"label":"d","text":"麻杏甘石湯"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":5,"explanation":"マオウを構成生薬に含むのは、五虎湯と麻杏甘石湯である（いずれも咳や気管支の症状に用いられる）。麦門冬湯と甘草湯にはマオウは含まれない。したがって c と d の組合せが正しい。マオウを含む製剤は、交感神経への刺激作用があるため使用上の注意が必要になる点も合わせて覚えておくとよい。","tags":["漢方処方製剤","マオウ"]},{"id":"R8-33","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":33,"stem":"鎮咳去痰薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"鎮咳去痰薬に解熱成分は配合されておらず、発熱を鎮める効果は期待できない。"},{"label":"b","text":"一般用医薬品の鎮咳去痰薬は、かぜ薬や抗ヒスタミン成分等を含有する医薬品との併用によって、副作用が起こりやすくなるおそれがある。"},{"label":"c","text":"チペピジンヒベンズ酸塩は、麻薬性鎮咳成分である。"},{"label":"d","text":"メチルエフェドリン塩酸塩は、粘液成分の含量比を調整し痰の切れを良くする作用がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"鎮咳去痰薬には解熱成分が配合されておらず発熱を鎮める効果は期待できないので a は正しい。かぜ薬や抗ヒスタミン成分などを含む薬との併用は成分の重複で副作用が起こりやすくなるため b も正しい。チペピジンヒベンズ酸塩は非麻薬性の鎮咳成分であり、麻薬性はコデイン類なので c は誤り。メチルエフェドリン塩酸塩は気管支を拡げる成分で、粘液成分の含量比を調整して痰の切れを良くするのはブロムヘキシン等の去痰成分のため d は誤りである。","tags":["鎮咳去痰薬","相互作用"]},{"id":"R8-35","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":35,"stem":"止瀉薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"タンニン酸アルブミンは、牛乳にアレルギーがある人では使用を避ける必要がある。"},{"label":"b","text":"ベルベリン塩化物は、収斂作用のほか、腸内で発生した有毒物質を分解する作用も持つとされる。"},{"label":"c","text":"次没食子酸ビスマスは、抗菌作用のほか抗炎症作用も併せ持つとされる。"},{"label":"d","text":"ロペラミド塩酸塩が配合された止瀉薬は、食あたりや水あたりによる下痢の症状に用いられることを目的としている。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"タンニン酸アルブミンは乳製カゼイン由来のアルブミンを含むため、牛乳アレルギーの人は使用を避ける必要があり a は正しい。ベルベリンは抗菌作用と抗炎症作用を併せ持つ成分で、腸内の有毒物質を分解するとされるのはビスマス系成分なので b は誤り。次没食子酸ビスマスは収斂作用と有毒物質の分解作用が特徴で、抗菌・抗炎症作用ではないため c も誤り。ロペラミドは食べすぎ・飲みすぎや寝冷えの下痢向けで、食あたり・水あたりは適用対象外のため d は誤りである。","tags":["止瀉薬","収斂成分"]},{"id":"R8-36","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":36,"stem":"３０歳の女性が便秘の症状があるため、次の成分の一般用医薬品の瀉下薬（腸溶性製剤）を購入する目的で店舗を訪れ、登録販売者は以下のような相談を受けた。この女性に対する説明の正誤について、正しい組合せを選べ。\n＜相談内容＞\n現在授乳中であるが、この薬を服用するときは、授乳をやめる必要があるか教えてほしい。また、この薬を服用する際に気をつけることも教えてほしい。\n３錠中：\n成分 / 分量\nビサコジル / 15mg\nセンノシド / 40mg\n（腸溶性製剤）","statements":[{"label":"a","text":"授乳中であっても、服用することは可能です。"},{"label":"b","text":"この医薬品と、ビフィズス菌や乳酸菌などの整腸成分の製剤を並行して使用することは避けてください。"},{"label":"c","text":"効果が出やすくなるので、毎日服用を続けてください。"},{"label":"d","text":"服用前後１時間以内は、牛乳を飲まないで下さい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"ビサコジルの腸溶性製剤は、胃内で溶け出さないよう服用前後1時間以内は牛乳や制酸成分を含む胃腸薬を避けるので d は正しい。センノシドは乳汁中へ移行して乳児に下痢を起こすおそれがあり、授乳中は使用を避けるか授乳を避ける必要があるため、a は誤り。大腸刺激性瀉下薬は便秘時の頓服が基本で、毎日の連用は効果が落ちて量が増えやすいので c は誤り。整腸成分の製剤との並行使用は、むしろ依存しない方法として勧められるため b も誤りである。","tags":["瀉下薬","ビサコジル","授乳"]},{"id":"R8-38","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":38,"stem":"次の成分の一般用医薬品の強心薬を購入しようとする者に対する登録販売者の説明の正誤について、正しい組合せを選べ。\n６粒中：\n成分 / 分量\nセンソ / 5mg\nゴオウ / 2mg\nロクジョウ末 / 5mg\nニンジン / 25mg\nレイヨウカク末 / 6mg\nシンジュ / 7.5mg\nジンコウ / 3mg\nリュウノウ / 2.7mg\n動物胆 / 8mg","statements":[{"label":"a","text":"口中で噛み砕くと舌等が麻痺することがあるため、噛まずに服用してください。"},{"label":"b","text":"このお薬には、心筋の収縮力を高める成分を主体として、鎮静作用や強壮作用等をもつ成分が配合されています。"},{"label":"c","text":"心臓の病気に限らず、医師の治療を受けている場合には、服用する前に治療を行っている医師等に相談してください。"},{"label":"d","text":"５～６日間服用しても症状の改善がみられない場合には、医療機関を受診してください。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"センソを含む内服固形製剤は、噛み砕くと舌などが麻痺することがあるため噛まずに服用する（a 正）。強心薬は心筋の収縮力を高める成分を主体に、鎮静・強壮などの成分を組み合わせたものである（b 正）。心臓病に限らず医師の治療を受けている人は、使用前に主治医や薬剤師へ相談する（c 正）。5～6日使用しても改善しないときは、心臓以外の要因も考えて受診を勧める（d 正）。よって全て正しい。","tags":["強心薬","センソ"]},{"id":"R8-40","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":40,"stem":"貧血及び貧血用薬（鉄製剤）の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"コバルトは、赤血球ができる過程で必要不可欠なビタミンＢ１２の構成成分であり、骨髄での造血機能を高める目的で、硫酸コバルトが配合されている場合がある。"},{"label":"b","text":"鉄製剤の服用前と比べて服用後に便が黒くなった場合は、重大な副作用が疑われるため、直ちに服用を中止する。"},{"label":"c","text":"鉄製剤は、消化器系への副作用を軽減するために食前に服用することが望ましい。"},{"label":"d","text":"鉄製剤は、貧血症状がみられる以前から予防的に使用することが適切である。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"コバルトはビタミンB12の構成成分で、骨髄での造血機能を高める目的で硫酸コバルトが配合されることがあり a は正しい。鉄製剤で便が黒くなるのは中止を要する副作用ではないので b は誤り。消化器系の副作用を軽くするには、吸収は空腹時のほうがよいとされるものの食後の服用が望ましく、c は誤り。貧血の症状がない段階での予防的な使用は適当でないため d も誤りである。","tags":["鉄剤","貧血用薬"]},{"id":"R8-41","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":41,"stem":"痔及び痔疾用薬とその配合成分に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品の痔疾用薬は、肛門部又は直腸内に適用する外用薬のみである。"},{"label":"b","text":"痔核は、一般に「いぼ痔」と呼ばれ、便秘や長時間同じ姿勢でいる等、肛門部への過度の圧迫が主な要因とされる。"},{"label":"c","text":"ジブカイン塩酸塩は、痔疾患に伴う局所の感染を防止することを期待して配合されている。"},{"label":"d","text":"アラントインは、痔による肛門部の創傷の治癒を促す効果を期待して配合されている。"}],"options":[{"n":1,"text":"（a、b）"},{"n":2,"text":"（a、c）"},{"n":3,"text":"（b、c）"},{"n":4,"text":"（b、d）"},{"n":5,"text":"（c、d）"}],"answer":4,"explanation":"痔核は「いぼ痔」と呼ばれ、便秘や長時間同じ姿勢での圧迫が主な要因とされるので b は正しい。アラントインは肛門部の創傷の治癒を促す組織修復成分として配合されるため d も正しい。痔疾用薬には外用薬のほか内服する内用薬もあるので、外用のみとする a は誤り。ジブカイン塩酸塩は痛みやかゆみを和らげる局所麻酔成分で、感染防止を目的とする殺菌消毒成分ではないため c は誤りである。","tags":["痔疾用薬","局所麻酔成分"]},{"id":"R8-43","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":43,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを選べ。\n体力中等度以下で、のぼせ感があり、肩がこり、疲れやすく、精神不安やいらだちなどの精神神経症状、ときに便秘の傾向のあるものの冷え症、虚弱体質、月経不順、月経困難、更年期障害、血の道症、不眠症に適すとされるが、胃腸の弱い人では悪心（吐きけ）、嘔吐、胃部不快感、下痢等の副作用が現れやすい等、不向きとされる。\nまれに重篤な副作用として、肝機能障害、腸間膜静脈硬化症を生じることが知られている。","statements":[],"options":[{"n":1,"text":"五積散"},{"n":2,"text":"桂枝茯苓丸"},{"n":3,"text":"加味逍遙散"},{"n":4,"text":"温清飲"},{"n":5,"text":"柴胡桂枝乾姜湯"}],"answer":3,"explanation":"のぼせ感・肩こり・精神不安やいらだち・便秘傾向といった特徴があり、冷え症、月経不順、更年期障害、血の道症、不眠症に用いられるのは加味逍遙散である。まれな重篤な副作用として肝機能障害に加え、長期服用に関連した腸間膜静脈硬化症が知られている点も、この処方を特定する手がかりになる。他の選択肢は適する症状や体力の目安が異なる。","tags":["漢方処方製剤","婦人薬"]},{"id":"R8-44","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":44,"stem":"女性の月経や更年期障害に伴う諸症状の緩和に用いられる漢方処方製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"桃核承気湯は、体力中等度以上で、のぼせて便秘しがちなものの月経不順、月経困難症、月経痛、月経時や産後の精神不安、腰痛、便秘、高血圧の随伴症状（頭痛、めまい、肩こり）、痔疾、打撲症に適すとされる。"},{"label":"b","text":"当帰芍薬散は、比較的体力があり、ときに下腹部痛、肩こり、頭重、めまい、のぼせて足冷えなどを訴えるものの、月経不順、月経異常、月経痛、更年期障害、血の道症、肩こり、めまい、頭重、打ち身（打撲症）、しもやけ、しみ、湿疹・皮膚炎、にきびに適すとされる。"},{"label":"c","text":"温経湯は、体力中等度以下で、手足がほてり、唇が乾くものの月経不順、月経困難、こしけ（おりもの）、更年期障害、不眠、神経症、湿疹・皮膚炎、足腰の冷え、しもやけ、手あれ（手の湿疹・皮膚炎）に適すとされる。"},{"label":"d","text":"四物湯は、体力虚弱で、冷え症で皮膚が乾燥、色つやの悪い体質で胃腸障害のないものの月経不順、月経異常、更年期障害、血の道症、冷え症、しもやけ、しみ、貧血、産後あるいは流産後の疲労回復に適すとされる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"桃核承気湯は体力中等度以上で、のぼせて便秘しがちな人の月経不順や痔疾などに用いるため a は正しい。温経湯は手足のほてりや唇の乾きがある人向けで c も正しく、四物湯は体力虚弱で冷え症・皮膚の乾燥がある人向けで d も正しい。b の記述（比較的体力があり、下腹部痛やのぼせて足冷え、にきび等）は桂枝茯苓丸の説明であり、当帰芍薬散は体力虚弱で冷え症・貧血傾向の人向けなので b は誤りである。","tags":["漢方処方製剤","婦人薬"]},{"id":"R8-46","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":46,"stem":"鼻炎用内服薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"パーキンソン病の治療のため医療機関でセレギリン塩酸塩等のモノアミン酸化酵素阻害剤が処方されて治療を受けている人が、プソイドエフェドリン塩酸塩が配合された鼻炎用内服薬を使用した場合、副作用が現れやすくなるおそれが高く、使用を避ける必要がある。"},{"label":"b","text":"ベラドンナ総アルカロイドは、ヒスタミンの働きを抑える作用を目的として配合されている抗ヒスタミン成分である。"},{"label":"c","text":"フェキソフェナジン塩酸塩は、鼻粘膜の血管を収縮させることによって鼻粘膜の充血や腫れを和らげるアドレナリン作動成分である。"},{"label":"d","text":"グリチルリチン酸は、鼻粘膜の炎症を和らげることを目的として配合されている場合がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"プソイドエフェドリン塩酸塩は、モノアミン酸化酵素阻害剤（セレギリン等）で治療中の人では代謝が妨げられて副作用が出やすくなるため、使用を避ける必要があり a は正しい。グリチルリチン酸は鼻粘膜の炎症を和らげる抗炎症成分として配合されることがあり d も正しい。ベラドンナ総アルカロイドは抗コリン成分で、鼻汁やくしゃみを抑えるため b は誤り。フェキソフェナジン塩酸塩は抗ヒスタミン成分であり、血管収縮によるアドレナリン作動成分ではないので c は誤りである。","tags":["鼻炎用内服薬","プソイドエフェドリン"]},{"id":"R8-48","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":48,"stem":"３０歳女性が、花粉による目の充血と痒みがあるため、次の成分の一般用医薬品のアレルギー用点眼薬を購入する目的で店舗を訪れた。この点眼薬に関する記述の正誤について、正しい組合せを選べ。\n１ｍＬ中：\n成分 / 分量\nクロモグリク酸ナトリウム / 10mg\nクロルフェニラミンマレイン酸塩 / 0.15mg\nプラノプロフェン / 0.5mg\n（添加物として、ホウ酸、ベンザルコニウム塩化物等を含む）","statements":[{"label":"a","text":"クロモグリク酸ナトリウムは、花粉、ハウスダスト（室内塵）等による目のアレルギー症状（結膜充血、痒み、かすみ、流涙、異物感）の緩和を目的として配合されている。"},{"label":"b","text":"プラノプロフェンは、ステロイド性抗炎症成分であり、目の炎症を改善する効果を期待して配合されている。"},{"label":"c","text":"この医薬品には、防腐剤が配合されているので、ソフトコンタクトレンズを装着したままの点眼は避ける。"},{"label":"d","text":"この医薬品を２日間使用しても症状の改善がみられない場合には、アレルギー以外の原因の可能性が考えられる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"クロモグリク酸ナトリウムは肥満細胞からのヒスタミン遊離を抑える抗アレルギー成分で、花粉やハウスダストによる目のアレルギー症状の緩和を目的に配合される（a 正）。ベンザルコニウム塩化物などの防腐剤はソフトコンタクトレンズに吸着されるおそれがあり、装着したままの点眼は避ける（c 正）。2日間使用しても改善しなければアレルギー以外の原因も考えられる（d 正）。プラノプロフェンはステロイドではなく非ステロイド性抗炎症成分なので b は誤りである。","tags":["アレルギー用点眼薬","コンタクトレンズ"]},{"id":"R8-49","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":49,"stem":"眼科用薬の購入希望者に対する登録販売者の説明の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"点眼の際は、雑菌が薬液に混入して汚染を生じないように、容器の先端がまぶたやまつげに触れないようにするよう説明した。"},{"label":"b","text":"目の痛みが激しいので、炎症を抑える成分が入った目薬を買いたいと訴える購入希望者に対して、すみやかに医療機関を受診し、専門医の診療を受けるように促した。"},{"label":"c","text":"アドレナリン作動成分が配合された眼科用薬について、頻回に使用すると、異常なまぶしさを感じたり、かえって充血を招くことがあると説明した。"},{"label":"d","text":"抗ヒスタミン成分が配合された眼科用薬について、鼻炎用点鼻薬と併用した場合、眠気が現れることがあるため、乗物又は機械類の運転操作を避けるよう説明した。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"点眼時に容器の先端がまぶたやまつげに触れると雑菌で汚染されるため触れないようにする（a 正）。目の痛みが激しい場合は急性緑内障や角膜潰瘍などの可能性があり、すみやかに眼科を受診するよう促す（b 正）。アドレナリン作動成分は頻回に使うと異常なまぶしさやかえって充血を招くことがある（c 正）。抗ヒスタミン成分配合の点眼薬は鼻炎用点鼻薬と併用すると眠気が出ることがあり、運転操作を避ける（d 正）。よって全て正しい。","tags":["眼科用薬","点眼の注意"]},{"id":"R8-51","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":51,"stem":"外皮用薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"外皮用薬は、皮膚表面に生じた創傷や症状、又は皮膚の下にある毛根、血管、筋組織、関節等の症状を改善・緩和するため、外用局所に直接適用される医薬品である。"},{"label":"b","text":"ユーカリ油は、創傷面からの出血を抑えることを目的として配合されている場合がある。"},{"label":"c","text":"ヘパリン類似物質は、患部局所の血行を促す目的で用いられるほか、抗炎症作用や保湿作用も期待される。"},{"label":"d","text":"クロタミトンは、皮膚に軽い灼熱感を与えることで痒みを感じにくくさせる効果を期待して配合されている場合がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"外皮用薬は皮膚表面の症状だけでなく、皮膚の下の毛根・血管・筋組織・関節等の症状の改善・緩和にも外用局所へ適用される（a 正）。ヘパリン類似物質は血行促進のほか抗炎症作用や保湿作用も期待される（c 正）。クロタミトンは軽い灼熱感を与えて痒みを感じにくくさせる（d 正）。ユーカリ油は冷感刺激成分として血行促進や鎮痛・鎮痒を期待して配合されるもので、出血を抑える血管収縮成分ではないので b は誤りである。","tags":["外皮用薬","配合成分"]},{"id":"R8-52","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":52,"stem":"抗真菌作用を有する外皮用薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ミコナゾール硝酸塩が配合されたみずむし薬でかぶれたことがある人は、他のイミダゾール系成分が配合された製品も避けるべきである。"},{"label":"b","text":"ウンデシレン酸亜鉛は、患部を酸性にすることで、皮膚糸状菌の発育を抑える。"},{"label":"c","text":"テルビナフィン塩酸塩は、皮膚糸状菌の細胞膜を構成する成分の産生を妨げることにより、その増殖を抑える。"},{"label":"d","text":"湿疹か皮膚糸状菌による皮膚感染かはっきりしない場合、抗真菌成分が配合された医薬品を使用することが適切である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":1,"explanation":"イミダゾール系成分でかぶれた人は、他のイミダゾール系成分の製品も避けるべきである（a 正）。ウンデシレン酸亜鉛は患部を酸性にして皮膚糸状菌の発育を抑える（b 正）。テルビナフィン塩酸塩は細胞膜を構成する成分の産生を妨げて増殖を抑える（c 正）。湿疹に抗真菌成分を使うと悪化することがあり、湿疹か白癬か判然としない場合に使用するのは適当でないため d は誤りである。","tags":["抗真菌薬","みずむし薬"]},{"id":"R8-54","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":54,"stem":"口内炎及び口内炎用薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"口内炎は、栄養摂取の偏り、ストレスや睡眠不足、唾液分泌の低下、口腔内の不衛生などが要因となって生じることが多いとされる。"},{"label":"b","text":"口内炎は、口腔の粘膜上皮に水疱や潰瘍ができて痛み、ときに口臭を伴う。"},{"label":"c","text":"口腔粘膜の組織修復を促す作用を期待して、アズレンスルホン酸ナトリウム（水溶性アズレン）が配合されている場合がある。"},{"label":"d","text":"口内炎用薬であれば、ステロイド性抗炎症成分が配合されていても、長期の連用は問題ない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"口内炎は栄養の偏り、ストレスや睡眠不足、唾液分泌の低下、口腔内の不衛生などが要因となることが多い（a 正）。口腔粘膜に水疱や潰瘍ができて痛み、ときに口臭を伴う（b 正）。水溶性アズレンは口腔粘膜の組織修復を促す作用を期待して配合されることがある（c 正）。口腔内に使うステロイド性抗炎症成分配合の薬は、含有量にかかわらず長期連用を避ける必要があり、d は誤りである。","tags":["口内炎用薬","ステロイド"]},{"id":"R8-56","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":56,"stem":"滋養強壮保健薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ビタミンは、「微量（それ自体エネルギー源や生体構成成分とならない）で体内の代謝に重要な働きを担うにもかかわらず、生体が自ら産生することができない、又は産生されても不十分であるため外部から摂取する必要がある化合物」と定義される。"},{"label":"b","text":"ビタミン成分等は、多く摂取したからといって適用となっている症状の改善が早まるものでなく、むしろ脂溶性ビタミンでは、過剰摂取により過剰症を生じるおそれがある。"},{"label":"c","text":"ヘスペリジンは、ビタミン様物質のひとつで、ビタミンＣの吸収を助ける等の作用があるとされている。"},{"label":"d","text":"グルクロノラクトンは、肝臓の働きを助け、肝血流を促進する働きがあり、全身倦怠感や疲労時の栄養補給を目的として配合されている場合がある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"ビタミンは、微量で代謝に重要な働きを担うが体内で産生できない、または不十分な化合物と定義される（a 正）。多く摂っても効果が早まるわけではなく、脂溶性ビタミンでは過剰症のおそれがある（b 正）。ヘスペリジンはビタミン様物質でビタミンCの吸収を助ける（c 正）。グルクロノラクトンは肝臓の働きを助け肝血流を促進し、倦怠感や疲労時の栄養補給を目的に配合される（d 正）。よって全て正しい。","tags":["ビタミン","滋養強壮保健薬"]},{"id":"R8-57","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":57,"stem":"ビタミンＡ主薬製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ビタミンＡは、夜間視力を維持したり、皮膚や粘膜の機能を正常に保つために重要な栄養素である。"},{"label":"b","text":"目の乾燥感や夜盲症の症状の緩和に用いられる。"},{"label":"c","text":"病中病後の体力低下時、発育期等のビタミンＡの補給に用いられる。"},{"label":"d","text":"妊娠３ヶ月以内の妊婦は、医薬品以外からのビタミンＡの摂取を含め、過剰摂取に留意する必要がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"ビタミンAは夜間視力の維持や皮膚・粘膜の機能を正常に保つ栄養素で（a 正）、目の乾燥感や夜盲症の緩和に用いられる（b 正）。病中病後の体力低下時や発育期などの補給にも用いられる（c 正）。妊娠3ヶ月以内の妊婦は、食品など医薬品以外からの摂取も含めて過剰摂取に留意が必要とされる（d 正）。よって全て正しい。","tags":["ビタミンA","妊婦"]},{"id":"R8-59","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":59,"stem":"消毒薬の誤用・事故等による中毒への応急処置に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"誤って飲み込んだ場合、一般的な家庭における応急処置として、通常は牛乳などを飲ませるが、手元に何もないときはまず水を飲ませる。"},{"label":"b","text":"原末や濃厚液を誤って飲み込んだ場合には、自己判断で安易に吐き出させることは避け、すみやかに医療機関を受診させる。"},{"label":"c","text":"誤って目に入った場合、顔を横に向けて上から水を流すか、水道水の場合には弱い流れの水で洗うなどにより、流水で十分に（１５分間以上）洗眼する。"},{"label":"d","text":"アルカリ性の消毒薬が誤って皮膚に付着した場合は、水洗する前に、中和剤を用いて中和する。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"誤飲時は牛乳などを飲ませ、なければまず水を飲ませる（a 正）。原末や濃厚液を飲み込んだ場合は、自己判断で吐かせず医療機関を受診させる（b 正）。目に入ったときは流水で15分間以上洗眼する（c 正）。皮膚に付着した場合も流水で十分に洗い、目に入った場合と同様に中和剤は用いない。酸とアルカリの中和は熱を生じて悪化するおそれがあるので、d は誤りである。","tags":["消毒薬","応急処置"]},{"id":"R8-60","chapter":3,"source":"関西広域連合 令和8年度 登録販売者試験 前半","no":60,"stem":"一般用検査薬に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般の生活者が正しく用いて健康状態を把握し、速やかな受診につなげることで、疾病を早期発見するためのものである。"},{"label":"b","text":"専ら疾病の診断に使用されることが目的とされる医薬品のうち、人体に直接使用されることのないものを体外診断用医薬品という。"},{"label":"c","text":"検査に用いる検体は、尿、糞便、鼻汁、唾液、涙液、採血した血液などである。"},{"label":"d","text":"一般用検査薬の対象には、遺伝性疾患の診断に関係するものも含まれる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"一般用検査薬は、生活者が健康状態を把握して速やかな受診につなげ、疾病の早期発見に役立てるものである（a 正）。専ら疾病の診断に使われ、人体に直接使用されないものが体外診断用医薬品である（b 正）。一般用検査薬の検体は尿、糞便、鼻汁、唾液、涙液など侵襲のないものであり、採血した血液は含まれないので c は誤り。遺伝性疾患など重大な疾患の診断に関係するものは対象外のため d も誤りである。","tags":["一般用検査薬","体外診断用医薬品"]},{"id":"R7-84","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":84,"stem":"毒薬及び劇薬に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"毒薬とは、毒性が強いものとして都道府県知事が薬事審議会の意見を聴いて指定する医薬品をいう。"},{"label":"b","text":"毒薬又は劇薬を、１４歳未満の者その他安全な取扱いに不安のある者に交付することは禁止されている。"},{"label":"c","text":"劇薬は、それを収める直接の容器又は被包に、白地に赤枠、赤字をもって「劇」の文字が記載されていなければならないとされており、当該医薬品の品名が記載されている必要はない。"},{"label":"d","text":"店舗管理者が登録販売者の店舗販売業者は、毒薬又は劇薬を開封して販売することができる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3（a誤・b正・c誤・d誤）。毒薬は、毒性が強いものとして厚生労働大臣が薬事審議会の意見を聴いて指定するもので、都道府県知事ではないためaは誤り（法第44条第1項）。bは正しく、14歳未満の者その他安全な取扱いに不安のある者への交付は禁止されている（法第47条）。cは、劇薬の直接の容器・被包に、白地に赤枠・赤字で「劇」の文字に加えて当該医薬品の品名も記載しなければならないため誤り（法第44条第2項）。dは、毒薬・劇薬を開封して販売できるのは店舗管理者が薬剤師である店舗販売業者などに限られ、店舗管理者が登録販売者の店舗販売業者には認められないため誤り（法第45条）。","tags":["毒薬・劇薬","法第44条","開封販売"]},{"id":"R7-88","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":88,"stem":"化粧品に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"化粧品は、「人の身体を清潔にし、美化し、魅力を増し、容貌を変え、又は皮膚若しくは毛髪を健やかに保つ」の範囲内においてのみ効能効果を表示・標榜することができる。"},{"label":"b","text":"化粧品的効能効果を標榜することは、化粧品のみに認められる。"},{"label":"c","text":"化粧品を業として製造販売する場合は、法に基づき、製造販売業の許可を取得し、品目ごとにあらかじめ届出を行うか、承認を得る必要がある。"},{"label":"d","text":"化粧品には、医薬品の成分が配合されることはない。"}],"options":[{"n":1,"text":"1（a、b）"},{"n":2,"text":"2（a、c）"},{"n":3,"text":"3（b、c）"},{"n":4,"text":"4（b、d）"},{"n":5,"text":"5（c、d）"}],"answer":2,"explanation":"正解は2（a、c）。aは正しく、化粧品は「人の身体を清潔にし、美化し、魅力を増し、容貌を変え、又は皮膚若しくは毛髪を健やかに保つ」の範囲内でのみ効能効果を表示・標榜でき、医薬品的な効能効果は認められない。bは誤りで、化粧品的な効能効果は薬用化粧品・薬用石けん・薬用歯みがき等の医薬部外品でも標榜できるため、化粧品のみに認められるわけではない。cは正しく、化粧品の製造販売には製造販売業の許可が必要で、品目ごとに届出（厚生労働大臣が指定する成分を含む場合は承認）を要する（法第12条、第14条、第14条の9）。dは誤りで、原則として医薬品成分は配合できないが、薬理作用が期待できない量以下に制限するなど、配合が認められる場合がある。","tags":["化粧品","効能効果の範囲","製造販売"]},{"id":"R7-92","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":92,"stem":"店舗販売業に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"店舗販売業の許可は、店舗ごとに、その店舗の所在地の都道府県知事（その店舗の所在地が保健所を設置する市又は特別区の区域にある場合においては、市長又は区長。）が与える。"},{"label":"b","text":"薬剤師が従事していても調剤を行うことはできず、要指導医薬品又は一般用医薬品以外の医薬品の販売等は認められていない。"},{"label":"c","text":"第一類医薬品を販売する店舗の店舗管理者は、必ず薬剤師でなければならない。"},{"label":"d","text":"店舗管理者は、保健衛生上支障を生ずるおそれがないよう、その店舗に勤務する他の従事者を監督するなど、その店舗の業務につき、必要な注意をしなければならない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"正解は2（a正・b正・c誤・d正）。aは正しく、店舗販売業の許可は店舗ごとに、その所在地の都道府県知事（保健所設置市・特別区では市長・区長）が与える（法第26条第1項）。bも正しく、店舗販売業では薬剤師が従事していても調剤はできず、要指導医薬品・一般用医薬品以外の医薬品の販売等も認められない（法第27条）。cは誤りで、第一類医薬品を販売する店舗の店舗管理者は原則として薬剤師だが、薬剤師を店舗管理者にできない場合には、一定の実務経験等の要件を満たす登録販売者を店舗管理者にできる例外がある（施行規則第140条）ため、「必ず」とはいえない。dは正しく、店舗管理者は他の従事者を監督するなど、店舗の業務につき必要な注意をする義務を負う（法第29条第1項）。","tags":["店舗販売業","店舗管理者"]},{"id":"R7-96","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":96,"stem":"医薬品の陳列に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"店舗販売業と異なり、薬局ではリスク区分の異なる医薬品を混在して陳列することができる。"},{"label":"b","text":"店舗販売業者が第一類医薬品を陳列する場合、購入しようとする者等が直接手の触れられない陳列設備に陳列すれば、薬局等構造設備規則に規定する第一類医薬品陳列区画の内部の陳列設備に陳列する必要はない。"},{"label":"c","text":"店舗販売業者は、指定第二類医薬品を陳列する陳列設備から１.２メートル以内の範囲に、医薬品を購入しようとする者等が進入することができないよう措置を採っている場合には、「情報提供を行うための設備」から７メートル以内の範囲に陳列する必要はない。"},{"label":"d","text":"配置販売業者は、第二類医薬品と第三類医薬品を混在させないように配置しなければならない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3（a誤・b正・c正・d正）。aは誤りで、薬局開設者も店舗販売業者と同様に、第一類・第二類・第三類医薬品を混在させないよう区分して陳列しなければならない（施行規則第218条の4第1項第3号）。bは正しく、第一類医薬品は第一類医薬品陳列区画の内部に陳列するのが原則だが、鍵をかけた陳列設備や、購入しようとする者等が直接手の触れられない陳列設備に陳列する場合は除かれる（同項第1号）。cも正しく、指定第二類医薬品は情報提供を行うための設備から7メートル以内に陳列するのが原則だが、その陳列設備から1.2メートル以内に購入しようとする者等が進入できない措置を採っている場合などは除かれる（同項第2号）。dは正しく、配置販売業者は第一類・第二類・第三類医薬品を混在させないよう配置しなければならない（同条第2項）。","tags":["医薬品の陳列","リスク区分","指定第二類医薬品"]},{"id":"R7-100","chapter":4,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":100,"stem":"医薬品の販売方法に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"店舗販売業者が、許可を受けた店舗以外の場所を拠点に、医薬品を販売する行為は認められている。"},{"label":"b","text":"医薬品の販売等に従事する専門家は、医薬品を多量に購入する者等に対して、積極的に事情を尋ねるなど慎重に対処し、状況によっては販売を差し控えるべきである。"},{"label":"c","text":"店舗販売業者は、在庫処分の目的で効能効果が重複する医薬品を組み合わせて販売することができる。"},{"label":"d","text":"医薬品を懸賞や景品として授与することは、原則として認められていない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"正解は4（a誤・b正・c誤・d正）。aは誤りで、許可を受けた店舗以外の場所に医薬品を貯蔵・陳列して、そこを拠点に販売する行為は店舗による販売等に当たらず、法第37条第1項違反として取締りの対象になる。bは正しく、医薬品を多量に購入する者等には、積極的に事情を尋ねるなど慎重に対処し、状況によっては販売を差し控えるべきである（無許可販売への便宜を防ぐ観点）。cは誤りで、効能効果が重複する組合せや、在庫処分など販売側の都合による抱き合わせ販売は認められない。dは正しく、医薬品を懸賞や景品として授与することは原則として認められていない（キャラクターグッズ等の景品を付けることは、景品表示法の限度内であれば可能）。","tags":["販売方法","組み合わせ販売","多量購入"]},{"id":"R7-106","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":106,"stem":"緊急安全性情報に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品、医療機器又は再生医療等製品について、緊急かつ重大な注意喚起や使用制限に係る対策が必要な状況にある場合に作成される。"},{"label":"b","text":"Ａ４サイズの青色地の印刷物で、ブルーレターとも呼ばれる。"},{"label":"c","text":"医療機関等への直接配布だけではなく、電子メールによる情報伝達も認められている。"},{"label":"d","text":"厚生労働省からの命令、指示でのみ作成されるものであり、製造販売業者が自主決定に基づいて作成することはない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"正解は4（a正・b誤・c正・d誤）。緊急安全性情報は、医薬品・医療機器・再生医療等製品について緊急かつ重大な注意喚起や使用制限に係る対策が必要な場合に作成されるため、aは正しい。A4サイズの「黄色地」の印刷物でイエローレターと呼ばれるので、青色地・ブルーレターとするbは誤り（青色地は安全性速報）。cは、製造販売業者からの直接配布のほか、ダイレクトメール、ファクシミリ、電子メール等でも情報伝達されるため正しい。dは、厚生労働省の命令・指示だけでなく製造販売業者の自主決定に基づいても作成されるため誤り。","tags":["緊急安全性情報","イエローレター","安全性速報"]},{"id":"R7-112","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":112,"stem":"一般用医薬品の安全対策に関する記述について、（　　）の中に入れるべき字句の正しい組合せを選べ。なお、同じアルファベットの（　　）の中には、同じ字句が入る。\n\n小柴胡湯による（　a　）については、１９９１年４月以降、使用上の注意に記載されていたが、その後、小柴胡湯と（　b　）の併用例による（　a　）が報告されたことから、１９９４年１月、（　b　）との併用を禁忌とする旨の使用上の注意の改訂がなされた。しかし、それ以降も慢性肝炎患者が小柴胡湯を使用して（　a　）が発症し、死亡を含む重篤な転帰に至った例もあったことから、１９９６年３月、厚生省（当時）より関係製薬企業に対して（　c　）の配布が指示された。","statements":[],"options":[{"n":1,"text":"a 間質性肺炎 / b インターフェロン製剤 / c 緊急安全性情報"},{"n":2,"text":"a 間質性肺炎 / b インターフェロン製剤 / c 安全性速報"},{"n":3,"text":"a 間質性肺炎 / b 塩酸フェニルプロパノールアミン / c 安全性速報"},{"n":4,"text":"a 出血性脳卒中 / b 塩酸フェニルプロパノールアミン / c 安全性速報"},{"n":5,"text":"a 出血性脳卒中 / b インターフェロン製剤 / c 緊急安全性情報"}],"answer":1,"explanation":"正解は1。小柴胡湯による間質性肺炎は1991年4月以降、使用上の注意に記載されていたが、その後、インターフェロン製剤との併用例で間質性肺炎が報告されたため、1994年1月にインターフェロン製剤との併用を禁忌とする改訂が行われた。しかし慢性肝炎患者が小柴胡湯を使用して間質性肺炎を発症し、死亡例も出たため、1996年3月に厚生省（当時）が関係製薬企業に対し緊急安全性情報の配布を指示した。よって a は間質性肺炎、b はインターフェロン製剤、c は緊急安全性情報。塩酸フェニルプロパノールアミン（PPA）は出血性脳卒中に関する別の事例の成分であり、本問の小柴胡湯の経緯には当たらない。","tags":["小柴胡湯","間質性肺炎","医薬品安全対策の歴史"]},{"id":"R7-120","chapter":5,"source":"関西広域連合 令和7年度 登録販売者試験 後半","no":120,"stem":"ロペラミド塩酸塩を含有する一般用医薬品の止瀉薬の添付文書等において、「使用上の注意」に記載されている事項に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"肝臓病の診断を受けた人は、「相談すること」とされている。"},{"label":"b","text":"授乳中の人は、「相談すること」とされている。"},{"label":"c","text":"けいれんの症状がある人は、「相談すること」とされている。"},{"label":"d","text":"出産予定日１２週以内の妊婦は、「使用（服用）しないこと」とされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3（a誤・b正・c誤・d誤）。手引きの別表（使用上の注意の記載）で、ロペラミド塩酸塩は「授乳中の人」の相談対象（乳汁中に移行する可能性がある成分）に挙げられているためbは正しい。肝臓病の診断を受けた人を「相談すること」とするのは、解熱鎮痛成分・小柴胡湯・ピペラジン・サントニン等で、ロペラミドは含まれないためaは誤り。けいれんの症状がある人の相談対象はピペラジンを含む成分であり、ロペラミドではないためcは誤り。出産予定日12週以内の妊婦を「使用しないこと」とするのはアスピリン、アスピリンアルミニウム、イブプロフェンで、ロペラミドは該当しないためdは誤り（ロペラミドで年齢に関して使用しないこととされるのは15歳未満の小児）。","tags":["ロペラミド塩酸塩","使用上の注意","止瀉薬"]},{"id":"R8-84","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":84,"stem":"一般用医薬品及び要指導医薬品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品及び要指導医薬品は、薬剤師その他の医薬関係者から提供された情報に基づく需要者の選択により使用されることが目的とされているものである。"},{"label":"b","text":"検体の採取に身体への直接のリスクを伴う検査薬（例えば、血液を検体とするもの）は、一般用医薬品又は要指導医薬品として認められていない。"},{"label":"c","text":"要指導医薬品の効能効果の表現は、診断疾患名（例えば、胃炎、胃・十二指腸潰瘍等）で示される。"},{"label":"d","text":"適正な使用のために薬剤師の対面による販売又は授与が行われることが特に必要な要指導医薬品として、厚生労働大臣が薬事審議会の意見を聴いて指定する要指導医薬品を「特定要指導医薬品」という。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"正解は1（a正・b正・c誤・d正）。aは正しく、一般用医薬品・要指導医薬品は、薬剤師その他の医薬関係者から提供された情報に基づく需要者の選択により使用されることが目的とされている（法第4条第5項）。bも正しく、検体の採取に身体への直接のリスクを伴う検査薬（血液を検体とするもの等）は認められない。cは誤りで、診断疾患名（胃炎、胃・十二指腸潰瘍等）で効能効果を示すのは医療用医薬品であり、要指導医薬品・一般用医薬品では、一般の生活者が判断できる症状（胃痛、胸やけ等）で示される。dは正しく、薬剤師の対面による販売・授与が特に必要な要指導医薬品として厚生労働大臣が薬事審議会の意見を聴いて指定するものを特定要指導医薬品という（法第4条第3項第4号ロ）。","tags":["要指導医薬品","一般用医薬品","特定要指導医薬品"]},{"id":"R8-88","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":88,"stem":"法第５０条の規定に基づき、一般用医薬品の直接の容器又は直接の被包に記載されていなければならない事項について、誤っているものを選べ。ただし、厚生労働省令で定める表示の特例に関する規定は考慮しなくてよい。","statements":[],"options":[{"n":1,"text":"一般用医薬品のリスク区分を示す字句"},{"n":2,"text":"配置販売品目以外の一般用医薬品にあっては、「店舗専用」の文字"},{"n":3,"text":"日本薬局方に収載されている医薬品以外の医薬品における有効成分の名称及びその分量"},{"n":4,"text":"製造番号又は製造記号"},{"n":5,"text":"効能、効果又は性能"}],"answer":5,"explanation":"誤っているものは5。「効能、効果又は性能」は、法第50条が定める直接の容器・被包への記載事項には含まれず、添付文書等（法第52条第2項）に記載される事項である。1（一般用医薬品のリスク区分を示す字句）、2（配置販売品目以外の一般用医薬品の「店舗専用」）、3（日本薬局方に収載されていない医薬品の有効成分の名称及びその分量）、4（製造番号又は製造記号）は、いずれも法第50条・施行規則に基づく容器等への記載事項なので正しい。","tags":["法定表示","法第50条","容器・被包"]},{"id":"R8-92","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":92,"stem":"薬局に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品を取り扱う場所であって、薬局として開設の許可を受けていないものについては、病院又は診療所の調剤所を除き、薬局の名称を付してはならない。"},{"label":"b","text":"薬局において、一般用医薬品を取り扱うためには、薬局の開設許可と併せて店舗販売業の許可も受ける必要がある。"},{"label":"c","text":"薬局の開店時間のうち、当該薬局において調剤に従事する薬剤師が、当該薬局以外の場所においてその業務を行うため、やむを得ず、かつ、一時的に当該薬局において薬剤師が不在になる時間を薬剤師不在時間という。"},{"label":"d","text":"薬局の管理者は、保健衛生上支障を生ずるおそれがないよう、その薬局に勤務するその他の従業者を監督しなければならない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"正解は1（a正・b誤・c正・d正）。aは正しく、薬局の許可を受けていない場所には、病院又は診療所の調剤所を除き、薬局の名称を付してはならない（法第6条、施行規則）。bは誤りで、薬局は開設許可のみで一般用医薬品を含めて取り扱えるため、店舗販売業の許可を重ねて受ける必要はない。cは正しく、薬局の開店時間のうち、調剤に従事する薬剤師が薬局以外の場所で業務を行うため、やむを得ず、かつ一時的に薬剤師が不在となる時間を薬剤師不在時間という（施行規則第1条）。dは正しく、薬局の管理者は、薬局に勤務するその他の従業者を監督するなど必要な注意をしなければならない（法第8条第1項）。","tags":["薬局","薬剤師不在時間","薬局の管理者"]},{"id":"R8-96","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":96,"stem":"医薬品の陳列に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"要指導医薬品と一般用医薬品は、混在しないように陳列しなければならない。"},{"label":"b","text":"店舗販売業者は、鍵をかけた陳列設備又は購入する者等が直接手の触れられない陳列設備に陳列する場合を除いて、第一類医薬品を薬局等構造設備規則に規定する第一類医薬品陳列区画の内部の陳列設備に陳列しなければならない。"},{"label":"c","text":"指定第二類医薬品は、鍵をかけた陳列設備に陳列する場合を除き、薬局等構造設備規則に規定する「情報提供を行うための設備」から１０メートル以内の範囲に陳列しなければならない。"},{"label":"d","text":"薬局開設者であれば、第三類医薬品と医薬部外品を混在して陳列することができる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"正解は1（a正・b正・c誤・d誤）。aは正しく、要指導医薬品と一般用医薬品は混在しないように陳列しなければならない（施行規則第218条の3第2号）。bも正しく、第一類医薬品は第一類医薬品陳列区画の内部に陳列するのが原則で、鍵をかけた陳列設備や、購入者等が直接手の触れられない陳列設備に陳列する場合は除かれる（第218条の4第1項第1号）。cは誤りで、指定第二類医薬品を陳列するのは情報提供を行うための設備から7メートル以内であり、10メートルではない（同項第2号）。dは誤りで、薬局開設者であっても、医薬品は他の物（医薬部外品を含む）と区別して貯蔵・陳列しなければならない（法第57条の2第1項）。","tags":["医薬品の陳列","情報提供を行うための設備","7メートル"]},{"id":"R8-100","chapter":4,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":100,"stem":"法に基づく行政庁による監視指導及び処分に関する記述の正誤について、正しい組合せを選べ。なお、本問において、「都道府県知事」とは、「都道府県知事（薬局又は店舗販売業にあっては、その薬局又は店舗の所在地が保健所を設置する市又は特別区の区域にある場合においては、市長又は区長。）」とする。","statements":[{"label":"a","text":"都道府県知事は、薬事監視員に、薬局開設者が医薬品を業務上取り扱う場所に立ち入り、関係者に質問させることができる。"},{"label":"b","text":"都道府県知事は、店舗販売業者に対して、その構造設備が基準に適合せず、又はその構造設備によって不良医薬品を生じるおそれがある場合においては、その構造設備の改善を命ずることができる。"},{"label":"c","text":"厚生労働大臣は、薬局開設者に対し、不正表示医薬品、不良医薬品等について、廃棄、回収その他公衆衛生上の危険の発生を防止するに足りる措置を採るべきことを命ずることができる。"},{"label":"d","text":"医薬品の製造販売業者が、その医薬品の使用によって保健衛生上の危害が発生し、又は拡大するおそれがあることを知ったとき、これを防止するための措置として回収を行う際には、行政庁による命令が必要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"正解は1（a正・b正・c正・d誤）。aは正しく、都道府県知事は薬事監視員に、薬局開設者が医薬品を業務上取り扱う場所へ立ち入り、関係者に質問させることができる（法第69条）。bも正しく、都道府県知事は、店舗販売業者の構造設備が基準に適合しない場合や、不良医薬品を生じるおそれがある場合に、その改善を命ずることができる（法第72条第4項）。cは正しく、不正表示医薬品・不良医薬品等について、厚生労働大臣又は都道府県知事は、業務上取り扱う者に対し廃棄・回収その他の措置を命ずることができる（法第70条第1項）。dは誤りで、製造販売業者は保健衛生上の危害の発生・拡大を防ぐため、行政庁の命令を待たずに自ら回収その他必要な措置を採る義務があり（法第68条の9）、回収する場合は行政庁への報告（法第68条の11）を行う。","tags":["監視指導","廃棄・回収命令","構造設備改善命令"]},{"id":"R8-109","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":109,"stem":"医薬品副作用被害救済制度に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品又は健康食品を適正に使用したにもかかわらず発生した副作用に対し、被害者の迅速な救済を図るため、製薬企業の社会的責任に基づく公的制度として運営が開始された。"},{"label":"b","text":"医薬品を適正に使用して生じた健康被害であっても、特に医療機関での治療を要さずに寛解したような軽度のものについては給付対象に含まれない。"},{"label":"c","text":"製品不良など、製薬企業に損害賠償責任がある場合の健康被害についても救済制度の対象となる。"},{"label":"d","text":"要指導医薬品又は一般用医薬品の使用による副作用被害への救済給付の請求に当たっては、その医薬品を販売等した薬局開設者、医薬品の販売業者が作成した販売証明書等が必要となる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"正解は4（a誤・b正・c誤・d正）。aは誤りで、この制度の対象は医薬品を適正に使用したにもかかわらず生じた副作用による健康被害であり、いわゆる健康食品（無承認無許可医薬品）の使用による被害は対象から除外されている。bは正しく、適正使用による健康被害でも、医療機関での治療を要さずに寛解したような軽度のものは給付対象に含まれない（入院相当の医療を要する程度などが対象）。cは誤りで、製品不良など製薬企業に損害賠償責任がある場合は救済制度の対象外であり、その場合は医薬品PLセンターへの相談が推奨される。dは正しく、要指導医薬品・一般用医薬品の給付請求には、医師の診断書等に加えて、販売した薬局開設者・販売業者が作成する販売証明書等が必要となる。","tags":["医薬品副作用被害救済制度","給付対象","販売証明書"]},{"id":"R8-120","chapter":5,"source":"関西広域連合 令和8年度 登録販売者試験 後半","no":120,"stem":"一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に、「胃酸過多の症状のある人」と記載することとされている医薬品成分・薬効群等の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"カフェインを含む成分を主薬とする眠気防止薬"},{"label":"b","text":"水酸化アルミニウムゲルが配合された胃腸薬"},{"label":"c","text":"大黄甘草湯"},{"label":"d","text":"オキセサゼインが配合された胃腸薬"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"正解は5（a正・b誤・c誤・d誤）。「次の人は使用（服用）しないこと」のうち「胃酸過多の症状のある人」と記載するのは、カフェイン、無水カフェイン、カフェインクエン酸塩等のカフェインを含む成分を主薬とする眠気防止薬で、カフェインが胃液の分泌を亢進し症状を悪化させるおそれがあるためである（aは正しい）。水酸化アルミニウムゲルが配合された胃腸薬は、長期連用でアルミニウム脳症等のおそれがあるため「透析療法を受けている人」が対象で、胃酸過多ではない（b誤）。大黄甘草湯は瀉下作用のある漢方処方製剤で、この項目には挙げられていない（c誤）。オキセサゼインは、15歳未満の小児や妊婦が「使用しないこと」の対象となる成分で、胃酸過多ではない（d誤）。","tags":["使用上の注意","胃酸過多","カフェイン","眠気防止薬"]},{"id":"R6-1","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":1,"stem":"医薬品の本質に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"人体に対して使用されない医薬品は、人体がそれに曝されても健康を害するおそれはない。"},{"label":"b","text":"医薬品が人体に及ぼす作用は複雑、かつ、多岐に渡り、必ずしも期待される有益な効果（薬効）のみをもたらすとは限らない。"},{"label":"c","text":"医薬品は、人の疾病の診断、治療若しくは予防に使用されること、又は人の身体の構造や機能に影響を及ぼすことを目的とする生命関連製品であるが、保健衛生上のリスクを伴うものではない。"},{"label":"d","text":"医薬品について、法では健康被害の発生の可能性がある場合のみ、異物等の混入、変質等があってはならない旨を定めている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"医薬品は人体に直接使われない場合でも、使い方や判断を誤れば健康被害につながり得るため、aは誤りです。bは医薬品が薬効以外の作用も併せ持つという基本どおりで正しい記述です。cは、医薬品が生命関連製品であると同時に保健衛生上のリスクを伴うものなので誤りです。dは、法が健康被害の可能性の有無にかかわらず異物混入や変質のある医薬品の販売等を禁じているため誤りで、正解はbのみ正しい3です。","tags":["医薬品の本質","医薬品の品質"]},{"id":"R6-2","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":2,"stem":"医薬品の効果とリスク評価に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品は、少量の投与であれば、長期投与された場合でも毒性が発現することはない。"},{"label":"b","text":"医薬品の投与量が治療量上限を超えると、やがて効果よりも有害反応が強く発現する「中毒量」となり、「最小致死量」を経て、「致死量」に至る。"},{"label":"c","text":"医薬品の効果とリスクは、用量と作用強度の関係（用量−反応関係）に基づいて評価される。"},{"label":"d","text":"LD50とは動物実験における最小致死量のことであり、薬物の毒性の指標として用いられる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"少量の投与でも長期に続けば慢性的な毒性が出る場合があるため、aは誤りです。bは、中毒量から最小致死量を経て致死量に至るという用量と反応の流れの説明そのもので正しい記述です。cも、効果とリスクは用量-反応関係で評価されるという内容で正しいです。dのLD50は最小致死量ではなく、動物実験で求める50%致死量であるため誤りで、正解は3です。","tags":["用量-反応関係","LD50"]},{"id":"R6-3","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":3,"stem":"医薬品のリスク評価に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"新規に開発される医薬品のリスク評価は、医薬品の安全性に関する非臨床試験の基準であるGood Laboratory Practice（GLP）の他に、医薬品毒性試験法ガイドラインに沿った各種毒性試験が厳格に実施されている。"},{"label":"b","text":"ヒトを対象にした臨床試験の実施の基準には、国際的にGood Vigilance Practice（GVP）が制定されている。"},{"label":"c","text":"医薬品に対しては製造販売後の調査及び試験の実施の基準として、Good Post-marketing Study Practice（GPSP）が制定されている。"},{"label":"d","text":"医薬品の安全性基準は、食品よりも厳しくない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"aは、新規医薬品のリスク評価でGLPと毒性試験ガイドラインに沿った各種試験が行われるという内容で正しいです。bは、ヒトを対象とする臨床試験の基準として制定されているのはGCPであり、GVPは製造販売後安全管理の基準なので誤りです。cのGPSPは製造販売後の調査・試験の基準で正しい記述です。dは、医薬品には食品よりもはるかに厳しい安全性基準が求められるので誤りで、正解は4です。","tags":["GLP/GCP/GPSP/GVP","リスク評価"]},{"id":"R6-4","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":4,"stem":"健康食品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"健康増進や維持の助けとなることが期待される、いわゆる「健康食品」は、医薬品とは法律上区別される。"},{"label":"b","text":"健康食品は、カプセルや錠剤等の医薬品に類似した形状で発売されているものも多く、誤った使用方法により健康被害を生じた例も報告されている。"},{"label":"c","text":"「特定保健用食品」は、事業者の責任で科学的根拠をもとに疾病に罹患していない者の健康維持及び増進に役立つ機能を商品のパッケージに表示するものとして国に届出された商品で、国に個別の許可を受けたものではない。"},{"label":"d","text":"「栄養機能食品」は、身体の健全な成長や発達、健康維持に必要な栄養成分（ビタミン、ミネラルなど）の補給を目的としたもので、国が定めた規格基準に適合したものであれば、その栄養成分の健康機能を表示できる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"健康食品はあくまで食品であり医薬品とは法律上区別されるので、aは正しいです。bも、医薬品に似た形状の製品があり誤使用で健康被害の報告があるという内容で正しいです。cは機能性表示食品の説明であり、特定保健用食品は個別に国の審査を受けて許可されたものなので誤りです。dの栄養機能食品は、規格基準に適合すれば栄養成分の機能を表示できる自己認証制度で正しく、正解は2です。","tags":["健康食品","保健機能食品"]},{"id":"R6-5","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":5,"stem":"医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"世界保健機関（WHO）の定義によれば、医薬品の副作用とは、「疾病の予防、診断、治療のため又は身体の機能を正常化するために、人に通常用いられる量で発現する医薬品の有害かつ意図しない反応」とされている。"},{"label":"b","text":"複数の疾病を有する人の場合、ある疾病のために使用された医薬品の作用によって、別の疾病に対して症状を悪化させることがある。"},{"label":"c","text":"医薬品が人体に及ぼす作用は、すべてが解明されていないが、十分注意して適正に使用すれば、副作用が生じることはない。"},{"label":"d","text":"医薬品の販売等に従事する専門家は、一般用医薬品を継続して使用する購入者等に特段の異常が認められない場合、医療機関の受診を促す必要はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"aはWHOによる副作用の定義どおりで正しいです。bも、複数の疾病がある人では、ある疾病のための薬が別の疾病を悪化させ得るという内容で正しいです。cは、医薬品の作用がすべて解明されているわけではなく、適正に使用しても副作用は起こり得るため誤りです。dは、副作用は自覚症状が出にくいこともあるので、継続使用する人には異常がなくても受診を促すことが重要とされており誤りです。正解は1です。","tags":["副作用","WHO定義"]},{"id":"R6-6","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":6,"stem":"アレルギーに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"通常の免疫反応の場合、炎症やそれに伴って発生する痛み、発熱等は、人体にとって有害なものを体内から排除するための必要な過程である。"},{"label":"b","text":"アレルギーは、医薬品の薬理作用等とは無関係に起こり得る。"},{"label":"c","text":"過去に医薬品でアレルギーを起こしたことがない人であれば、病気等に対する抵抗力が低下している場合であっても、医薬品でアレルギーを生じることはない。"},{"label":"d","text":"カゼインは、アレルギーを引き起こすことのない添加物である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"通常の免疫反応での炎症や痛み、発熱は、有害なものを排除する必要な過程なので、aは正しいです。アレルギーはあらゆる物質で起こり得て薬理作用とは無関係に生じるため、bも正しいです。cは、普段アレルギーがない人でも抵抗力が低下しているとアレルギーを起こすことがあるので誤りです。dのカゼインはアレルゲンとなり得る添加物の例に挙げられており誤りで、正解は1です。","tags":["アレルギー","添加物"]},{"id":"R6-7","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":7,"stem":"一般用医薬品の適正使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"症状の改善等がなされないまま、一般用医薬品の使用を漫然と続けているような場合には、副作用を招く危険性が増加する。"},{"label":"b","text":"指示どおりの使用量で一般用医薬品を使用しても、長期連用により精神的な依存が起こることがある。"},{"label":"c","text":"青少年は、薬物乱用の危険性に関する認識や理解が十分であり、薬物を興味本位で乱用することはない。"},{"label":"d","text":"医薬品の販売等に従事する専門家は、必要以上の大量購入や頻回購入を試みる者に対して、積極的に事情を尋ねるなどの対策を講じることが望ましい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"症状が改善しないまま漫然と使い続けると副作用の危険が増すため、aは正しいです。bも、指示どおりの量でも長期連用で精神的依存が起こり得るので正しいです。cは、青少年は薬物乱用の危険性の認識が必ずしも十分でなく、興味本位で乱用することがあるため誤りです。dは、大量購入や頻回購入をする人には積極的に事情を尋ねるなどの対応が望ましいとされ正しく、正解は1です。","tags":["適正使用","乱用・依存"]},{"id":"R6-8","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":8,"stem":"他の医薬品との相互作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品の相互作用は、医薬品の薬理作用をもたらす部位でのみ起こる。"},{"label":"b","text":"複数の医薬品を併用した場合、医薬品の作用が増強することはあるが、減弱することはない。"},{"label":"c","text":"一般用医薬品のかぜ薬や解熱鎮痛薬等では、成分や作用が重複することが少ないため、通常、これらの医薬品を併用することが望ましい。"},{"label":"d","text":"複数の疾病を有する人では、疾病ごとにそれぞれ医薬品が使用される場合が多く、医薬品同士の相互作用に関して特に注意が必要である。"}],"options":[{"n":1,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":1,"explanation":"相互作用には、吸収・分布・代謝・排泄の過程で起こるものと薬理作用の部位で起こるものがあるため、aは誤りです。bは、併用で作用が増強することも減弱することもあるので誤りです。cは、かぜ薬や解熱鎮痛薬などでは成分や作用が重複することが多く、通常は併用を避けるのが原則なので誤りです。dは、複数の疾病がある人は疾病ごとに薬が使われやすく相互作用に特に注意が必要という内容で正しく、正解は1です。","tags":["相互作用","成分の重複"]},{"id":"R6-9","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":9,"stem":"食品と医薬品の相互作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"食品と医薬品の相互作用は、しばしば「飲み合わせ」と表現され、食品と飲み薬が体内で相互作用を生じる場合が主に想定される。"},{"label":"b","text":"酒類（アルコール）をよく摂取する者では、肝臓の代謝機能が高まっていることが多く、アセトアミノフェンの薬効が強く現れることがある。"},{"label":"c","text":"カフェインを含む総合感冒薬とコーヒーを一緒に服用しても、カフェインの過剰摂取にはならない。"},{"label":"d","text":"外用薬や注射薬であれば、食品の摂取によって、これら医薬品の作用や代謝が影響を受ける可能性はない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"aは、食品と飲み薬が体内で相互作用を生じる場合が主に想定されるという説明どおりで正しいです。bは、アルコールをよく摂る人では肝臓の代謝機能が高まり、アセトアミノフェンは代謝されやすく十分な薬効が得られないことがあるため、薬効が強く出るとする点が誤りです。cは、カフェイン含有の総合感冒薬とコーヒーの併用で過剰摂取になり得るので誤りです。dは、外用薬や注射薬でも食品の影響を受ける可能性があるため誤りです。正解は4です。","tags":["食品との飲み合わせ","アセトアミノフェン"]},{"id":"R6-10","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":10,"stem":"小児等への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"乳児向けの用法用量が設定されている医薬品であれば、乳児は医薬品の使用により状態が急変することはない。"},{"label":"b","text":"乳幼児は、医薬品が喉につかえると、大事に至らなくても咳き込んで吐き出し苦しむことになり、その体験から医薬品の服用に対する拒否意識を生じることがある。"},{"label":"c","text":"「医療用医薬品の添付文書等の記載要領の留意事項」（平成29年6月8日付け薬生安発0608第1号厚生労働省医薬・生活衛生局安全対策課長通知別添）において、おおよその目安として、小児は5歳以上、15歳未満との年齢区分が用いられている。"},{"label":"d","text":"大人に比べて小児は、吸収されて循環血液中に移行した医薬品の成分が脳に達しやすい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"乳児は状態が急変しやすく、用法用量が設定された薬でも影響を受けやすいので、aは誤りです。bは、喉につかえた体験が服用への拒否意識につながるという内容で正しいです。cは、留意事項通知の年齢区分で小児は7歳以上15歳未満とされており、5歳以上ではないので誤りです。dは、小児は血液脳関門が未発達で成分が脳に達しやすいため正しく、正解は4です。","tags":["小児","年齢区分"]},{"id":"R6-11","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":11,"stem":"高齢者への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"基礎体力や生理機能の衰えの度合いに個人差はほとんどない。"},{"label":"b","text":"医薬品の取り違えや飲み忘れを起こしやすいなどの傾向があるため、家族や周囲の人（介護関係者等）の理解や協力が重要となる。"},{"label":"c","text":"医薬品の説明を理解するのに時間がかかる場合があり、情報提供や相談対応において特段の配慮が必要となる。"},{"label":"d","text":"医薬品の副作用で口渇を生じることがあり、誤嚥を誘発しやすくなるので注意が必要である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"高齢者でも基礎体力や生理機能の衰えの度合いは個人差が大きいので、aは誤りです。bは、取り違えや飲み忘れが起こりやすく、家族や介護関係者の理解と協力が重要という内容で正しいです。cは、説明の理解に時間がかかる場合があり特段の配慮が必要という内容で正しいです。dは、副作用による口渇が誤嚥を誘発しやすくなるという記述で正しく、正解は4です。","tags":["高齢者","誤嚥"]},{"id":"R6-12","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":12,"stem":"妊婦又は妊娠していると思われる女性への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"胎盤には、胎児の血液と母体の血液とが混ざりあう仕組みがあるため、妊婦が医薬品を使用した場合は胎児へ医薬品の成分が容易に移行する。"},{"label":"b","text":"購入者等にとって、妊娠の有無は他人に知られたくない場合もあることから、一般用医薬品の販売等に従事する専門家がその内容について聞き取る必要はない。"},{"label":"c","text":"体の変調や不調に対して、一般用医薬品を使用することにより症状を緩和したいという相談があった場合、一般用医薬品の販売等に従事する専門家は、その対処が適切かどうかを含めて慎重に考慮する必要がある。"},{"label":"d","text":"一般用医薬品において、多くの場合、妊婦が使用した場合における安全性に関する評価が困難であるため、妊婦の使用については「相談すること」としているものが多い。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"胎盤には胎児と母体の血液が混ざらない仕組み（血液-胎盤関門）があり、成分の移行がどこまで防がれるかは未解明の点も多いため、aは誤りです。bは、妊娠の有無は他人に知られたくない場合もあるので配慮が必要という趣旨で、聞き取る必要がないとまでは言えず誤りです。cは、一般用医薬品による対処が適当かを含めて慎重に考える必要があるので正しいです。dは、安全性評価が困難で「相談すること」とするものが多いという内容で正しく、正解は4です。","tags":["妊婦","血液-胎盤関門"]},{"id":"R6-13","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":13,"stem":"医療機関で治療を受けている人等への医薬品の使用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"生活習慣病等の慢性疾患では、一般用医薬品を使用することでその症状が悪化することはない。"},{"label":"b","text":"医療機関・薬局で交付された薬剤を使用している人について、登録販売者は一般用医薬品との併用の可否を容易に判断できることが多い。"},{"label":"c","text":"疾患の程度や購入しようとする医薬品の種類等に応じて、問題を生じるおそれがあれば使用を避けることができるよう情報提供がなされることが重要である。"},{"label":"d","text":"医療機関での治療を特に受けていない場合であっても、医薬品の種類や配合成分等によっては、特定の症状がある人が使用するとその症状を悪化させるおそれがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"慢性疾患では一般用医薬品の使用で症状が悪化したり治療が妨げられたりすることがあるため、aは誤りです。医療機関・薬局で交付された薬剤を使っている人について、登録販売者が併用の可否を判断することは困難なことが多く、医師や薬剤師への相談を促す必要があるので、bも誤りです。cは、問題を生じるおそれがあれば使用を避けられるよう情報提供することが重要という内容で正しく、dも治療を受けていなくても特定の症状を悪化させる場合があるので正しいです。正解は5です。","tags":["医療機関受診中","情報提供"]},{"id":"R6-14","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":14,"stem":"医薬品の品質に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品は、購入された後すぐに使用されるとは限らないため、外箱等に記載されている「使用期限」から十分な余裕をもって販売することが重要である。"},{"label":"b","text":"医薬品は、高い水準で均一な品質が保証されていなければならない。"},{"label":"c","text":"医薬品の外箱等に記載されている「使用期限」は、開封状態で保管された場合でも品質が保持される期限である。"},{"label":"d","text":"医薬品は、適切な保管・陳列がなされていれば、経時変化による品質の劣化は起こらない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"一般用医薬品は購入後すぐ使われるとは限らないので、使用期限に十分余裕をもって販売することが重要で、aは正しいです。bは、高い水準で均一な品質の保証が必要という内容で正しいです。cは、使用期限は未開封で保管した場合に品質が保たれる期限であり、開封状態を前提にしていないため誤りです。dは、適切に保管・陳列しても経時変化による劣化は避けられないので誤りです。正解は3です。","tags":["医薬品の品質","使用期限"]},{"id":"R6-15","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":15,"stem":"適切な医薬品選択と受診勧奨に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般用医薬品は、医療機関での治療を受けるほどではない体調不良や疾病の初期段階、あるいは日常において、生活者が自らの疾病の治療、予防又は生活の質の改善・向上を図ることを目的として用いられる。"},{"label":"b","text":"一般用医薬品の役割の一つに、生活習慣病の治療がある。"},{"label":"c","text":"一般用医薬品であっても、使用すればドーピングに該当する成分を含むものがあるため、スポーツ競技者から相談があった場合は、専門知識を有する薬剤師などへの確認が必要である。"},{"label":"d","text":"乳幼児や妊婦等では、一般用医薬品で対処可能な範囲は、通常の成人の場合に比べ限られてくることがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":3,"explanation":"一般用医薬品は、医療機関を受けるほどではない不調や病気の初期、日常のQOL向上などを目的とするため、aは正しいです。bは、役割として挙がるのは生活習慣病等に伴う症状発現の予防であって、生活習慣病の治療ではないので誤りです。cは、ドーピングに該当し得る成分があるため薬剤師などへの確認が必要という内容で正しいです。dも、乳幼児や妊婦では対処できる範囲が限られるという内容で正しく、正解は3です。","tags":["一般用医薬品の役割","受診勧奨","ドーピング"]},{"id":"R6-16","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":16,"stem":"一般用医薬品の販売時のコミュニケーションに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"登録販売者は、全ての一般用医薬品の販売、情報提供等を担う観点から、一般の生活者のセルフメディケーションに対して支援していくという姿勢で臨むことが基本となる。"},{"label":"b","text":"購入者等が自分自身や家族の健康に対する責任感を持ち、適切な医薬品を選択して、適正に使用するよう働きかけていくことが重要である。"},{"label":"c","text":"購入者側に情報提供を受けようとする意識が乏しい場合は、情報提供を行うためのコミュニケーションを図る必要はない。"},{"label":"d","text":"購入者等が医薬品を使用する状況は随時変化する可能性があるため、販売数量は一時期に使用する必要量とする等、販売時のコミュニケーションの機会を継続的に確保するよう配慮することが重要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"aは、登録販売者が担うのは第二類・第三類医薬品の販売や情報提供であり、全ての一般用医薬品ではないため誤りです。bは、購入者が責任感を持って適切に選び使うよう働きかけることが重要という内容で正しいです。cは、情報提供を受ける意識が乏しい場合でも、情報を引き出すコミュニケーション技術を身につけるべきとされるので誤りです。dは、販売数量を一時期の必要量にして継続的にコミュニケーションの機会を確保するという内容で正しく、正解は5です。","tags":["販売時のコミュニケーション","セルフメディケーション"]},{"id":"R6-17","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":17,"stem":"サリドマイド及びサリドマイド訴訟に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"解熱鎮痛薬として販売されたサリドマイド製剤を妊娠している女性が使用したことにより、出生児に四肢欠損、耳の障害等の先天異常（サリドマイド胎芽症）が発生した。"},{"label":"b","text":"サリドマイドの血管新生を妨げる作用は、サリドマイドの光学異性体のうち、一方の異性体のみが有する作用であるため、もう一方の異性体を分離して製剤化すれば避けることができる。"},{"label":"c","text":"妊娠している女性がサリドマイドを摂取した場合、サリドマイドは血液−胎盤関門を通過して胎児に移行する。"},{"label":"d","text":"1961年11月、西ドイツ（当時）のレンツ博士がサリドマイド製剤の催奇形性について警告を発し、西ドイツでは製品が回収されたことに伴い、日本でも、同年中に速やかに販売停止及び回収措置が取られた。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"サリドマイド製剤は催眠鎮静剤等として販売されたもので、解熱鎮痛薬ではないため、aは誤りです。bは、血管新生を妨げるS体だけを分離しても、R体とS体は体内で相互に転換するため催奇形性は避けられず誤りです。cは、サリドマイドが血液-胎盤関門を通過して胎児に移行するという内容で正しいです。dは、日本では販売停止と回収が1962年9月まで遅れ、対応の遅さが問題視されたので誤りです。正解は2です。","tags":["サリドマイド","薬害"]},{"id":"R6-18","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":18,"stem":"HIV訴訟に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"血友病患者が、ヒト免疫不全ウイルス（HIV）が混入した原料血漿から製造された免疫グロブリン製剤の投与を受けたことにより、HIVに感染したことに対する損害賠償訴訟である。"},{"label":"b","text":"本訴訟の和解を踏まえ、国は、薬害の再発を防止するための様々な取り組みを推進したが、その後、サリドマイド訴訟、スモン訴訟が相次いで起こった。"},{"label":"c","text":"本訴訟を踏まえ、医薬品の副作用等による健康被害の再発防止に向けた取り組みの一つとして、製薬企業に対し、感染症報告の義務づけ等を内容とする薬事法の改正が行われた。"},{"label":"d","text":"本訴訟を契機に、血液製剤の安全確保対策として検査や献血時の問診の充実が図られた。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"HIV訴訟で投与されたのは、原料血漿から作られた血液凝固因子製剤であり、免疫グロブリン製剤ではないため、aは誤りです。bは、HIV訴訟より前にサリドマイド訴訟とスモン訴訟があり、その和解後に再び薬害が起きたという流れなので誤りです。cは、感染症報告の義務づけ等を含む薬事法改正が行われたので正しいです。dも、血液製剤の検査や献血時の問診の充実が図られたので正しく、正解は2です。","tags":["HIV訴訟","薬害"]},{"id":"R6-19","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":19,"stem":"クロイツフェルト・ヤコブ病（CJD）及びCJD訴訟に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"CJD訴訟とは、脳外科手術等に用いられていたヒト乾燥硬膜を介してCJDに罹患したことに対する損害賠償訴訟である。"},{"label":"b","text":"CJD訴訟は、生物由来製品による感染等被害救済制度が創設等される契機のひとつとなった。"},{"label":"c","text":"CJDは、次第に認知症に類似した症状が現れ、死に至る重篤な神経難病である。"},{"label":"d","text":"CJDは、細菌でもウイルスでもない脂質の一種であるプリオンが原因とされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"CJD訴訟はヒト乾燥硬膜を介してCJDに感染した患者による損害賠償訴訟なので、aは正しいです。bも、この訴訟が生物由来製品による感染等被害救済制度の創設などの契機になったので正しいです。cは、認知症に類似した症状が現れ死に至る重篤な神経難病という説明どおりです。dは、プリオンは脂質ではなくタンパク質の一種であるため誤りで、正解は3です。","tags":["CJD訴訟","プリオン"]},{"id":"R6-20","chapter":1,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":20,"stem":"C型肝炎訴訟に関する記述について、（　）の中に入れるべき字句の正しい組合せを選べ。なお、複数箇所の（ b ）内は同じ字句が入る。\n出産や手術での大量出血などの際に特定の（ a ）や血液凝固第IX因子製剤の投与を受けたことにより、C型肝炎ウイルスに感染したことに対する損害賠償訴訟である。（ b ）を被告として、2002年から2007年にかけて、5つの地裁で提訴されたが、判決は（ b ）が責任を負うべき期間等について判断が分かれていた。このような中、C型肝炎ウイルス感染者の早期・一律救済の要請にこたえるべく、（ c ）によって、2008年1月に特別措置法が制定、施行された。","statements":[],"options":[{"n":1,"text":"a アルブミン製剤 / b 国及び製薬企業 / c 議員立法"},{"n":2,"text":"a アルブミン製剤 / b 国及び医療機関 / c 厚生労働省"},{"n":3,"text":"a フィブリノゲン製剤 / b 国及び医療機関 / c 議員立法"},{"n":4,"text":"a フィブリノゲン製剤 / b 国及び製薬企業 / c 厚生労働省"},{"n":5,"text":"a フィブリノゲン製剤 / b 国及び製薬企業 / c 議員立法"}],"answer":5,"explanation":"この訴訟で投与されたのは特定のフィブリノゲン製剤と血液凝固第IX因子製剤なので、aはフィブリノゲン製剤です。被告は国及び製薬企業で、判決は両者が責任を負うべき期間等について分かれていました。早期・一律救済のため、2008年1月の特別措置法は議員立法で制定されたのでcは議員立法です。したがって正解は5です。","tags":["C型肝炎訴訟","薬害"]},{"id":"R6-61","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":61,"stem":"消化酵素に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"唾液腺から分泌される唾液には、デンプンをアミノ酸に分解する消化酵素が含まれる。"},{"label":"b","text":"胃から分泌されるペプシノーゲンは、胃酸により、タンパク質を半消化するペプシンとなる。"},{"label":"c","text":"膵液に含まれるトリプシノーゲンは、消化管内で半消化されたタンパク質をさらに細かく消化するトリプシンに変換される。"},{"label":"d","text":"脂質（トリグリセリド）は、膵液に含まれるエレプシンにより分解され、小腸粘膜より吸収される。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"aは誤り。唾液に含まれるアミラーゼはデンプンをデキストリンや麦芽糖に分解するもので、アミノ酸まで分解するわけではない。bは正しく、ペプシノーゲンが胃酸の作用でペプシンとなり、タンパク質を半消化する。cも正しく、膵液中のトリプシノーゲンが腸で活性型のトリプシンに変わり、半消化されたタンパク質をさらに細かく分解する。dは誤りで、エレプシンは小腸の腸液側で働く酵素であり、脂質の分解は膵液中のリパーゼが担う。","tags":["消化酵素","消化器系"]},{"id":"R6-62","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":62,"stem":"咽頭、喉頭及び食道に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"咽頭は鼻腔と口腔につながっており、消化管と気道の両方に属する。"},{"label":"b","text":"喉頭は、咽頭と気管の間にある軟骨に囲まれた円筒状の器官で、軟骨の突起した部分（喉頭隆起）がいわゆる「のどぼとけ」である。"},{"label":"c","text":"食道は直径１～２ｃｍの管状の器官で、消化液を分泌する。"},{"label":"d","text":"嚥下の際には、喉頭の入り口にある喉頭蓋が反射的に開くことにより、飲食物が食道へと送られる。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":1,"explanation":"aは正しく、咽頭は食物の通り道と気道が交わる場所である。bも正しく、喉頭は咽頭と気管の間にある軟骨に囲まれた器官で、喉頭隆起がのどぼとけにあたる。cは誤りで、食道は消化液を分泌する腺を持たず、食物は蠕動運動で胃へ送られる。dも誤りで、嚥下の際は喉頭蓋が反射的に「閉じる」ことで飲食物が気管に入らず食道へ向かう。開くのではない点に注意する。","tags":["咽頭・喉頭・食道","嚥下"]},{"id":"R6-63","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":63,"stem":"呼吸器系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"気道は上気道、下気道に分かれ、喉頭は上気道に含まれる。"},{"label":"b","text":"鼻汁は、鼻腔の内壁にある粘液分泌腺から、かぜやアレルギーのときの防御反応としてのみ分泌される。"},{"label":"c","text":"肺は内部で気管支が細かく枝分かれし、末端はブドウの房のような構造となっており、その球状の袋部分を肺胞という。"},{"label":"d","text":"肺胞の壁は非常に薄くできていて、周囲を毛細血管が網のように取り囲んでいる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"aは正しく、咽頭・喉頭までを上気道、気管から肺までを下気道という。bは誤りで、鼻汁は湿り気を与え粘膜を保護するため常に少しずつ分泌されており、かぜやアレルギーのときに大量に出るのは防御反応の一つにすぎない。「のみ」が誤り。cは正しく、気管支の末端が房状になった球状の袋が肺胞。dも正しく、肺胞の壁は薄く、周囲を毛細血管が網状に取り囲んでガス交換を行う。","tags":["呼吸器系","肺胞"]},{"id":"R6-64","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":64,"stem":"循環器系に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"心臓の左側部分（左心房、左心室）は、全身から集まってきた血液を肺へ送り出す。"},{"label":"b","text":"心臓は心筋でできた握りこぶし大の袋状の臓器で、胸骨の後方に位置する。"},{"label":"c","text":"心臓から拍出された血液を送る静脈は弾力性があり、圧力がかかっても耐えられる。"},{"label":"d","text":"四肢を通る静脈では一定の間隔で静脈弁が発達しており、血液の逆流を防いでいる。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"aは誤りで、左心房・左心室は肺でガス交換を終えた血液を全身へ送り出す。肺へ送るのは右側である。bは正しく、心臓は心筋でできた握りこぶし大の袋状の臓器で胸骨の後方にある。cは誤りで、圧力に耐える弾力性を持つのは動脈であり、静脈ではない。dは正しく、四肢の静脈には一定間隔で静脈弁があり、血液の逆流を防いでいる。","tags":["循環器系","動脈と静脈"]},{"id":"R6-65","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":65,"stem":"泌尿器系に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ネフロンは、腎小体と尿細管で構成される。"},{"label":"b","text":"腎臓は血液中の老廃物の除去のほか、水分及び電解質の排出調節を行っている。"},{"label":"c","text":"腎臓には内分泌腺としての機能があり、骨髄での血小板産生を促進するホルモンを分泌する。"},{"label":"d","text":"食品から摂取あるいは体内で生合成されたビタミンＤは、腎臓で活性型ビタミンＤに転換されて、骨の形成や維持の作用を発揮する。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"aは正しく、腎小体と尿細管でネフロンを構成する。bも正しく、腎臓は老廃物の除去に加え、水分と電解質の排出を調節する。cは誤りで、腎臓が分泌して産生を促すホルモンは骨髄での赤血球産生に関わるもので、血小板ではない。dは正しく、ビタミンDは腎臓で活性型に転換され、骨の形成や維持に働く。","tags":["泌尿器系","腎臓"]},{"id":"R6-66","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":66,"stem":"目に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"涙液にはリゾチームや免疫グロブリン等が含まれており、角膜や結膜を感染から防ぐ役割がある。"},{"label":"b","text":"水晶体は、その周りを囲んでいる毛様体の収縮・弛緩によって、遠くの物を見るときには丸く厚みが増し、近くの物を見るときには扁平になる。"},{"label":"c","text":"目の充血は血管が拡張して赤く見える状態であるが、結膜の充血では白目の部分だけでなく眼瞼（まぶた）の裏側も赤くなる。"},{"label":"d","text":"眼精疲労は、眼筋の疲労や、毛様体の疲労、涙液の供給不足等により生じ、全身症状を伴わない生理的な目の疲れである。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"aは正しく、涙液はリゾチームや免疫グロブリンを含み、角膜や結膜を感染から守る。bは誤りで、遠近の調節は逆であり、近くを見るときに水晶体が丸く厚くなり、遠くを見るときに扁平になる。cは正しく、結膜の充血は白目だけでなくまぶたの裏側も赤くなる点で目の充血と区別される。dは誤りで、肩こりや頭痛などの全身症状を伴う慢性的な疲れが眼精疲労であり、「生理的で全身症状を伴わない疲れ」は疲れ目の説明である。","tags":["目","水晶体","眼精疲労"]},{"id":"R6-67","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":67,"stem":"鼻及び耳に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"鼻腔上部の粘膜にある嗅細胞を、においの元となる物質の分子が刺激すると、その刺激が脳の嗅覚中枢へ伝えられる。"},{"label":"b","text":"鼻腔と副鼻腔を連絡する管は非常に狭いため、鼻腔粘膜が腫れると副鼻腔の開口部がふさがりやすくなり、副鼻腔に炎症を生じることがある。"},{"label":"c","text":"副鼻腔に入った埃等の粒子は、粘液に捉えられて、線毛の働きによって鼻腔内へ排出される。"},{"label":"d","text":"鼓膜まで伝導された音は、鼓膜を振動させ、互いに連結した微細な３つの耳小骨が鼓膜の振動を増幅して、中耳へ音を伝える。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"aは正しく、鼻腔上部の嗅細胞がにおい分子で刺激され、嗅覚中枢へ伝えられる。bも正しく、鼻腔と副鼻腔をつなぐ管は狭く、鼻粘膜が腫れると開口部がふさがって副鼻腔炎を生じやすい。cも正しく、副鼻腔に入った埃などは粘液に捉えられ、線毛の働きで鼻腔内へ排出される。dは誤りで、耳小骨が鼓膜の振動を増幅して伝える先は内耳であり、中耳ではない（耳小骨自体が中耳にある）。","tags":["鼻","耳","副鼻腔"]},{"id":"R6-68","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":68,"stem":"皮膚に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"外皮系は、皮膚、皮膚腺、角質の総称である。"},{"label":"b","text":"皮膚の色は、表皮や真皮に沈着したメラニン色素によるものであるが、毛の色についてはメラニン色素の量による影響を受けない。"},{"label":"c","text":"ヒトの皮膚の表面には常に一定の微生物が付着しており、それら微生物の存在によって、皮膚の表面での病原菌の繁殖が抑えられている。"},{"label":"d","text":"汗腺には、エクリン腺とアポクリン腺の二種類があり、エクリン腺は体臭腺である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"aは正しく、皮膚、汗腺や皮脂腺などの皮膚腺、爪や毛などの角質を総称して外皮系という。bは誤りで、毛の色もメラニン色素の量によって決まる。cは正しく、皮膚表面に常在する微生物が病原菌の繁殖を抑えている。dは誤りで、体臭腺と呼ばれるのはアポクリン腺であり、エクリン腺は全身に分布して体温調節などの汗を分泌する。","tags":["皮膚","外皮系","汗腺"]},{"id":"R6-69","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":69,"stem":"骨格系及び筋組織に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"骨の成長が停止すると骨吸収と骨形成は行われず、カルシウムが骨から溶け出し骨密度は低下する。"},{"label":"b","text":"骨の関節面は、弾力性に富む柔らかい軟骨層に覆われており、衝撃を和らげ、関節の動きを滑らかにしている。"},{"label":"c","text":"骨格筋の疲労は、乳酸の代謝に伴って生成するグリコーゲンが蓄積し、筋組織の収縮性が低下する現象である。"},{"label":"d","text":"心臓壁にある筋組織は、消化管壁や膀胱等に分布する筋と同様に、自律神経に支配される平滑筋に分類される。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"aは誤りで、骨は成長が止まった後も一生を通じて骨吸収と骨形成を繰り返し、そのバランスで骨密度が保たれる。bは正しく、関節面は弾力のある軟骨層に覆われ、衝撃を和らげ動きを滑らかにする。cは誤りで、乳酸が蓄積して収縮性が低下するのであり、乳酸の代謝で生じるのがグリコーゲンという記述は逆。dも誤りで、心筋は自律神経に支配される不随意筋だが、平滑筋ではなく横紋のある別の種類（心筋）に分類される。","tags":["骨格系","筋組織","骨吸収"]},{"id":"R6-70","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":70,"stem":"脳や神経系の働きに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"脊髄は脊椎の中にあり、脳と末梢の間で刺激を伝えるほか、末梢からの刺激の一部に対して脳を介さずに刺激を返す場合があり、これを脊髄反射と呼ぶ。"},{"label":"b","text":"脳は、細胞同士が複雑かつ活発に働くため、酸素の消費量は全身の約５０％を占める。"},{"label":"c","text":"自律神経系は、交感神経系と副交感神経系からなり、多くの効果器に対し、これら二つの神経系が支配している。"},{"label":"d","text":"全身に広く分布する汗腺を支配する交感神経線維の末端では、アセチルコリンが神経伝達物質として放出される。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"aは正しく、脊髄反射は末梢からの刺激に対し脳を介さず反応を返す仕組み。bは誤りで、脳の酸素消費量は全身の約20%であり、約50%ではない。cは正しく、多くの効果器は交感神経系と副交感神経系の二重支配を受ける。dも正しく、汗腺を支配する交感神経線維の末端は例外的にアセチルコリンを放出する（通常の交感神経末端はノルアドレナリン）。","tags":["神経系","自律神経","脊髄反射"]},{"id":"R6-71","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":71,"stem":"薬の有効成分の吸収に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"内服薬の有効成分は、主に胃で吸収される。"},{"label":"b","text":"鼻腔粘膜の下には毛細血管が豊富なため、点鼻薬の成分は循環血液中に移行しやすい。"},{"label":"c","text":"坐剤の有効成分は直腸下部の粘膜から吸収されると、肝臓で代謝を受けた後、全身に分布する。"},{"label":"d","text":"皮膚に適用する医薬品（塗り薬、貼り薬等）の有効成分が皮膚表面から血液中に移行した場合、肝臓で代謝を受ける前に血流に乗って全身に分布する。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"aは誤りで、内服薬の有効成分は主に小腸で吸収される。bは正しく、鼻腔粘膜の下には毛細血管が豊富で、点鼻薬の成分は循環血液中に移行しやすい。cは誤りで、直腸下部の静脈血は肝臓を経由せずに心臓へ向かうため、坐剤の成分は肝臓で代謝を受けずに全身へ分布する（肝で代謝を受けるのは直腸上部から吸収された場合）。dは正しく、皮膚から血液中へ移行した成分は肝臓の代謝を受ける前に全身へ分布する。","tags":["薬の吸収","剤形","肝初回通過効果"]},{"id":"R6-72","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":72,"stem":"薬の代謝、排泄に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"有効成分が体内で代謝を受けると、作用を失ったり、作用が現れたり、あるいは体外へ排泄されやすい水溶性の物質に変化したりする。"},{"label":"b","text":"有効成分の体外への排泄経路として母乳中もあるが、その排泄量は微量であるため、乳児に対する副作用の発現の点では重要ではない。"},{"label":"c","text":"経口投与後、消化管で吸収されて血液中に移行した有効成分は、全身循環に入る前に、門脈という血管を経由して腎臓を通過する。"},{"label":"d","text":"腎機能が低下した人では、正常の人よりも有効成分の尿中への排泄が過剰となり、血中濃度が速やかに低下する。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"aは正しく、代謝により作用が失われる場合、作用が現れる場合、排泄されやすい水溶性の物質になる場合がある。bは誤りで、母乳中への排泄量は少ないものの、乳児への副作用の点では軽視できない。cは誤りで、消化管から吸収された成分は門脈を経て「肝臓」を通過し、まず代謝を受ける（肝初回通過効果）。腎臓ではない。dは誤りで、腎機能が低下すると排泄が遅れて血中濃度が下がりにくくなり、効きすぎや副作用が出やすくなる。","tags":["薬の代謝","排泄","門脈"]},{"id":"R6-73","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":73,"stem":"薬の体内での働きに関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"循環血液中に移行した有効成分は、多くの場合、標的となる細胞に存在する受容体、酵素、トランスポーターなどのタンパク質と結合し、その機能を変化させることで薬効や副作用を現す。"},{"label":"b","text":"医薬品が摂取された後、有効成分の血中濃度は上昇し、ある時点でピークに達するが、代謝・排泄の速度が吸収・分布の速度を上回ると低下していく。"},{"label":"c","text":"医薬品の有効成分がわずかでも循環血液中に移行すると、生体の反応としての薬効が現れる。"},{"label":"d","text":"一度に大量の医薬品を摂取したり、十分な間隔をあけずに追加摂取したりして血中濃度を高くしても、ある濃度以上になると薬効は頭打ちとなり、有害な作用（副作用や毒性）も現れにくくなる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"aは正しく、有効成分は標的細胞の受容体・酵素・トランスポーターなどのタンパク質と結合して薬効や副作用を現す。bも正しく、血中濃度はピークに達した後、代謝・排泄が吸収・分布を上回ると低下する。cは誤りで、薬効が現れるには血中濃度が一定以上（最小有効濃度以上）になる必要があり、わずかでも移行すれば現れるわけではない。dは誤りで、濃度を上げても薬効は頭打ちになる一方、副作用や毒性は現れやすくなる。","tags":["薬の作用","血中濃度"]},{"id":"R6-74","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":74,"stem":"内服用医薬品の剤形及びその一般的な特徴に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般的に、錠剤（内服）は、胃や腸で崩壊し、有効成分が溶出することが薬効発現の前提となる。"},{"label":"b","text":"口腔内崩壊錠は、固形物を飲み込むことが困難な高齢者や乳幼児でも、口の中で溶かした後に、唾液と一緒に飲み込むことができる。"},{"label":"c","text":"顆粒剤は、粒の表面がコーティングされているものもあるので、噛み砕かずに水などで飲み込む。"},{"label":"d","text":"カプセル剤は、水なしで服用するとゼラチンが喉や食道に貼り付くことがあるため、必ず適切な量の水（又はぬるま湯）とともに服用する。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"aは正しく、錠剤（内服）は胃や腸で崩壊して有効成分が溶出することが薬効の前提となる。bは正しく、口腔内崩壊錠は口の中で溶かして唾液と一緒に飲み込めるため、飲み込みが難しい人にも向く。cは正しく、顆粒剤は表面がコーティングされたものがあるので噛み砕かずに服用する。dも正しく、カプセル剤は水なしだとゼラチンが喉や食道に貼り付くおそれがあり、適切な量の水かぬるま湯で服用する。よって全て正しい。","tags":["剤形","内服薬"]},{"id":"R6-75","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":75,"stem":"医薬品の副作用として現れる肝機能障害及び偽アルドステロン症に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品により生じる肝機能障害の主な症状には、全身の倦怠感、黄疸のほか、発熱、発疹、皮膚の掻痒感、吐きけ等がある。"},{"label":"b","text":"黄疸とは、グロブリンが胆汁中へ排出されず、血液中に滞留することにより生じる、皮膚や白眼が黄色くなる病態である。"},{"label":"c","text":"偽アルドステロン症は、体から塩分（ナトリウム）と水が失われ、体内にカリウムが貯留することによって生じる病態である。"},{"label":"d","text":"偽アルドステロン症は、小柄な人や高齢者で生じやすく、原因医薬品の長期服用後に初めて発症する場合もある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"aは正しく、肝機能障害の主な症状は倦怠感、黄疸、発熱、発疹、かゆみ、吐きけなど。bは誤りで、黄疸は「ビリルビン（黄色色素）」が胆汁中へ排出されず血液中に滞留して生じ、グロブリンではない。cは誤りで、偽アルドステロン症は体内にナトリウムと水が貯留し、カリウムが失われる病態であり、記述は逆。dは正しく、体表面積の小さい人や高齢者で生じやすく、長期服用後に初めて発症することもある。","tags":["肝機能障害","偽アルドステロン症","副作用"]},{"id":"R6-76","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":76,"stem":"精神神経系に現れる医薬品の副作用に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"中枢神経系が影響を受け、物事に集中できない、落ち着きがなくなる等のほか、不眠、不安、震え（振戦）、興奮、眠気、うつ等の精神神経症状を生じることがある。"},{"label":"b","text":"精神神経症状は、医薬品の添付文書に記載されている通常の用法・用量では発生することはない。"},{"label":"c","text":"無菌性髄膜炎は、医薬品の副作用が原因の場合、全身性エリテマトーデス、関節リウマチ等の基礎疾患がある人で発症リスクが高い。"},{"label":"d","text":"医薬品の副作用が原因で軽度の無菌性髄膜炎を経験した人は、同じ医薬品を使用しても再発することはない。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":2,"explanation":"aは正しく、中枢神経系が影響を受けて集中困難、不眠、不安、振戦、興奮、眠気、うつなどが現れることがある。bは誤りで、精神神経症状は大量服用や長期連用など不適正な使用に限らず、通常の用法・用量でも起こり得る。cは正しく、医薬品による無菌性髄膜炎は全身性エリテマトーデスや関節リウマチなどの基礎疾患がある人でリスクが高い。dは誤りで、過去に軽度の無菌性髄膜炎を経験した人が同じ医薬品を使うと再発し、急激に進行することがある。","tags":["精神神経系","無菌性髄膜炎","副作用"]},{"id":"R6-77","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":77,"stem":"消化器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"消化性潰瘍とは、胃や十二指腸の粘膜組織が傷害されているが、粘膜組織の欠損は粘膜筋板を超えない状態をいう。"},{"label":"b","text":"副作用による消化性潰瘍は、自覚症状が乏しい場合もあり、突然の吐血・下血によって発見されることもある。"},{"label":"c","text":"イレウス様症状（腸閉塞様症状）では、腹痛などの症状のために水分や食物の摂取が抑制され、嘔吐がない場合でも脱水状態となることがある。"},{"label":"d","text":"小児や高齢者のほか、普段から便秘傾向にある人は、イレウス様症状の発症のリスクが高い。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"aは誤りで、消化性潰瘍は粘膜組織の欠損が粘膜筋板を超えて深く及ぶ状態をいう。粘膜筋板を超えないものではない。bは正しく、自覚症状に乏しく、突然の吐血・下血で見つかることもある。cは正しく、イレウス様症状では腹痛のため水分や食物の摂取が減り、嘔吐がなくても脱水になることがある。dも正しく、小児・高齢者や普段から便秘傾向にある人はリスクが高い。","tags":["消化性潰瘍","イレウス様症状","副作用"]},{"id":"R6-78","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":78,"stem":"呼吸器系に現れる医薬品の副作用に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"間質性肺炎は、気管支又は肺胞が細菌に感染して炎症を生じたものである。"},{"label":"b","text":"間質性肺炎を発症すると、体内は低酸素状態となり、呼吸困難、空咳（痰の出ない咳）、発熱等の症状を呈する。"},{"label":"c","text":"医薬品を原因とする喘息は、内服薬にのみ生じ、坐薬や外用薬では誘発されない。"},{"label":"d","text":"合併症を起こさない限り、喘息の原因となった医薬品の有効成分が体内から消失すれば、症状は寛解する。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"aは誤りで、細菌感染による炎症は通常の肺炎の説明であり、間質性肺炎は肺胞と毛細血管を支える組織（間質）の炎症である。bは正しく、ガス交換効率が下がって低酸素状態となり、呼吸困難、空咳、発熱が現れる。cは誤りで、医薬品による喘息は内服薬のほか、坐薬や外用薬でも誘発されることがある。dは正しく、合併症がなければ原因成分が体内から消失すれば症状は寛解する。","tags":["間質性肺炎","喘息","副作用"]},{"id":"R6-79","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":79,"stem":"循環器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"うっ血性心不全とは、心筋の自動性や興奮伝導の異常が原因で心臓の拍動リズムが乱れる病態である。"},{"label":"b","text":"息切れ、疲れやすい、足のむくみ、急な体重の増加、咳とピンク色の痰などを認めた場合は、うっ血性心不全の可能性がある。"},{"label":"c","text":"不整脈は、医薬品の代謝機能の低下によって発症リスクが高まることがあるので、腎機能や肝機能の低下、併用薬との相互作用等に留意するべきである。"},{"label":"d","text":"医薬品を適正に使用した場合であっても、動悸や一過性の血圧上昇、顔のほてり等を生じることがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"aは誤りで、記述は不整脈の説明。うっ血性心不全は、全身が必要とする血液量を心臓が送り出せなくなる病態である。bは正しく、息切れ、疲れやすさ、足のむくみ、急な体重増加、咳とピンク色の痰は、うっ血性心不全の可能性を示す症状。cは正しく、不整脈は代謝機能の低下で発症リスクが高まるため、腎機能・肝機能の低下や併用薬に留意する。dも正しく、適正に使用しても動悸、一過性の血圧上昇、顔のほてりなどが生じることがある。","tags":["うっ血性心不全","不整脈","副作用"]},{"id":"R6-80","chapter":2,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":80,"stem":"泌尿器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"副交感神経系の機能を亢進する作用がある成分が配合された医薬品を使用すると、膀胱の排尿筋の収縮が抑制され、尿が出にくくなる。"},{"label":"b","text":"医薬品による排尿困難や尿閉は、前立腺肥大の基礎疾患がある男性にのみ現れる。"},{"label":"c","text":"医薬品による排尿困難や尿閉等の症状が現れた場合、原因となる医薬品の使用を中止することにより症状は速やかに改善することが多い。"},{"label":"d","text":"尿の回数増加、排尿時の疼痛、残尿感等の膀胱炎様症状が現れることがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"aは誤りで、排尿筋の収縮が抑制されて尿が出にくくなるのは、副交感神経系の機能を「抑制」する成分を使ったときである。亢進すると逆の作用になる。bは誤りで、前立腺肥大などの基礎疾患がない人や女性でも現れる。cは正しく、多くの場合は原因薬の使用中止で速やかに改善するが、処置が必要な場合もある。dは正しく、頻尿、排尿時痛、残尿感などの膀胱炎様症状が現れることがある。","tags":["排尿困難・尿閉","膀胱炎様症状","副作用"]},{"id":"R6-21","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":21,"stem":"かぜ及びその治療に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"かぜ薬は、原因となるウイルスの増殖を抑えたり、体内から除去することにより、かぜの諸症状の緩和を図るものである。"},{"label":"b","text":"原因となるウイルスには、ライノウイルス、アデノウイルスなどがある。"},{"label":"c","text":"発熱、咳、鼻水など症状がはっきりしている場合には、総合感冒薬ではなく、それぞれの症状に合わせて薬を選択することが望ましい。"},{"label":"d","text":"急激な発熱を伴う場合や、症状が4日以上続くとき、又は症状が重篤なときは、かぜではない可能性が高い。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"かぜ薬はウイルスの増殖を抑えたり体内から除去したりするものではなく、咳や発熱などの症状を和らげる対症療法薬である。したがってaは誤り。原因ウイルスにはライノウイルス、コロナウイルス、アデノウイルスなどがあり(b正)、症状がはっきりしている場合は総合感冒薬よりも症状に合わせた薬を選ぶことが望ましい(c正)。急な発熱、4日以上続く症状、重い症状はかぜ以外の疾患の可能性が高い(d正)。","tags":["かぜ","かぜ薬の働き"]},{"id":"R6-23","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":23,"stem":"かぜ薬（総合感冒薬）の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"解熱鎮痛成分として、サリチルアミド、イソプロピルアンチピリン等が用いられる。"},{"label":"b","text":"エテンザミドは、15歳未満の小児で水痘にかかっているときは使用を避ける。"},{"label":"c","text":"アドレナリン作動成分として、クレマスチンフマル酸塩が用いられる。"},{"label":"d","text":"抗コリン成分として、グリチルリチン酸二カリウムが用いられる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":1,"explanation":"サリチルアミドやイソプロピルアンチピリンはかぜ薬の解熱鎮痛成分であり(a正)、エテンザミドは15歳未満の小児で水痘(現行版ではインフルエンザも)にかかっているときは使用を避ける(b正)。クレマスチンフマル酸塩は抗ヒスタミン成分でありアドレナリン作動成分ではない(c誤)。グリチルリチン酸二カリウムは抗炎症成分であり抗コリン成分ではない(d誤)。","tags":["かぜ薬","配合成分"]},{"id":"R6-24","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":24,"stem":"かぜの症状緩和に用いられる漢方処方製剤のうち、体力虚弱な人に用いるものの組合せを選べ。","statements":[{"label":"a","text":"葛根湯"},{"label":"b","text":"桂枝湯"},{"label":"c","text":"小柴胡湯"},{"label":"d","text":"香蘇散"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"かぜの漢方処方のうち、桂枝湯は体力虚弱で汗が出るもののかぜの初期、香蘇散は体力虚弱で神経過敏・胃腸の弱いもののかぜの初期に用いるとされ、体力虚弱向けである。葛根湯は体力中等度以上、小柴胡湯は体力中等度で、いずれも虚弱な人には向かないとされる。よってb、dの組合せが正しい。","tags":["漢方","かぜ"]},{"id":"R6-25","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":25,"stem":"解熱鎮痛薬（生薬成分を除く。）及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"発熱や痛みの原因となっている病気や外傷を根本的に治すことを目的とする。"},{"label":"b","text":"飲酒によって、解熱鎮痛薬による胃腸障害が増強する可能性がある。"},{"label":"c","text":"アスピリンには血液を凝固しにくくさせる作用がある。"},{"label":"d","text":"アスピリン喘息は、アスピリン特有の副作用ではなく、他の解熱鎮痛成分でも生じる可能性がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"解熱鎮痛薬は病気や外傷そのものを治すものではなく、発熱や痛みを緩和する対症療法薬なのでaは誤り。飲酒は胃粘膜の荒れを通じて解熱鎮痛成分による胃腸障害を増強するおそれがある(b正)。アスピリンには血液を凝固しにくくさせる作用がある(c正)。アスピリン喘息はアスピリン特有ではなく、他の解熱鎮痛成分でも起こりうる(d正)。","tags":["解熱鎮痛薬","アスピリン"]},{"id":"R6-26","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":26,"stem":"鎮痛の目的で用いられる漢方処方製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"呉茱萸湯は、体力中等度以下で、手足が冷えて肩がこり、ときにみぞおちが膨満するものの頭痛、頭痛に伴う吐きけ・嘔吐、しゃっくりに適すとされる。"},{"label":"b","text":"釣藤散は、体力に関わらず使用でき、筋肉の急激な痙攣を伴う痛みのあるもののこむらがえり、筋肉の痙攣、腹痛、腰痛に適すとされる。"},{"label":"c","text":"桂枝加朮附湯は、体力虚弱で、汗が出、手足が冷えてこわばり、ときに尿量が少ないものの関節痛、神経痛に適すとされる。"},{"label":"d","text":"芍薬甘草湯は、体力中等度で、慢性に経過する頭痛、めまい、肩こりなどがあるものの慢性頭痛、神経症、高血圧の傾向のあるものに適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":1,"explanation":"呉茱萸湯は体力中等度以下で手足が冷えて肩がこり、頭痛や吐きけを伴うものに用いるとされ、aは正しい。桂枝加朮附湯は体力虚弱で汗が出て手足が冷えてこわばるものの関節痛・神経痛で、cも正しい。bの筋肉の痙攣を伴う痛みやこむらがえりに用いるのは芍薬甘草湯であり、釣藤散ではないので誤り。dの慢性頭痛・高血圧傾向は釣藤散の説明で、芍薬甘草湯ではないため誤り。","tags":["漢方","鎮痛"]},{"id":"R6-27","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":27,"stem":"一般用医薬品の解熱鎮痛薬購入者に対する登録販売者の説明について、適切なものの組合せを選べ。","statements":[{"label":"a","text":"発熱が1週間以上続く場合は、服用量を増やしてください。"},{"label":"b","text":"年月の経過に伴って月経痛が悪化している場合は、病院を受診してください。"},{"label":"c","text":"頭痛に対して使用する場合には、症状が出る前に服用してください。"},{"label":"d","text":"肝機能障害を起こすことがあるので、服用期間中の飲酒はやめてください。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"月経痛が年月とともに悪化する場合は子宮内膜症などの可能性があり、受診を勧める(b適切)。解熱鎮痛成分はアルコールにより肝機能障害などの副作用を起こしやすくなるおそれがあるため、服用期間中の飲酒は避ける(d適切)。発熱が1週間以上続く場合は他の重い病気の可能性があり、服用量を増やすのではなく受診を勧める(a不適切)。頭痛薬は症状が軽いうちに使うと効果的だが、症状が出る前の予防的使用は適切でない(c不適切)。","tags":["解熱鎮痛薬","受診勧奨"]},{"id":"R6-28","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":28,"stem":"眠気防止薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"小児用の眠気防止薬はない。"},{"label":"b","text":"かぜ薬を使用したことによる眠気を抑えるために、眠気防止薬を使用することは適切ではない。"},{"label":"c","text":"カフェインには、腎臓におけるナトリウムイオンの再吸収抑制作用がある。"},{"label":"d","text":"眠気防止薬におけるカフェインの1回摂取量はカフェインとして20mg、1日摂取量はカフェインとして50mgが上限とされている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"成長期の小児の睡眠は重要であるため、小児用の眠気防止薬はない(a正)。かぜ薬などによる眠気を抑える目的で眠気防止薬を使うのは適切でない(b正)。カフェインには腎臓でのナトリウムイオン再吸収を抑える作用があり利尿をもたらす(c正)。眠気防止薬のカフェイン上限は1回200mg、1日500mgであり、dの20mg・50mgは誤り。","tags":["眠気防止薬","カフェイン"]},{"id":"R6-29","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":29,"stem":"乗物酔い防止薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ジフェニドール塩酸塩は、前庭神経の調節作用と内耳への血流改善作用を示す。"},{"label":"b","text":"メクリジン塩酸塩は、他の抗ヒスタミン成分と比べて作用の持続時間が短い。"},{"label":"c","text":"スコポラミン臭化水素酸塩水和物は、中枢に作用して自律神経系の混乱を軽減させるとともに、末梢では消化管緊張低下作用を示す。"},{"label":"d","text":"ジプロフィリンは、脳の興奮を抑制するキサンチン系成分である。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"ジフェニドール塩酸塩は前庭神経の調節作用と内耳への血流改善作用を示す(a正)。スコポラミン臭化水素酸塩水和物は、中枢で自律神経系の混乱を軽減し、末梢では消化管の緊張を低下させる(c正)。メクリジン塩酸塩は他の抗ヒスタミン成分に比べ作用が遅く持続が長いため、bは誤り。ジプロフィリンは脳に軽い興奮を起こすキサンチン系成分で、抑制ではないためdも誤り。","tags":["乗物酔い防止薬","配合成分"]},{"id":"R6-30","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":30,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを選べ。\n\n体力虚弱で疲労しやすく腹痛があり、血色がすぐれず、ときに動悸、手足のほてり、冷え、ねあせ、鼻血、頻尿及び多尿などを伴うものの小児虚弱体質、疲労倦怠、慢性胃腸炎、腹痛、神経質、小児夜尿症、夜なきに適すとされる。","statements":[],"options":[{"n":1,"text":"柴胡加竜骨牡蛎湯"},{"n":2,"text":"桂枝加芍薬湯"},{"n":3,"text":"小建中湯"},{"n":4,"text":"抑肝散"},{"n":5,"text":"白虎加人参湯"}],"answer":3,"explanation":"体力虚弱で疲労しやすく腹痛があり、動悸、手足のほてり、寝汗、夜尿、夜なきなどを伴うという記述は小建中湯の説明に当たる。柴胡加竜骨牡蛎湯と抑肝散は小児の夜なきに用いられる他の処方だが、体力や症状の特徴が異なる。桂枝加芍薬湯は腸の不調に、白虎加人参湯は別の分野で扱われる処方である。","tags":["漢方","小児鎮静薬"]},{"id":"R6-31","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":31,"stem":"ジヒドロコデインリン酸塩に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"使用するにあたっては、12歳以上であることの確認が必要である。"},{"label":"b","text":"母乳への移行が少ないことから、授乳中であっても服用することができる。"},{"label":"c","text":"長期連用や大量摂取によって多幸感等が現れることがあり、依存性がある。"},{"label":"d","text":"延髄の咳嗽中枢に作用して、咳を抑える。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"ジヒドロコデインリン酸塩は12歳未満の小児に使用しないこととされ、使用にあたり12歳以上であることの確認が必要である(a正)。延髄の咳嗽中枢に作用して咳を抑える(d正)。長期連用や大量摂取で多幸感などが現れ、依存性がある(c正)。一方、母乳中に移行して乳児にモルヒネ中毒が生じた報告があり、授乳中は服用しないか授乳を避けるため、bは誤り。","tags":["コデイン類","鎮咳薬"]},{"id":"R6-32","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":32,"stem":"口腔咽喉薬・含嗽薬に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"口腔咽喉薬及び含嗽薬は、口腔内や咽頭における局所的な作用を目的とする医薬品であるため、全身的な影響を生じることはない。"},{"label":"b","text":"含嗽薬は即効性があり、使用後すぐに食事を摂っても、殺菌消毒効果に対する影響はほとんどない。"},{"label":"c","text":"医薬部外品として製造販売されている製品もある。"},{"label":"d","text":"噴射式の液剤では、口腔の奥まで薬液が届くように、軽く息を吸いながら噴射することが望ましい。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"口腔咽喉薬・含嗽薬は局所作用が目的だが、成分が粘膜から吸収されて全身的な影響を生じることがあり、aは誤り。含嗽薬は使用後すぐに食事をとると殺菌消毒効果が薄れやすく、bも誤り。効能効果が限られた範囲のものは医薬部外品として製造販売されており、cは正しい。噴射式液剤は息を吸いながらだと気管支や肺に入るおそれがあり、軽く息を吐きながら噴射するのが望ましいためdは誤り。","tags":["口腔咽喉薬","含嗽薬"]},{"id":"R6-33","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":33,"stem":"次の記述にあてはまる咳止めや痰を出しやすくする目的で用いられる漢方処方製剤として、最も適切なものを選べ。\n\n体力中等度以下で、痰が切れにくく、ときに強く咳こみ、又は咽頭の乾燥感があるもののから咳、気管支炎、気管支喘息、咽頭炎、しわがれ声に適すとされるが、水様痰の多い人には不向きとされる。","statements":[],"options":[{"n":1,"text":"駆風解毒湯"},{"n":2,"text":"麦門冬湯"},{"n":3,"text":"響声破笛丸"},{"n":4,"text":"桔梗湯"},{"n":5,"text":"白虎加人参湯"}],"answer":2,"explanation":"体力中等度以下で痰が切れにくく、強く咳こんだり咽頭が乾燥したりするから咳や咽頭炎に用いられ、水様痰の多い人には不向きとされるのは麦門冬湯である。駆風解毒湯・響声破笛丸・桔梗湯は主にのどの痛みや声がれなどに用いられる処方であり、白虎加人参湯は口渇やほてりなどに用いる処方なので、記述に合わない。","tags":["漢方","鎮咳去痰"]},{"id":"R6-34","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":34,"stem":"胃に作用する薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ジメチルポリシロキサン（ジメチコン）は、制酸成分である。"},{"label":"b","text":"ピレンゼピン塩酸塩は、消化成分である。"},{"label":"c","text":"タカヂアスターゼは、健胃成分である。"},{"label":"d","text":"メタケイ酸アルミン酸マグネシウムは、胃液分泌抑制成分である。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"ジメチルポリシロキサン(ジメチコン)は消化管内の気泡を除く消泡成分であり、制酸成分ではない(a誤)。ピレンゼピン塩酸塩は胃液の分泌を抑える成分で消化成分ではない(b誤)。タカヂアスターゼは消化酵素で消化成分であり、健胃成分ではない(c誤)。メタケイ酸アルミン酸マグネシウムは胃酸を中和する制酸成分であって、胃液分泌抑制成分ではない(d誤)。","tags":["胃薬","配合成分の分類"]},{"id":"R6-35","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":35,"stem":"止瀉薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ベルベリン塩化物は、細菌感染による下痢の症状を鎮めることを目的として配合されている。"},{"label":"b","text":"天然ケイ酸アルミニウムは、腸管内の異常発酵等によって生じた有害物質を吸着することを目的として配合されている。"},{"label":"c","text":"タンニン酸アルブミンは、収斂作用により腸粘膜を保護することを目的として配合されている。"},{"label":"d","text":"ロペラミド塩酸塩が配合された止瀉薬は、食べすぎ・飲みすぎによる下痢、寝冷えによる下痢の症状に用いられることを目的としており、食あたりや水あたりによる下痢については適用対象ではない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"ベルベリン塩化物は腸内殺菌成分で、細菌感染による下痢の症状を鎮める(a正)。天然ケイ酸アルミニウムは、腸管内の異常発酵などで生じた有害物質を吸着する(b正)。タンニン酸アルブミンは収斂作用で腸粘膜を保護する(c正)。ロペラミド塩酸塩は食べすぎ・飲みすぎ、寝冷えによる下痢に用いるもので、食あたりや水あたりの下痢は適用対象でない(d正)。よって全て正しい。","tags":["止瀉薬","配合成分"]},{"id":"R6-36","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":36,"stem":"胃腸の不調を改善する目的で用いられる漢方処方製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"麻子仁丸は、体力虚弱で、疲れやすくて手足などが冷えやすいものの胃腸虚弱、下痢、嘔吐、胃痛、腹痛、急・慢性胃炎に適すとされる。"},{"label":"b","text":"六君子湯は、体力中等度以上で、下腹部痛があって、便秘しがちなものの月経不順、月経困難、月経痛、便秘、痔疾に適すとされる。"},{"label":"c","text":"大黄甘草湯は、体力に関わらず使用でき、便秘、便秘に伴う頭重、のぼせ、湿疹・皮膚炎、ふきでもの、食欲不振、腹部膨満、腸内異常発酵、痔などの症状の緩和に適すとされる。"},{"label":"d","text":"安中散は、体力中等度以下で、腹部は力がなくて、胃痛又は腹痛があって、ときに胸やけや、げっぷ、胃もたれ、食欲不振、吐きけ、嘔吐などを伴うものの神経性胃炎、慢性胃炎、胃腸虚弱に適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"aの「体力虚弱で疲れやすく手足が冷えやすい、胃腸虚弱・下痢・嘔吐」は人参湯の説明で、麻子仁丸ではないので誤り。bの「下腹部痛があって便秘しがち、月経不順・痔疾」は大黄牡丹皮湯の説明で、六君子湯ではないので誤り。cの大黄甘草湯は体力に関わらず使用でき、便秘や便秘に伴う頭重・のぼせ・痔などに適する(正)。dの安中散の説明も正しい。","tags":["漢方","胃腸薬・瀉下"]},{"id":"R6-37","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":37,"stem":"瀉下薬又は浣腸薬の購入者に対する登録販売者の説明について、不適切なものの組合せを選べ。","statements":[{"label":"a","text":"複数の瀉下薬を同時に使用しないよう説明した。"},{"label":"b","text":"センノシドが配合された瀉下薬を服用する際には、授乳を控えるように説明した。"},{"label":"c","text":"ビサコジルが配合された瀉下薬は、服用後すぐに効果があることが多いため、起床時に服用するよう説明した。"},{"label":"d","text":"グリセリンが配合された浣腸薬について、繰り返し使用することで効果が強くなると説明した。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"瀉下薬を使用している間は他の瀉下薬の併用を避けるので、aの説明は適切。センノシドは乳汁中に移行して乳児に下痢を生じるおそれがあり、授乳を避けるよう伝えるbも適切。ビサコジルなどの大腸刺激性瀉下薬は服用後数時間で効果が出るものが多く、就寝前に服用して起床時に効果を求めるのが一般的なので、cは不適切。グリセリン浣腸薬を含む浣腸薬は繰り返すと直腸の感受性が低下して効果が弱くなるため、dも不適切。","tags":["瀉下薬","浣腸薬"]},{"id":"R6-38","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":38,"stem":"胃腸鎮痛鎮痙薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"下痢を伴う腹痛の場合、基本的に下痢への対処が優先されるため、胃腸鎮痛鎮痙薬の適用となる症状ではない。"},{"label":"b","text":"チキジウム臭化物には、胃液分泌を抑える作用はない。"},{"label":"c","text":"ブチルスコポラミン臭化物は、アセチルコリンと受容体の反応を妨げる。"},{"label":"d","text":"オキセサゼインは、局所麻酔作用のほか、胃液分泌を抑える作用もあるとされる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"下痢に伴う腹痛は基本的に下痢への対処が優先され、胃腸鎮痛鎮痙薬の適用ではない(a正)。ブチルスコポラミン臭化物は抗コリン成分で、アセチルコリンと受容体の反応を妨げる(c正)。チキジウム臭化物も抗コリン成分なので胃液分泌を抑える作用があり、bは誤り。オキセサゼインは局所麻酔作用のほか胃液分泌を抑える作用もあるとされる(d正)。","tags":["胃腸鎮痛鎮痙薬","抗コリン成分"]},{"id":"R6-39","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":39,"stem":"一般用医薬品の強心薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ゴオウは強心作用のほか、末梢血管の拡張による血圧降下、興奮を静める等の作用があるとされる。"},{"label":"b","text":"ユウタンは苦味による健胃作用を期待して用いられるほか、消化補助成分として配合される場合もある。"},{"label":"c","text":"センソが配合された内服固形製剤は、口中で噛み砕くと舌等が麻痺することがある。"},{"label":"d","text":"シンジュは、中枢神経系の刺激作用による気つけの効果を期待して用いられる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":1,"explanation":"ゴオウは強心作用のほか、末梢血管の拡張による血圧降下や興奮を静める作用があるとされる(a正)。ユウタンは苦味による健胃作用に加え、消化補助成分として用いられることもある(b正)。センソ配合の内服固形製剤は口中で噛み砕くと舌などが麻痺することがあるため、噛まずに服用する(c正)。中枢神経系の刺激による気つけの効果を期待するのはリュウノウで、シンジュは鎮静作用を期待する成分なのでdは誤り。","tags":["強心薬","生薬成分"]},{"id":"R6-42","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":42,"stem":"痔及び一般用医薬品の痔疾用薬とその配合成分に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"一般に「いぼ痔」と呼ばれる痔核のうち、直腸粘膜と皮膚の境目となる歯状線より上部の、直腸粘膜にできた痔核を外痔核と呼ぶ。"},{"label":"b","text":"痔瘻は、肛門内部に存在する肛門腺窩と呼ばれる小さなくぼみに糞便の滓が溜まって炎症・化膿を生じた状態である。"},{"label":"c","text":"痔に伴う痛み・痒みを和らげることを目的に、リドカイン等の局所麻酔成分が用いられる。"},{"label":"d","text":"現在、製造販売されている一般用医薬品の痔疾用薬は、肛門部又は直腸内に適用する外用薬のみである。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":3,"explanation":"歯状線より上部の直腸粘膜にできる痔核は内痔核で、外痔核は歯状線より下部にできるため、aは誤りです。痔瘻は肛門腺窩に糞便の滓が溜まって炎症・化膿を生じた状態で、bは正しい記述です。痔の痛み・痒みには局所麻酔成分のリドカイン等が用いられ、cも正しいです。痔疾用薬には外用薬のほか内服して使う内用痔疾用薬もあるため、dは誤りです。","tags":["痔","痔核","痔瘻"]},{"id":"R6-43","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":43,"stem":"婦人薬として用いられる生薬成分及び漢方処方製剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"サフラン、コウブシは、鎮静、鎮痛のほか、女性の滞っている月経を促す作用を期待して用いられる。"},{"label":"b","text":"加味逍遙散、桃核承気湯は、構成生薬としてカンゾウを含まない。"},{"label":"c","text":"温経湯は、体力中等度以下で、手足がほてり、唇が乾くものの月経不順、月経困難、こしけ、更年期障害、不眠、神経症、湿疹・皮膚炎、足腰の冷え、しもやけ、手あれに適すとされる。"},{"label":"d","text":"桂枝茯苓丸は、体力虚弱で、冷え症で貧血の傾向があり疲労しやすいものの月経不順、月経異常、月経痛、更年期障害、腰痛、足腰の冷え症、しもやけ、むくみ、しみ、耳鳴りに適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"サフラン・コウブシは鎮静・鎮痛のほか、滞った月経を促す作用を期待して用いられ、aは正しいです。加味逍遙散と桃核承気湯はいずれも構成生薬にカンゾウを含むため、bは誤りです。温経湯の適応の記述は手引きの内容と合致し、cは正しいです。dの記述は体力虚弱で貧血傾向のものに用いる処方の特徴で、桂枝茯苓丸は比較的体力があるものに用いるとされるため誤りです。","tags":["婦人薬","漢方","カンゾウ"]},{"id":"R6-45","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":45,"stem":"鼻炎及び鼻炎用点鼻薬とその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"アレルギー性鼻炎は、鼻腔内に付着したウイルスや細菌が原因となって生じる鼻粘膜の炎症で、かぜの随伴症状として現れることが多い。"},{"label":"b","text":"ベンザルコニウム塩化物は、黄色ブドウ球菌、溶血性連鎖球菌及び結核菌に対する殺菌消毒作用を示す。"},{"label":"c","text":"テトラヒドロゾリン塩酸塩は、鼻粘膜を通っている血管を拡張させることにより、鼻粘膜の充血や腫れを和らげる。"},{"label":"d","text":"一般用医薬品の鼻炎用点鼻薬の対応範囲は、アレルギー性鼻炎及びそれに伴う副鼻腔炎、蓄膿症等である。"}],"options":[{"n":1,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"aの記述はウイルスや細菌による急性鼻炎の説明で、アレルギー性鼻炎はアレルゲンに対する過敏反応で起こるため誤りです。ベンザルコニウム塩化物は結核菌やウイルスには効果がないので、bは誤りです。テトラヒドロゾリン塩酸塩は血管を収縮させて充血や腫れを和らげるため、cは誤りです。鼻炎用点鼻薬の対応範囲に、蓄膿症などの慢性のものは含まれないので、dも誤りです。したがって全て誤りです。","tags":["鼻炎","点鼻薬","アドレナリン作動成分"]},{"id":"R6-46","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":46,"stem":"点眼薬における一般的な注意に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"コンタクトレンズをしたままでの点眼は、添付文書に使用可能と記載されてない限り行うべきでない。"},{"label":"b","text":"薬液を結膜嚢に行き渡らせるためには、点眼後にまばたきを数回行うと効果的とされる。"},{"label":"c","text":"正確に点眼するために、容器の先端を目尻につけて点眼すると良い。"},{"label":"d","text":"一度に数滴点眼することで効果が増し、副作用も起こりにくくなる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"コンタクトレンズをしたままの点眼は、添付文書に使用可能と記載されていない限り行うべきでなく、aは正しいです。点眼後はしばらくまぶたを閉じて薬液を結膜嚢に行き渡らせるのが基本で、まばたきを繰り返すと薬液が流れ出やすいため、bは誤りです。容器の先端がまぶたやまつげに触れると薬液が汚染されるため、目尻につけるcは誤りです。結膜嚢の容積は約30μLで、一度に何滴も点眼しても効果は増さず、鼻や喉から吸収されて副作用が起こりやすくなるので、dも誤りです。","tags":["点眼薬","コンタクトレンズ"]},{"id":"R6-47","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":47,"stem":"眼科用薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"パンテノールは、自律神経系の伝達物質の産生に重要な成分であり、目の調節機能の回復を促す効果を期待して用いられる。"},{"label":"b","text":"アズレンスルホン酸ナトリウムは、結膜を通っている血管を収縮させて目の充血を除去する目的で配合されている場合がある。"},{"label":"c","text":"イプシロン－アミノカプロン酸は、炎症の原因となる物質の生成を抑える作用を示し、目の炎症を改善する効果を期待して用いられる。"},{"label":"d","text":"アスパラギン酸カリウムは、角膜の乾燥を防ぐことを目的として配合されている場合がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"パンテノールは自律神経系の伝達物質の産生に重要な成分で、目の調節機能の回復を促す効果を期待して用いられ、aは正しいです。アズレンスルホン酸ナトリウムは炎症を生じた眼粘膜の組織修復を促す成分で、血管を収縮させて充血を除去する成分ではないため、bは誤りです。イプシロン-アミノカプロン酸は炎症の原因物質の生成を抑える抗炎症成分で、cは正しいです。アスパラギン酸カリウムは新陳代謝を促して目の疲れを改善する目的のアミノ酸成分で、角膜の乾燥を防ぐ成分ではないため、dは誤りです。","tags":["眼科用薬","ビタミン成分","抗炎症成分"]},{"id":"R6-48","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":48,"stem":"きず口等の殺菌消毒成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"オキシドールの作用は持続的であり、組織への浸透性は高い。"},{"label":"b","text":"きず口等の殺菌消毒成分として使用されるポビドンヨードの濃度は、含嗽薬として用いられている濃度と同じである。"},{"label":"c","text":"ヨウ素の殺菌力はアルカリ性になると低下するため、石けん等と併用する場合には、石けん分をよく洗い落としてから使用する。"},{"label":"d","text":"消毒用エタノールの粘膜（口唇等）や目の周りへの使用は、避ける必要がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"オキシドールの作用は、過酸化水素の分解で生じる活性酸素と泡立ちによるもので、持続性は乏しく組織への浸透性も低いため、aは誤りです。ポビドンヨードは口腔咽喉薬や含嗽薬より高濃度で配合されているので、bも誤りです。ヨウ素の殺菌力はアルカリ性で低下するため、石けんと併用する際は石けん分をよく洗い落とす必要があり、cは正しいです。消毒用エタノールは粘膜や目の周りへの使用を避ける必要があり、dも正しいです。","tags":["殺菌消毒成分","ヨウ素","エタノール"]},{"id":"R6-49","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":49,"stem":"打撲や捻挫等への対応に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"患部を氷嚢などで冷やすことにより、内出血を最小限にし、痛みの緩和を図る。"},{"label":"b","text":"患部を弾性包帯やサポーターで軽く圧迫し、心臓よりも高くしておくことにより、腫れを抑える。"},{"label":"c","text":"冷感刺激成分であるノニル酸ワニリルアミドが配合された外用鎮痛薬は、急性の腫れや熱感を伴う症状に対して適している。"},{"label":"d","text":"フェルビナクは、打撲、捻挫等による鎮痛を目的として用いられるステロイド性抗炎症成分である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"打撲や捻挫では、患部を氷嚢などで冷やして内出血を最小限にし痛みの緩和を図るので、aは正しいです。腫れを抑えるため、弾性包帯やサポーターで軽く圧迫して患部を心臓より高くしておくことも手引きの記載どおりで、bも正しいです。ノニル酸ワニリルアミドは冷感ではなく温感刺激成分であり、急性の腫れや熱感には冷感刺激成分が適するため、cは誤りです。フェルビナクは非ステロイド性抗炎症成分で、ステロイド性ではないので、dは誤りです。","tags":["打撲・捻挫","外用鎮痛薬","フェルビナク"]},{"id":"R6-50","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":50,"stem":"外皮用薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ケトプロフェンが配合された外皮用薬は、使用している間だけでなく使用後も当分の間、塗布部が紫外線に当たるのを避ける必要がある。"},{"label":"b","text":"創傷面に薄い皮膜を形成して保護することを目的として、ピロキシリン（ニトロセルロース）が用いられる場合がある。"},{"label":"c","text":"イオウは、皮膚の角質層を構成するケラチンを変質させることにより、角質軟化作用を示す。"},{"label":"d","text":"尿素は、角質層の水分保持量を高め、皮膚の乾燥を改善することを目的として用いられる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"ケトプロフェン配合の外皮用薬は、使用中だけでなく使用後も当分の間、塗布部が紫外線に当たるのを避ける必要があり、aは正しいです。ピロキシリン（ニトロセルロース）は創傷面に薄い皮膜をつくって保護する目的で用いられ、bも正しいです。イオウは角質層のケラチンを変質させて角質軟化作用を示し、cも正しいです。尿素は角質層の水分保持量を高めて皮膚の乾燥を改善する目的で用いられ、dも正しいです。よって全て正しい記述です。","tags":["外皮用薬","ケトプロフェン","保湿成分"]},{"id":"R6-52","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":52,"stem":"歯痛・歯槽膿漏の病態及び治療薬とその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"歯槽膿漏は、歯肉炎が重症化して、歯周組織全体に炎症が広がったものである。"},{"label":"b","text":"歯痛薬（外用）は、歯痛を鎮め、歯の齲蝕を修復することを目的として用いられる。"},{"label":"c","text":"銅クロロフィリンナトリウムは、炎症を起こした歯周組織の修復を促す作用のほか、歯肉炎に伴う口臭を抑える効果も期待して配合される。"},{"label":"d","text":"ジブカイン塩酸塩は、齲蝕を生じた部分における細菌の繁殖を抑えることを目的として配合される。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"歯肉炎が重症化して炎症が歯周組織全体に広がったものが歯周炎（歯槽膿漏）で、aは正しいです。歯痛薬（外用）は歯痛を応急的に鎮めるためのもので、齲蝕が修復されるわけではないため、bは誤りです。銅クロロフィリンナトリウムは歯周組織の修復を促し、歯肉炎に伴う口臭を抑える効果も期待して配合され、cは正しいです。ジブカイン塩酸塩は局所麻酔成分で、細菌の繁殖を抑える成分（殺菌消毒成分）ではないため、dは誤りです。","tags":["歯痛薬","歯槽膿漏","局所麻酔成分"]},{"id":"R6-53","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":53,"stem":"一般用医薬品の禁煙補助剤に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"咀嚼剤とパッチ製剤の2種類の禁煙補助剤を併用しても、ニコチンの過剰摂取のおそれはなく、禁煙達成に効果的である。"},{"label":"b","text":"咀嚼剤は、口腔内が酸性になるとニコチンの吸収が促進されるため、炭酸飲料を摂取した後はしばらく使用を避ける。"},{"label":"c","text":"禁煙補助剤は、喫煙を完全に止めたうえ使用する。"},{"label":"d","text":"重い狭心症や不整脈と診断された人では、循環器系に重大な悪影響を及ぼすおそれがあるため、使用を避ける必要がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"咀嚼剤とパッチ製剤など他のニコチン含有製剤を併用するとニコチンの過剰摂取のおそれがあるため、aは誤りです。口腔内が酸性になるとニコチンの吸収が低下するので、炭酸飲料などの摂取後は咀嚼剤の使用を避けるとされ、吸収が促進されるとするbは誤りです。禁煙補助剤は喫煙を完全に止めたうえで使用するので、cは正しいです。重い狭心症や不整脈と診断された人は循環器系に重大な悪影響のおそれがあり、使用を避ける必要があるため、dも正しいです。","tags":["禁煙補助剤","ニコチン","咀嚼剤"]},{"id":"R6-54","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":54,"stem":"滋養強壮保健薬及びその配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"体調不良を生じやすい状態や体質の改善等を目的として、ビタミン成分、カルシウム、アミノ酸、生薬成分等が配合されている。"},{"label":"b","text":"生薬成分であるゴオウ、ロクジョウの配合は、医薬品においてのみ認められている。"},{"label":"c","text":"適用となっている症状の改善を早めたい場合には、多めに摂取すれば良い。"},{"label":"d","text":"数種類の生薬をアルコールで抽出した薬用酒は、手術や出産の直後等の滋養強壮を目的として用いられる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"滋養強壮保健薬は体調不良を生じやすい状態や体質の改善などを目的に、ビタミン成分、カルシウム、アミノ酸、生薬成分等を配合した医薬品で、aは正しいです。ゴオウ、ロクジョウ等の生薬成分は医薬品においてのみ配合が認められており、bも正しいです。症状の改善を早めたいからといって多めに摂取するのは不適切で、cは誤りです。薬用酒は血行を促進する作用があり、手術や出産の直後など出血しやすい人では使用を避ける必要があるため、dは誤りです。","tags":["滋養強壮保健薬","生薬","薬用酒"]},{"id":"R6-55","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":55,"stem":"滋養強壮保健薬の配合成分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"ビタミンB2は、脂質の代謝に関与し、皮膚や粘膜の機能を正常に保つために重要な栄養素である。"},{"label":"b","text":"アミノエチルスルホン酸は、骨格筋の疲労の原因となる乳酸の分解を促す等の働きを期待して用いられる。"},{"label":"c","text":"システインは、皮膚におけるメラニンの生成を抑えるとともに、皮膚の新陳代謝を活発にしてメラニンの排出を促す働きがあるとされる。"},{"label":"d","text":"ビタミンB6は、体内の脂質を酸化から守り、細胞の活動を助ける栄養素で、血流を改善させる作用がある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"ビタミンB2は脂質の代謝に関与し、皮膚や粘膜の機能を正常に保つのに重要な栄養素で、aは正しいです。乳酸の分解を促す等の働きを期待して用いられるのはアスパラギン酸ナトリウムで、アミノエチルスルホン酸（タウリン）は肝臓機能を改善する働きがあるとされるため、bは誤りです。システインはメラニンの生成を抑え、排出を促す働きがあるとされ、cは正しいです。dの「脂質を酸化から守り血流を改善する」はビタミンEの説明で、ビタミンB6はタンパク質の代謝に関与するため誤りです。","tags":["ビタミン","アミノ酸成分","滋養強壮保健薬"]},{"id":"R6-56","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":56,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを選べ。\n\n体力中等度以下で、疲れやすく、汗のかきやすい傾向があるものの肥満に伴う関節の腫れや痛み、むくみ、多汗症、肥満症（筋肉にしまりのない、いわゆる水ぶとり）に適すとされる。","statements":[],"options":[{"n":1,"text":"黄連解毒湯"},{"n":2,"text":"防已黄耆湯"},{"n":3,"text":"防風通聖散"},{"n":4,"text":"大柴胡湯"},{"n":5,"text":"清上防風湯"}],"answer":2,"explanation":"体力中等度以下で疲れやすく、汗をかきやすい傾向があり、肥満に伴う関節の腫れや痛み、むくみ、多汗症、いわゆる水ぶとりに適すとされるのは防已黄耆湯です。同じ肥満症に使われる防風通聖散や大柴胡湯は、体力が比較的あるタイプが対象で、黄連解毒湯や清上防風湯は肥満症の処方ではありません。なお防已黄耆湯は構成生薬にカンゾウを含みます。","tags":["漢方処方製剤","防已黄耆湯","肥満症"]},{"id":"R6-57","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":57,"stem":"漢方の特徴・漢方薬使用における基本的な考え方に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"漢方薬を使用する場合、「証」に基づいて用いることが、有効性及び安全性を確保するために重要である。"},{"label":"b","text":"「皮膚の色つやが悪く」と表現される状態は、漢方の病態認識では水毒となる。"},{"label":"c","text":"漢方処方製剤に使われる生薬成分は、医薬品的な効能効果が暗示されていなければ、全て食品として流通させることができる。"},{"label":"d","text":"漢方処方製剤は、用法用量において適用年齢の下限が設けられていない場合であっても、生後6か月未満の乳児には使用しないこととされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"漢方薬は「証」に基づいて用いることが有効性・安全性の確保に重要で、aは正しいです。「皮膚の色つやが悪く」は気血水のうち血虚を表す表現で、水毒は「口渇があり尿量が減少する」などと表されるため、bは誤りです。生薬成分は医薬品的な効能効果が標榜・暗示されなければ食品として流通できるものもあるだけで、全てが可能ではないため、cは誤りです。適用年齢の下限がない漢方処方製剤でも使用しないとされるのは生後3か月未満の乳児で、6か月未満ではないため、dは誤りです。","tags":["漢方","証","乳児"]},{"id":"R6-58","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":58,"stem":"殺菌・消毒、滅菌及び消毒薬に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"滅菌は、物質中の特定の微生物を殺滅又は除去することをいう。"},{"label":"b","text":"次亜塩素酸ナトリウムは、一般細菌類、真菌類、ウイルス全般に対する殺菌消毒作用を有するため、金属性の医療機器の消毒によく用いられる。"},{"label":"c","text":"エタノールは、微生物のタンパク質の変性作用を有し、結核菌を含む一般細菌類、真菌類に対する殺菌消毒作用を示す。"},{"label":"d","text":"生息条件が整えば消毒薬の溶液中で生存、増殖する微生物もいる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"滅菌は物質中のすべての微生物を殺滅または除去することで、特定の微生物に限るわけではないため、aは誤りです。次亜塩素酸ナトリウムは金属腐食性があり、金属製の医療機器の消毒には向かないので、bも誤りです。エタノールは微生物のタンパク質を変性させ、結核菌を含む一般細菌類や真菌類に殺菌消毒作用を示し、cは正しいです。条件が整えば消毒薬の溶液中でも生存・増殖する微生物がいるため、dも正しいです。","tags":["消毒薬","滅菌","エタノール"]},{"id":"R6-59","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":59,"stem":"代表的な衛生害虫に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"ツツガムシは、ヒトへの吸血によって皮膚に発疹や痒みを引き起こすほか、日本脳炎、マラリア、黄熱、デング熱等の重篤な病気を媒介する。"},{"label":"b","text":"ペットのイヌに寄生するシラミは、ヒトにも寄生し吸血する。"},{"label":"c","text":"ゴキブリの燻蒸処理を行う場合、卵から孵化した幼虫の駆除のための燻蒸処理を、3週間位後に再度行う必要がある。"},{"label":"d","text":"トコジラミに刺されると、アレルギー反応による全身の発熱、睡眠不足、神経性の消化不良を起こすことがある。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"aは蚊の説明で、ツツガムシはツツガムシ病リケッチアを媒介するダニの一種のため誤りです。シラミは種類ごとに寄生する動物が決まっており、イヌに寄生するシラミがヒトに寄生することはないので、bも誤りです。ゴキブリの卵は薬剤が浸透しない殻に覆われるため、約3週間後にもう一度燻蒸処理をして孵化した幼虫を駆除する必要があり、cは正しいです。トコジラミに刺されると、アレルギー反応による全身の発熱、睡眠不足、神経性の消化不良を起こすことがあり、dも正しいです。","tags":["衛生害虫","ゴキブリ","トコジラミ"]},{"id":"R6-60","chapter":3,"source":"関西広域連合 令和6年度 登録販売者試験 前半","no":60,"stem":"一般用検査薬に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"検体中に検査の対象物質が存在していないにもかかわらず、検査対象外の物質と非特異的な反応が起こって検査結果が陽性となった場合を偽陽性という。"},{"label":"b","text":"原則として、尿糖検査の場合、早朝尿（起床直後の尿）を検体とし、尿タンパク検査の場合、食後2～3時間を目安に採尿を行う。"},{"label":"c","text":"妊娠検査薬は、尿中のヒト絨毛性性腺刺激ホルモン（hCG）の有無を調べるものである。"},{"label":"d","text":"近年、疾病を早期発見するために、一般用検査薬の対象として、悪性腫瘍、心筋梗塞の診断に関係するものが含まれるようになった。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":5,"explanation":"検体中に対象物質がないのに、非特異的な反応で陽性となる場合を偽陽性といい、aは正しいです。尿糖検査は食後1〜2時間等、尿タンパク検査は原則として早朝尿を検体とするため、記述が入れ替わっているbは誤りです。妊娠検査薬は尿中のヒト絨毛性性腺刺激ホルモン（hCG）の有無を調べるもので、cは正しいです。悪性腫瘍や心筋梗塞など重大な疾患の診断に関係するものは一般用検査薬の対象外であり、dは誤りです。","tags":["一般用検査薬","偽陽性","妊娠検査薬"]},{"id":"R6-81","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":81,"stem":"次の記述は、法第１条の条文である。（　）の中に入れるべき字句の正しい組合せを選べ。\n\n　この法律は、医薬品、医薬部外品、化粧品、医療機器及び再生医療等製品の品質、（　a　）及び安全性の確保並びにこれらの使用による保健衛生上の危害の発生及び拡大の防止のために必要な規制を行うとともに、（　b　）の規制に関する措置を講ずるほか、医療上特にその必要性が高い医薬品、医療機器及び再生医療等製品の（　c　）の促進のために必要な措置を講ずることにより、保健衛生の向上を図ることを目的とする。","statements":[],"options":[{"n":1,"text":"a 有効性 / b 麻薬及び覚醒剤 / c 品質向上"},{"n":2,"text":"a 有効性 / b 麻薬及び覚醒剤 / c 研究開発"},{"n":3,"text":"a 有効性 / b 指定薬物 / c 研究開発"},{"n":4,"text":"a 経済性 / b 指定薬物 / c 研究開発"},{"n":5,"text":"a 経済性 / b 指定薬物 / c 品質向上"}],"answer":3,"explanation":"法第1条は、医薬品等の「品質、有効性及び安全性」を確保するための規制、指定薬物の規制、医療上特に必要性が高い医薬品等の「研究開発」の促進を並べて保健衛生の向上を目的とする、という構成である。経済性は目的に含まれず、麻薬及び覚醒剤は別の法律で規制されているため入らない。促進されるのは品質向上ではなく研究開発なので、a有効性・b指定薬物・c研究開発の組合せである3が正しい。","tags":["法の目的","第1条"]},{"id":"R6-82","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":82,"stem":"登録販売者及び法に規定する販売従事登録に関する記述の正誤について、正しい組合せを選べ。ただし、厚生労働省令で定める書類の省略に関する規定は考慮しなくてよい。","statements":[{"label":"a","text":"販売従事登録を受けようとする者は、申請者の居住地の都道府県知事に申請書を提出しなければならない。"},{"label":"b","text":"申請書には、申請者が登録販売者試験に合格したことを証する書類を添えなければならない。"},{"label":"c","text":"申請者が薬局開設者又は医薬品の販売業者でないときは、雇用契約書の写しその他薬局開設者又は医薬品の販売業者の申請者に対する使用関係を証する書類を添えなければならない。"},{"label":"d","text":"登録事項に変更を生じたときは、３０日以内に、登録を受けた都道府県知事にその旨を届け出なければならない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"販売従事登録の申請書の提出先は、居住地ではなく、医薬品の販売又は授与に従事する薬局・店舗の所在地の都道府県知事（配置販売業は配置区域を含む都道府県の知事）なので、aは誤り。bの試験合格を証する書類、cの使用関係を証する書類（申請者が開設者・販売業者でない場合）は、いずれも申請書に添付が必要で正しい。dの登録事項の変更は30日以内に届け出るとされ正しい。よってa誤・b正・c正・d正の3が正解。","tags":["販売従事登録","登録販売者"]},{"id":"R6-83","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":83,"stem":"医薬品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"動物の疾病の治療に使用されることが目的とされているものは、法の規制対象外である。"},{"label":"b","text":"医薬品には器具用消毒薬のように、人の身体に直接使用されないものもある。"},{"label":"c","text":"日本薬局方に収載されている物は、全て法で医薬品と定義されている。"},{"label":"d","text":"薬局開設者及び医薬品の販売業者は、不正表示医薬品を販売の目的で陳列してはならない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"医薬品の定義には人だけでなく動物の疾病の治療等を目的とするものも含まれ、動物用医薬品も法の規制を受けるため、aは誤り。器具用消毒薬のように人の身体に直接使用しない医薬品もあり、日本薬局方に収載されている物は全て医薬品と定義されるので、b・cは正しい。dの不正表示医薬品は、販売・授与のほか販売目的の貯蔵・陳列も禁止されている。したがってa誤・b正・c正・d正の3が正解。","tags":["医薬品の定義","不正表示医薬品"]},{"id":"R6-84","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":84,"stem":"一般用医薬品及び要指導医薬品に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"要指導医薬品は、その適正な使用のために薬剤師又は登録販売者の対面による情報の提供及び薬学的知見に基づく指導が行われることを必要とする。"},{"label":"b","text":"医師等の診療によらなければ一般に治癒が期待できない、がん、心臓病等の疾患に対する効能効果は、要指導医薬品にのみ認められている。"},{"label":"c","text":"配置販売業は、要指導医薬品の販売は認められていない。"},{"label":"d","text":"一般用医薬品の効能効果の表現は、一般の生活者が判断できる症状で示されている。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"要指導医薬品の情報提供・指導は薬剤師が行うもので、登録販売者は行えないためaは誤り。医師の診療でなければ治癒が期待しにくいがん・心臓病等への効能効果は、要指導医薬品にも一般用医薬品にも認められておらず、bも誤り。配置販売業は一般用医薬品のみが対象で要指導医薬品は販売できず（c正）、一般用医薬品の効能効果は生活者が判断できる症状で表現される（d正）。よってc・dの5が正解。","tags":["要指導医薬品","一般用医薬品"]},{"id":"R6-85","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":85,"stem":"毒薬、劇薬及び生物由来製品に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"毒薬については、それを収める直接の容器又は被包に、赤地に白枠、白字をもって、当該医薬品の品名及び「毒」の文字が記載されていなければならない。"},{"label":"b","text":"店舗管理者が薬剤師である場合に限り、店舗販売業者は毒薬又は劇薬を開封販売することができる。"},{"label":"c","text":"生物由来製品には、植物に由来するもののみを原料又は材料として製造されるものもある。"},{"label":"d","text":"現在のところ、生物由来製品として指定された一般用医薬品はない。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"毒薬の表示は「黒地に白枠、白字」で、赤地ではないためaは誤り（劇薬は白地に赤枠、赤字）。毒薬・劇薬の開封販売は、店舗管理者が薬剤師である店舗販売業者などに限られるので、bは正しい。生物由来製品は「植物を除く」生物に由来するものが対象で、植物のみを原料とするものは該当せず、cは誤り。現在、生物由来製品に指定された一般用医薬品はなく、dは正しい。よってb・dの4が正解。","tags":["毒薬・劇薬","生物由来製品"]},{"id":"R6-86","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":86,"stem":"一般用医薬品のリスク区分に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"第一類医薬品は、その副作用等により日常生活に支障を来す程度の健康被害が生ずるおそれがあるすべての一般用医薬品が指定される。"},{"label":"b","text":"第二類医薬品のうち、特別の注意を要するものとして厚生労働大臣が指定するものを「指定第二類医薬品」という。"},{"label":"c","text":"第三類医薬品は、第一類医薬品及び第二類医薬品以外の一般用医薬品である。"},{"label":"d","text":"リスク区分については、安全性に関する新たな知見や副作用の発生状況等を踏まえて適宜見直しが図られているが、第三類医薬品が第一類医薬品又は第二類医薬品に分類が変更されることはない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":2,"explanation":"第一類医薬品に指定されるのは、日常生活に支障を来す健康被害のおそれがある医薬品のうち「特に注意が必要なもの」だけで、「すべて」とするaは誤り。bの指定第二類医薬品の説明とcの第三類医薬品の定義は正しい。リスク区分は新たな知見や副作用の発生状況で見直され、第三類が第一類・第二類に変更されることもあるため、dは誤り。a誤・b正・c正・d誤の2が正解。","tags":["リスク区分","指定第二類医薬品"]},{"id":"R6-87","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":87,"stem":"法第５０条に基づき、一般用医薬品及び要指導医薬品の直接の容器又は直接の被包に記載されていなければならない事項の正誤について、正しい組合せを選べ。ただし、厚生労働省令で定める表示の特例に関する規定は考慮しなくてよい。","statements":[{"label":"a","text":"製造販売業者の氏名又は名称及び住所"},{"label":"b","text":"製造番号又は製造記号"},{"label":"c","text":"要指導医薬品については「要指導医薬品」の文字"},{"label":"d","text":"指定第二類医薬品にあっては、枠の中に「指定」の文字"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"製造販売業者等の氏名（名称）と住所、製造番号又は製造記号、要指導医薬品の「要指導医薬品」の文字は、いずれも直接の容器等への法定表示事項であり、a・b・cは正しい。指定第二類医薬品に必要なのは、枠の中に「2」の数字を記載することで、「指定」の文字ではないためdが誤り。よってa正・b正・c正・d誤の1が正解。","tags":["法定表示","法第50条"]},{"id":"R6-88","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":88,"stem":"医薬部外品及び化粧品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬部外品には、衛生害虫類（ねずみ、はえ、蚊、のみその他これらに類する生物）の防除を目的とする物がある。"},{"label":"b","text":"医薬部外品は、化粧品的な効能効果を標榜することができる場合がある。"},{"label":"c","text":"化粧品を販売する場合には都道府県知事の許可は不要であるが、医薬部外品を販売する場合には、都道府県知事の許可が必要である。"},{"label":"d","text":"化粧品において、医薬品的な効能効果を表示・標榜することは、一切認められていない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"医薬部外品には、ねずみ・はえ・蚊・のみなど衛生害虫類の防除を目的とする製品があり（a正）、薬用化粧品のように化粧品的な効能効果を標榜できるものもある（b正）。化粧品だけでなく医薬部外品も、販売に医薬品のような販売業の許可は不要で一般小売店で販売できるため、cは誤り。化粧品で医薬品的な効能効果を表示・標榜することは一切認められておらず、dは正しい。よってa正・b正・c誤・d正の1が正解。","tags":["医薬部外品","化粧品"]},{"id":"R6-89","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":89,"stem":"保健機能食品等の食品に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"食品として販売等されている製品であっても、その成分本質、効能効果の標榜内容等に照らして医薬品とみなされる場合には、無承認無許可医薬品として法に基づく取締りの対象となる。"},{"label":"b","text":"機能性表示食品は、個別に生理的機能や特定の保健機能を示す有効性や安全性等に関する審査を受け、許可又は承認を取得することが必要である。"},{"label":"c","text":"栄養機能食品の栄養成分の機能の表示に関しては、当該栄養成分を摂取する上での注意事項を適正に表示することが求められる。"},{"label":"d","text":"特別用途食品（特定保健用食品を除く。）とは、乳児、幼児、妊産婦又は病者の発育又は健康の保持若しくは回復の用に供することが適当な旨を医学的・栄養学的表現で記載し、かつ用途を限定したものである。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"食品として売られていても、成分や標榜内容から医薬品とみなされれば無承認無許可医薬品として取締り対象になる（a正）。栄養機能食品は、栄養成分の機能とあわせて摂取上の注意事項の表示も求められる（c正）。特別用途食品（特定保健用食品を除く）の説明はdのとおりで正しい。bは特定保健用食品の説明で、機能性表示食品は事業者の責任で根拠を消費者庁長官に届け出る制度であり、個別の許可・承認は不要なため誤り。よってa正・b誤・c正・d正の2が正解。","tags":["保健機能食品","機能性表示食品"]},{"id":"R6-90","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":90,"stem":"薬局に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品を取り扱う場所であって、薬局として開設の許可を受けていないものについては、病院又は診療所の調剤所を除き、薬局の名称を付してはならない。"},{"label":"b","text":"薬局の管理者は、その薬局の所在地の都道府県知事（その薬局の所在地が保健所を設置する市又は特別区の区域にある場合においては、市長又は区長。）の許可を受けた場合を除き、その薬局以外の場所で業として薬局の管理その他薬事に関する実務に従事する者であってはならない。"},{"label":"c","text":"薬局において、一般用医薬品を取り扱うためには、薬局の開設許可と併せて店舗販売業の許可も受ける必要がある。"},{"label":"d","text":"地域連携薬局とは、患者が継続して利用するために必要な機能及び個人の主体的な健康の保持増進への取組を積極的に支援する機能を有する薬局をいう。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"aの薬局の名称制限（病院・診療所の調剤所を除く）と、bの管理者の兼務制限（所在地の知事の許可がある場合を除く）は正しい。薬局は開設許可のみで一般用医薬品も取り扱えるので、店舗販売業の許可を併せて受ける必要はなく、cは誤り。dの記述は健康サポート薬局の説明であり、地域連携薬局は他の医療提供施設との連携により薬剤・医薬品の適正使用に必要な情報提供や指導を行う薬局として知事の認定を受けるものなので誤り。a正・b正・c誤・d誤の3が正解。","tags":["薬局","健康サポート薬局","地域連携薬局"]},{"id":"R6-91","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":91,"stem":"薬局に関する記述について、正しいものの組合せを選べ。なお、本問において「薬剤師不在時間」とは、法施行規則第１条第２項第２号で規定されるものとする。","statements":[{"label":"a","text":"薬局で医薬品の販売に従事する登録販売者は、薬剤師不在時間内に限り、第一類医薬品を販売することができる。"},{"label":"b","text":"薬剤師不在時間内は、調剤に従事する薬剤師が不在のため調剤に応じることができない旨を当該薬局の外側の見やすい場所に掲示すれば、薬局内に掲示しなくてもよい。"},{"label":"c","text":"薬剤師不在時間内には、当該薬局の管理を行う薬剤師が、その薬局において勤務している従事者と連絡ができる体制を備えていなければならない。"},{"label":"d","text":"薬局開設者は、薬剤師不在時間内は、調剤室を閉鎖しなければならない。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"薬剤師不在時間内でも登録販売者が販売できるのは第二類・第三類医薬品だけで、第一類医薬品は販売できないためaは誤り。不在のため調剤に応じられない旨は薬局内と薬局の外側の両方の見やすい場所に掲示する必要があり、外側だけでよいとするbも誤り。管理薬剤師が勤務中の従事者と連絡できる体制の確保（c）と、調剤室の閉鎖（d）は求められている。よってc・dの5が正解。","tags":["薬剤師不在時間","薬局"]},{"id":"R6-92","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":92,"stem":"店舗販売業に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"薬剤師が従事していれば、医療用医薬品の販売又は授与が可能である。"},{"label":"b","text":"店舗販売業の許可を受けた事業者は、第三類医薬品について、薬剤師又は登録販売者に販売又は授与させなければならない。"},{"label":"c","text":"第一類医薬品を販売する店舗の店舗管理者は、必ず薬剤師でなければならない。"},{"label":"d","text":"店舗管理者は、保健衛生上支障を生ずるおそれがないよう、店舗販売業者に対して必要な意見を口頭により述べなければならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"店舗販売業では薬剤師がいても調剤や医療用医薬品の販売はできず（法第27条）、aは誤り。第二類・第三類医薬品は薬剤師又は登録販売者に販売させるので、bは正しい。第一類を扱う店舗の管理者は原則薬剤師だが、薬剤師を管理者にできない場合は一定の実務経験を持つ登録販売者を管理者にでき、その場合は薬剤師を補佐として置くため、「必ず」とするcは誤り。管理者の意見は書面で述べるものであり、口頭とするdも誤り。a誤・b正・c誤・d誤の3が正解。","tags":["店舗販売業","店舗管理者"]},{"id":"R6-93","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":93,"stem":"配置販売業に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"配置販売業者は、医薬品を開封して分割販売することができる。"},{"label":"b","text":"配置販売業者は、一般用医薬品のうち経年変化が起こりにくいこと等の基準に適合するもの以外の医薬品を販売等してはならない。"},{"label":"c","text":"配置販売業者が、購入者の居宅に常備薬として用いられる製品をひと揃い収めた「配置箱」をあらかじめ預けておくことは、法上、「陳列」に該当しない。"},{"label":"d","text":"配置販売業者又はその配置員は、その住所地の都道府県知事が発行する身分証明書の交付を受け、かつ、これを携帯しなければ、医薬品の配置販売に従事してはならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"配置販売業では医薬品を開封して分割販売することは禁じられており、aは誤り。経年変化が起こりにくいこと等の基準に適合する一般用医薬品以外は販売できないので、bは正しい。常備薬を収めた配置箱をあらかじめ預けておくことは法上「陳列」に当たるため、cは誤り。配置員は住所地の知事が発行する身分証明書の交付と携帯が必要で、dは正しい。a誤・b正・c誤・d正の4が正解。","tags":["配置販売業","身分証明書"]},{"id":"R6-94","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":94,"stem":"店舗販売業者が行う、一般用医薬品のリスク区分に応じた情報提供に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"第一類医薬品を購入しようとする者から説明を要しない旨の意思の表明がなくても、その店舗において医薬品の販売に従事する薬剤師が、当該第一類医薬品が適正に使用されると認められると判断した場合には、必要な情報提供をせずに販売することが認められている。"},{"label":"b","text":"第二類医薬品を販売する場合には、その店舗において医薬品の販売に従事する薬剤師又は登録販売者に、必ず書面を用いて必要な情報を提供させなければならない。"},{"label":"c","text":"指定第二類医薬品を販売する場合には、その医薬品を購入しようとする者が、禁忌事項を確認すること及び当該医薬品の使用について薬剤師又は登録販売者に相談することを勧める旨を、確実に認識できるようにするために必要な措置を講じなければならない。"},{"label":"d","text":"第三類医薬品を販売する場合には、購入者から質問等がなくても、その店舗において医薬品の販売に従事する薬剤師又は登録販売者に必要な情報提供をさせることが望ましい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"第一類医薬品の情報提供を省略できるのは、購入者から説明不要の意思表明があり、かつ薬剤師が適正使用されると判断した場合の両方がそろったときで、購入者の意思表明なしに省略できるとするaは誤り。第二類医薬品の情報提供は努力義務で、書面の使用が必須ではないため、bも誤り。指定第二類医薬品では、禁忌の確認と専門家への相談を勧める旨を購入者が確実に認識できる措置が必要（c正）。第三類は質問がなくても情報提供することが望ましい（d正）。よってa誤・b誤・c正・d正の2。","tags":["情報提供","リスク区分"]},{"id":"R6-95","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":95,"stem":"薬局における医薬品の陳列方法に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"購入者の利便性を考慮し、薬効分類が同じである要指導医薬品と第一類医薬品を、区別することなく陳列することができる。"},{"label":"b","text":"指定第二類医薬品は、「情報提供を行うための設備」から８メートル離れた場所であっても、鍵をかけた陳列設備であれば陳列することができる。"},{"label":"c","text":"第二類医薬品と第三類医薬品は、混在させて陳列することができる。"},{"label":"d","text":"一般用医薬品を販売し、又は授与しない時間は、一般用医薬品を通常陳列し、又は交付する場所を閉鎖しなければならない。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"要指導医薬品と一般用医薬品は混在させずに陳列する必要があり、aは誤り。指定第二類医薬品は情報提供設備から7メートル以内に陳列するのが原則だが、鍵をかけた陳列設備に入れる場合は例外で、bは正しい。第一類・第二類・第三類は区分ごとに混在させず陳列するため、第二類と第三類の混在陳列を認めるcは誤り。一般用医薬品を販売しない時間は、陳列・交付する場所を閉鎖する必要があり、dは正しい。よってb・dの4が正解。","tags":["陳列","指定第二類医薬品"]},{"id":"R6-96","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":96,"stem":"特定販売に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"特定販売とは、その薬局又は店舗におけるその薬局又は店舗以外の場所にいる者に対する一般用医薬品又は薬局製造販売医薬品（毒薬及び劇薬であるものも含む。）の販売又は授与をいう。"},{"label":"b","text":"特定販売を行うことについてインターネットを利用して広告するときは、ホームページに、薬局又は店舗の主要な外観の写真を表示しなければならない。"},{"label":"c","text":"特定販売を行うことについてインターネットを利用して広告をするときは、ホームページに、現在勤務している薬剤師又は登録販売者の別、その氏名及び写真を表示しなければならない。"},{"label":"d","text":"一般用医薬品を購入しようとする者から、対面又は電話により相談応需の希望があった場合には、薬局開設者又は店舗販売業者は、その薬局又は店舗において医薬品の販売又は授与に従事する薬剤師又は登録販売者に、対面又は電話により情報提供を行わせなければならない。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"特定販売の対象から毒薬・劇薬は除かれるため、それらも含むとするaは誤り。インターネット広告では薬局・店舗の主要な外観の写真を表示することが必要でbは正しい。勤務する薬剤師・登録販売者については、別・氏名等の表示が必要であって、写真の表示までは求められないためcは誤り。dの対面又は電話による相談応需の希望があれば、薬剤師又は登録販売者に情報提供させる点は正しい。よってb・dの4が正解。","tags":["特定販売","広告"]},{"id":"R6-98","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":98,"stem":"濫用等のおそれのあるものとして厚生労働大臣が指定する医薬品を販売する場合、法施行規則の規定に基づき、店舗販売業者が当該医薬品を購入しようとする者に対し、薬剤師又は登録販売者に必ず確認させなければならない事項の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"購入しようとする者が若年者である場合は、その者の年齢及び保護者の同意"},{"label":"b","text":"他の店舗販売業者等からの当該医薬品及び当該医薬品以外の濫用等のおそれのある医薬品の購入状況"},{"label":"c","text":"適正な使用のために必要と認められる数量を超えて当該医薬品を購入しようとする場合は、その理由"},{"label":"d","text":"購入しようとする者の住所"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"購入者が若年者の場合に確認するのは、年齢と、18歳未満であればその者の氏名であって、保護者の同意は確認事項ではないためaは誤り。他店での当該医薬品及び他の指定濫用防止医薬品の購入状況（b）と、適正な使用に必要な数量を超えて購入しようとする場合のその理由（c）は確認が必要で正しい。購入者の住所は確認事項に含まれず、dは誤り。よってa誤・b正・c正・d誤の3が正解。","tags":["濫用等のおそれのある医薬品","確認事項"]},{"id":"R6-99","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":99,"stem":"医薬品の広告に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"誇大広告等を禁止する法の規定は、広告等の依頼主だけでなく、その広告等に関与するすべての人が対象となる。"},{"label":"b","text":"承認前の医薬品については、効能効果を標榜しなければ、名称のみ広告することは認められている。"},{"label":"c","text":"医薬関係者が推薦している旨の医薬品の広告は、事実であったとしても、原則として不適当とされている。"},{"label":"d","text":"漢方処方製剤等について、使用する人の体質等を限定した上で特定の症状等に対する改善を目的として、効能効果に一定の前提条件を付した「しばり表現」を省いて広告することは、原則として認められていない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"法第66条（誇大広告）と第68条（承認前の広告）は、広告の依頼主だけでなく関与するすべての人が対象になるため、aは正しい。承認前の医薬品は、効能効果を述べなくても名称のみの広告も禁止であり、bは誤り。医薬関係者などが推薦している旨の広告は、事実でも原則として不適当とされ（c正）、漢方処方製剤等の「しばり表現」を省いた広告も原則認められない（d正）。a正・b誤・c正・d正の2が正解。","tags":["医薬品の広告","誇大広告"]},{"id":"R6-100","chapter":4,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":100,"stem":"法に基づく行政庁による監視指導及び処分に関する記述の正誤について、正しい組合せを選べ。なお、本問において、「都道府県知事」とは、「都道府県知事（薬局又は店舗販売業にあっては、その薬局又は店舗の所在地が保健所を設置する市又は特別区の区域にある場合においては、市長又は区長。）」とする。","statements":[{"label":"a","text":"都道府県知事は、薬事監視員に医薬品の販売業者が医薬品を業務上取り扱う場所に立ち入らせ、帳簿書類を検査させることができる。"},{"label":"b","text":"都道府県知事は、店舗管理者に薬事に関する法令又はこれに基づく処分に違反する行為があったとき、又はその者が管理者として不適当であると認めるときは、その店舗販売業者に対して、店舗管理者の変更を命ずることができる。"},{"label":"c","text":"薬剤師及び登録販売者以外の従業員は、薬事監視員の質問に対して、正当な理由なく、答弁しなかったとしても、法に規定された罰則が適用されることはない。"},{"label":"d","text":"都道府県知事は、店舗販売業者に対し、不正表示医薬品、不良医薬品等について、廃棄、回収その他公衆衛生上の危険の発生を防止するに足りる措置をとるべきことを命ずることができる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"知事は、薬事監視員に販売業者の医薬品を取り扱う場所へ立ち入らせ、帳簿書類を検査させることができ（a正）、店舗管理者に法令違反や不適格な事情があれば、店舗販売業者に管理者の変更を命じることもできる（b正）。従業員が薬事監視員の質問に正当な理由なく答弁しない場合には、50万円以下の罰金の対象となるため、罰則が適用されないとするcは誤り。不正表示医薬品・不良医薬品等について、廃棄や回収などの措置を命じることができ、dは正しい。よってa正・b正・c誤・d正の2が正解。","tags":["監視指導","罰則","薬事監視員"]},{"id":"R6-101","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":101,"stem":"一般用医薬品（一般用検査薬を除く。）の添付文書等に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"添付文書の内容は、医薬品の有効性・安全性等に係る新たな知見、使用に係る情報に基づき、１年に１回の改訂が義務づけられている。"},{"label":"b","text":"添付文書は開封時に一度目を通されれば十分なので、保管しておく必要はない。"},{"label":"c","text":"一般用医薬品を使用した人が医療機関を受診する際には、その添付文書を持参し、医師や薬剤師に見せて相談がなされることが重要である。"},{"label":"d","text":"製造販売業者の名称及び所在地が記載されているが、販売を他社に委託している場合には、販売を請け負っている販社等の名称及び所在地も併せて記載されることもある。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"添付文書は新しい知見や使用情報に基づいて必要に応じて随時改訂されるもので、年1回の改訂義務はないためaは誤りです。また、添付文書は開封時に一度読めば済むものではなく、必要なときにいつでも読めるよう保管する必要があるためbも誤りです。医療機関を受診する際に添付文書を持参して相談することは重要で(c)、製造販売を他社に委託している場合に販社等の名称・所在地が併記されることもあります(d)。","tags":["添付文書","保管"]},{"id":"R6-102","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":102,"stem":"一般用医薬品（一般用検査薬を含む。）の添付文書等の「してはいけないこと」の項に記載される事項に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"一般用検査薬（一般用黄体形成ホルモンキットを除く。）では、その検査結果のみで確定診断はできないので、判定が陽性であれば速やかに医師の診断を受ける旨が記載されている。"},{"label":"b","text":"体に吸収されると一部が乳汁中に移行して、乳児に悪影響を及ぼすおそれがあることが知られている成分が配合されている場合、「授乳中の人は本剤を服用しないか、本剤を服用する場合は授乳を避けること」と記載されている。"},{"label":"c","text":"摂取されたアルコールによって、医薬品の作用が増強し、副作用を生じる危険性の増大等が予測される場合、「服用前後は飲酒しないこと」と記載されている。"},{"label":"d","text":"連用すると効果が減弱して医薬品に頼りがちになりやすい成分が配合されている場合、「長期連用しないこと」「症状があるときのみの使用にとどめ、連用しないこと」等と記載されている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"一般用検査薬は結果だけで確定診断できないため、陽性なら速やかに医師の診断を受ける旨が記載されます(a)。乳汁移行のおそれがある成分では授乳を避ける旨(b)、アルコールで作用増強や副作用増大が予測される場合の飲酒禁止(c)、連用で効果が減弱し薬に頼りがちになる成分での長期連用の禁止(d)も、いずれも「してはいけないこと」の典型的な記載です。よってa〜dすべて正しくなります。","tags":["してはいけないこと","添付文書"]},{"id":"R6-103","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":103,"stem":"一般用医薬品の添付文書等の「相談すること」の項に記載される事項に関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"使用上の注意の記載における「高齢者」とは、およその目安として７５歳以上を指す。"},{"label":"b","text":"「薬などによりアレルギー症状を起こしたことがある人」の項目には、他の医薬品でアレルギーの既往歴があっても、その医薬品によりアレルギー症状を起こしたことがない人は該当しない。"},{"label":"c","text":"「次の診断を受けた人」の項目には、現に医師の治療を受けているか否かによらず、その医薬品が使用されると状態の悪化や副作用等を招きやすい基礎疾患等が示されている。"},{"label":"d","text":"「次の症状がある人」の項目には、その一般用医薬品の軽率な使用がなされると状態の悪化や副作用等を招きやすい症状や、その状態等によっては医療機関を受診することが適切と考えられる場合について記載されている。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"使用上の注意でいう「高齢者」はおよそ65歳以上を指すため、75歳以上とするaは誤りです。他の医薬品でアレルギー歴がある人は、その医薬品でアレルギーを起こしたことがなくても「薬などによりアレルギー症状を起こしたことがある人」に該当し得るため、bも誤りです。「次の診断を受けた人」は現に治療中かどうかを問わず状態悪化や副作用を招きやすい基礎疾患を示し(c)、「次の症状がある人」は軽率な使用で悪化しやすい症状や受診が適切な場合を示します(d)。","tags":["相談すること","高齢者"]},{"id":"R6-104","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":104,"stem":"一般用医薬品の保管及び取扱い上の注意に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"シロップ剤は、温度変化による変質を防ぐ観点から、開封後は室温での保管が適切である。"},{"label":"b","text":"エアゾール製品の添付文書等には、「保管及び取扱上の注意」の項目に高圧ガス保安法に基づく注意事項が記載されているが、その容器への表示は不要である。"},{"label":"c","text":"点眼薬は、開封後長期間保存すると変質する可能性が高いため、複数の使用者で共用し、できる限り早く使い切ることが重要である。"},{"label":"d","text":"散剤は、冷蔵庫から取り出したときに室温との急な温度差で湿気を帯びるおそれがあるため、冷蔵庫での保管は不適当である。"}],"options":[{"n":1,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":1,"explanation":"シロップ剤は変質しやすいため、開封後は室温ではなく冷蔵庫保管が望ましく、aは誤りです。エアゾール製品の高圧ガス保安法に基づく注意事項は、法律上その容器への表示も義務づけられているためbは誤りです。点眼薬は細菌汚染時に感染するおそれがあるため複数人での共用は避けるべきで、cも誤りです。散剤等は冷蔵庫から出すと温度差で湿気を帯びるおそれがあり、冷蔵庫保管は不適当なのでdだけが正しくなります。","tags":["保管及び取扱い","剤形"]},{"id":"R6-105","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":105,"stem":"緊急安全性情報に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"厚生労働省からの命令、指示、製造販売業者の自主決定等に基づいて作成される。"},{"label":"b","text":"Ａ４サイズの青色地の印刷物で、医療機関や薬局等への直接配布、ファックス、電子メール等により情報伝達される。"},{"label":"c","text":"医薬品、再生医療等製品について緊急かつ重大な注意喚起や使用制限に係る対策が必要な際に作成されるが、医療機器についても作成の対象となる。"},{"label":"d","text":"一般用医薬品に関係する緊急安全性情報が発出されたことがあり、例えば、葛根湯による間質性肺炎に関するものがある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"緊急安全性情報は、厚生労働省の命令・指示や製造販売業者の自主決定等に基づいて作成され(a正)、医薬品のほか医療機器・再生医療等製品も対象です(c正)。A4サイズの黄色地でイエローレターと呼ばれるため、青色地とするbは誤りです(青色地は安全性速報)。一般用医薬品に関係する例は小柴胡湯による間質性肺炎(平成8年)であり、葛根湯とするdも誤りです。","tags":["緊急安全性情報","イエローレター"]},{"id":"R6-106","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":106,"stem":"医薬品の購入者等に対する情報提供に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"購入者等が抱く疑問等に対する答えは添付文書に記載されていることが多く、そうした相談への対応において、添付文書情報は有用である。"},{"label":"b","text":"添付文書や外箱表示は、それらの記載内容が改訂された場合、すぐにそれらが反映された製品が流通し、改訂前の添付文書等が購入者等の目に触れることはない。"},{"label":"c","text":"健康に対する一般の生活者の意識・関心の高まりに伴って、医薬品の有効性や安全性等に関する情報に対するニーズが多様化・高度化する傾向にある。"},{"label":"d","text":"医薬品の販売等に従事する専門家においては、購入者等に対して科学的な根拠に基づいた正確なアドバイスを与え、セルフメディケーションを適切に支援することが期待されている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"購入者等の疑問の答えは添付文書に載っていることが多く、相談対応で添付文書情報は有用です(a)。健康への関心の高まりから情報ニーズは多様化・高度化しており(c)、専門家には科学的根拠に基づく助言でセルフメディケーションを支援することが期待されます(d)。一方、記載内容が改訂されても、それを反映した製品が流通するまでには一定の期間を要し、改訂前の添付文書等が購入者の目に触れることはあるため、bは誤りです。","tags":["情報提供","添付文書"]},{"id":"R6-107","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":107,"stem":"医薬品の副作用情報等の収集、評価及び措置に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"サリドマイド薬害事件を契機として、世界保健機関（ＷＨＯ）加盟各国を中心に、各国自らが医薬品の副作用情報を収集、評価する体制（ＷＨＯ国際医薬品モニタリング制度）を確立した。"},{"label":"b","text":"医薬品・医療機器等安全性情報報告制度は、都道府県が約３０００の医療機関から直接副作用報告を受ける「医薬品副作用モニター制度」としてスタートした。"},{"label":"c","text":"医薬関係者が医薬品の副作用等によるものと疑われる健康被害の発生を知った場合において、保健衛生上の危害の発生又は拡大を防止するため必要があると認めるときは、その旨を厚生労働大臣に報告しなければならないとされているが、実務上は報告書を保健所に提出することとされている。"},{"label":"d","text":"厚生労働省の健康危機管理業務は、科学的・客観的な評価を行うとともに、情報の広範な収集、分析の徹底と対応方針の弾力的な見直しに努め、国民に対して情報の速やかな提供と公表を行うことを基本としている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"サリドマイド薬害を契機に、1968年にWHO加盟各国を中心とした国際医薬品モニタリング制度が確立され(a正)、健康危機管理業務は科学的・客観的評価と迅速な情報提供・公表を基本とします(d正)。医薬品副作用モニター制度は、都道府県ではなく当時の厚生省が約3000の医療機関から直接報告を受ける形で始まったのでbは誤りです。また、医薬関係者の報告は厚生労働大臣宛ですが、実務上の報告書の提出先は保健所ではなく総合機構(PMDA)であり、cも誤りです。","tags":["副作用報告","安全性情報報告制度"]},{"id":"R6-108","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":108,"stem":"企業からの医薬品の副作用等の報告制度に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"製造販売業者等が、その製造販売をし、又は承認を受けた医薬品について、その副作用等によるものと疑われる健康被害の発生等を知ったときは、その旨を定められた期限までに都道府県知事に報告することが義務づけられている。"},{"label":"b","text":"薬局開設者、医療施設の開設者、医薬品の販売業者又は医師、歯科医師、薬剤師に加え、登録販売者も製造販売業者が行う副作用等の情報収集に協力するよう努めなければならない。"},{"label":"c","text":"製造販売業者には、医療用医薬品で使用されていた有効成分を一般用医薬品で初めて配合したものについて、承認後の一定期間、安全性に関する調査及び調査結果の厚生労働省への報告が求められている。"},{"label":"d","text":"医薬品の市販後においても、常にその品質、有効性及び安全性に関する情報を収集することが、医薬品の適切な使用を確保する観点からも、企業責任として重要なことである。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"製造販売業者等の副作用等報告の宛先は、都道府県知事ではなく厚生労働大臣(実務上は総合機構へ提出)であり、aは誤りです。登録販売者を含む医薬関係者・販売業者等は、製造販売業者が行う情報収集に協力するよう努めなければなりません(b)。医療用成分を一般用で初めて配合したものには、承認後の一定期間(概ね3年)、安全性の調査と結果報告が求められ(c)、市販後も品質・有効性・安全性の情報収集は企業責任として重要です(d)。","tags":["企業報告","市販後調査"]},{"id":"R6-109","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":109,"stem":"医薬品副作用被害救済制度に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"医薬品を適正に使用したにもかかわらず、生じた副作用による被害者の迅速な救済を図るための制度である。"},{"label":"b","text":"健康被害が医薬品の副作用によるものかどうかなど、医学的薬学的に判断を要する事項について薬事審議会（旧：薬事・食品衛生審議会）の諮問・答申を経て、厚生労働大臣が判定した結果に基づいて、医療費等の給付が行われる。"},{"label":"c","text":"医薬品を適正に使用して生じた健康被害であれば、医療機関での治療を要さずに寛解したような軽度なものについても給付対象となる。"},{"label":"d","text":"健康被害を受けた本人又は家族が、給付請求を行うことができる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"医薬品副作用被害救済制度は、医薬品を適正に使用したにもかかわらず生じた副作用による被害者を迅速に救済する制度です(a)。医学的薬学的な判断を要する事項は、薬事審議会への諮問・答申を経て厚生労働大臣が判定し、その結果に基づき給付が行われます(b)。給付請求は健康被害を受けた本人または家族が行えます(d)。しかし、医療機関での治療を要さず寛解した軽度のものは給付対象に含まれないため、cは誤りです。","tags":["救済制度","医薬品副作用被害救済制度"]},{"id":"R6-110","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":110,"stem":"次の一般用医薬品のうち、医薬品副作用被害救済制度の対象とならないものの組合せを選べ。","statements":[{"label":"a","text":"漢方処方製剤"},{"label":"b","text":"ワセリン（日本薬局方収載医薬品）"},{"label":"c","text":"一般用検査薬"},{"label":"d","text":"殺菌消毒剤（人体に直接使用するもの）"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":3,"explanation":"要指導医薬品・一般用医薬品で救済制度の対象とならないものには、人体に直接使用しない殺虫剤・殺鼠剤・殺菌消毒剤、一般用検査薬、精製水やワセリン等の一部の日局収載医薬品があります。したがって、ワセリン(b)と一般用検査薬(c)が対象外です。漢方処方製剤は通常の医薬品として対象になり、人体に直接使用する殺菌消毒剤も対象に含まれます。","tags":["救済制度","対象外医薬品"]},{"id":"R6-111","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":111,"stem":"医薬品ＰＬセンターに関する記述について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"医薬品副作用被害救済制度の対象とならないケースのうち、製品不良など、製薬企業に損害賠償責任がある場合には、医薬品ＰＬセンターへの相談が推奨される。"},{"label":"b","text":"消費者が、医薬品又は医薬部外品に関する苦情について、製造販売元の企業と交渉するに当たり、公平・中立な立場で申立ての相談を受け付け、交渉の仲介や調整・あっせんを行っている。"},{"label":"c","text":"医療機器に関する紛争処理も、対象としている。"},{"label":"d","text":"製造物責任法の施行と同時に医薬品ＰＬセンターが、各都道府県において開設された。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":1,"explanation":"医薬品PLセンターは、救済制度の対象とならないケースのうち製品不良など製薬企業に損害賠償責任がある場合の相談先として推奨されます(a)。医薬品又は医薬部外品に関する苦情について、公平・中立な立場で企業との交渉の仲介や調整・あっせんを行います(b)。対象は医薬品・医薬部外品であり、医療機器は含まれないためcは誤りです。またPLセンターは日本製薬団体連合会がPL法施行と同時に開設したもので、各都道府県での開設ではなくdも誤りです。","tags":["医薬品PLセンター","紛争処理"]},{"id":"R6-112","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":112,"stem":"塩酸フェニルプロパノールアミン（ＰＰＡ）含有医薬品に関する記述について、（　）の中に入れるべき字句の正しい組合せを選べ。\n\n　２００３年８月までに、ＰＰＡが配合された一般用医薬品による（　a　）等の副作用症例が複数報告され、それらの多くが用法・用量の範囲を超えた使用又は禁忌とされている（　b　）患者の使用によるものであった。そのため、厚生労働省から関係製薬企業等に対して、使用上の注意の改訂、情報提供の徹底等を行うとともに、代替成分として（　c　）等へ速やかに切り替えるよう指示がなされた。","statements":[],"options":[{"n":1,"text":"a 間質性肺炎 / b 糖尿病 / c ナファゾリン塩酸塩"},{"n":2,"text":"a 間質性肺炎 / b 高血圧症 / c プソイドエフェドリン塩酸塩"},{"n":3,"text":"a 脳出血 / b 糖尿病 / c プソイドエフェドリン塩酸塩"},{"n":4,"text":"a 脳出血 / b 高血圧症 / c ナファゾリン塩酸塩"},{"n":5,"text":"a 脳出血 / b 高血圧症 / c プソイドエフェドリン塩酸塩"}],"answer":5,"explanation":"PPA含有医薬品では、米国で出血性脳卒中との関連が報告されたことを受け、日本でも2003年8月までに脳出血等の副作用症例が複数報告されました。その多くは用法・用量を超えた使用や、禁忌である高血圧症患者の使用によるものでした。これを受けて厚生労働省は、使用上の注意の改訂等とともに、代替成分としてプソイドエフェドリン塩酸塩(PSE)等への切替えを指示しました。","tags":["PPA","安全対策"]},{"id":"R6-113","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":113,"stem":"医薬品の安全対策や適正使用のための啓発活動に関する記述の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"登録販売者は、一般用医薬品の販売等に従事する医薬関係者として、医薬品の適正使用の推進のための啓発活動に積極的に参加、協力することが期待される。"},{"label":"b","text":"薬物乱用防止を一層推進するため、毎年６月２０日～７月１９日までの１か月間、国、自治体、関係団体等により、「ダメ。ゼッタイ。」普及運動が実施されている。"},{"label":"c","text":"薬物乱用に関する啓発は、小中学生に行うと、かえって違法薬物に対する好奇心を刺激することになるため、高校生以上から行うこととされている。"},{"label":"d","text":"薬物乱用や薬物依存は、違法薬物（麻薬、覚醒剤、大麻等）により生じるものであり、一般用医薬品によって生じることはない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"登録販売者は、薬剤師とともに医薬関係者として、適正使用の啓発活動への積極的な参加・協力が期待されます(a)。「ダメ。ゼッタイ。」普及運動は毎年6月20日〜7月19日に実施されます(b)。一方、適正使用の重要性の啓発は小中学生のうちから行うことが重要とされ、高校生以上からとするcは誤りです。また薬物乱用や依存は違法薬物だけでなく一般用医薬品でも生じ得るため、dも誤りです。","tags":["薬物乱用防止","啓発活動"]},{"id":"R6-115","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":115,"stem":"一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に、「本剤又は本剤の成分、牛乳によるアレルギー症状を起こしたことがある人」と記載することとされている成分の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"オキセサゼイン"},{"label":"b","text":"次没食子酸ビスマス"},{"label":"c","text":"ケイ酸アルミン酸マグネシウム"},{"label":"d","text":"タンニン酸アルブミン"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"牛乳(乳由来のカゼイン)によるアレルギー症状を起こしたことがある人が使用しないこととされる成分は、乳製カゼインを由来とするタンニン酸アルブミンです。オキセサゼイン、次没食子酸ビスマス、ケイ酸アルミン酸マグネシウムには牛乳アレルギーを理由とする記載はありません(それぞれ別の理由の注意があります)。したがってdのみが正しくなります。","tags":["牛乳アレルギー","タンニン酸アルブミン"]},{"id":"R6-117","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":117,"stem":"一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に、「妊婦又は妊娠していると思われる人」（出産予定日１２週以内の妊婦も含む。）と記載することとされている成分等の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"アスピリン"},{"label":"b","text":"ヒマシ油類"},{"label":"c","text":"エチニルエストラジオール"},{"label":"d","text":"グリチルリチン酸二カリウム"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"「妊婦又は妊娠していると思われる人」(出産予定日12週以内の妊婦を含む)に使用しないとされる成分は、アスピリン(出産予定日12週以内の妊婦)、腸の刺激で流産・早産を誘発するおそれのあるヒマシ油類、胎児の先天性異常が報告されている女性ホルモン成分のエチニルエストラジオールです。グリチルリチン酸二カリウムは主に高血圧等での相談事項の成分で、この項の対象ではないためdは誤りです。","tags":["妊婦","してはいけないこと"]},{"id":"R6-118","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":118,"stem":"一般用医薬品の添付文書等において、目のかすみ、異常なまぶしさを生じることがあるため、「服用後、乗物又は機械類の運転操作をしないこと」と記載することとされている成分を選べ。","statements":[],"options":[{"n":1,"text":"アルジオキサ"},{"n":2,"text":"イブプロフェン"},{"n":3,"text":"ピレンゼピン塩酸塩水和物"},{"n":4,"text":"ピリドキシン塩酸塩"},{"n":5,"text":"メチルエフェドリン塩酸塩"}],"answer":3,"explanation":"眠気だけでなく目のかすみ・異常なまぶしさを生じるおそれがあるため運転操作を控えるよう記載される成分として、胃腸薬に配合されるピレンゼピン塩酸塩水和物が挙げられます。アルジオキサ、イブプロフェン、ピリドキシン塩酸塩、メチルエフェドリン塩酸塩は、この理由での運転操作の注意の対象ではありません。","tags":["乗物運転","ピレンゼピン"]},{"id":"R6-119","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":119,"stem":"フェニレフリン塩酸塩が配合された一般用医薬品の鼻炎用内服薬の添付文書等において、「相談すること」の項目中に「次の診断を受けた人」として記載することとされている基礎疾患等について、正しいものの組合せを選べ。","statements":[{"label":"a","text":"糖尿病"},{"label":"b","text":"肝臓病"},{"label":"c","text":"甲状腺機能障害"},{"label":"d","text":"胃・十二指腸潰瘍"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":2,"explanation":"フェニレフリン塩酸塩などのアドレナリン作動成分は、交感神経を興奮させるため、血糖値を上げて糖尿病を悪化させるおそれがあり、また甲状腺機能亢進症の症状も悪化させるおそれがあります。そのため「相談すること」の「次の診断を受けた人」には糖尿病と甲状腺機能障害が挙げられ、正しい組合せはa、cです。肝臓病や胃・十二指腸潰瘍は、この成分に関する記載の対象ではありません。","tags":["フェニレフリン","相談すること"]},{"id":"R6-120","chapter":5,"source":"関西広域連合 令和6年度 登録販売者試験 後半","no":120,"stem":"ロートエキスが配合された一般用医薬品の制酸薬の添付文書等において、「相談すること」の項目中に記載することとされている対象者の正誤について、正しい組合せを選べ。","statements":[{"label":"a","text":"下痢の症状がある人"},{"label":"b","text":"排尿困難の症状がある人"},{"label":"c","text":"糖尿病の診断を受けた人"},{"label":"d","text":"心臓病の診断を受けた人"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"ロートエキスなど抗コリン成分は、排尿筋の弛緩などにより排尿困難を悪化させるおそれがあり、また心臓に負担をかけるため心臓病の診断を受けた人も相談対象です。したがってb、dが正しくなります。下痢の症状がある人という記載は緩下作用のある成分を想定したもので、ロートエキスの制酸薬では対象でなく、糖尿病もアドレナリン作動成分等での記載であり、a、cは誤りです。","tags":["ロートエキス","抗コリン成分"]},{"id":"R5-1","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":1,"stem":"医薬品の本質に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"法では、健康被害の発生の可能性の有無にかかわらず、異物等の混入、変質等がある医薬品を販売してはならない旨を定めている。"},{"label":"b","text":"一般用医薬品には、添付文書や製品表示に必要な情報が記載されているので、販売時に専門家は専門用語を分かりやすい表現で伝えるなどの情報提供を行う必要はない。"},{"label":"c","text":"医薬品は、効能効果、用法用量、副作用等の必要な情報が適切に伝達されることを通じて、購入者等が適切に使用することにより、初めてその役割を十分に発揮するものである。"},{"label":"d","text":"医薬品は、人の疾病の診断、治療若しくは予防に使用されるなど、その有用性が認められたものであり、使用に際して保健衛生上のリスクは伴わない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"a 正 b 誤 c 正 d 誤の組合せが正しい。異物混入や変質のある医薬品は、健康被害の可能性の有無を問わず販売できない。医薬品は必要な情報が適切に伝わり、購入者が正しく使って初めて役割を果たす。bは、添付文書等があっても専門家が専門用語をかみ砕いて伝える情報提供は必要なので誤り。dは、有用性が認められた医薬品でも保健衛生上のリスクは伴うので誤り。","tags":["医薬品の本質"]},{"id":"R5-2","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":2,"stem":"医薬品のリスク評価に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品は、治療量上限を超えると、効果よりも有害反応が強く発現する「中毒量」となり、「最小致死量」を経て、「致死量」に至る。"},{"label":"b","text":"医薬品は、少量の投与でも長期投与されれば慢性的な毒性が発現する場合がある。"},{"label":"c","text":"ヒトを対象とした臨床試験の実施の基準には、国際的にGood Clinical Practice（ＧＣＰ）が制定されている。"},{"label":"d","text":"医薬品の製造販売後の調査及び試験の実施の基準として、Good Vigilance Practice（ＧＶＰ）が制定されている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"aは、治療量上限を超えると中毒量、最小致死量を経て致死量に至る流れの通りで正しい。bの通り、少量でも長期投与で慢性毒性が出ることがある。cのGCPはヒトを対象とする臨床試験の実施基準で正しい。dは誤りで、製造販売後の調査・試験の基準はGPSPであり、GVPは製造販売後安全管理の基準である。","tags":["リスク評価","GCP・GPSP"]},{"id":"R5-3","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":3,"stem":"健康食品に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"「特定保健用食品」は、身体の生理機能などに影響を与える保健機能成分を含むものであり、特定の保健機能を示す有効性や安全性などに関して、国への届出が必要である。"},{"label":"b","text":"「栄養機能食品」は、国が定めた規格基準に適合したものであれば、身体の健全な成長や発達、健康維持に必要な栄養成分（ビタミン、ミネラルなど）の健康機能を表示することができる。"},{"label":"c","text":"「機能性表示食品」は、事業者の責任で科学的根拠をもとに疾病に罹患した者の健康維持及び増進に役立つ機能を商品のパッケージに表示するものとして国に届出された商品である。"},{"label":"d","text":"一般用医薬品の販売時には、健康食品の摂取の有無について確認することは重要で、購入者等の健康に関する意識を尊重しつつも、必要があれば健康食品の摂取についての指導も行うべきである。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"aは誤り。特定保健用食品は国への届出ではなく、個別に効果や安全性の審査を受けて許可（一部は承認）を得たものである。bは、国の規格基準に適合すれば栄養成分の機能を表示できる栄養機能食品の説明で正しい。cは誤り。機能性表示食品は疾病に罹患していない者の健康の維持・増進に役立つ機能を表示するもので、疾病に罹患した者向けではない。dの通り、健康食品の摂取状況の確認は重要で、必要なら指導も行う。","tags":["健康食品","保健機能食品"]},{"id":"R5-4","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":4,"stem":"セルフメディケーションに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"世界保健機関（ＷＨＯ）によれば、セルフメディケーションとは、「自分自身の健康に責任を持ち、中程度の身体の不調は自分で手当てすること」とされている。"},{"label":"b","text":"急速に少子高齢化が進む中、持続可能な医療制度の構築に向け、医療費の増加やその国民負担の増大を解決し、健康寿命を伸ばすことが日本の大きな課題であり、セルフメディケーションの推進は、その課題を解決する重要な活動のひとつである。"},{"label":"c","text":"平成２９年１月からは、適切な健康管理の下で医療用医薬品からの代替を進める観点から、条件を満たした場合にスイッチＯＴＣ（Over The Counter）医薬品の購入の対価について、一定の金額をその年分の総所得金額等から控除するセルフメディケーション税制が導入された。"},{"label":"d","text":"セルフメディケーション税制については、令和４年１月の見直しにより、スイッチＯＴＣ医薬品以外にも腰痛や肩こり、風邪やアレルギーの諸症状に対応する一般用医薬品が税制の対象となっている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":4,"explanation":"aは誤り。WHOの定義は「軽度な身体の不調は自分で手当てすること」であり、中程度ではない。bの通り、少子高齢化の中でセルフメディケーションの推進は医療費増大等の課題解決に重要な活動である。cは平成29年1月に導入されたセルフメディケーション税制の説明で正しい。dは令和4年1月の見直しでスイッチOTC以外の一部一般用医薬品も対象となった点で正しい。","tags":["セルフメディケーション","税制"]},{"id":"R5-5","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":5,"stem":"アレルギーに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"外用薬によって、アレルギーが引き起こされることはない。"},{"label":"b","text":"医薬品の有効成分だけでなく、薬理作用がない添加物も、アレルギーを引き起こす原因物質となり得る。"},{"label":"c","text":"アレルギーと体質的・遺伝的な要素は関連がないため、近い親族にアレルギー体質の人がいたとしても注意する必要はない。"},{"label":"d","text":"医薬品の中には、鶏卵や牛乳等を原材料として作られているものがあるため、それらに対するアレルギーがある人では使用を避けなければならない場合もある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"aは誤り。外用薬でもアレルギーは起こり得る。bの通り、有効成分だけでなく薬理作用のない添加物もアレルゲンになり得る。cは誤り。アレルギーには体質的・遺伝的な要素が関わるので、近親者にアレルギー体質の人がいる場合は注意が必要である。dの通り、鶏卵や牛乳を原材料とする医薬品があり、該当アレルギーの人は使用を避ける場合がある。","tags":["アレルギー","副作用"]},{"id":"R5-6","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":6,"stem":"医薬品の不適正な使用と副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の不適正な使用は、概ね使用する人の誤解や認識不足に起因するものと、医薬品を本来の目的以外の意図で使用するものに大別することができる。"},{"label":"b","text":"人体に直接使用されない医薬品であっても、使用する人の誤解や認識不足によって、使い方や判断を誤り、副作用につながることがある。"},{"label":"c","text":"医薬品の長期連用により精神的な依存がおこり、使用量が増え、購入するための経済的な負担が大きくなる例が見られる。"},{"label":"d","text":"医薬品は、その目的とする効果に対して副作用が生じる危険性が最小限となるよう、使用する量や使い方が定められている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"すべて正しく、a 正 b 正 c 正 d 正が答え。不適正な使用は誤解や認識不足によるものと、本来の目的以外の意図で使うものに大別される。人体に直接使わない医薬品でも誤った使い方や判断が副作用につながり得る。長期連用による精神的依存で使用量が増え、経済的負担が大きくなる例もある。医薬品は効果に対し副作用の危険が最小限になるよう用量・用法が定められている。","tags":["不適正使用","依存"]},{"id":"R5-7","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":7,"stem":"一般用医薬品の適正使用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"手軽に入手できる一般用医薬品を使用して、症状を一時的に緩和するだけの対処を漫然と続けているような場合には、適切な治療の機会を失うことにつながりやすい。"},{"label":"b","text":"指示どおりの使用量であれば、一般用医薬品を長期連用しても、医薬品を代謝する器官を傷めることはない。"},{"label":"c","text":"青少年は、薬物乱用の危険性に関する認識や理解が必ずしも十分でないため、身近に入手できる薬物を興味本位で乱用することがある。"},{"label":"d","text":"適正に使用された場合は安全かつ有効な医薬品であっても、乱用された場合には薬物依存を生じることがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"aの通り、症状を一時的に和らげるだけの対処を漫然と続けると、適切な治療の機会を失いやすい。bは誤り。指示通りの量でも長期連用すれば、医薬品を代謝する肝臓や排泄する腎臓などを傷めることがある。cの通り、青少年は薬物乱用の危険性の認識が不十分で、身近な薬を興味本位で乱用しやすい。dの通り、適正使用なら安全有効な医薬品でも乱用すれば薬物依存を生じ得る。","tags":["適正使用","乱用"]},{"id":"R5-8","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":8,"stem":"他の医薬品との相互作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の相互作用は、医薬品が吸収、分布、代謝又は排泄される過程で起こり、医薬品の薬理作用をもたらす部位において起こることはない。"},{"label":"b","text":"一般用医薬品のかぜ薬（総合感冒薬）やアレルギー用薬では、成分や作用が重複することが多く、通常、これらの薬効群に属する医薬品の併用は避けることとされている。"},{"label":"c","text":"一般用医薬品の購入者等が医療機関で治療を受けている場合には、一般用医薬品を併用しても問題ないかどうか、治療を行っている医師若しくは歯科医師、又は処方された医薬品を調剤する薬剤師に確認する必要がある。"},{"label":"d","text":"複数の医薬品を併用した場合、医薬品の作用が減弱することはあるが、増強することはない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":1,"explanation":"aは誤り。相互作用は吸収・分布・代謝・排泄の過程だけでなく、薬理作用をもたらす部位でも起こる。bの通り、かぜ薬とアレルギー用薬などは成分が重複しやすく、通常併用を避ける。cの通り、医療機関で治療中の人は、医師・歯科医師または調剤した薬剤師に併用の可否を確認する。dは誤り。併用により作用が増強することも減弱することもある。","tags":["相互作用"]},{"id":"R5-9","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":9,"stem":"食品と医薬品の相互作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"カフェインを含む総合感冒薬と、コーヒーを一緒に服用しても、カフェインの過剰摂取になることはない。"},{"label":"b","text":"酒類（アルコール）は、医薬品の吸収や代謝に影響を与えることがある。"},{"label":"c","text":"生薬成分が配合された医薬品とハーブ等の食品を合わせて摂取すると、その医薬品の効き目や副作用を増強させることがある。"},{"label":"d","text":"外用薬であっても、食品によって医薬品の作用や代謝が影響を受ける可能性がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"aは誤り。カフェイン含有の総合感冒薬とコーヒーを一緒にとるとカフェインの過剰摂取になり得る。bの通り、アルコールは医薬品の吸収や代謝に影響することがある。cの通り、生薬成分を含む医薬品とハーブ等を併せると効き目や副作用が増強する場合がある。dの通り、外用薬でも食品の影響を受ける可能性がある。","tags":["食品との相互作用"]},{"id":"R5-10","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":10,"stem":"小児等への医薬品の使用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"小児の血液脳関門は未発達であるため、吸収されて循環血液中に移行した医薬品の成分が脳に達しやすい。"},{"label":"b","text":"小児では、大人と比べて身体の大きさに対して腸が長いため、服用した医薬品の吸収率が相対的に高い。"},{"label":"c","text":"乳児向けの用法用量が設定されている医薬品であっても、乳児は医薬品の影響を受けやすく、また、状態が急変しやすいため、基本的には医師の診療を受けることが優先され、一般用医薬品による対処は最小限にとどめるのが望ましい。"},{"label":"d","text":"医薬品の販売に従事する専門家は、年齢に応じた用法用量が定められていない医薬品の場合には、成人用の医薬品の量を減らして小児へ与えるように保護者等に説明すべきである。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"aの通り、小児は血液脳関門が未発達で、成分が脳に達しやすい。bの通り、小児は体の大きさに比べ腸が長く、吸収率が相対的に高い。cの通り、乳児は影響を受けやすく状態も急変しやすいため、医師の診療を優先し、一般用医薬品での対処は最小限にとどめるのが望ましい。dは誤り。年齢に応じた用法用量がない医薬品を、成人用を減らして小児に与えるよう勧めてはならない。","tags":["小児","血液脳関門"]},{"id":"R5-11","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":11,"stem":"高齢者への医薬品の使用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"「医療用医薬品の添付文書等の記載要領の留意事項」において、おおよその目安として６５歳以上を「高齢者」としている。"},{"label":"b","text":"高齢者は、持病（基礎疾患）を抱えていることが多いが、一般用医薬品の使用によって基礎疾患の症状が悪化することはない。"},{"label":"c","text":"高齢者は、生理機能の衰えの度合いに個人差が小さいため、年齢から副作用を生じるリスクがどの程度増大しているか判断することができる。"},{"label":"d","text":"高齢者は、喉の筋肉が衰えて飲食物を飲み込む力が弱まっている場合があり、内服薬を使用する際に喉に詰まらせやすい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"aの通り、医療用医薬品の添付文書等の記載要領の留意事項ではおよその目安として65歳以上を高齢者とする。bは誤り。基礎疾患を抱える高齢者では、一般用医薬品の使用で基礎疾患の症状が悪化することがある。cは誤り。高齢者は生理機能の衰えの度合いに個人差が大きく、年齢のみからリスクを判断するのは難しい。dの通り、飲み込む力の低下で内服薬を喉に詰まらせやすい。","tags":["高齢者"]},{"id":"R5-12","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":12,"stem":"妊婦又は妊娠していると思われる女性及び母乳を与える女性（授乳婦）への医薬品の使用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の種類によっては、授乳婦が使用した医薬品の成分の一部が乳汁中に移行することが知られており、母乳を介して乳児が医薬品の成分を摂取することになる場合がある。"},{"label":"b","text":"多くの一般用医薬品は、妊婦が使用した場合における胎児への安全性に関する評価は困難とされている。"},{"label":"c","text":"便秘薬には、配合成分やその用量によっては、流産や早産を誘発するおそれがあるものがある。"},{"label":"d","text":"ビタミンＡは、胎児にとって非常に重要な成分の一つであるため、妊婦に対して特に妊娠初期（妊娠３か月以内）のビタミンＡ含有製剤の過剰摂取には留意する必要はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":1,"explanation":"aの通り、成分の一部が乳汁中に移行し、母乳を介して乳児が摂取することがある。bの通り、多くの一般用医薬品は妊婦使用時の胎児への安全性評価が困難とされる。cの通り、便秘薬には配合成分や用量によって流産・早産を誘発するおそれのあるものがある。dは誤り。ビタミンA含有製剤は、妊娠初期に通常量を超えて摂取すると胎児の先天異常の危険が高まるため、過剰摂取に留意が必要である。","tags":["妊婦","授乳婦"]},{"id":"R5-13","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":13,"stem":"プラセボ効果に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"プラセボ効果は、医薬品を使用したこと自体による楽観的な結果への期待（暗示効果）は関与しないと考えられている。"},{"label":"b","text":"プラセボ効果によってもたらされる反応や変化は、望ましいもの（効果）であり、不都合なもの（副作用）はない。"},{"label":"c","text":"プラセボ効果は、主観的な変化だけでなく、客観的に測定可能な変化として現れることがある。"},{"label":"d","text":"医薬品の使用によってプラセボ効果と思われる反応や変化が現れたときには、それを目的として使用の継続が推奨される。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":5,"explanation":"aは誤り。プラセボ効果には使用したこと自体による楽観的な期待（暗示効果）が関わると考えられている。bは誤り。プラセボ効果には不都合な反応（副作用）もあり得る。cの通り、主観的な変化に限らず、客観的に測定可能な変化として現れることもある。dは誤り。プラセボ効果と思われる反応を目的に使用の継続を勧めてはならない。","tags":["プラセボ効果"]},{"id":"R5-14","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":14,"stem":"医薬品の品質に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の有効成分には、高温や多湿により品質劣化を起こすものはあるが、光（紫外線）による品質劣化を起こすものはない。"},{"label":"b","text":"医薬品が保管・陳列される場所については、清潔性が保たれるとともに、その品質が十分保持される環境となるよう留意する必要がある。"},{"label":"c","text":"品質が承認等された基準に適合しない医薬品、その全部又は一部が変質・変敗した物質から成っている医薬品は販売が禁止されている。"},{"label":"d","text":"一般用医薬品は家庭の常備薬として購入されることも多いため、外箱等に表示されている使用期限から十分な余裕をもって販売することが重要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"aは誤り。医薬品の有効成分には、高温・多湿に加え光（紫外線）でも品質劣化するものがある。bの通り、保管・陳列場所は清潔性と品質保持に留意する。cの通り、承認基準に適合しない医薬品や変質・変敗した医薬品は販売が禁止されている。dの通り、家庭の常備薬として購入されることが多いため、使用期限に十分な余裕をもって販売する。","tags":["品質","使用期限"]},{"id":"R5-15","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":15,"stem":"一般用医薬品で対処可能な症状等の範囲に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品の役割として、健康の維持・増進があるが、健康状態の自己検査は含まれない。"},{"label":"b","text":"科学的・合理的に効果が期待できるものであれば、生活習慣病の治療も一般用医薬品の役割として含まれる。"},{"label":"c","text":"乳幼児や妊婦等では、通常の成人の場合に比べ、一般用医薬品で対処可能な範囲は限られる。"},{"label":"d","text":"一般用医薬品にも使用すればドーピングに該当する成分を含んだものがあるため、スポーツ競技者から相談があった場合は、専門知識を有する薬剤師などへの確認が必要である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"aは誤り。一般用医薬品の役割には健康の維持・増進のほか、健康状態の自己検査も含まれる。bは誤り。生活習慣病等の治療は、一般用医薬品の役割としては含まれない。cの通り、乳幼児や妊婦等は対処可能な範囲が限られる。dの通り、ドーピングに該当する成分を含むものがあり、競技者から相談があれば薬剤師など専門知識のある人に確認する。","tags":["一般用医薬品の役割","ドーピング"]},{"id":"R5-16","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":16,"stem":"一般用医薬品の販売時のコミュニケーションに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品では、情報提供を受けた当人のみが医薬品を使用するとして、販売時のコミュニケーションを考える。"},{"label":"b","text":"一般用医薬品の購入者は、使用者の体質や症状等を考慮して製品を事前に調べて選択しているのでなく、宣伝広告や販売価格等に基づき漠然と製品を選択していることがあることにも留意しなければならない。"},{"label":"c","text":"登録販売者は、生活者のセルフメディケーションに対して、第二類医薬品及び第三類医薬品の販売、情報提供等を担う観点から、支援する姿勢が基本となる。"},{"label":"d","text":"登録販売者からの情報提供は、説明内容が購入者等にどう理解されたかなどの実情を把握しながら行う必要はなく、専門用語を分かりやすい平易な表現で説明するだけでよい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":2,"explanation":"aは誤り。情報提供を受けた当人のみが使用するとは限らず、家族など別の人が使用する場合も考えてコミュニケーションを図る。bの通り、購入者は使用者の体質や症状を考えず、宣伝や価格から漠然と選んでいることもある。cの通り、登録販売者は第二類・第三類医薬品の販売等を担い、セルフメディケーションを支援する姿勢が基本となる。dは誤り。説明が購入者にどう理解されたかを確認しながら行う必要がある。","tags":["販売時コミュニケーション"]},{"id":"R5-17","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":17,"stem":"医薬品の販売等に従事する専門家が、一般用医薬品の購入者から確認しておきたい基本的なポイント（事項）としての正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"何のためにその医薬品を購入しようとしているか（購入者等のニーズ、購入の動機）。"},{"label":"b","text":"その医薬品を使用する人が医療機関で治療を受けていないか。"},{"label":"c","text":"その医薬品を使用する人がアレルギーや医薬品による副作用等の経験があるか。"},{"label":"d","text":"その医薬品がすぐに使用される状況にあるか（その医薬品によって対処しようとする症状等が現にあるか）。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"すべて正しく、a 正 b 正 c 正 d 正が答え。購入者から確認したい基本的事項には、購入の動機（ニーズ）、使用者が医療機関で治療を受けていないか、アレルギーや副作用の経験の有無、その医薬品がすぐに使用される状況にあるか（対処する症状が現にあるか）などがある。いずれも適切な選択と情報提供の前提となる。","tags":["購入者への確認事項"]},{"id":"R5-18","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":18,"stem":"厚生省（当時）は、悲惨な被害を再び発生させることのないように、その決意を銘記した「誓いの碑」を建立した。この「誓いの碑」の記述について、（　）の中に入れるべき字句の正しい組合せを一つ選べ。\n「誓いの碑」には、「命の尊さを心に刻みサリドマイド、スモン、（ａ）のような（ｂ）による悲惨な被害を再び発生させることのないよう（ｃ）の確保に最善の努力を重ねていくことをここに銘記する 千数百名もの感染者を出した『（ｄ）』事件 このような事件の発生を反省しこの碑を建立した平成１１年８月 厚生省」と刻まれている。\n（ＨＩＶ：ヒト免疫不全ウイルス、Ｏ１５７：腸管出血性大腸菌Ｏ１５７）","statements":[],"options":[{"n":1,"text":"a Ｏ１５７感染 / b 医薬品 / c 医薬品の安全性・有効性 / d 薬害肝炎"},{"n":2,"text":"a Ｏ１５７感染 / b 毒物及び劇物 / c 医療の安全 / d 薬害肝炎"},{"n":3,"text":"a ＨＩＶ感染 / b 医薬品 / c 医薬品の安全性・有効性 / d 薬害エイズ"},{"n":4,"text":"a ＨＩＶ感染 / b 医薬品 / c 医療の安全 / d 薬害肝炎"},{"n":5,"text":"a ＨＩＶ感染 / b 毒物及び劇物 / c 医薬品の安全性・有効性 / d 薬害エイズ"}],"answer":3,"explanation":"誓いの碑には「サリドマイド、スモン、HIV感染のような医薬品による悲惨な被害を再び発生させることのないよう医薬品の安全性・有効性の確保に最善の努力を重ねる」と刻まれ、千数百名の感染者を出した薬害エイズ事件の反省から建立された。したがってa HIV感染、b 医薬品、c 医薬品の安全性・有効性、d 薬害エイズの組合せが正しい。O157感染や毒物及び劇物は碑の文言に含まれない。","tags":["薬害","誓いの碑"]},{"id":"R5-19","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":19,"stem":"クロイツフェルト・ヤコブ病（ＣＪＤ）及びＣＪＤ訴訟に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ＣＪＤ訴訟とは、脳外科手術等に用いられていたウシ原料由来の人工硬膜を介してＣＪＤに罹患したことに対する損害賠償訴訟である。"},{"label":"b","text":"ＣＪＤは、細菌の一種であるプリオンが原因とされている。"},{"label":"c","text":"本訴訟では、輸入販売業者及び製造業者が被告として提訴されたが、国は提訴されなかった。"},{"label":"d","text":"本訴訟を一因として、生物由来製品による感染等被害救済制度が創設された。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"aは誤り。CJD訴訟で問題となったのはウシ由来ではなく、ヒト乾燥硬膜（ヒト由来の人工硬膜）を介した感染である。bは誤り。プリオンは細菌ではなく、タンパク質の一種とされる病原体である。cは誤り。本訴訟では輸入販売業者・製造業者に加え国も被告とされた。dの通り、本訴訟を一因として生物由来製品感染等被害救済制度が創設された。","tags":["CJD","薬害"]},{"id":"R5-20","chapter":1,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":20,"stem":"Ｃ型肝炎及びＣ型肝炎訴訟に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"Ｃ型肝炎訴訟とは、ウイルスに汚染された注射器（注射針や注射筒）が連続使用されたことが原因で、Ｃ型肝炎ウイルスに感染したことに対する損害賠償訴訟である。"},{"label":"b","text":"国及び製薬企業を被告として、複数の地裁で提訴されたが、判決は、国及び製薬企業が責任を負うべき期間等について判断が分かれていた。"},{"label":"c","text":"Ｃ型肝炎ウイルス感染者の早期・一律救済の要請にこたえるべく、２００８年１月に議員立法による特別措置法が制定、施行された。"},{"label":"d","text":"「薬害再発防止のための医薬品行政等の見直しについて（最終提言）」を受け、医師、薬剤師、法律家、薬害被害者などの委員により構成される医薬品等行政評価・監視委員会が設置された。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":4,"explanation":"aは誤り。C型肝炎訴訟は、特定のフィブリノゲン製剤や血液凝固第IX因子製剤の投与でC型肝炎ウイルスに感染したことへの訴訟で、注射器の連続使用が原因なのは別の事例である。bの通り、国と製薬企業を被告に複数の地裁で提訴され、判決は責任を負う期間等で判断が分かれた。cの通り、2008年1月に議員立法の特別措置法が制定・施行された。dの通り、最終提言を受けて医薬品等行政評価・監視委員会が設置された。","tags":["C型肝炎","薬害"]},{"id":"R5-61","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":61,"stem":"消化管に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"食道の上端と下端には括約筋があり、胃の内容物が逆流しないように防いでいる。"},{"label":"b","text":"胃で分泌されるペプシノーゲンは、胃酸によりペプシンとなって、脂質を消化する。"},{"label":"c","text":"小腸は全長６～７ｍの臓器で、十二指腸、回腸、盲腸の３部分に分かれる。"},{"label":"d","text":"大腸内には腸内細菌が多く存在し、腸管内の食物繊維（難消化性多糖類）を発酵分解する。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":2,"explanation":"食道の上端・下端の括約筋(a)は正しく、大腸内の腸内細菌が食物繊維を発酵分解する(d)も正しい。bのペプシンはタンパク質を分解する酵素で、脂質の消化ではない。cの小腸は十二指腸・空腸・回腸の3部分で、盲腸は大腸に属する。よって正しい組合せはa、d。","tags":["消化管","消化酵素"]},{"id":"R5-62","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":62,"stem":"肝臓及び胆嚢に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"腸内に放出された胆汁酸塩の大部分は、大腸で再吸収されて肝臓に戻る。"},{"label":"b","text":"胆汁に含まれるビリルビンは、赤血球中のグロブリンが分解された老廃物である。"},{"label":"c","text":"小腸で吸収されたブドウ糖は、肝臓に運ばれてグリコーゲンとして蓄えられる。"},{"label":"d","text":"胆管閉塞によりビリルビンが循環血液中に滞留すると、黄疸を生じる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":3,"explanation":"腸内に放出された胆汁酸塩の大部分は小腸で再吸収されて肝臓に戻る(腸肝循環)ので、大腸とするaは誤り。胆汁中のビリルビンは赤血球中のヘモグロビンが分解されて生じた老廃物で、グロブリンではないのでbも誤り。小腸で吸収されたブドウ糖が肝臓でグリコーゲンとして蓄えられること(c)、胆管閉塞などでビリルビンが循環血液中に滞留すると黄疸を生じること(d)は正しい。","tags":["肝臓","胆汁"]},{"id":"R5-63","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":63,"stem":"呼吸器系に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"気道は上気道、下気道に分けられ、気管は上気道に含まれる器官である。"},{"label":"b","text":"喉頭の大部分と気管から気管支までの粘膜は、線毛上皮で覆われている。"},{"label":"c","text":"横隔膜や肋間筋によって、肺が拡張・収縮して呼吸運動が行われている。"},{"label":"d","text":"肺胞の壁を介して、二酸化炭素が血液中の赤血球に取り込まれる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"気管は下気道に含まれるのでaは誤り。喉頭の大部分と気管〜気管支の粘膜が線毛上皮で覆われること(b)、肺は自ら動かず横隔膜や肋間筋で胸郭が拡張・収縮して呼吸運動が行われること(c)は正しい。肺胞では血液中の二酸化炭素が肺胞気へ放出され、酸素が取り込まれる。dは向きが逆で誤り。","tags":["呼吸器","気道"]},{"id":"R5-64","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":64,"stem":"循環器系に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"四肢を通る動脈には、内腔に向かう薄い帆状のひだが一定間隔で存在する。"},{"label":"b","text":"血管壁の収縮と弛緩は、自律神経系によって制御される。"},{"label":"c","text":"心室には、血液を送り出す側には弁があるが、取り込む側には弁がない。"},{"label":"d","text":"血管系は閉鎖循環系であるのに対して、リンパ系は開放循環系である。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"血管壁の収縮・弛緩を自律神経系が制御する(b)、血管系は閉鎖循環系でリンパ系は開放循環系(d)はいずれも正しい。弁(帆状のひだ)があるのは主に四肢の静脈であり、動脈ではないのでaは誤り。心室は血液を取り込む側にも送り出す側にも弁があるため、cも誤り。","tags":["循環器","血管"]},{"id":"R5-65","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":65,"stem":"血液に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"血液の粘稠性は、主として血漿の水分量や白血球の量で決まる。"},{"label":"b","text":"アルブミンは、血液の浸透圧を保持する働きがある。"},{"label":"c","text":"赤血球は、中央部がくぼんだ円盤状の細胞で、血液全体の約１０％を占める。"},{"label":"d","text":"リンパ球は、血管壁を通り抜けて組織の中に入り込むと、マクロファージと呼ばれる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"血液の粘稠性は主に赤血球の量と血漿の水分量で決まり、白血球ではないのでaは誤り。アルブミンが血液の浸透圧保持に働く(b)は正しい。赤血球が血液全体に占める割合は約40%で、約10%ではないのでcは誤り。組織に入りマクロファージと呼ばれるのは単球であり、リンパ球ではないためdも誤り。","tags":["血液","血球"]},{"id":"R5-66","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":66,"stem":"目に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"眼瞼（まぶた）は、物理的・化学的刺激から目を防護するために、皮下組織が多く厚くできていて、内出血や裂傷を生じにくい。"},{"label":"b","text":"角膜と水晶体の間は、組織液（房水）で満たされ、眼圧を生じさせている。"},{"label":"c","text":"雪眼炎は、赤外線に眼球が長時間曝されることにより、角膜の上皮が損傷を起こした状態である。"},{"label":"d","text":"視細胞が光を感じる反応にはビタミンＤが不可欠であるため、ビタミンＤが不足すると夜間の視力が低下する夜盲症を生じる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"眼瞼は皮下組織が少なく薄いため、内出血や裂傷を生じやすい。よってaは誤り。角膜と水晶体の間を房水が満たし眼圧を生じさせる(b)は正しい。雪眼炎の原因は紫外線であり赤外線ではないのでcは誤り。視細胞の光反応に不可欠なのはビタミンAで、不足すると夜盲症になる。dはビタミンDとしている点が誤り。","tags":["目","ビタミンA"]},{"id":"R5-67","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":67,"stem":"鼻及び耳に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"鼻中隔の前部は、毛細血管が豊富に分布していることに加えて粘膜が薄いため、傷つきやすく鼻出血を起こしやすい。"},{"label":"b","text":"鼻腔粘膜に炎症が起きて腫れた状態を鼻炎といい、鼻閉（鼻づまり）や鼻汁過多などの症状が生じる。"},{"label":"c","text":"中耳は、外耳と内耳をつなぐ部分であり、鼓膜、鼓室、耳小骨、耳管からなる。"},{"label":"d","text":"内耳は、平衡器官である蝸牛と聴覚器官である前庭の２つの部分からなり、いずれも内部はリンパ液で満たされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":1,"explanation":"鼻中隔前部は毛細血管が豊富で粘膜が薄く出血しやすい(a)、鼻炎の定義と症状(b)、中耳は鼓膜・鼓室・耳小骨・耳管からなる(c)はいずれも正しい。内耳では聴覚を担うのが蝸牛、平衡感覚を担うのが前庭であり、dは名称が入れ替わっているため誤り。","tags":["鼻","耳"]},{"id":"R5-68","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":68,"stem":"皮膚に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"皮膚の主な機能は、身体の維持と保護，体水分の保持、熱交換及び外界情報の感知である。"},{"label":"b","text":"皮膚は、表皮、真皮、皮下組織からなり、このうち皮下組織は、角質細胞と細胞間脂質で構成されている。"},{"label":"c","text":"メラニン色素は、真皮の最下層にあるメラニン産生細胞で産生され、太陽光に含まれる紫外線から皮膚組織を防護する役割がある。"},{"label":"d","text":"体温調節のための発汗は全身の皮膚に生じるが、精神的緊張による発汗は手のひらや足底、脇の下、顔面などの限られた皮膚に生じる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"皮膚の主な機能(a)と、精神的緊張による発汗が手のひら・足底・脇の下・顔面など限られた部位に生じること(d)は正しい。角質細胞と細胞間脂質で構成されるのは表皮で、皮下組織ではないためbは誤り。メラニン産生細胞は表皮の最下層にあり、真皮ではないのでcも誤り。","tags":["皮膚","メラニン"]},{"id":"R5-69","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":69,"stem":"骨組織に関する記述について、（ ）の中に入れるべき字句の正しい組合せを一つ選べ。\n骨は生きた組織であり、（ａ）と骨形成が互いに密接な連絡を保ちながら進行し、これを繰り返すことで（ｂ）が行われる。骨組織の構成成分のうち、（ｃ）は、骨に硬さを与える役割をもつ。","statements":[],"options":[{"n":1,"text":"a 骨吸収 / b 骨の新陳代謝 / c 無機質"},{"n":2,"text":"a 骨吸収 / b 骨の新陳代謝 / c 有機質"},{"n":3,"text":"a 骨吸収 / b 造血 / c 有機質"},{"n":4,"text":"a 骨代謝 / b 造血 / c 無機質"},{"n":5,"text":"a 骨代謝 / b 骨の新陳代謝 / c 有機質"}],"answer":1,"explanation":"骨は生きた組織で、破壊(骨吸収)と修復(骨形成)が互いに密接な連絡を保ちながら進行し、これが繰り返されることで骨の新陳代謝が行われる。骨組織のうち、カルシウムなどの無機質は骨に硬さを与え、有機質(タンパク質及び多糖体)は骨の強靱さを保つ。よってa骨吸収、b骨の新陳代謝、c無機質の組合せが正しい。","tags":["骨","骨の新陳代謝"]},{"id":"R5-70","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":70,"stem":"脳や神経系の働きに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"中枢神経系は脳と脊髄から構成され、脳は脊髄と延髄でつながっている。"},{"label":"b","text":"脳における血液の循環量は、心拍出量の約１５％、ブドウ糖の消費量は全身の約２５％、酸素の消費量は全身の約２０％と多い。"},{"label":"c","text":"末梢神経系は、脳や脊髄から体の各部に伸びており、体性神経系と自律神経系に分類されている。"},{"label":"d","text":"自律神経系は、交感神経系と副交感神経系からなり、各臓器・器官でそれぞれの神経線維の末端から神経伝達物質と呼ばれる生体物質を放出している。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"中枢神経系が脳と脊髄からなり脳は延髄で脊髄とつながる(a)、脳の循環血液量・ブドウ糖・酸素の消費割合(b)、末梢神経系が体性神経系と自律神経系に分類される(c)、自律神経系の二系統が神経線維の末端から神経伝達物質を放出する(d)は、いずれも手引きの記載どおりで正しい。全て正の組合せが答え。","tags":["神経系","脳"]},{"id":"R5-71","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":71,"stem":"内服薬の有効成分の吸収に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"内服薬のほとんどは、その有効成分が消化管の中でも主に大腸で吸収される。"},{"label":"b","text":"消化管からの有効成分の吸収は、一般に、濃度の低い方から高い方へ能動的に取り込まれる現象である。"},{"label":"c","text":"有効成分の吸収量や吸収速度は、消化管内容物や他の医薬品の作用によって影響を受ける。"},{"label":"d","text":"全身作用を目的としない内服薬の中には、有効成分が消化管で吸収されて循環血液中に移行することで、好ましくない作用を生じるものもある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"内服薬の有効成分は主に小腸で吸収されるので、大腸としたaは誤り。消化管吸収は濃度の高い方から低い方へ受動的に拡散する現象であり、bの能動的・低い方から高い方は誤り。吸収量や速度が消化管内容物や他剤の影響を受けること(c)、全身作用を目的としない薬でも吸収されると好ましくない作用を生じ得ること(d)は正しい。","tags":["薬の吸収","内服薬"]},{"id":"R5-72","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":72,"stem":"薬の代謝、排泄に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"有効成分が体内で代謝を受けると、作用を失ったり、作用が現れたり、あるいは体外へ排泄されやすい水溶性の物質に変化する。"},{"label":"b","text":"経口投与後、消化管で吸収された有効成分は、全身循環に入る前に門脈を経由して肝臓を通過するため、まず肝臓で代謝を受ける。"},{"label":"c","text":"肝機能が低下した人では、正常な人に比べて全身循環に到達する有効成分の量が多くなり、効き目が過剰に現れることがある。"},{"label":"d","text":"有効成分と血漿タンパク質との複合体は、腎臓で濾過されやすくなり、尿中へ速やかに排泄される。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":1,"explanation":"代謝で作用の消失・発現・水溶性化が起こる(a)、消化管で吸収された成分は門脈を経由してまず肝臓で代謝を受ける(b)、肝機能が低下した人では全身循環に届く量が多くなり効き目が過剰になり得る(c)は正しい。血漿タンパク質との複合体は腎臓で濾過されないため、有効成分が長く循環血液中に留まり作用が持続する原因となる。速やかに排泄されるとするdは誤り。","tags":["代謝","排泄"]},{"id":"R5-73","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":73,"stem":"内服用医薬品の剤形及びその一般的な特徴に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"錠剤は、飛散せずに服用できる点や、有効成分の苦味や刺激性を口中で感じることなく服用できる点が主な特徴である。"},{"label":"b","text":"腸溶錠は、腸内での溶解を目的として錠剤表面をコーティングしているため、水とともに服用してはならない。"},{"label":"c","text":"経口液剤は、有効成分の血中濃度が上昇しやすいため、習慣性や依存性がある成分が配合されている場合、不適正な使用がなされることがある。"},{"label":"d","text":"カプセル剤は、カプセル内に散剤や顆粒剤、液剤等を充填した剤形であり、水なしで服用してもよい。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":2,"explanation":"錠剤は飛散せず、有効成分の苦味や刺激性を口中で感じずに服用できる点が特徴(a)。経口液剤は有効成分の血中濃度が上昇しやすく、習慣性や依存性のある成分では不適正な使用がなされることがある(c)。内服の錠剤は水(又はぬるま湯)とともに飲み込むもので、腸溶錠は特に口中で噛み砕いてはならないとされているため、水とともに服用してはならないとするbは誤り。カプセル剤は水なしで服用するとゼラチンが喉や食道に貼り付くことがあり、必ず水とともに服用するのでdも誤り。","tags":["剤形","内服薬"]},{"id":"R5-74","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":74,"stem":"外用薬の剤形及びその一般的な特徴に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"軟膏剤は、油性基剤に水分を加えたもので、患部を水で洗い流したい場合に用いる。"},{"label":"b","text":"クリーム剤は、油性の基剤で皮膚への刺激が弱く、適用部位を水から遮断したい場合に用いる。"},{"label":"c","text":"外用液剤は、軟膏剤やクリーム剤に比べて、適用部位が乾きにくいという特徴がある。"},{"label":"d","text":"貼付剤は、適用部位に有効成分が一定時間留まるため、薬効の持続が期待できる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"軟膏剤は油性の基剤で皮膚への刺激が弱く、適用部位を水から遮断したい場合等に用いる。基剤に水分を加え、患部を水で洗い流したい場合等に用いられるのはクリーム剤なので、軟膏剤をそう説明するaは誤り。bはクリーム剤に軟膏剤の特徴を当てはめており、これも誤り。外用液剤は軟膏剤やクリーム剤に比べて患部が乾きやすいので、cも誤り。貼付剤は有効成分が一定時間留まるため薬効の持続が期待できる(d)は正しい。","tags":["外用薬","剤形"]},{"id":"R5-75","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":75,"stem":"全身的に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ショック（アナフィラキシー）は、発症後の進行が非常に速やかな（通常、２時間以内に急変する。）ことが特徴である。"},{"label":"b","text":"医薬品により生じる肝機能障害は、有効成分又はその代謝物の直接的肝毒性が原因の中毒性のものに限定される。"},{"label":"c","text":"偽アルドステロン症は、体内にカリウムが貯留し、ナトリウムと水が失われることによって生じる病態である。"},{"label":"d","text":"ステロイド性抗炎症薬や抗癌薬などの使用は、易感染性をもたらすことがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"ショック(アナフィラキシー)は進行が非常に速く、通常2時間以内に急変する(a)。ステロイド性抗炎症薬や抗癌薬は易感染性をもたらすことがある(d)。医薬品による肝機能障害は中毒性に限らずアレルギー性のものもあるため、bの限定は誤り。偽アルドステロン症は、ナトリウムと水が貯留しカリウムが失われて生じる病態であり、cは逆で誤り。","tags":["副作用","ショック"]},{"id":"R5-76","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":76,"stem":"精神神経系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の副作用として現れる精神神経症状は、医薬品の大量服用や長期連用、乳幼児への適用外の使用等の不適正な使用がなされた場合に限って発生する。"},{"label":"b","text":"眠気を催すことが知られている医薬品を使用した後は、乗物や危険な機械類の運転操作に従事しないよう十分注意することが必要である。"},{"label":"c","text":"医薬品の副作用による無菌性髄膜炎では、早期に原因医薬品の使用を中止した場合でも、予後不良となることがほとんどである。"},{"label":"d","text":"医薬品の副作用による無菌性髄膜炎は、過去に軽度の症状を経験した人の場合、再度、同じ医薬品を使用することにより再発し、急激に症状が進行する場合がある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"精神神経症状は通常の用法でも現れ得るため、不適正使用に限るとするaは誤り。眠気を催す薬の使用後は運転操作を避ける(b)は正しい。無菌性髄膜炎は早期に原因薬を中止すれば予後は比較的良好なことが多く、予後不良がほとんどとするcは誤り。過去に経験した人が同じ薬で再発し急激に進行することがある(d)は正しい。","tags":["精神神経系","無菌性髄膜炎"]},{"id":"R5-77","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":77,"stem":"消化器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"消化性潰瘍とは、胃や十二指腸の粘膜組織が傷害されているが、粘膜組織の欠損は粘膜筋板を超えない状態をいう。"},{"label":"b","text":"医薬品の副作用による消化性潰瘍は、必ず自覚症状があり、胃のもたれ、食欲低下、胸やけ、吐きけ、胃痛、空腹時にみぞおちが痛くなる、消化管出血に伴って糞便が黒くなるなどの症状が現れる。"},{"label":"c","text":"イレウス様症状が悪化すると、腸内細菌の異常増殖によって全身状態の衰弱が急激に進行する可能性がある。"},{"label":"d","text":"イレウス様症状は、下痢治癒後の便秘を放置すると、症状を悪化させてしまうことがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":3,"explanation":"消化性潰瘍は、胃や十二指腸の粘膜組織の一部が粘膜筋板を超えて欠損する状態であり、超えないとするaは誤り。消化性潰瘍は自覚症状が乏しい場合もあり、貧血症状の検査や突然の吐血・下血で見つかることもあるため、必ず自覚症状があるとするbも誤り。イレウス様症状が悪化すると腸内細菌の異常増殖で全身状態の衰弱が急激に進行する可能性がある(c)、下痢治癒後の便秘を放置して症状を悪化させることがある(d)は正しい。","tags":["消化器","イレウス様症状"]},{"id":"R5-78","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":78,"stem":"呼吸器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"間質性肺炎は、気管支又は肺胞が細菌に感染して炎症を生じたものである。"},{"label":"b","text":"医薬品の副作用による間質性肺炎は、一般的に、医薬品の使用開始から数か月後に発症することが多い。"},{"label":"c","text":"医薬品の副作用による間質性肺炎は、かぜや気管支炎の症状と明らかに異なるため、区別がつきやすい。"},{"label":"d","text":"医薬品の副作用による喘息の症状は、時間とともに悪化し、顔面の紅潮や目の充血、吐きけ、腹痛、下痢等を伴うこともある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"間質性肺炎は肺胞と毛細血管を取り囲んで支持している組織(間質)の炎症で、気管支や肺胞が細菌に感染して起こる通常の肺炎とは異なるのでaは誤り。医薬品による間質性肺炎は、一般的に使用開始から1〜2週間程度で起きることが多く、数か月後とするbも誤り。かぜや気管支炎の症状と区別が難しいこともあるため、区別がつきやすいとするcも誤り。副作用の喘息が時間とともに悪化し、顔面の紅潮や目の充血、吐きけ、腹痛、下痢等を伴うこともある(d)は正しい。","tags":["呼吸器","間質性肺炎"]},{"id":"R5-79","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":79,"stem":"循環器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"うっ血性心不全とは、心筋の自動性や興奮伝導の異常が原因で心臓の拍動リズムが乱れる病態である。"},{"label":"b","text":"不整脈の種類によっては失神（意識消失）することもあり、その場合には自動体外式除細動器（ＡＥＤ）の使用を考慮するとともに、直ちに救急救命処置が可能な医療機関を受診する必要がある。"},{"label":"c","text":"医薬品の副作用としての不整脈は、代謝機能の低下によってその発症リスクが高まることがあるので、腎機能や肝機能の低下、併用薬との相互作用等に留意するべきである。"},{"label":"d","text":"高血圧や心臓病等、循環器系疾患の診断を受けている人は、心臓や血管に悪影響を及ぼす可能性が高い医薬品を使用してはならない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"うっ血性心不全は、全身が必要とする量の血液を心臓から送り出せなくなり、肺に血液が貯留して種々の症状を示す疾患で、心拍リズムの乱れは不整脈の説明なのでaは誤り。失神を伴う不整脈ではAEDの使用を考慮し直ちに救急救命処置が可能な医療機関を受診する(b)、代謝機能の低下で発症リスクが高まるため腎機能・肝機能の低下や併用薬との相互作用に留意する(c)、循環器系疾患の診断を受けている人は悪影響を及ぼす可能性が高い医薬品を使用してはならない(d)は、いずれも手引きの記載どおり正しい。","tags":["循環器","不整脈"]},{"id":"R5-80","chapter":2,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":80,"stem":"感覚器系に現れる医薬品の副作用に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"コリン作動成分が配合された医薬品によって、眼圧が上昇することがある。"},{"label":"b","text":"眼圧の上昇に伴って、頭痛や吐きけ・嘔吐等の症状が現れることもある。"},{"label":"c","text":"高眼圧を長時間放置すると、視神経が損傷して視野欠損といった視覚障害に至るおそれがあるが、この症状は可逆的である。"},{"label":"d","text":"瞳の拡大（散瞳）を生じる可能性のある成分が配合された医薬品を使用した後は、乗物や機械類の運転操作を避けなければならない。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"眼圧上昇の原因となるのは抗コリン成分であり、コリン作動成分ではないのでaは誤り。眼圧上昇に伴い頭痛や吐きけ・嘔吐が現れること(b)、散瞳を生じ得る成分の使用後は運転操作を避けること(d)は正しい。高眼圧の放置による視神経損傷・視野欠損は不可逆的であり、可逆的とするcは誤り。","tags":["感覚器","眼圧"]},{"id":"R5-21","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":21,"stem":"かぜ及びかぜ薬（総合感冒薬）に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"かぜは様々な症状が組み合わさって現れるため、様々な症状を緩和させるために多くの成分を含有する総合感冒薬を選択することが推奨される。"},{"label":"b","text":"かぜ薬は症状の緩和に加えて、原因となるウイルスの増殖抑制効果も期待できる。"},{"label":"c","text":"冷気や乾燥、アレルギーのような非感染性の要因は、かぜの原因とはならない。"},{"label":"d","text":"かぜはウイルス（ライノウイルス、コロナウイルスなど）の感染が原因であり、細菌の感染は原因とはならない。"}],"options":[{"n":1,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"かぜ薬は咳や発熱など出ている症状を和らげる対症療法であり、ウイルスの増殖を抑えるものではないため、bは誤り。症状が限られる場合は症状に合った薬を選ぶ方が適切で、多成分の総合感冒薬を勧めるaも誤り。かぜの原因は冷気・乾燥・アレルギーなどの非感染性要因もあるためcは誤り、ウイルスだけでなく細菌の感染でも起こるためdも誤り。よって全て誤の5が正解。","tags":["かぜ薬","総合感冒薬"]},{"id":"R5-22","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":22,"stem":"かぜ薬（総合感冒薬）の配合成分とその配合目的との関係について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"サリチルアミド：咳を抑える。"},{"label":"b","text":"グアイフェネシン：痰の切れを良くする。"},{"label":"c","text":"チペピジンヒベンズ酸塩：発熱を鎮める。"},{"label":"d","text":"ベラドンナ総アルカロイド：くしゃみや鼻汁を抑える。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"a、d"},{"n":4,"text":"b、c"},{"n":5,"text":"b、d"}],"answer":5,"explanation":"サリチルアミドは解熱鎮痛成分、チペピジンヒベンズ酸塩は咳を抑える鎮咳成分であり、a・cは目的が入れ替わっていて誤り。グアイフェネシンは気道粘液の分泌を促して痰を出しやすくする去痰成分、ベラドンナ総アルカロイドは抗コリン成分で鼻汁やくしゃみを抑えるので、b・dが正しく、5が正解。","tags":["かぜ薬","配合成分"]},{"id":"R5-23","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":23,"stem":"かぜの症状緩和に用いられる漢方処方製剤のうち、マオウを含むものの組合せを一つ選べ。","statements":[{"label":"a","text":"柴胡桂枝湯"},{"label":"b","text":"麦門冬湯"},{"label":"c","text":"小青竜湯"},{"label":"d","text":"葛根湯"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"マオウを構成生薬に含むかぜ関連の漢方処方は、葛根湯と小青竜湯である。柴胡桂枝湯と麦門冬湯はマオウを含まないので、c・dの組合せである5が正解。","tags":["漢方","マオウ"]},{"id":"R5-24","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":24,"stem":"解熱鎮痛薬及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"アセトアミノフェンは、１５歳未満の小児に対しては、いかなる場合も一般用医薬品として使用してはならない。"},{"label":"b","text":"アスピリン喘息は、アスピリン特有の副作用であり、他の解熱鎮痛成分では起こらない。"},{"label":"c","text":"解熱鎮痛薬の服用期間中は、飲酒は避けることとされている。"},{"label":"d","text":"多くの解熱鎮痛薬には、体内におけるプロスタグランジンの産生を抑える成分が配合されている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":3,"explanation":"アセトアミノフェンは15歳未満に一律禁止ではなく、いかなる場合も使用不可とされるのはアスピリン等なのでaは誤り。アスピリン喘息は他の解熱鎮痛成分でも起こりうるためbも誤り。服用期間中の飲酒回避（c）と、プロスタグランジン産生を抑える成分が多くの解熱鎮痛薬に配合されること（d）は正しい。","tags":["解熱鎮痛薬","アスピリン喘息"]},{"id":"R5-25","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":25,"stem":"解熱鎮痛薬に配合される成分の配合目的に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"ケイヒは、骨格筋の緊張を鎮める目的で配合される。"},{"label":"b","text":"水酸化アルミニウムゲルは、解熱鎮痛成分（生薬成分を除く。）による胃腸障害の軽減を目的として配合される。"},{"label":"c","text":"メトカルバモールは、中枢神経系を刺激して頭をすっきりさせたり、疲労感・倦怠感を和らげることなどを目的として配合される。"},{"label":"d","text":"ビタミンＢ１は、発熱等によって消耗されやすいビタミンの補給を目的として配合される。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"a、d"},{"n":4,"text":"b、c"},{"n":5,"text":"b、d"}],"answer":5,"explanation":"ケイヒは発汗を促して解熱を助ける目的で配合され、骨格筋の緊張を鎮めるわけではないのでaは誤り。メトカルバモールは骨格筋の緊張を鎮める成分で、中枢刺激で頭をすっきりさせるのはカフェインの働きなのでcも誤り。制酸成分は解熱鎮痛成分による胃腸障害の軽減目的（b）、ビタミンB1は消耗しやすいビタミンの補給目的（d）で正しい。","tags":["解熱鎮痛薬","配合目的"]},{"id":"R5-26","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":26,"stem":"２５歳女性が月経痛の症状があるため、次の成分の一般用医薬品の解熱鎮痛薬を購入する目的で店舗を訪れた。\n１錠中：\n成分 / 分量\nイソプロピルアンチピリン / ７５ ｍｇ\nアセトアミノフェン / １２５ ｍｇ\nアリルイソプロピルアセチル尿素 / ３０ ｍｇ\n無水カフェイン / ２５ ｍｇ\nこの解熱鎮痛薬に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"イソプロピルアンチピリンは、ピリン系解熱鎮痛成分によって薬疹等のアレルギーを起こしたことのある人は使用しない。"},{"label":"b","text":"本剤には、血栓予防薬としても用いられる成分が含まれている。"},{"label":"c","text":"アセトアミノフェンは、他の解熱鎮痛成分に比べて胃腸障害を起こしやすいため、本剤は空腹を避けて服用する。"},{"label":"d","text":"アリルイソプロピルアセチル尿素は、脳の興奮を抑え、痛覚を鈍くする効果が期待できる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"イソプロピルアンチピリンは一般用医薬品で唯一のピリン系成分で、ピリン疹の既往がある人は使用しないのでaは正しい。血栓予防に用いられるのは医療用のアスピリンで、本剤には含まれずbは誤り。アセトアミノフェンは他の成分より胃腸障害が少ないため、cの理由付けは誤り。アリルイソプロピルアセチル尿素は鎮静成分で、脳の興奮を抑え痛覚を鈍くする効果が期待でき、dは正しい。","tags":["解熱鎮痛薬","ピリン系"]},{"id":"R5-27","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":27,"stem":"神経質、精神不安、不眠等の症状の改善を目的とした漢方処方製剤に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"加味帰脾湯は、体力中等度以上で、精神不安があって、動悸、不眠、便秘などを伴う高血圧の随伴症状、神経症、更年期神経症、小児夜なき、便秘に適すとされる。"},{"label":"b","text":"抑肝散は、体力中等度をめやすとして、神経がたかぶり、怒りやすい、イライラなどがあるものの神経症、不眠症、小児夜なき、小児疳症、歯ぎしり、更年期障害、血の道症に適すとされる。"},{"label":"c","text":"酸棗仁湯は、体力中等度以下で、心身が疲れ、精神不安、不眠などがあるものの不眠症、神経症に適すとされる。"},{"label":"d","text":"柴胡加竜骨牡蛎湯は、体力中等度以下で、心身が疲れ、血色が悪く、ときに熱感を伴うものの貧血、不眠症、精神不安、神経症に適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"加味帰脾湯と柴胡加竜骨牡蛎湯の説明が入れ替わっているため、a・dは誤り（aの内容は柴胡加竜骨牡蛎湯、dの内容は加味帰脾湯に当たる）。抑肝散（b）と酸棗仁湯（c）の記述は適応に合っており正しい。","tags":["漢方","不眠"]},{"id":"R5-28","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":28,"stem":"眠気防止薬の有効成分として配合されるカフェインに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"腎臓におけるナトリウムイオンの再吸収抑制作用があり、尿量の増加をもたらす。"},{"label":"b","text":"胃液分泌抑制作用があるため、胃酸過多の人でも服用できる。"},{"label":"c","text":"作用は弱いながら反復摂取により依存を形成するという性質がある。"},{"label":"d","text":"乳汁中に移行しないことから、授乳中の女性でも摂取量を気にせず摂取できる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":2,"explanation":"カフェインには腎臓でのナトリウム再吸収を抑えて尿量を増やす作用があり（a）、作用は弱いが反復摂取で依存を形成する（c）。一方、胃液の分泌を促すため胃酸過多の人には向かず（b誤）、乳汁中へ移行するので授乳中は摂取量に注意が必要（d誤）。","tags":["カフェイン","眠気防止薬"]},{"id":"R5-29","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":29,"stem":"乗物酔い防止薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ジプロフィリンは、不安や緊張などの心理的な要因を和らげることにより乗物酔いの発現を抑える。"},{"label":"b","text":"メクリジン塩酸塩は、胃粘膜への麻酔作用によって嘔吐刺激を和らげる。"},{"label":"c","text":"スコポラミン臭化水素酸塩水和物は、肝臓で速やかに代謝されるため、抗ヒスタミン成分と比べて作用の持続時間は短い。"},{"label":"d","text":"ジフェニドール塩酸塩は、内耳にある前庭と脳を結ぶ神経（前庭神経）の調節作用のほか、内耳への血流を改善する作用を示す。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":3,"explanation":"ジプロフィリンは脳を軽く興奮させて平衡感覚の混乱によるめまいを和らげる成分で、心理面に作用するわけではないためaは誤り。胃粘膜への麻酔作用で嘔吐刺激を和らげるのはアミノ安息香酸エチルなので、メクリジンのbも誤り。スコポラミンは肝臓で速やかに代謝され作用持続が短い（c）、ジフェニドールは前庭神経の調節と内耳血流の改善を示す（d）ので正しい。","tags":["乗物酔い防止薬"]},{"id":"R5-30","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":30,"stem":"小児の疳を適応症とする生薬製剤・漢方処方製剤（小児鎮静薬）に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ゴオウ、ジャコウは、鎮静、健胃、強壮などの作用を期待して、小児の疳を適応症とする生薬製剤に用いられる。"},{"label":"b","text":"身体的な問題がなく生じる夜泣き、ひきつけ、疳の虫等の症状については、症状が治まるまでは保護者側の安眠等を図ることを優先して小児鎮静薬を使用することは適すとされている。"},{"label":"c","text":"小児の疳を適応症とする漢方処方製剤のうち、用法用量において適用年齢の下限が設けられていない場合は、生後１か月の乳児にも使用できる。"},{"label":"d","text":"小建中湯を乳幼児に使用する場合は、体格の個人差から体重当たりのグリチルリチン酸の摂取量が多くなることがあるので、特に留意する必要がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":5,"explanation":"ゴオウ・ジャコウは緊張や興奮を鎮め血液の循環を促す目的で用いられ、鎮静・健胃・強壮はジンコウの説明であるためaは誤り。身体的な問題のない夜泣き等に保護者の安眠を優先して使うのは適当でなくbも誤り。漢方処方製剤は適用年齢の下限がなくても生後3か月未満には使わないので、生後1か月に使えるとするcも誤り。小建中湯はカンゾウを含み、乳幼児では体重当たりのグリチルリチン酸摂取量に留意するのでdは正しい。","tags":["小児鎮静薬","漢方"]},{"id":"R5-31","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":31,"stem":"呼吸器官に作用する薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"デキストロメトルファン臭化水素酸塩水和物は、延髄の咳嗽中枢に作用する麻薬性鎮咳成分である。"},{"label":"b","text":"メチルエフェドリン塩酸塩は、交感神経系を抑制して気管支を拡張させる作用がある。"},{"label":"c","text":"キサンチン系成分は、心臓刺激作用も示すことから、副作用として動悸が現れることがある。"},{"label":"d","text":"クロルフェニラミンマレイン酸塩は、気道粘膜からの粘液の分泌を促進し、痰を出しやすくする。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":5,"explanation":"デキストロメトルファンは延髄の咳嗽中枢に作用する非麻薬性の鎮咳成分であり、麻薬性とするaは誤り（麻薬性はコデイン類）。メチルエフェドリンは交感神経系を刺激して気管支を拡げるのでbも誤り。キサンチン系成分は心臓刺激作用を示し、副作用として動悸が現れることがあるためcは正しい。クロルフェニラミンは抗ヒスタミン成分で、気道粘膜の粘液分泌を抑えて痰が出にくくなることがあり、痰を出しやすくする成分ではないのでdは誤り。","tags":["鎮咳去痰薬","キサンチン系"]},{"id":"R5-32","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":32,"stem":"咳止めや痰を出しやすくする目的で用いられる漢方処方製剤として、次の記述にあてはまる最も適切なものを一つ選べ。\n体力中程度をめやすとして、気分がふさいで、咽喉・食道部に異物感があり、ときに動悸、めまい、嘔気などを伴う不安神経症、神経性胃炎、つわり、咳、しわがれ声、のどのつかえ感に適すとされる。","statements":[],"options":[{"n":1,"text":"麻杏甘石湯"},{"n":2,"text":"響声破笛丸"},{"n":3,"text":"半夏厚朴湯"},{"n":4,"text":"五虎湯"},{"n":5,"text":"甘草湯"}],"answer":3,"explanation":"気分がふさぎ、咽喉・食道部の異物感やつわり、のどのつかえ感などに適するとされる処方は半夏厚朴湯である。麻杏甘石湯・五虎湯は咳や気管支喘息、響声破笛丸は声がれ、甘草湯は咳・咽喉痛に用いる処方と区別して覚える。","tags":["漢方","半夏厚朴湯"]},{"id":"R5-33","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":33,"stem":"胃に作用する薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"スクラルファートは、マグネシウムを含む成分であるため、透析を受けている人では使用を避ける必要がある。"},{"label":"b","text":"ピレンゼピン塩酸塩は、血栓のある人、血栓を起こすおそれのある人では、生じた血栓が分解されにくくなることが考えられる。"},{"label":"c","text":"ジメチルポリシロキサン（ジメチコン）は、消化管内容物中に発生した気泡の分離を促すことを目的として配合されている場合がある。"},{"label":"d","text":"ウルソデオキシコール酸は、胆汁の分泌を促す作用（利胆作用）があるとされ、消化を助ける効果を期待して用いられる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":3,"explanation":"スクラルファートに含まれるのはマグネシウムではなくアルミニウムで、透析を受けている人で使用を避ける理由もアルミニウムを含むためなのでaは誤り。血栓が分解されにくくなる懸念があるのは、体内でトラネキサム酸を生じるセトラキサート塩酸塩などであり、ピレンゼピンは一般的な抗コリン作用（排尿困難・動悸・目のかすみ等）に注意する成分なのでbも誤り。ジメチコンは消化管内の気泡の分離を促す消泡成分（c）、ウルソデオキシコール酸は胆汁の分泌を促す利胆作用があり消化を助ける効果を期待して用いられる（d）ので正しい。","tags":["胃薬","制酸成分"]},{"id":"R5-34","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":34,"stem":"整腸薬又は止瀉薬及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"腸内殺菌成分の入った止瀉薬は、下痢の予防で服用したり、症状が治まったのに漫然と服用したりすると、腸内細菌のバランスを崩し、腸内環境を悪化させることがある。"},{"label":"b","text":"トリメブチンマレイン酸塩は、消化管の平滑筋に直接作用して、消化管の運動を調整する作用があるが、まれに重篤な副作用として肝機能障害を生じることがある。"},{"label":"c","text":"ロペラミド塩酸塩が配合された止瀉薬は、効き目が強すぎて便秘が現れることがあり、まれに重篤な副作用としてイレウス様症状を生じることがある。"},{"label":"d","text":"ベルベリン塩化物は、海外において長期連用した場合に精神神経症状が現れたとの報告があるため、１週間以上継続して使用しないこととされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"腸内殺菌成分を漫然と服用すると腸内細菌のバランスを崩すことがあり（a）、トリメブチンは消化管平滑筋に直接作用して運動を調整し、まれに肝機能障害を生じる（b）。ロペラミドは効き過ぎて便秘やイレウス様症状を生じることがある（c）。1週間以上続けないとされ精神神経症状の報告があるのはビスマスを含む成分で、ベルベリンではないためdは誤り。","tags":["止瀉薬","ビスマス"]},{"id":"R5-35","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":35,"stem":"瀉下薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"酸化マグネシウムは、腸内容物の浸透圧をさげることにより、糞便中の水分量を増やす作用がある。"},{"label":"b","text":"センノシドが配合された瀉下薬については、妊婦又は妊娠していると思われる女性では、使用を避けるべきである。"},{"label":"c","text":"ビサコジルを含む腸溶性製剤は、胃内でビサコジルが溶け出すおそれがあるため、服用後１時間以内は牛乳の摂取を避けることとされている。"},{"label":"d","text":"ジオクチルソジウムスルホサクシネートは、糞便中の水分量を増して柔らかくすることによる瀉下作用を期待して用いられる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"酸化マグネシウムは腸内容物の浸透圧を高めて糞便中の水分を増やすので、浸透圧を下げるとするaは誤り。センノシド配合の瀉下薬は流産・早産を誘発するおそれから妊婦では避けるべき（b）、腸溶性のビサコジルは牛乳の摂取を避ける（c）、ジオクチルソジウムスルホサクシネートは糞便を柔らかくする（d）は正しい。","tags":["瀉下薬","酸化マグネシウム"]},{"id":"R5-36","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":36,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを一つ選べ。\n体力中程度以下で、ときに便が硬く塊状なものの便秘、便秘に伴う頭重、のぼせ、湿疹・皮膚炎、ふきでもの、食欲不振、腹部膨満、腸内異常醗酵、痔などの症状の緩和に適すとされる。","statements":[],"options":[{"n":1,"text":"六君子湯"},{"n":2,"text":"大黄牡丹皮湯"},{"n":3,"text":"人参湯"},{"n":4,"text":"麻子仁丸"},{"n":5,"text":"桂枝加芍薬湯"}],"answer":4,"explanation":"体力中程度以下で、ときに便が硬く塊状の便秘や、便秘に伴う頭重・のぼせ・湿疹・皮膚炎などに用いられる処方は麻子仁丸である。六君子湯は胃腸が弱く食欲不振などのある人の胃炎・胃腸虚弱、大黄牡丹皮湯は体力中等度以上で下腹部痛のある便秘・月経不順、桂枝加芍薬湯は腹部膨満感のあるしぶり腹・腹痛・下痢・便秘、人参湯は疲れやすく手足が冷えやすい人の胃腸虚弱に用いる処方で、内容が異なる。","tags":["漢方","便秘"]},{"id":"R5-37","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":37,"stem":"胃腸鎮痛鎮痙薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"チキジウム臭化物には、口渇、便秘、排尿困難等の副作用が現れることがある。"},{"label":"b","text":"ブチルスコポラミン臭化物は、まれに重篤な副作用としてショック（アナフィラキシー）を生じることが知られている。"},{"label":"c","text":"ロートエキスは、吸収された成分の一部が母乳中に移行して乳児の脈が速くなる（頻脈）おそれがある。"},{"label":"d","text":"パパベリン塩酸塩は、抗コリン成分と異なり、眼圧を上昇させる作用はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"チキジウムは抗コリン作用による口渇・便秘・排尿困難等が起こることがあり（a）、ブチルスコポラミンはまれにショックを生じる（b）。ロートエキスの成分は母乳に移行し乳児に頻脈を起こすおそれがある（c）。パパベリンは抗コリン成分と異なるが、眼圧を上昇させて緑内障を悪化させるおそれがあるためdは誤り。","tags":["胃腸鎮痛鎮痙薬","抗コリン成分"]},{"id":"R5-38","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":38,"stem":"一般用医薬品の強心薬に配合される生薬成分のうち、鎮静作用を目的として配合されるものの組合せを一つ選べ。","statements":[{"label":"a","text":"ロクジョウ"},{"label":"b","text":"シンジュ"},{"label":"c","text":"センソ"},{"label":"d","text":"ジンコウ"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"強心薬の生薬のうち、鎮静作用を目的とするのはシンジュ（真珠）とジンコウ（沈香）である。ロクジョウは強心・強壮、センソは強心作用を目的とした成分で、b・dの4が正解。","tags":["強心薬","生薬"]},{"id":"R5-39","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":39,"stem":"一般用医薬品の苓桂朮甘湯に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"体力中等度以下で、めまい、ふらつきがあり、ときにのぼせや動悸があるものの立ちくらみ、めまい、頭痛、耳鳴り、動悸、息切れ、神経症、神経過敏に適すとされる。"},{"label":"b","text":"利尿作用により、水毒（漢方の考え方で、体の水分が停滞したり偏在して、その循環が悪いことを意味する。）の排出を促す。"},{"label":"c","text":"強心作用が期待される生薬を含んでいる。"},{"label":"d","text":"構成生薬としてカンゾウを含むため、高血圧、心臓病、腎臓病の診断を受けた人では、偽アルドステロン症を生じやすい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"苓桂朮甘湯は、めまい・ふらつきやのぼせ・動悸のある人の立ちくらみ等に用いられ（a）、主に利尿作用で水毒の排出を促す（b）。強心作用が期待される生薬は含まれないためcは誤り。構成生薬にカンゾウを含み、高血圧・心臓病・腎臓病の診断を受けた人は偽アルドステロン症を生じやすい（d）。","tags":["漢方","苓桂朮甘湯"]},{"id":"R5-40","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":40,"stem":"次の成分の一般用医薬品の高コレステロール改善薬を購入しようとする者への登録販売者の説明について、適切なものの組合せを一つ選べ。\n６カプセル中：\n成分 / 分量\nパンテチン / ３７５ ｍｇ\n大豆油不けん化物 / ６００ ｍｇ\nトコフェロール酢酸エステル / １００ ｍｇ","statements":[{"label":"a","text":"腸管におけるコレステロールの吸収を抑える働きがある成分が含まれています。"},{"label":"b","text":"末梢血管における血行を促進する成分が含まれています。"},{"label":"c","text":"尿が黄色くなる成分が含まれていますが心配ありません。"},{"label":"d","text":"１年くらい服用を続けても症状・コレステロール値に改善が見られない時には、服用を中止し、医療機関を受診してください。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":1,"explanation":"大豆油不けん化物は腸管でのコレステロール吸収を抑えるためaは適切、トコフェロール酢酸エステル（ビタミンE）は末梢血管の血行を促進するのでbも適切。本剤には尿を黄色くするリボフラビン（ビタミンB2）は含まれずcは不適切。服用の目安は1〜3か月程度で、それで改善がなければ中止して受診を勧めるため、「1年くらい」とするdも不適切。","tags":["高コレステロール改善薬","ビタミンE"]},{"id":"R5-41","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":41,"stem":"貧血用薬（鉄製剤）及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"赤血球ができる過程で必要不可欠なビタミンＢ１２の構成成分である銅が配合されている場合がある。"},{"label":"b","text":"消化管内で鉄が吸収されやすい状態に保つことを目的として、ビタミンＣが配合されていることがある。"},{"label":"c","text":"服用後、便が黒くなる場合には、重大な副作用の可能性があるため直ちに服用を中止する。"},{"label":"d","text":"貧血の症状がみられる以前から予防的に使用することが適当である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3で、bだけが正しい。ビタミンCは、消化管内で鉄が吸収されやすい状態に保つ目的で配合されることがある。aは誤りで、ビタミンB12の構成成分はコバルトであり、銅はヘモグロビンができる過程で鉄の代謝や輸送を助ける成分である。cは誤りで、鉄製剤で便が黒くなること自体は使用の中止を要する副作用ではない（服用前から便が黒い場合は消化管出血の可能性がある）。dも誤りで、貧血の症状がみられる以前から予防的に使うことは適当でないとされている。","tags":["貧血用薬","鉄製剤","銅とコバルト"]},{"id":"R5-42","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":42,"stem":"次の成分を含む一般用医薬品の外用痔疾用薬に関する記述の正誤について、正しい組合せを一つ選べ。\n坐剤１個（１.７５ｇ）中：\n成分 / 分量\nリドカイン / ６０ ｍｇ\nグリチルレチン酸 / ３０ ｍｇ\nアラントイン / ２０ ｍｇ\nトコフェロール酢酸エステル / ５０ ｍｇ","statements":[{"label":"a","text":"リドカインは、まれに重篤な副作用としてショック（アナフィラキシー）を生じることがある。"},{"label":"b","text":"グリチルレチン酸は、比較的緩和な抗炎症作用を示す成分である。"},{"label":"c","text":"アラントインは、痛みや痒みを和らげることを目的として配合される局所麻酔成分である。"},{"label":"d","text":"トコフェロール酢酸エステルは、出血を抑えることを目的として配合される止血成分である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"正解は1で、aとbが正しい。リドカインなどの局所麻酔成分を配合した坐剤では、まれに重篤な副作用としてショック（アナフィラキシー）が起こることがある。グリチルレチン酸は比較的緩和な抗炎症作用を示す成分である。cは誤りで、アラントインは局所麻酔成分ではなく、肛門部の創傷の治癒を促す組織修復成分として配合される。dも誤りで、トコフェロール酢酸エステル（ビタミンE）は止血成分ではなく、末梢血管の血行を改善する目的で配合される。","tags":["痔疾用薬","局所麻酔成分","組織修復成分"]},{"id":"R5-43","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":43,"stem":"婦人薬として用いられる漢方処方製剤のうち、カンゾウを含むものの組合せを一つ選べ。","statements":[{"label":"a","text":"当帰芍薬散"},{"label":"b","text":"加味逍遙散"},{"label":"c","text":"桂枝茯苓丸"},{"label":"d","text":"桃核承気湯"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"正解は4（b、d）。手引きでは、婦人薬の漢方処方製剤のうち構成生薬としてカンゾウを含むものとして、温経湯、加味逍遙散、五積散、柴胡桂枝乾姜湯、桃核承気湯が挙げられている。選択肢のうち加味逍遙散（b）と桃核承気湯（d）がこれに当たる。当帰芍薬散（a）と桂枝茯苓丸（c）はカンゾウを含む処方として挙げられていないため、該当しない。","tags":["婦人薬","漢方処方製剤","カンゾウ"]},{"id":"R5-44","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":44,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを一つ選べ。\n比較的体力があり、ときに下腹部痛、肩こり、頭重、めまい、のぼせて足冷えなどを訴えるものの、月経不順、月経異常、月経痛、更年期障害、血の道症、肩こり、めまい、頭重、打ち身、しもやけ、しみ、湿疹・皮膚炎、にきびに適すとされる。","statements":[],"options":[{"n":1,"text":"桂枝茯苓丸"},{"n":2,"text":"温清飲"},{"n":3,"text":"桃核承気湯"},{"n":4,"text":"当帰芍薬散"},{"n":5,"text":"四物湯"}],"answer":1,"explanation":"正解は1の桂枝茯苓丸。手引きの桂枝茯苓丸の説明（比較的体力があり、下腹部痛、肩こり、頭重、めまい、のぼせて足冷えなどを訴えるもの。月経不順、月経痛、更年期障害、打ち身、しもやけ、しみ、湿疹・皮膚炎、にきびに適す）と一致する。当帰芍薬散は体力虚弱で冷え症・貧血の傾向がある人、四物湯は体力虚弱で皮膚が乾燥する人、温清飲は皮膚がかさかさしてのぼせる人、桃核承気湯は体力中等度以上でのぼせて便秘しがちな人が対象で、いずれも記述と異なる。","tags":["婦人薬","漢方処方製剤","桂枝茯苓丸"]},{"id":"R5-45","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":45,"stem":"鼻炎用内服薬及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"メチルエフェドリン塩酸塩は、依存性がある抗コリン成分であり、長期間にわたって連用された場合、薬物依存につながるおそれがある。"},{"label":"b","text":"ロラタジンは、肥満細胞から遊離したヒスタミンが受容体と反応するのを妨げることにより、ヒスタミンの働きを抑える作用を示す。"},{"label":"c","text":"トラネキサム酸は、皮膚や鼻粘膜の炎症を和らげることを目的として用いられる。"},{"label":"d","text":"クレマスチンフマル酸塩が配合された内服薬を服用した後は、乗物又は機械類の運転操作を避けることとされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":4,"explanation":"正解は4で、b、c、dが正しく、aが誤り。ロラタジンは抗ヒスタミン成分で、肥満細胞から遊離したヒスタミンが受容体と反応するのを妨げ、ヒスタミンの働きを抑える。トラネキサム酸は、鼻粘膜などの炎症による腫れを和らげる目的で用いられる。クレマスチンフマル酸塩などの抗ヒスタミン成分は眠気を起こしやすく、服用後は乗物や機械類の運転操作を避ける。aは誤りで、メチルエフェドリン塩酸塩は抗コリン成分ではなくアドレナリン作動成分であり、依存性があることは正しいが分類が違う。","tags":["鼻炎用内服薬","抗ヒスタミン成分","アドレナリン作動成分"]},{"id":"R5-46","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":46,"stem":"鼻炎用点鼻薬の配合成分に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"ナファゾリン塩酸塩は、鼻粘膜を通っている血管を拡張させることにより、鼻粘膜の充血や腫れを和らげる。"},{"label":"b","text":"ケトチフェンフマル酸塩は、ヒスタミンの働きを抑えることにより、くしゃみや鼻汁等の症状を緩和する。"},{"label":"c","text":"クロモグリク酸ナトリウムは、アレルギー性でない鼻炎や副鼻腔炎に対しても有効である。"},{"label":"d","text":"リドカイン塩酸塩は、鼻粘膜の過敏性や痛みや痒みを抑えることを目的として配合される場合がある。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":4,"explanation":"正解は4（b、d）。ケトチフェンフマル酸塩などの抗ヒスタミン成分は、ヒスタミンの働きを抑えてくしゃみや鼻汁を和らげる。リドカイン塩酸塩は、鼻粘膜の過敏性や痛み・痒みを抑える目的で配合されることがある。aは誤りで、ナファゾリン塩酸塩などのアドレナリン作動成分は血管を収縮させて充血や腫れを和らげる。cも誤りで、クロモグリク酸ナトリウムはアレルギー性でない鼻炎や副鼻腔炎には無効である。","tags":["鼻炎用点鼻薬","アドレナリン作動成分","クロモグリク酸"]},{"id":"R5-47","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":47,"stem":"眼科用薬及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"人工涙液は、涙液成分を補うことを目的とするもので、目の疲れや乾き、コンタクトレンズ装着時の不快感等に用いられる。"},{"label":"b","text":"プラノプロフェンは、炎症の原因となる物質の生成を抑える作用を示し、目の炎症を改善する効果を期待して用いられる。"},{"label":"c","text":"ホウ酸は、角膜の乾燥を防ぐことを目的として用いられる。"},{"label":"d","text":"サルファ剤は、細菌及び真菌の感染に対する効果が期待できるが、ウイルスの感染に対する効果はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"正解は2で、aとbが正しい。人工涙液は涙液成分を補う目的で、目の疲れや乾き、コンタクトレンズ装着時の不快感などに用いられる。プラノプロフェンは非ステロイド性抗炎症成分で、炎症の原因物質の生成を抑えて目の炎症を改善する。cは誤りで、ホウ酸は洗眼薬として結膜嚢の洗浄・消毒に用いられたり、抗菌作用による防腐剤として配合される成分で、角膜の乾燥を防ぐ目的ではない。dも誤りで、サルファ剤は細菌感染には用いられるが、ウイルスや真菌の感染に対する効果はない。","tags":["眼科用薬","サルファ剤","ホウ酸"]},{"id":"R5-48","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":48,"stem":"３０歳女性が、目の充血があるため、次の成分の一般用医薬品の一般点眼薬を購入する目的で店舗を訪れた。\n１００ｍＬ中：\n成分 / 分量\nテトラヒドロゾリン塩酸塩 / ０.０５ ｇ\nグリチルリチン酸二カリウム / ０.２５ ｇ\nクロルフェニラミンマレイン酸塩 / ０.０３ ｇ\nパンテノール / ０.１ｇ\nアスパラギン酸カリウム / １.０ｇ\n（添加物として、ベンザルコニウム塩化物、ｐＨ調整剤等を含む。）\nこの点眼薬に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"この医薬品には、結膜を通っている血管を収縮させて目の充血を除去することを目的としてテトラヒドロゾリン塩酸塩が配合されている。"},{"label":"b","text":"この医薬品に配合されるアスパラギン酸カリウムは、新陳代謝を促し、目の疲れを改善する効果を期待して配合されているアミノ酸成分である。"},{"label":"c","text":"この医薬品を点眼する際には、容器の先端が眼瞼（まぶた）や睫毛（まつげ）に触れないようにする。"},{"label":"d","text":"この医薬品は、ソフトコンタクトレンズを装着したまま点眼することができる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"正解は2で、a、b、cが正しく、dが誤り。テトラヒドロゾリン塩酸塩は結膜の血管を収縮させて目の充血を除去する目的で配合されるアドレナリン作動成分である。アスパラギン酸カリウムは、新陳代謝を促して目の疲れを改善する効果を期待して配合されるアミノ酸成分である。点眼時は容器の先端がまぶたやまつ毛に触れないようにし、汚染を防ぐ。dは誤りで、この製品には防腐剤としてベンザルコニウム塩化物が含まれ、ソフトコンタクトレンズに吸着して角膜障害の原因となるおそれがあるため、装着したままの点眼は避ける。","tags":["一般点眼薬","コンタクトレンズ","アドレナリン作動成分"]},{"id":"R5-49","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":49,"stem":"きず口等の殺菌消毒成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ベンザルコニウム塩化物は、石けんとの混合により殺菌消毒効果が高まる。"},{"label":"b","text":"ヨードチンキは、ヨウ素をポリビニルピロリドン（ＰＶＰ）に結合させて水溶性とし、ヨウ素が遊離して殺菌作用を示すように工夫されている。"},{"label":"c","text":"クロルヘキシジン塩酸塩は、結核菌を含む一般細菌類、真菌類、ウイルスに対して殺菌消毒作用を示す。"},{"label":"d","text":"消毒用エタノールは、皮膚への刺激性が弱いため、脱脂綿やガーゼに浸して患部に貼付することができる。"}],"options":[{"n":1,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"正解は5で、a、b、c、dはすべて誤り。aは、ベンザルコニウム塩化物は石けんと混ざると殺菌消毒効果が低下するので、石けんで洗った後は十分に洗い流す必要がある。bは、ヨウ素をPVPに結合させて水溶性にしたのはポビドンヨードで、ヨードチンキはヨウ素とヨウ化カリウムをエタノールに溶かしたものである。cは、クロルヘキシジンは一般細菌類や真菌類には作用するが、結核菌やウイルスには殺菌消毒作用がない。dは、消毒用エタノールは皮膚刺激性が強く、脱脂綿やガーゼに浸して患部に貼付することは避けるべきとされている。","tags":["殺菌消毒成分","ポビドンヨード","クロルヘキシジン"]},{"id":"R5-50","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":50,"stem":"外皮用薬及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"分子内にステロイド骨格を持たない非ステロイド性抗炎症成分として、デキサメタゾンがある。"},{"label":"b","text":"ケトプロフェンを主薬とする外皮用薬では、紫外線により、使用中又は使用後しばらくしてから重篤な光線過敏症が現れることがある。"},{"label":"c","text":"フェルビナクを主薬とする外皮用薬は、皮膚感染症に対して効果がなく、痛みや腫れを鎮めることでかえって皮膚感染が自覚されにくくなるおそれがある。"},{"label":"d","text":"インドメタシンを主薬とする外皮用薬は、妊婦又は妊娠していると思われる女性にも使用を推奨できる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"正解は3で、bとcが正しい。ケトプロフェンを主薬とする外皮用薬では、紫外線により重篤な光線過敏症が使用中や使用後しばらくしてから現れることがある。フェルビナクなどの非ステロイド性抗炎症成分は殺菌作用がなく、痛みや腫れを鎮めることで皮膚感染が自覚されにくくなるおそれがある。aは誤りで、デキサメタゾンはステロイド骨格を持つステロイド性抗炎症成分である。dも誤りで、インドメタシンなどを主薬とする外皮用薬は、胎児への影響を考慮し、妊婦や妊娠していると思われる女性では使用を避けるべきである。","tags":["外皮用薬","非ステロイド性抗炎症成分","光線過敏症"]},{"id":"R5-51","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":51,"stem":"外皮用薬及びその配合成分に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"温感刺激成分が配合された外皮用薬は、打撲や捻挫などの急性の腫れや熱感を伴う症状に対して適している。"},{"label":"b","text":"ジフェンヒドラミンは、適用部位でプロスタグランジンの産生を抑えることで、湿疹、皮膚炎、かぶれ、あせも等の皮膚症状の緩和を目的として使用される。"},{"label":"c","text":"ヘパリン類似物質は、患部局所の血行を促す目的で用いられるほか、抗炎症作用や保湿作用も期待される。"},{"label":"d","text":"アンモニアは、皮下の知覚神経に麻痺を起こさせる成分として、主に虫さされによる痒みに用いられる。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":5,"explanation":"正解は5（c、d）。ヘパリン類似物質は、患部局所の血行を促す目的で用いられ、抗炎症作用や保湿作用も期待される。アンモニアは皮下の知覚神経に麻痺を起こさせる成分として、主に虫さされによる痒みに用いられる。aは誤りで、打撲や捻挫などの急性の腫れや熱感を伴う症状には冷感刺激成分を配合したものが適しており、温感刺激成分は不向きである。bも誤りで、ジフェンヒドラミンは抗ヒスタミン成分で、ヒスタミンの働きを抑えて痒みなどを和らげる。プロスタグランジンの産生を抑えるのは非ステロイド性抗炎症成分である。","tags":["外皮用薬","抗ヒスタミン成分","ヘパリン類似物質"]},{"id":"R5-52","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":52,"stem":"毛髪用薬及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"効能・効果に「壮年性脱毛症」や「円形脱毛症」等の疾患名を掲げた製品の中には、医薬部外品として販売されているものもある。"},{"label":"b","text":"カシュウは、タデ科のツルドクダミの塊根を基原とする生薬で、頭皮における脂質代謝を高めて、余分な皮脂を取り除く作用を期待して用いられる。"},{"label":"c","text":"エストラジオール安息香酸エステルは、女性ホルモンによる脱毛抑制効果を期待して配合されている場合がある。"},{"label":"d","text":"ヒノキチオールは、ヒノキ科のタイワンヒノキ、ヒバ等から得られた精油成分で、抗菌、抗炎症などの作用を期待して用いられる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3で、b、c、dが正しく、aが誤り。カシュウはツルドクダミの塊根を基原とし、頭皮の脂質代謝を高めて余分な皮脂を取り除く作用を期待して用いられる。エストラジオール安息香酸エステルは、女性ホルモンによる脱毛抑制効果を期待して配合されることがある。ヒノキチオールはタイワンヒノキやヒバなどから得られる精油成分で、抗菌・抗炎症作用を期待して用いられる。aは誤りで、「壮年性脱毛症」「円形脱毛症」などの疾患名を掲げた効能・効果は、医薬部外品では認められず、医薬品においてのみ認められている。","tags":["毛髪用薬","医薬部外品","エストラジオール"]},{"id":"R5-53","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":53,"stem":"歯痛・歯槽膿漏薬の配合成分とその配合目的としての作用に関する記述の正誤について、正しい組合せを一つ選べ。（配合成分：配合目的としての作用）","statements":[{"label":"a","text":"ジブカイン塩酸塩：齲蝕（むし歯）で露出した歯髄の知覚神経の伝達を遮断して痛みを鎮める。"},{"label":"b","text":"カルバゾクロム：歯肉炎、歯周炎（歯槽膿漏）の症状である口臭を抑える。"},{"label":"c","text":"オイゲノール：齲蝕（むし歯）部分での細菌の繁殖を抑える。"},{"label":"d","text":"銅クロロフィリンナトリウム：炎症を起こした歯周組織の修復を促す。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"正解は2で、a、c、dが正しく、bが誤り。ジブカイン塩酸塩は局所麻酔成分で、むし歯で露出した歯髄の知覚神経の伝達を遮断して痛みを鎮める。オイゲノールは殺菌消毒成分で、むし歯部分での細菌の繁殖を抑える。銅クロロフィリンナトリウムは、炎症を起こした歯周組織の修復を促す。bは誤りで、カルバゾクロムは止血成分であり、炎症を起こした歯周組織からの出血を抑える作用を期待して配合されるもので、口臭を抑える目的ではない。","tags":["歯痛・歯槽膿漏薬","局所麻酔成分","止血成分"]},{"id":"R5-54","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":54,"stem":"次の記述は、登録販売者と禁煙補助剤（咀嚼剤）の購入者との会話である。購入者からの相談に対する登録販売者の説明について、適切なものの組合せを一つ選べ。","statements":[{"label":"a","text":"購入者：ニコチン離脱症状とはどのような症状ですか。／登録販売者：血中のニコチン濃度の低下によって、イライラしたり、集中できなくなったり、落ち着かない等の症状がでます。"},{"label":"b","text":"購入者：ニコチン置換療法とはどのようなものですか。／登録販売者：喫煙を継続しながら徐々に本剤に変更していく方法です。離脱症状の軽減を図りながら徐々に摂取量を減らし、最終的にニコチン摂取をゼロにします。"},{"label":"c","text":"購入者：本剤を使用する場合、食べ物や飲み物で気をつけることはありますか。／登録販売者：口の中が酸性になるとニコチンの吸収が増加するので、口腔内を酸性にするコーヒーや炭酸飲料などを飲んだ後はしばらく使用を避ける必要があります。"},{"label":"d","text":"購入者：高血圧の薬を飲んでいるのですが、本剤を使用しても大丈夫ですか。／登録販売者：使用している治療薬の効果に影響を生じたり、症状を悪化させる可能性があるため、使用の適否については主治医と相談してください。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":2,"explanation":"正解は2（a、d）。aは、ニコチン離脱症状は血中ニコチン濃度の低下によるイライラ、集中困難、落ち着かないなどの症状で、説明は適切である。dは、高血圧などの診断を受けた人は治療薬の効果に影響したり症状を悪化させる可能性があるため、使用の適否を医師などに相談するよう伝えるのが適切である。bは誤りで、ニコチン置換療法は喫煙を完全にやめたうえで、ニコチンの摂取方法を喫煙以外に換える方法である。cも誤りで、口腔内が酸性になるとニコチンの吸収は増加ではなく低下するため、コーヒーや炭酸飲料の後はしばらく使用を避ける。","tags":["禁煙補助剤","ニコチン置換療法","相互作用"]},{"id":"R5-55","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":55,"stem":"ビタミン成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ビタミンＢ６は、脂質の代謝に関与し、皮膚や粘膜の機能を正常に保つために重要な栄養素である。"},{"label":"b","text":"ビタミンＢ２は、炭水化物からのエネルギー産生に不可欠な栄養素で、腸管運動を促進する作用がある。"},{"label":"c","text":"ビタミンＤの欠乏症として、高カルシウム血症、異常石灰化が知られている。"},{"label":"d","text":"ビタミンＡは、夜間視力を維持したり、皮膚や粘膜の機能を正常に保つために重要な栄養素である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":5,"explanation":"正解は5で、dだけが正しい。ビタミンAは夜間視力を維持し、皮膚や粘膜の機能を正常に保つために重要な栄養素である。aは誤りで、記述は脂質の代謝に関与し皮膚や粘膜の機能を保つビタミンB2の説明であり、ビタミンB6はタンパク質の代謝に関与する。bは誤りで、炭水化物からのエネルギー産生に不可欠で腸管運動を促進するのはビタミンB1の説明である。cは誤りで、高カルシウム血症や異常石灰化はビタミンDの欠乏症ではなく過剰症として知られている。","tags":["ビタミン成分","ビタミンB群","ビタミンD"]},{"id":"R5-56","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":56,"stem":"滋養強壮保健薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"コンドロイチン硫酸は、肝臓の働きを助け、肝血流を促進する働きがあり、全身倦怠感や疲労時の栄養補給を目的として配合される場合がある。"},{"label":"b","text":"カルシウムは、骨や歯の形成に必要な栄養素であり、筋肉の収縮、血液凝固、神経機能にも関与する。"},{"label":"c","text":"アスパラギン酸ナトリウムは、アスパラギン酸のビタミンＣの吸収を助ける等の作用を期待して、滋養強壮保健薬やかぜ薬に配合されている場合がある。"},{"label":"d","text":"ナイアシンは、下垂体や副腎系に作用してホルモンの分泌の調節に関与するため、ときに経血量が多くなることがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"正解は3で、bだけが正しい。カルシウムは骨や歯の形成に必要な栄養素で、筋肉の収縮、血液凝固、神経機能にも関与する。aは誤りで、肝臓の働きを助け肝血流を促進するのはグルクロノラクトンであり、コンドロイチン硫酸は軟骨成分を形成・修復する働きが期待される成分である。cは誤りで、ビタミンCの吸収を助ける作用があるのはヘスペリジンで、アスパラギン酸ナトリウムはエネルギー産生効率を高め、乳酸の分解を促すなどの働きが期待される。dは誤りで、下垂体や副腎系に作用しホルモン分泌の調節に関与し、経血量が増えることがあるのはビタミンEである。","tags":["滋養強壮保健薬","アミノ酸成分","ビタミンE"]},{"id":"R5-57","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":57,"stem":"一般用医薬品の防風通聖散に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"体力が充実して、脇腹からみぞおちあたりにかけて苦しく、便秘の傾向があるものの胃炎、常習便秘、高血圧や肥満に伴う肩こり・頭痛・便秘、神経症、肥満症に適すとされる。"},{"label":"b","text":"構成生薬としてマオウは含まれない。"},{"label":"c","text":"便秘に用いられる場合には、漫然と長期の使用は避け、１週間位使用しても症状の改善がみられないときは、いったん使用を中止して専門家に相談するなどの対応が必要である。"},{"label":"d","text":"肥満症又は肥胖症に用いられる場合、医薬品の販売等に従事する専門家においては、生活習慣の改善が重要であることを説明する等、正しい理解を促すことが重要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"正解は2で、cとdが正しい。防風通聖散を便秘に用いる場合は、漫然と長期使用せず、1週間位使用しても症状の改善がみられないときはいったん使用を中止して専門家に相談する。肥満症に用いる場合は、生活習慣の改善が重要であることを説明して正しい理解を促す。aは誤りで、この記述は大柴胡湯の説明であり、防風通聖散は体力充実で腹部に皮下脂肪が多く便秘がちな人が対象となる。bも誤りで、防風通聖散の構成生薬にはカンゾウ、マオウ、ダイオウが含まれる。","tags":["漢方処方製剤","防風通聖散","肥満症"]},{"id":"R5-58","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":58,"stem":"感染症の防止及び消毒薬に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"滅菌は、物質中のすべての微生物を殺滅又は除去することである。"},{"label":"b","text":"消毒薬の効果は、微生物の種類による影響を受けない。"},{"label":"c","text":"クレゾール石ケン液は、結核菌を含む一般細菌類、真菌類に対して殺菌消毒作用を示すが、大部分のウイルスに対する殺菌消毒作用はない。"},{"label":"d","text":"次亜塩素酸ナトリウムは、皮膚刺激性が弱く、手指・皮膚の消毒に適している。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":2,"explanation":"正解は2で、aとcが正しい。滅菌は物質中のすべての微生物を殺滅または除去することである。クレゾール石ケン液は、結核菌を含む一般細菌類や真菌類に作用するが、大部分のウイルスには殺菌消毒作用がない。bは誤りで、消毒薬の効果は成分の種類や濃度、温度、時間、対象物の汚染度、微生物の種類や状態などによって異なる。dも誤りで、次亜塩素酸ナトリウムなどの塩素系殺菌消毒成分は皮膚刺激性が強いため、通常は人体の消毒には用いられない。","tags":["消毒薬","滅菌","クレゾール石ケン液"]},{"id":"R5-59","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":59,"stem":"殺虫剤・忌避剤及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"シラミの防除には、フェノトリンが配合されたシャンプーが有効である。"},{"label":"b","text":"ゴキブリの卵は、殺虫剤の成分が浸透しやすい殻で覆われているため、燻蒸処理を行えば駆除できる。"},{"label":"c","text":"イエダニは、ネズミを宿主として生息場所を広げていくため、まず、宿主動物であるネズミを駆除することが重要である。"},{"label":"d","text":"イカリジンは、年齢による使用制限がない成分で、蚊やマダニに対して殺虫効果を示す。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"正解は1で、aとcが正しい。シラミの防除には、フェノトリンを配合したシャンプーなどが用いられる。イエダニはネズミを宿主として生息場所を広げるため、防除ではまず宿主のネズミを駆除することが重要である。bは誤りで、ゴキブリの卵は医薬品の成分が浸透しない殻で覆われているため、1回の燻蒸処理では卵に殺虫効果が及ばず、3週間位後にもう一度燻蒸処理を行って孵化した幼虫を駆除する必要がある。dは誤りで、イカリジンは年齢による使用制限がない忌避成分であり、殺虫効果を示すのではなく、蚊やマダニなどを寄せつけにくくする。","tags":["殺虫剤・忌避剤","フェノトリン","イカリジン"]},{"id":"R5-60","chapter":3,"source":"関西広域連合 令和5年度 登録販売者試験 前半","no":60,"stem":"尿糖・尿タンパク検査薬に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"通常、尿は弱アルカリ性であるが、食事その他の影響で中性～弱酸性に傾くと、正確な検査結果が得られなくなることがある。"},{"label":"b","text":"尿タンパク検査の場合、中間尿ではなく出始めの尿を採取して検査することが望ましい。"},{"label":"c","text":"尿タンパク検査の場合、原則として早朝尿（起床直後の尿）を検体とし、激しい運動の直後は避ける必要がある。"},{"label":"d","text":"尿糖検査の結果に異常がある場合、その要因は、腎炎やネフローゼ、尿路感染症、尿路結石等がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":3,"explanation":"正解は3で、cだけが正しい。尿タンパク検査では、原則として早朝尿（起床直後の尿）を検体とし、激しい運動の直後は避ける必要がある。aは誤りで、通常の尿は弱酸性であり、食事などの影響で中性から弱アルカリ性に傾くと正確な検査結果が得られなくなることがある。bは誤りで、出始めの尿は尿道や外陰部の細菌などが混入しやすいため、中間尿を採取することが望ましい。dは誤りで、腎炎、ネフローゼ、尿路感染症、尿路結石などは尿タンパク値の異常の要因であり、尿糖は主に高血糖や腎性糖尿などと結びつく。","tags":["尿糖・尿タンパク検査薬","早朝尿","中間尿"]},{"id":"R5-81","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":81,"stem":"次の記述は、法第１条の５第１項の条文の一部である。（　　）の中に入れるべき字句の正しい組合せを一つ選べ。なお、複数箇所の（　ｂ　）内は、いずれも同じ字句が入る。\n医師、歯科医師、薬剤師、（　ａ　）その他の医薬関係者は、医薬品等の有効性及び安全性その他これらの（　ｂ　）に関する知識と理解を深めるとともに、これらの使用の対象者（略）及びこれらを購入し、又は譲り受けようとする者に対し、これらの（　ｂ　）に関する事項に関する（　ｃ　）な情報の提供に努めなければならない。","statements":[],"options":[{"n":1,"text":"a 登録販売者 / b 適正な使用 / c 正確かつ適切"},{"n":2,"text":"a 登録販売者 / b 適正な保管方法 / c 具体的"},{"n":3,"text":"a 獣医師 / b 適正な使用 / c 具体的"},{"n":4,"text":"a 獣医師 / b 適正な使用 / c 正確かつ適切"},{"n":5,"text":"a 獣医師 / b 適正な保管方法 / c 具体的"}],"answer":4,"explanation":"法第1条の5第1項は医薬関係者の責務を定めた規定で、医師・歯科医師・薬剤師のあとに入るのは獣医師です。医薬品等の有効性・安全性その他の「適正な使用」に関する知識と理解を深め、購入者などに対して「正確かつ適切」な情報提供に努めるよう求めています。登録販売者は条文に列挙された職種ではなく、「保管方法」や「具体的」といった語も条文にはありません。よって獣医師・適正な使用・正確かつ適切の組合せである4が正解です。","tags":["医薬関係者の責務","法第1条の5"]},{"id":"R5-82","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":82,"stem":"登録販売者に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"薬局開設者は、その薬局において業務に従事する登録販売者に対し、厚生労働大臣に届出を行った研修実施機関が行う研修を、毎年度受講させなければならない。"},{"label":"b","text":"販売従事登録を受けようと申請する者が、精神機能の障害により業務を適正に行うに当たって必要な認知、判断及び意思疎通を適切に行うことができないおそれがある場合は、当該申請者に係る精神の機能の障害に関する医師の診断書を、申請書に添えなければならない。"},{"label":"c","text":"二以上の都道府県において一般用医薬品の販売又は授与に従事しようとする者は、いずれか一の都道府県知事の販売従事登録のみを受けることができる。"},{"label":"d","text":"登録販売者は、一般用医薬品の販売又は授与に従事しようとしなくなったときは、３０日以内に、登録販売者名簿の登録の消除を申請しなければならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"登録販売者について、a・b・c・dはいずれも正しい記述です。aは規則第15条の11の3などにより、薬局開設者・店舗販売業者・配置販売業者が、厚生労働大臣に届け出た研修実施機関の研修を登録販売者に毎年度受講させる義務です。bは規則第159条の7第2項第3号で、精神の機能の障害により業務に必要な認知・判断・意思疎通を適切に行えないおそれがある申請者には医師の診断書の添付が必要です。cは同条第3項で、複数の都道府県で申請しても登録を受けられるのは一つの都道府県知事のものだけです。dは規則第159条の10第1項で、販売又は授与に従事しなくなったときは30日以内に名簿の登録消除を申請します。誤りの記述はなく5が正解です。","tags":["登録販売者","販売従事登録","研修"]},{"id":"R5-83","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":83,"stem":"一般用医薬品及び要指導医薬品に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品及び要指導医薬品は、あらかじめ定められた用量に基づき、適正使用することによって効果を期待するものである。"},{"label":"b","text":"一般用医薬品及び要指導医薬品の効能効果の表現は、通常、診断疾患名（胃炎、胃・十二指腸潰瘍等）で示されている。"},{"label":"c","text":"要指導医薬品は、定められた期間を経過し、薬事・食品衛生審議会において、一般用医薬品として取り扱うことが適切であると認められると、一般用医薬品に分類される。"},{"label":"d","text":"要指導医薬品には、人体に直接使用されない検査薬であって、血液を検体とするものなど、検体の採取に身体への直接のリスクを伴うものもある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"aは正しく、一般用医薬品・要指導医薬品はあらかじめ定められた用量で適正に使うことで効果を期待するものです（医療用医薬品は医師が患者ごとに量を決める）。bは誤りで、診断疾患名（胃炎、胃・十二指腸潰瘍等）で効能効果が示されるのは医療用医薬品であり、一般用・要指導医薬品は生活者が判断できる症状（胃痛、胸やけ等）で示されます。cは正しく、定められた期間を経過し薬事審議会が一般用医薬品として取り扱うことが適切と認めたものは一般用医薬品に分類されます。dは誤りで、血液を検体とするなど検体採取に身体への直接のリスクを伴う検査薬は、一般用・要指導医薬品として認められていません。したがってa正・b誤・c正・d誤の4が正解です。","tags":["要指導医薬品","一般用医薬品","医療用医薬品との違い"]},{"id":"R5-84","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":84,"stem":"毒薬及び劇薬に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"毒薬は、１８歳未満の者その他安全な取扱いに不安のある者に交付してはならない。"},{"label":"b","text":"劇薬を貯蔵、陳列する場所には、かぎを施さなければならない。"},{"label":"c","text":"現在のところ、一般用医薬品には、毒薬又は劇薬に該当するものはない。"},{"label":"d","text":"劇薬を一般の生活者に対して販売又は譲渡する際、当該医薬品を譲り受ける者から交付を受ける文書には、当該譲受人の職業の記載は不要である。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"aは誤りで、毒薬・劇薬を交付してはならないのは「14歳未満の者」その他安全な取扱いに不安のある者です（法第47条）。bは誤りで、かぎを施して貯蔵・陳列しなければならないのは毒薬を貯蔵・陳列する場所であり、劇薬にはこの義務はありません（法第48条第2項）。cは正しく、現在のところ毒薬・劇薬に該当する一般用医薬品はありません（要指導医薬品には該当するものがある）。dは誤りで、一般の生活者に販売・譲渡する際に受け取る文書には、品名・数量・使用目的・譲渡年月日のほか、譲受人の氏名・住所・職業の記載が必要です（法第46条、規則第205条）。よってa誤・b誤・c正・d誤の4が正解です。","tags":["毒薬・劇薬","法第44条〜第48条"]},{"id":"R5-85","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":85,"stem":"生物由来製品に関する記述について、［　　］の中に入れるべき字句の正しい組合せを一つ選べ。\n生物由来製品は、法第２条第１０項において、「人その他の生物（［　ａ　］を除く。）に由来するものを原料又は材料として製造をされる医薬品、［　ｂ　］のうち、保健衛生上特別の注意を要するものとして、厚生労働大臣が薬事・食品衛生審議会の意見を聴いて指定するもの」と定義されており、現在の科学的知見において、［　ｃ　］の発生リスクの蓋然性が極めて低いものについては、指定の対象とならない。","statements":[],"options":[{"n":1,"text":"a 植物 / b 医薬部外品、化粧品又は医療機器 / c 感染症"},{"n":2,"text":"a 植物 / b 医薬部外品、化粧品又は医療機器 / c 副作用"},{"n":3,"text":"a 植物 / b 医薬部外品又は医療機器 / c 副作用"},{"n":4,"text":"a 微生物 / b 医薬部外品、化粧品又は医療機器 / c 感染症"},{"n":5,"text":"a 微生物 / b 医薬部外品又は医療機器 / c 副作用"}],"answer":1,"explanation":"生物由来製品は法第2条第10項で、人その他の生物（植物を除く）に由来するものを原料・材料として製造される医薬品、医薬部外品、化粧品又は医療機器のうち、保健衛生上特別の注意を要するものとして指定されたものをいいます。植物は除かれるので、aは微生物ではなく植物です。bは対象が医薬部外品、化粧品又は医療機器の3種で、化粧品が含まれます。cは製品の使用による「感染症」の発生リスクに着目して指定されるため、副作用ではありません。現在のところ、生物由来製品に指定された一般用医薬品・要指導医薬品はありません。以上から1が正解です。","tags":["生物由来製品","法第2条第10項"]},{"id":"R5-86","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":86,"stem":"法第５０条に基づき、一般用医薬品の直接の容器又は直接の被包に記載されていなければならない事項について、正しいものの組合せを一つ選べ。ただし、厚生労働省令で定める表示の特例に関する規定は考慮しなくてよい。","statements":[{"label":"a","text":"重量、容量又は個数等の内容量"},{"label":"b","text":"配置販売品目以外の一般用医薬品にあっては、「店舗専用」の文字"},{"label":"c","text":"用法及び用量"},{"label":"d","text":"製造販売業者等の氏名又は名称及び電話番号"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":1,"explanation":"法第50条に基づき直接の容器・被包に記載する事項（法定表示）には、aの重量・容量又は個数等の内容量と、bの配置販売品目以外の一般用医薬品における「店舗専用」の文字が含まれます。cの用法及び用量は、容器等ではなく添付文書等に記載する事項（法第52条）に当たります。dは、記載するのは製造販売業者等の氏名又は名称及び「住所」であり、電話番号は法定の表示事項ではありません。したがって正しいのはa、bで1が正解です。","tags":["法定表示","法第50条"]},{"id":"R5-87","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":87,"stem":"医薬部外品に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般小売店では、医薬品の販売業の許可がなくても医薬部外品を販売することができる。"},{"label":"b","text":"人又は動物の保健のために、ねずみ、はえ、蚊、のみ、その他これらに類する生物の防除の目的のために使用される物であり、機械器具等を含む。"},{"label":"c","text":"効能効果があらかじめ定められた範囲内であって、成分や用法等に照らして人体に対する作用が緩和であることを要件として、医薬品的な効能効果を表示・標榜することが認められている。"},{"label":"d","text":"医薬部外品の直接の容器又は直接の被包には、「医薬部外品」の文字の表示が義務付けられている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"aは正しく、医薬部外品は医薬品のような販売業の許可が不要で、一般小売店で販売できます。bは誤りで、防除の目的で使う医薬部外品は「機械器具等でないもの」とされており、機械器具等は含まれません（法第2条第2項）。cは正しく、効能効果があらかじめ定められた範囲内で、人体に対する作用が緩和であることを要件に、医薬品的な効能効果の表示・標ぼうが認められます。dは正しく、直接の容器又は被包に「医薬部外品」の文字の表示が義務付けられています（法第59条）。よってa正・b誤・c正・d正の2が正解です。","tags":["医薬部外品","法第2条第2項","法第59条"]},{"id":"R5-88","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":88,"stem":"化粧品の効能効果として表示・標榜することが認められている範囲に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"乾燥による小ジワを目立たなくする。"},{"label":"b","text":"日やけによるシミ、ソバカスを防ぐ。"},{"label":"c","text":"脱毛を防止する。"},{"label":"d","text":"芳香を与える。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"化粧品は、身体を清潔にし、美化し、魅力を増し、容貌を変え、又は皮膚・毛髪を健やかに保つ範囲でのみ効能効果の表示・標ぼうが認められ、医薬品的な効能効果は認められません。手引きの化粧品の効能効果の範囲には、aの乾燥による小ジワを目立たなくする、bの日やけによるシミ、ソバカスを防ぐ、dの芳香を与える、が含まれます。cの脱毛を防止することは、育毛・脱毛の防止として医薬部外品に認められる範囲の効能であり、化粧品では標ぼうできません。よってa正・b正・c誤・d正の2が正解です。","tags":["化粧品","効能効果の範囲"]},{"id":"R5-89","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":89,"stem":"保健機能食品等の食品に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"食品とは、医薬品、医薬部外品及び再生医療等製品以外のすべての飲食物をいう。"},{"label":"b","text":"特定保健用食品、機能性表示食品、特別用途食品を総称して、保健機能食品という。"},{"label":"c","text":"特別用途食品の中には、えん下困難者用食品が含まれる。"},{"label":"d","text":"機能性表示食品は、食品表示法に基づく食品表示基準に規定されている食品である。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"aは正しく、食品とは医薬品、医薬部外品及び再生医療等製品以外のすべての飲食物をいいます。bは誤りで、保健機能食品は特定保健用食品、栄養機能食品、機能性表示食品の総称であり、特別用途食品は含まれません。cは正しく、特別用途食品にはえん下困難者用食品などが含まれます。dは正しく、機能性表示食品は食品表示法に基づく食品表示基準に規定された食品で、事業者の責任で届け出るものです。よってa正・b誤・c正・d正の2が正解です。","tags":["保健機能食品","特別用途食品","機能性表示食品"]},{"id":"R5-91","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":91,"stem":"薬局に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"医療法において、調剤を実施する薬局は、医療提供施設として位置づけられている。"},{"label":"b","text":"薬局では、特定の購入者の求めに応じて医薬品の包装を開封して分割販売することはできるが、医薬品をあらかじめ小分けし、販売することはできない。"},{"label":"c","text":"薬局で薬事に関する実務に従事する薬剤師を管理者とすることができない場合には、その薬局において一般用医薬品の販売又は授与に関する業務に従事する登録販売者を管理者にすることができる。"},{"label":"d","text":"薬剤の適正な使用の確保のため、診療又は調剤に従事する他の医療提供施設と連携することで、専門的な薬学的知見に基づく指導を実施するために必要な機能を備える薬局は、傷病の区分ごとに、その所在地の都道府県知事の認定を受けて地域連携薬局と称することができる。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":1,"explanation":"aは正しく、調剤を実施する薬局は医療法上、医療提供施設に位置づけられています。bも正しく、薬局では特定の購入者の求めに応じて包装を開封して分割販売できますが、あらかじめ小分けして販売することは無許可製造等に当たり認められません。cは誤りで、薬局の管理者になれるのは薬事に関する実務に従事する薬剤師であり、登録販売者を管理者にする規定はありません（法第7条）。dは誤りで、傷病の区分ごとに都道府県知事の認定を受けるのは専門医療機関連携薬局（法第6条の3）であり、地域連携薬局（法第6条の2）ではありません。したがって正しいのはa、bで1が正解です。","tags":["薬局","分割販売","専門医療機関連携薬局"]},{"id":"R5-92","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":92,"stem":"店舗販売業者が薬剤師又は登録販売者に行わせる、要指導医薬品又は一般用医薬品のリスク区分に応じた情報提供等に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"要指導医薬品を販売又は授与する場合には、情報提供を行った薬剤師の氏名、店舗の名称及び店舗の電話番号、その他連絡先を購入者等へ伝えさせなければならない。"},{"label":"b","text":"第一類医薬品を販売又は授与する場合には、その店舗において医薬品の販売又は授与に従事する薬剤師又は登録販売者に、書面を用いて、必要な情報を提供させなければならない。"},{"label":"c","text":"第二類医薬品を販売又は授与する場合には、その店舗において医薬品の販売又は授与に従事する薬剤師又は登録販売者に、必要な情報を提供させるよう努めなければならない。"},{"label":"d","text":"第三類医薬品を購入した者から相談があった場合には、その店舗において医薬品の販売等に従事する薬剤師又は登録販売者に、必要な情報を提供させなければならない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"aは正しく、要指導医薬品の販売では、販売した薬剤師の氏名、薬局・店舗の名称及び電話番号その他連絡先を購入者に伝えさせる義務があります（規則第158条の11）。bは誤りで、第一類医薬品の書面による情報提供を行うのは薬剤師に限られ、登録販売者は行えません（法第36条の10第1項）。cは正しく、第二類医薬品の情報提供は薬剤師又は登録販売者による努力義務です（同条第3項）。dは正しく、第三類医薬品でも購入者等から相談があった場合は必要な情報を提供させなければなりません（同条第5項、規則第159条の17）。よってa正・b誤・c正・d正の1が正解です。","tags":["情報提供","リスク区分","法第36条の10"]},{"id":"R5-93","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":93,"stem":"店舗販売業者が医薬品を陳列する方法に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品は、他の物と区別して陳列しなければならない。"},{"label":"b","text":"要指導医薬品と一般用医薬品を、混在しないように陳列しなければならない。"},{"label":"c","text":"一般用医薬品は、薬効群ごとに区別すれば、リスク区分ごとに区別して陳列する必要はない。"},{"label":"d","text":"指定第二類医薬品を、鍵をかけた陳列設備に陳列する場合は、「情報提供を行うための設備」から７メートル以内の範囲に陳列する必要はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"aは正しく、医薬品は他の物と区別して貯蔵・陳列します（法第57条の2第1項）。bも正しく、要指導医薬品と一般用医薬品は混在しないよう陳列します（規則第218条の3）。cは誤りで、一般用医薬品は第一類・第二類・第三類のリスク区分ごとに区別して陳列する必要があり、薬効群での区別だけでは足りません（規則第218条の4）。dは正しく、指定第二類医薬品は情報提供を行うための設備から7メートル以内に陳列するのが原則ですが、鍵をかけた陳列設備に陳列する場合は例外です。よってa正・b正・c誤・d正の2が正解です。","tags":["陳列","指定第二類医薬品","法第57条の2"]},{"id":"R5-94","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":94,"stem":"薬局開設者が、法第９条の５の規定に基づき、当該薬局の見やすい場所に掲示しなければならない事項の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"勤務する薬剤師の薬剤師免許証"},{"label":"b","text":"営業時間、営業時間外で相談できる時間及び営業時間外で医薬品の購入、譲受けの申込みを受理する時間"},{"label":"c","text":"指定第二類医薬品を購入し、又は譲り受けようとする場合は、当該指定第二類医薬品の禁忌を確認すること及び当該指定第二類医薬品の使用について、薬剤師又は登録販売者に相談することを勧める旨"},{"label":"d","text":"医薬品による健康被害の救済制度に関する解説"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"法第9条の5に基づく薬局内の掲示事項は、管理・運営に関する事項と、医薬品の販売制度に関する事項に分かれます。aは誤りで、掲示するのは勤務する薬剤師・登録販売者の別、氏名及び担当業務であり、免許証そのものの掲示は求められていません。bは正しく、営業時間、営業時間外で相談できる時間及び購入等の申込みを受理する時間を掲示します。cも正しく、指定第二類医薬品について禁忌を確認すること及び薬剤師又は登録販売者に相談することを勧める旨を掲示します。dも正しく、医薬品による健康被害の救済制度に関する解説が掲示事項に含まれます（規則第15条の15、別表第1の2）。よってa誤・b正・c正・d正の3が正解です。","tags":["掲示事項","法第9条の5"]},{"id":"R5-95","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":95,"stem":"薬局における特定販売に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"劇薬に該当する薬局製造販売医薬品は、特定販売により販売することができる。"},{"label":"b","text":"特定販売を行うことについて、インターネットを利用して広告する場合はホームページに、一般用医薬品の陳列の状況を示す写真を見やすく表示しなければならない。"},{"label":"c","text":"特定販売を行う薬局に注文された医薬品がない場合、別の薬局から発送することができる。"},{"label":"d","text":"特定販売により一般用医薬品を購入しようとする者から、対面又は電話による相談応需の希望があった場合には、当該薬局において従事する薬剤師又は登録販売者が対面又は電話により情報提供を行わなければならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"特定販売は、薬局・店舗に貯蔵・陳列している要指導医薬品（特定要指導医薬品を除く）、一般用医薬品又は薬局製造販売医薬品（毒薬及び劇薬であるものを除く）を店舗外の者に販売する方法です（規則第1条の2第2項）。aは誤りで、劇薬に該当する薬局製造販売医薬品は特定販売の対象外です。bは正しく、広告時にはホームページに一般用医薬品等の陳列の状況を示す写真などを見やすく表示します。cは誤りで、その薬局に貯蔵・陳列している医薬品を販売するのが要件であり、別の薬局から発送することはできません。dは正しく、対面又は電話での相談希望があれば、薬剤師又は登録販売者が対面又は電話で情報提供します（規則第159条の17第2項）。よってa誤・b正・c誤・d正の5が正解です。","tags":["特定販売","薬局製造販売医薬品"]},{"id":"R5-96","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":96,"stem":"医薬品の広告に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の効能、効果等について、医師その他の者がこれを保証したものと誤解されるおそれがある記事を広告し、記述し、又は流布してはならない。"},{"label":"b","text":"医薬品の広告に該当するか否かについては、（１）顧客を誘引する意図が明確であること、（２）特定の医薬品の商品名（販売名）が明らかにされていること、（３）一般人が認知できる状態であることのうち、いずれかの要件を満たす場合、該当するものと判断される。"},{"label":"c","text":"厚生労働大臣が医薬品、医療機器等の名称、製造方法、効能、効果又は性能に関する虚偽・誇大な広告を行った者に対して、違反を行っていた期間中における対象商品の売上額×４.５％の課徴金の納付を命じる「課徴金制度」がある。"},{"label":"d","text":"医薬品の製造販売業者に限っては、承認前の医薬品の名称に関する広告を行うことができる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"aは正しく、医薬品の効能・効果等について医師その他の者が保証したと誤解されるおそれのある記事の広告・記述・流布は禁止されています（法第66条第2項）。bは誤りで、広告に該当するかは、顧客を誘引する意図が明確、特定の医薬品の商品名が明らか、一般人が認知できる状態、の3要件の「いずれも」を満たす場合に判断されます（1つでは足りません）。cは正しく、虚偽・誇大な広告を行った者には、違反期間中の対象商品の売上額の4.5%の課徴金制度があります（法第75条の5の2）。dは誤りで、承認前の医薬品の名称・効能・効果等に関する広告は、製造販売業者を含め何人もしてはなりません（法第68条）。よってa正・b誤・c正・d誤の4が正解です。","tags":["医薬品の広告","課徴金","法第66条・第68条"]},{"id":"R5-97","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":97,"stem":"医薬品等適正広告基準に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"「医薬品等適正広告基準」においては、購入者等に対して、医薬品について、事実に反する認識を与えるおそれがある広告のほか、過度の消費や乱用を助長するおそれがある広告についても、不適正なものとされている。"},{"label":"b","text":"医薬品等の使用前後の写真は、効能効果を保証するために積極的に用いるのが適当である。"},{"label":"c","text":"漢方処方製剤の効能効果は、配合されている個々の生薬成分がそれぞれ作用しているため、それらの構成生薬の作用を個別に挙げて説明することが適当である。"},{"label":"d","text":"一般用医薬品については、同じ有効成分を含有する医療用医薬品の効能効果をそのまま標榜すれば、承認されている内容を正確に反映した広告といえる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"aは正しく、医薬品等適正広告基準は、事実に反する認識を与えるおそれのある広告に加え、過度の消費や乱用を助長するおそれのある広告も不適正としています。bは誤りで、使用前後を問わず図画・写真等が効能効果の保証表現となるものは認められず、積極的に用いるのは不適当です。cは誤りで、漢方処方製剤の効能効果は個々の生薬成分が相互に作用するものなので、構成生薬の作用を個別に挙げて説明するのは不適当です。dは誤りで、医療用医薬品の効能効果をそのまま標ぼうしても、承認された一般用医薬品の内容を正確に反映した広告とはいえません。よってa正・b誤・c誤・d誤の4が正解です。","tags":["医薬品等適正広告基準","漢方処方製剤"]},{"id":"R5-98","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":98,"stem":"医薬品の販売方法に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品を懸賞や景品として授与することは、原則として認められていない。"},{"label":"b","text":"キャラクターグッズ等の景品類を提供して医薬品を販売することは、不当景品類及び不当表示防止法の限度内であれば認められている。"},{"label":"c","text":"配置販売業において、医薬品を先用後利によらず現金売りを行うことは、顧客の求めに応じたものであれば、適正な販売方法である。"},{"label":"d","text":"店舗販売業者が、在庫処分を主な目的に、効能効果が重複する医薬品を組み合わせて販売することは、適正な販売方法である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"aは正しく、一般用医薬品を懸賞や景品として授与することは原則として認められません。bも正しく、キャラクターグッズ等の景品類を付けて販売することは、不当景品類及び不当表示防止法の限度内であれば認められます。cは誤りで、配置販売業で先用後利によらず現金売りをすることは配置による販売行為に当たらず、顧客の求めがあっても法第37条第1項に違反します。dは誤りで、組み合わせ販売は購入者の利便性のために合理性がある場合に限られ、在庫処分などの販売側の都合や効能効果が重複する組み合わせは認められません。よってa正・b正・c誤・d誤の3が正解です。","tags":["販売方法","組み合わせ販売","配置販売"]},{"id":"R5-99","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":99,"stem":"法に基づく行政庁による監視指導及び処分に関する記述の正誤について、正しい組合せを一つ選べ。なお、本問において、「都道府県知事」とは、「都道府県知事（薬局又は店舗販売業にあっては、その薬局又は店舗の所在地が保健所設置市又は特別区の区域にある場合においては、市長又は区長。）」とする。","statements":[{"label":"a","text":"薬局開設者や医薬品の販売業者が、薬事監視員による立入検査や収去を拒んだり、妨げたり、忌避した場合の罰則の規定が設けられている。"},{"label":"b","text":"都道府県知事は、店舗販売業において一般用医薬品の販売等を行うための業務体制が基準（体制省令）に適合しなくなった場合、店舗管理者に対して、その業務体制の整備を命ずることができる。"},{"label":"c","text":"都道府県知事は、薬事監視員に、薬局開設者又は医薬品の販売業者が医薬品を業務上取り扱う場所に立ち入らせ、帳簿書類を収去させることができる。"},{"label":"d","text":"厚生労働大臣は、配置販売業の配置員が、その業務に関し、法若しくはこれに基づく命令又はこれらに基づく処分に違反する行為があったときは、その配置販売業者に対して、期間を定めてその配置員による配置販売の業務の停止を命ずることができる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"aは正しく、薬事監視員による立入検査や収去を拒み、妨げ、忌避した場合は罰則（法第87条）の対象になります。bは誤りで、業務体制が基準に適合しなくなったとき整備を命じる相手は、薬局開設者又は医薬品の販売業者であり、店舗管理者ではありません（法第72条の2）。cは誤りで、収去できるのは無承認無許可医薬品・不良医薬品・不正表示医薬品等の疑いのある物を試験のため必要な最少分量に限ったものであり、帳簿書類は検査の対象で収去するものではありません（法第69条）。dは誤りで、配置員による配置販売の業務停止を命じるのは都道府県知事です（法第74条）。よってa正・b誤・c誤・d誤の5が正解です。","tags":["立入検査","行政処分","法第69条・第72条の2・第74条"]},{"id":"R5-100","chapter":4,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":100,"stem":"一般の生活者からの医薬品の苦情及び相談に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の販売関係の業界団体・職能団体においては、一般用医薬品の販売等に関する相談を受けつける窓口を設置し、業界内における自主的なチェックと自浄的是正を図る取り組みがなされている。"},{"label":"b","text":"独立行政法人国民生活センターでは、寄せられた苦情等の内容から、薬事に関する法令への違反、不遵守につながる情報が見出された場合には、法に基づき立入検査によって事実関係を確認のうえ、必要な指導、処分等を行っている。"},{"label":"c","text":"生活者からの苦情等は、消費者団体等の民間団体にも寄せられることがあるが、これらの団体では生活者へのアドバイスは行ってはならないとされている。"},{"label":"d","text":"消費者団体等の民間団体では、必要に応じて行政庁への通報や問題提起を行っている。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":2,"explanation":"aは正しく、業界団体・職能団体が相談窓口を設け、業界内の自主的なチェックと自浄的是正を図る取り組みを行っています。bは誤りで、立入検査によって事実関係を確認し指導・処分を行うのは、薬事監視員を任命している行政庁（薬務主管課、保健所等）であり、国民生活センターではありません。cは誤りで、消費者団体等の民間団体は、生活者へのアドバイスを行うほか、必要に応じ行政庁への通報や問題提起も行います。dは正しく、民間団体が必要に応じて行政庁へ通報や問題提起を行うことは手引きに記載があります。したがって正しいのはa、dで2が正解です。","tags":["苦情相談窓口","国民生活センター"]},{"id":"R5-101","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":101,"stem":"一般用医薬品（一般用検査薬を除く）の添付文書等に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の有効性・安全性等に係る新たな知見、使用に係る情報に関し、重要な内容が変更された場合は、改訂年月の記載と改訂箇所の明示がなされる。"},{"label":"b","text":"添付文書は開封時に一度目を通されれば十分というものでなく、必要なときにいつでも取り出して読むことができるように保管される必要がある。"},{"label":"c","text":"「効能又は効果」には、一般の生活者が自ら判断できる症状、用途等が示されているが、「適応症」として記載されている場合もある。"},{"label":"d","text":"一般用医薬品も医療用医薬品と同様に、紙の添付文書の同梱を廃止し、注意事項等の情報は電子的な方法により提供されることとなった。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"添付文書は改訂年月の記載と改訂箇所の明示がなされ（a正）、使用時に必要に応じて読み返せるよう保管が必要（b正）。効能又は効果は「適応症」と記載される場合もある（c正）。dは誤りで、紙の添付文書の同梱を廃止し電子的に提供する扱いになったのは医療用医薬品で、一般用医薬品など消費者が直接購入する製品は、添付文書がある場合は引き続き紙で同梱される。","tags":["添付文書","電子化"]},{"id":"R5-102","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":102,"stem":"一般用医薬品の添付文書等の「使用上の注意」に関する記述について、誤っているものを一つ選べ。","statements":[],"options":[{"n":1,"text":"使用上の注意は、「してはいけないこと」、「相談すること」及び「その他の注意」から構成され、枠囲い、文字の色やポイントを替えるなど他の記載事項と比べて目立つように記載されている。"},{"n":2,"text":"摂取されたアルコールによって、医薬品の作用の増強、副作用を生じる危険性の増大等が予測される場合に、「服用前後は飲酒しないこと」と記載されている。"},{"n":3,"text":"「使用上の注意」、「してはいけないこと」及び「相談すること」の各項目の見出しには、それぞれ標識的マークが付されていることが多い。"},{"n":4,"text":"「してはいけないこと」には、守らないと症状が悪化する事項、副作用又は事故等が起こりやすくなる事項について記載されている。"},{"n":5,"text":"「服用後、乗物又は機械類の運転操作をしないこと」は、小児に通常当てはまらない内容であるため、小児に使用される医薬品においては記載されていない。"}],"answer":5,"explanation":"使用上の注意は「してはいけないこと」「相談すること」「その他の注意」で構成され、目立つ表示がなされる（1）。飲酒に関する記載は、アルコールで作用増強や副作用の危険が予測される場合に付く（2）。見出しに標識的マークが付くことが多い（3）。「してはいけないこと」の内容も正しい（4）。誤りは5で、運転操作の注意は小児に通常当てはまらなくても、配合成分に基づく一般的注意として小児用医薬品にも記載される。","tags":["使用上の注意","してはいけないこと"]},{"id":"R5-103","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":103,"stem":"一般用医薬品の保管及び取扱いに関する記述について、最も適切なものを一つ選べ。","statements":[],"options":[{"n":1,"text":"添付文書に「直射日光の当たらない、湿気の少ない涼しい場所に密栓して保管すること」と表示されているので、錠剤を冷蔵庫内で保管した。"},{"n":2,"text":"５歳の子供が誤飲することを避けるため、子供の手が届かず、かつ目につかないところに医薬品を保管した。"},{"n":3,"text":"勤務先に携行するのに便利だと考え、医薬品を別の容器へ移し替えた。"},{"n":4,"text":"開封後は早く使い切らないと変質すると思い、点眼薬を家族の数人で使い回した。"},{"n":5,"text":"シロップ剤は特に変質しにくい剤形であるため、開封後、室温で保管した。"}],"answer":2,"explanation":"誤飲事故を避けるには、子供の手の届かない所だけでなく目につかない所に保管するのが適切（2が正）。錠剤は取り出し時の温度差で湿気を帯びるおそれがあり、冷蔵庫保管は不適当（1）。別容器への移し替えは誤用や品質変化の原因になる（3）。点眼薬の使い回しは細菌汚染による感染のおそれがある（4）。シロップ剤は変質しやすく、開封後は冷蔵庫保管が望ましい（5）。","tags":["保管","取扱い"]},{"id":"R5-104","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":104,"stem":"一般用医薬品の製品表示に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"使用期限の表示については、適切な保存条件下で製造後１年を超えて性状及び品質が安定であることが確認されている医薬品において、法的な表示義務はない。"},{"label":"b","text":"滋養強壮を目的とする内服液剤で、１回服用量中０.１ｍＬを超えるアルコールを含有するものについては、アルコールを含有する旨及びその分量が記載されている。"},{"label":"c","text":"配置販売される医薬品の使用期限は、「配置期限」として記載される場合がある。"},{"label":"d","text":"可燃性ガスを噴射剤としているエアゾール製品では、添付文書等の「保管及び取扱い上の注意」に消防法に基づく注意事項が記載されているが、その容器への表示は義務づけられていない。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"b、d"},{"n":5,"text":"c、d"}],"answer":3,"explanation":"使用期限の法的な表示義務がないのは「製造後3年を超えて」安定な医薬品であり、1年ではないのでaは誤り。アルコールを含む滋養強壮内服液剤（1回服用量中0.1mL超）はその旨と分量が記載される（b正）。配置販売の医薬品では「配置期限」と記載される場合がある（c正）。エアゾール製品の消防法に基づく注意事項は容器への表示が法律上義務づけられているため、dも誤り。","tags":["製品表示","使用期限"]},{"id":"R5-105","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":105,"stem":"緊急安全性情報に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"Ａ４サイズの黄色地の印刷物で、イエローレターとも呼ばれる。"},{"label":"b","text":"医療用医薬品や医家向け医療機器についての情報伝達である場合が多いが、一般用医薬品に関係した情報が発出されたこともある。"},{"label":"c","text":"医療機関や薬局等へ直接配布されるものであり、電子メールによる情報伝達は認められていない。"},{"label":"d","text":"厚生労働省からの命令、指示に基づいて作成されるもので、製造販売業者の自主決定に基づいて作成されることはない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":1,"explanation":"緊急安全性情報はA4サイズの黄色地の印刷物でイエローレターとも呼ばれる（a正）。医療用医薬品などが多いが、小柴胡湯の件のように一般用医薬品に関係して発出されたこともある（b正）。情報伝達は直接配布のほか電子メールなども用いられるためcは誤り。厚生労働省の命令・指示だけでなく製造販売業者の自主決定に基づく場合もあるため、dも誤り。","tags":["緊急安全性情報","安全性情報"]},{"id":"R5-106","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":106,"stem":"医薬品等の安全性情報等に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ＰＭＤＡのホームページには、要指導医薬品の添付文書情報は掲載されているが、一般用医薬品の添付文書情報は掲載されていない。"},{"label":"b","text":"ＰＭＤＡのホームページには、厚生労働省が製造販売業者等に指示した緊急安全性情報、「使用上の注意」の改訂情報が掲載されている。"},{"label":"c","text":"ＰＭＤＡが配信する医薬品医療機器情報配信サービス（ＰＭＤＡメディナビ）は、誰でも利用できる。"},{"label":"d","text":"医薬品・医療機器等安全性情報は、厚生労働省が情報をとりまとめ、広く医薬関係者向けに情報提供を行っている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"PMDAのホームページには要指導医薬品だけでなく一般用医薬品の添付文書情報も掲載されているため、aは誤り。緊急安全性情報や使用上の注意の改訂情報も掲載される（b正）。PMDAメディナビは誰でも利用できる（c正）。医薬品・医療機器等安全性情報は厚生労働省が取りまとめ、広く医薬関係者向けに提供している（d正）。","tags":["PMDA","安全性情報"]},{"id":"R5-107","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":107,"stem":"医薬品の副作用情報等の収集、評価及び措置に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品・医療機器等安全性情報報告制度は、厚生省（当時）が全国の全ての医療機関から、直接副作用報告を受ける「医薬品副作用モニター制度」としてスタートした。"},{"label":"b","text":"登録販売者は、医薬品・医療機器等安全性情報報告制度に基づいて報告を行う医薬関係者として位置づけられている。"},{"label":"c","text":"収集された副作用等の情報は、その医薬品の製造販売業者等において評価・検討され、必要な安全対策が図られる。"},{"label":"d","text":"厚生労働大臣は、各制度により集められた副作用情報の調査検討結果に基づき、使用上の注意の改訂の指示等、安全対策上必要な行政措置を講じている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"医薬品・医療機器等安全性情報報告制度は、約3000の医療機関をモニター施設に指定して始まったもので、全国の全ての医療機関が対象ではないためaは誤り。登録販売者も報告を行う医薬関係者に位置づけられている（b正）。収集情報は製造販売業者等で評価・検討され安全対策が図られる（c正）。厚生労働大臣は調査検討結果に基づき使用上の注意の改訂指示等の行政措置を講じる（d正）。","tags":["副作用報告制度","登録販売者"]},{"id":"R5-108","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":108,"stem":"法第６８条の１０第１項の規定に基づき、医薬品の製造販売業者がその製造販売した医薬品について行う副作用等の報告において、１５日以内に厚生労働大臣に報告することとされている事項の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品によるものと疑われる副作用症例のうち、使用上の注意から予測できないもので、非重篤な国内事例"},{"label":"b","text":"医薬品によるものと疑われる感染症症例のうち、使用上の注意から予測できないもので、非重篤な国内事例"},{"label":"c","text":"医薬品によるものと疑われる副作用症例のうち、使用上の注意から予測できるもので、死亡に至った国内事例"},{"label":"d","text":"医薬品によるものと疑われる副作用症例のうち、発生傾向の変化が保健衛生上の危害の発生又は拡大のおそれを示すもので、重篤（死亡含む）な国内事例"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"製造販売業者の副作用症例報告は、使用上の注意から予測できない非重篤な国内事例は定期報告であり15日以内ではないため、aは誤り。感染症症例は予測できないもので非重篤でも15日以内（b正）。予測できる副作用でも死亡事例は15日以内（c正）。発生傾向の変化が保健衛生上の危害の発生・拡大のおそれを示す重篤事例も15日以内（d正）。","tags":["15日報告","企業報告"]},{"id":"R5-109","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":109,"stem":"医薬品の副作用等による健康被害の救済に関する記述について、（　）の中に入れるべき字句の正しい組合せを一つ選べ。\n（　a　）・スモン事件等を踏まえ、１９７９年に薬事法が改正され、医薬品の市販後の安全対策の強化を図るため、再審査・再評価制度の創設、副作用等の報告制度の整備、（　b　）の危害の発生又は拡大を防止するための緊急命令、廃棄・（　c　）に関する法整備等がなされた。","statements":[],"options":[{"n":1,"text":"a 違法薬物事件 / b 保健衛生上 / c 廃止命令"},{"n":2,"text":"a 違法薬物事件 / b 国民生活上 / c 回収命令"},{"n":3,"text":"a サリドマイド事件 / b 国民生活上 / c 廃止命令"},{"n":4,"text":"a サリドマイド事件 / b 保健衛生上 / c 回収命令"},{"n":5,"text":"a サリドマイド事件 / b 保健衛生上 / c 廃止命令"}],"answer":4,"explanation":"1979年の薬事法改正は、サリドマイド事件・スモン事件等を踏まえて行われた。市販後の安全対策強化のため、再審査・再評価制度の創設、副作用等報告制度の整備、保健衛生上の危害の発生・拡大防止のための緊急命令、廃棄・回収命令に関する法整備がなされ、あわせて医薬品副作用被害救済制度が創設された。","tags":["救済制度","薬事法改正"]},{"id":"R5-110","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":110,"stem":"医薬品副作用被害救済制度に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の副作用による疾病のため、入院治療が必要と認められるが、やむをえず自宅療養を行った場合は、給付の対象とならない。"},{"label":"b","text":"製薬企業に損害賠償責任がある場合にも、救済制度の対象となる。"},{"label":"c","text":"健康被害が医薬品の副作用によると診断した医師が、ＰＭＤＡに対して給付請求を行うこととされている。"},{"label":"d","text":"救済給付業務に必要な費用のうち、事務費はすべて国庫補助により賄われている。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"入院治療が必要と認められるがやむを得ず自宅療養した場合も給付対象に含まれるため、aは誤り。製薬企業に損害賠償責任がある場合は救済制度の対象から除外されるため、bは誤り。給付請求は健康被害を受けた本人（又は家族）が行うので、cも誤り。事務費は2分の1相当額が国庫補助であり、すべてではないため、dも誤り。よってすべて誤り。","tags":["救済制度","給付対象"]},{"id":"R5-111","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":111,"stem":"医薬品副作用被害救済制度の給付に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"遺族年金の給付は、請求期限がない。"},{"label":"b","text":"葬祭料の給付は、請求期限がない。"},{"label":"c","text":"医療手当の給付の請求期限は、請求に係る医療が行われた日の属する月の翌月の初日から５年以内である。"},{"label":"d","text":"障害年金は、医薬品の副作用により一定程度の障害の状態にある１８歳以上の人の生活補償等を目的として給付されるものである。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"遺族年金・葬祭料には死亡のときから5年以内などの請求期限があり、期限なしではないためa・bは誤り。医療手当は請求に係る医療が行われた日の属する月の翌月の初日から5年以内で正しい（c正）。障害年金は一定程度の障害状態にある18歳以上の人の生活補償等を目的とし、請求期限はない（d正）。","tags":["救済制度","請求期限"]},{"id":"R5-112","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":112,"stem":"医薬品等を適正に使用したにもかかわらず、副作用によって一定程度以上の健康被害が生じた場合に、医薬品副作用被害救済制度の対象となるものの正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品の胃腸薬"},{"label":"b","text":"いわゆる健康食品として販売されたもの"},{"label":"c","text":"一般用医薬品の殺菌消毒剤（人体に直接使用するもの）"},{"label":"d","text":"ワセリン（日本薬局方収載医薬品）"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"一般用医薬品の胃腸薬は救済制度の対象（a正）。いわゆる健康食品などの無承認無許可医薬品は対象外（b誤）。殺菌消毒剤は人体に直接使用しないものが除外なので、人体に使用するものは対象（c正）。ワセリンなど一部の日本薬局方収載医薬品は対象外（d誤）。","tags":["救済制度","対象除外"]},{"id":"R5-113","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":113,"stem":"一般用医薬品の安全対策に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"アンプル入りかぜ薬の使用による重篤な副作用（ショック）で死亡例が発生したことから、１９６５年に厚生省（当時）は関係製薬企業に対し、アンプル入りかぜ薬製品の回収を要請した。"},{"label":"b","text":"塩酸フェニルプロパノールアミンが配合された一般用医薬品による脳出血等の副作用症例が複数報告されたことから、厚生労働省は、代替成分としてプソイドエフェドリン塩酸塩等への速やかな切替えを指示した。"},{"label":"c","text":"慢性肝炎患者が小柴胡湯を使用して間質性肺炎を発症し、死亡を含む重篤な転帰に至った例もあったことから、１９９６年に厚生省（当時）は関係製薬企業に対して緊急安全性情報の配布を指示した。"},{"label":"d","text":"一般用かぜ薬の使用によると疑われる肝機能障害の発生事例が報告されたことを受けて、２００３年に厚生労働省は一般用かぜ薬全般につき使用上の注意の改訂を指示した。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":1,"explanation":"アンプル入りかぜ薬でショック死が発生し、1965年に製品の回収が要請された（a正）。フェニルプロパノールアミンでは脳出血等の症例報告を受け、代替成分への切替えが指示された（b正）。小柴胡湯による間質性肺炎で1996年に緊急安全性情報の配布が指示された（c正）。2003年の使用上の注意改訂指示は肝機能障害ではなく間質性肺炎に関するものなので、dは誤り。","tags":["安全対策","薬害"]},{"id":"R5-114","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":114,"stem":"次の表は、ある一般用医薬品の解熱鎮痛薬に含まれている成分の一覧である。\n２錠中：\n成分 / 分量\nイブプロフェン / １４４ ｍｇ\nエテンザミド / ８４ ｍｇ\nブロモバレリル尿素 / ２００ ｍｇ\n無水カフェイン / ５０ ｍｇ\nこの解熱鎮痛薬の添付文書等の「相談すること」の項目中において、「次の診断を受けた人」と記載されている基礎疾患の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"緑内障"},{"label":"b","text":"腎臓病"},{"label":"c","text":"てんかん"},{"label":"d","text":"肝臓病"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"この製剤にはイブプロフェン・エテンザミドが含まれ、これらは腎臓病・肝臓病の診断を受けた人で悪化のおそれがあるため「相談すること」に記載される（b・d正）。緑内障は抗コリン成分等が関係し、てんかんはジプロフィリン等が関係するが、この製剤にはいずれも含まれないため、a・cは誤り。","tags":["相談すること","解熱鎮痛薬"]},{"id":"R5-115","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":115,"stem":"次硝酸ビスマスが配合された内服用の一般用医薬品の添付文書等において、「相談すること」の項目中に「胃・十二指腸潰瘍の診断を受けた人」と記載される主な理由について、最も適切なものを一つ選べ。","statements":[],"options":[{"n":1,"text":"下痢症状の副作用が発現するおそれがあるため。"},{"n":2,"text":"ナトリウム、カルシウム、マグネシウム等の無機塩類の排泄が遅れることで、副作用が発現するおそれがあるため。"},{"n":3,"text":"本剤の吸収が高まり、血中に移行する量が多くなり、本剤による精神神経障害等が発現するおそれがあるため。"},{"n":4,"text":"胃液の分泌が亢進し、胃・十二指腸潰瘍の症状を悪化させるおそれがあるため。"},{"n":5,"text":"消化管粘膜の防御機能が低下し、胃・十二指腸潰瘍の症状を悪化させるおそれがあるため。"}],"answer":3,"explanation":"次硝酸ビスマスは、胃・十二指腸潰瘍がある場合に消化管粘膜が傷んでいるため吸収が高まり、血中に移行する量が増えてビスマスによる精神神経障害等が生じるおそれがある、という理由で相談事項とされる。したがって3が正しい。胃酸分泌や粘膜防御の低下を理由とする4・5は、この成分の記載理由ではない。","tags":["ビスマス","相談すること"]},{"id":"R5-116","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":116,"stem":"一般用医薬品の添付文書等において、生じた血栓が分解されにくくなるため、「相談すること」の項目中に「血栓のある人（脳血栓、心筋梗塞、血栓静脈炎等）、血栓症を起こすおそれのある人」と記載することとされている内服薬の成分を一つ選べ。","statements":[],"options":[{"n":1,"text":"アスピリン"},{"n":2,"text":"トラネキサム酸"},{"n":3,"text":"アセトアミノフェン"},{"n":4,"text":"タンニン酸アルブミン"},{"n":5,"text":"グリチルリチン酸二カリウム"}],"answer":2,"explanation":"トラネキサム酸（内服）は凝固した血液を溶解されにくくする働きがあり、生じた血栓が分解されにくくなるため、血栓のある人や血栓症を起こすおそれのある人は使用前に相談が必要とされる。アスピリン等の他の選択肢はこの理由では記載されない。","tags":["トラネキサム酸","血栓"]},{"id":"R5-117","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":117,"stem":"プソイドエフェドリン塩酸塩が配合された一般用医薬品の鼻炎用内服薬の添付文書等において、「次の人は使用（服用）しないこと」の項目中に記載することとされている対象者の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"糖尿病の診断を受けた人"},{"label":"b","text":"心臓病の診断を受けた人"},{"label":"c","text":"吐き気・嘔吐の症状がある人"},{"label":"d","text":"前立腺肥大による排尿困難の症状がある人"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"プソイドエフェドリン塩酸塩配合の鼻炎用内服薬では、糖尿病・心臓病の診断を受けた人と、前立腺肥大による排尿困難の症状がある人は使用（服用）しないこととされる（a・b・d正）。吐き気・嘔吐の症状は該当せず、cは誤り。","tags":["プソイドエフェドリン","してはいけないこと"]},{"id":"R5-118","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":118,"stem":"一般用医薬品の胃腸薬の添付文書等において、アルミニウム脳症及びアルミニウム骨症を生じるおそれがあるため、「長期連用しないこと」と記載することとされている成分の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"アルジオキサ"},{"label":"b","text":"テプレノン"},{"label":"c","text":"ロートエキス"},{"label":"d","text":"合成ヒドロタルサイト"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":5,"explanation":"アルミニウムを含む成分（アルジオキサ、合成ヒドロタルサイト等）は、長期連用でアルミニウム脳症・骨症を生じるおそれがあるため「長期連用しないこと」と記載される。テプレノンとロートエキスはアルミニウムを含まないため該当しない。","tags":["アルミニウム","胃腸薬"]},{"id":"R5-119","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":119,"stem":"一般用医薬品の添付文書等において、「相談すること」の項目中に「次の診断を受けた人」として記載することとされている基礎疾患等と医薬品成分・薬効群等との関係の正誤について、正しい組合せを一つ選べ。\n基礎疾患等 / 医薬品成分・薬効群等","statements":[{"label":"a","text":"肝臓病 / アセトアミノフェンを含む解熱鎮痛薬"},{"label":"b","text":"高血圧 / スクラルファートを含む胃腸薬"},{"label":"c","text":"甲状腺機能障害 / メトキシフェナミン塩酸塩を含む鎮咳去痰薬"},{"label":"d","text":"腎臓病 / 酸化マグネシウムを含む瀉下薬"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"アセトアミノフェンは肝機能障害を悪化させるおそれがあり、肝臓病で相談（a正）。メトキシフェナミン塩酸塩などのアドレナリン作動成分は交感神経を興奮させ、甲状腺機能障害で相談（c正）。酸化マグネシウムは腎臓病で無機塩類の排泄が遅れやすい（d正）。スクラルファートは高血圧ではなく腎臓病（透析）に関する記載なので、bは誤り。","tags":["相談すること","基礎疾患"]},{"id":"R5-120","chapter":5,"source":"関西広域連合 令和5年度 登録販売者試験 後半","no":120,"stem":"一般用医薬品の添付文書等において、眠気、目のかすみ、異常なまぶしさを生じることがあるため、「服用後、乗物又は機械類の運転操作をしないこと」と記載することとされている成分等を一つ選べ。","statements":[],"options":[{"n":1,"text":"スコポラミン臭化水素酸塩水和物"},{"n":2,"text":"イブプロフェン"},{"n":3,"text":"メチルエフェドリン塩酸塩"},{"n":4,"text":"芍薬甘草湯"},{"n":5,"text":"ビサコジル"}],"answer":1,"explanation":"スコポラミン臭化水素酸塩水和物は抗コリン成分で、眠気、目のかすみ、異常なまぶしさを生じることがあるため、服用後に乗物又は機械類の運転操作をしないよう記載される。他の選択肢はこの理由での記載対象ではない。","tags":["スコポラミン","運転操作"]},{"id":"R4-1","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":1,"stem":"医薬品の本質に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医療用医薬品に限らず一般用医薬品も、科学的な根拠に基づく適切な理解や判断によって適正な使用が図られる必要がある。"},{"label":"b","text":"一般用医薬品の販売に従事する専門家は、随時新たに付加される医薬品の有効性、安全性等に関する情報の把握に努める必要がある。"},{"label":"c","text":"人体に対して使用されない医薬品は、人の健康に影響を与えることはない。"},{"label":"d","text":"一般用医薬品の販売等に従事する専門家は、購入者等が知りたい情報を十分に得ることができるように、相談に対応することが不可欠である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":2,"explanation":"医療用・一般用を問わず医薬品は、科学的根拠に基づく適切な理解と判断のもとで適正に使用される必要があり、専門家は随時付加される有効性・安全性情報の把握に努めなければならない。一方、殺虫剤など人体に直接使用しない医薬品であっても、誤用や事故により人の健康に影響を及ぼすことがあるため、cの「影響を与えることはない」という記述は誤りである。専門家は購入者等が知りたい情報を十分に得られるよう相談対応することが不可欠であり、dは正しい。","tags":["医薬品の本質","専門家の役割"]},{"id":"R4-2","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":2,"stem":"医薬品の効果とリスク評価に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の投与量と効果の関係は、薬物用量の増加に伴い、効果の発現が検出されない「無作用量」から、最小有効量を経て「治療量」に至る。"},{"label":"b","text":"動物実験で求められる５０％致死量（ＬＤ５０）は、薬物の有効性の指標として用いられる。"},{"label":"c","text":"新規に開発される医薬品のリスク評価では、ＧＬＰ（Good Laboratory Practice）の他に、医薬品毒性試験法ガイドラインに沿った各種毒性試験が厳格に実施されている。"},{"label":"d","text":"医薬品の効果とリスクは、用量と作用強度の関係（用量-反応関係）に基づいて評価される。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"医薬品の用量と効果の関係は、無作用量から最小有効量を経て治療量に至り、さらに増量すると中毒量・致死量へと進むとされる。動物実験で求められるLD50は薬物の毒性の強さを示す指標であって有効性の指標ではないため、bの記述は誤りである。新規医薬品の開発ではGLPに基づく非臨床試験に加え、医薬品毒性試験法ガイドラインに沿った各種毒性試験が厳格に実施されており、効果とリスクは用量-反応関係に基づいて評価される。","tags":["リスク評価","LD50","GLP"]},{"id":"R4-3","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":3,"stem":"健康食品に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品の販売時に健康食品の摂取の有無について確認することは、重要である。"},{"label":"b","text":"いわゆる「健康食品」では、誤った使用方法や個々の体質により健康被害を生じた例が報告されている。"},{"label":"c","text":"「特定保健用食品」は、事業者の責任で科学的根拠をもとに疾病に罹患していない者の健康維持及び増進に役立つ機能を商品のパッケージに表示するものとして国に届出された商品である。"},{"label":"d","text":"いわゆる「健康食品」は、安全性や効果を担保する科学的データの面で医薬品と同等のものである。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"一般用医薬品の販売時には健康食品の摂取状況を確認することが重要であり、誤った使用方法や体質により健康被害を生じた例も報告されている。cの記述内容は「事業者の責任で科学的根拠をもとに」「国に届出」という点で、実際には特定保健用食品ではなく機能性表示食品の説明であり、特定保健用食品は個別に国の審査を受けて許可される制度であるため誤りである。いわゆる健康食品は、法的にも安全性・効果を担保する科学的データの面でも医薬品とは異なるため、dも誤りである。","tags":["健康食品","特定保健用食品","機能性表示食品"]},{"id":"R4-4","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":4,"stem":"医薬品の副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"世界保健機関（ＷＨＯ）の定義によれば、疾病の予防のために人に通常用いられる量で発現する医薬品の有害かつ意図しない反応は、医薬品の副作用には含まれない。"},{"label":"b","text":"医薬品の有効成分である薬物が生体の生理機能に影響を与えることを薬理作用といい、通常、薬物は単一の薬理作用を有する。"},{"label":"c","text":"複数の疾病を有する人の場合、ある疾病のために使用された医薬品の作用によって、別の疾病の治療が妨げられることがある。"},{"label":"d","text":"眠気や口渇等の日常生活に支障を来さない程度の症状は、副作用とは言わない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":3,"explanation":"WHOの定義では、疾病の予防等のため人に通常用いられる量で発現する有害かつ意図しない反応こそが医薬品の副作用とされているため、「含まれない」とするaは誤りである。薬物は通常、複数の薬理作用を併せ持つとされるため、「単一の薬理作用を有する」とするbも誤りである。複数の疾病を持つ人では、ある疾病のために使用した医薬品の作用が別の疾病の治療を妨げることがあり、cは正しい。眠気や口渇のような比較的よくみられる軽い症状も副作用として扱われるため、「副作用とは言わない」とするdは誤りである。","tags":["副作用","WHO定義","薬理作用"]},{"id":"R4-5","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":5,"stem":"アレルギーに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"通常の免疫反応と比べ、アレルギーにおいては過剰に組織に刺激を与える場合も多く、引き起こされた炎症自体が過度に苦痛を与えることになる。"},{"label":"b","text":"アレルギーは、一般的にあらゆる物質によって起こり得るものであり、医薬品の薬理作用等とは関係なく起こり得る。"},{"label":"c","text":"アレルギー症状は、結膜炎症状や鼻炎症状、蕁麻疹や湿疹等の皮膚症状及び血管性浮腫のようなやや広い範囲にわたる腫れ等が生じることが多い。"},{"label":"d","text":"医薬品の添加物は、アレルギーを引き起こす原因物質とはならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"アレルギーでは通常の免疫反応より過剰に組織を刺激することが多く、引き起こされた炎症自体が過度な苦痛を与える。アレルギーはあらゆる物質によって起こり得るもので、医薬品の薬理作用とは関係なく生じ、結膜炎症状・鼻炎症状・蕁麻疹や湿疹等の皮膚症状・血管性浮腫のような広い範囲の腫れなどが生じることが多い。ただし黄色4号（タートラジン）やカゼイン、亜硫酸塩など添加物にもアレルゲンとなり得る成分があるため、「原因物質とはならない」とするdは誤りである。","tags":["アレルギー","添加物","アレルゲン"]},{"id":"R4-6","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":6,"stem":"一般用医薬品の使用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品は、軽度な疾病に伴う症状の改善等を図るためのものである。"},{"label":"b","text":"一般用医薬品の使用に際しては、通常、その重大な副作用の回避よりも、使用を中断することによる不利益の回避が優先される。"},{"label":"c","text":"一般用医薬品の販売等に従事する専門家は、購入者等から副作用の発生の経過を聴いて、その後の適切な医薬品の選択に資する情報提供を行うほか、副作用の状況次第では、速やかに適切な医療機関を受診するよう勧奨する必要がある。"},{"label":"d","text":"一般用医薬品を継続して使用する場合、医薬品の販売等に従事する専門家は、特段の異常が感じられなければ、医療機関を受診するよう購入者等に促す必要はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"一般用医薬品は軽度な疾病に伴う症状の改善等を図るためのものであり、専門家は副作用の経過を聴取したうえで適切な情報提供を行い、状況次第で速やかな医療機関受診を勧奨する必要がある。しかし通常は、使用を中断することによる不利益よりも重大な副作用の回避が優先されるべきであり、記述が逆になっているbは誤りである。継続使用中であっても、特段の異常がなくても状況に応じて受診を促す必要がある場合があるため、dも誤りである。","tags":["一般用医薬品","受診勧奨","副作用回避"]},{"id":"R4-7","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":7,"stem":"一般用医薬品の不適正な使用と副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"購入者等の誤解や認識不足が一般用医薬品の不適正な使用につながることがある。"},{"label":"b","text":"疾病の根本的な治療や生活習慣の改善等がなされずに、一般用医薬品を使用して症状を一時的に緩和するだけの対処を漫然と続けていると、副作用を招く危険性が増す。"},{"label":"c","text":"一般用医薬品は医療用医薬品に比べ作用が弱いため、乱用の繰り返しによる慢性的な臓器障害は生じない。"},{"label":"d","text":"医薬品の販売等に従事する専門家は、一般用医薬品の適正な使用を図るため、購入者等の理解力や医薬品を使用する状況等に即して購入者等に説明をすべきである。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":2,"explanation":"購入者等の誤解や認識不足は不適正な使用につながることがあり、根本的な治療や生活習慣の改善をせずに症状緩和だけの対処を漫然と続けると副作用を招く危険性が増す。一般用医薬品であっても乱用を繰り返せば慢性的な臓器障害等を生じるおそれがあるため、「生じない」とするcは誤りである。専門家は購入者等の理解力や使用状況に即した説明を行うべきであり、dは正しい。","tags":["不適正な使用","乱用","臓器障害"]},{"id":"R4-8","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":8,"stem":"他の医薬品との相互作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"複数の医薬品を併用した場合、医薬品の作用が増強することはあるが、減弱することはない。"},{"label":"b","text":"医薬品の相互作用は、医薬品が薬理作用をもたらす部位や、医薬品の吸収、分布、代謝又は排泄の過程で起こる。"},{"label":"c","text":"一般用医薬品は、一つの医薬品の中に作用の異なる複数の成分を組み合わせて含んでいることが多いため、他の医薬品と併用すると、同様な作用を持つ成分が重複することがある。"},{"label":"d","text":"購入者等が医療機関・薬局から交付された薬剤を使用している場合には、一般用医薬品の販売等に従事する専門家が、一般用医薬品を併用しても問題ないかを判断する。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"複数医薬品の併用では作用が増強する場合だけでなく減弱する場合もあるため、「減弱することはない」とするaは誤りである。相互作用は医薬品の吸収・分布・代謝・排泄の過程や、薬理作用をもたらす部位で起こるとされ、一般用医薬品は複数成分を組み合わせて含むことが多いため、他薬併用で同様の作用を持つ成分が重複することがある。ただし医療機関・薬局から交付された薬剤との併用の可否は、専門家が独自に判断するのではなく、処方した医師・歯科医師や調剤した薬剤師に相談するよう説明すべきであるため、dは誤りである。","tags":["相互作用","併用注意"]},{"id":"R4-9","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":9,"stem":"食品と医薬品の相互作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"食品と医薬品の相互作用は、しばしば「飲み合わせ」と表現される。"},{"label":"b","text":"酒類（アルコール）をよく摂取する者は、肝臓の代謝機能が高まっていることが多く、アセトアミノフェンでは、体内から速く消失して、十分な薬効が得られなくなることがある。"},{"label":"c","text":"総合感冒薬とコーヒーを一緒に服用すると、カフェインの過剰摂取になる場合がある。"},{"label":"d","text":"内服薬以外では、食品の摂取によって、医薬品の作用や代謝に影響を受ける可能性はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"食品と医薬品の相互作用はしばしば「飲み合わせ」と表現され、飲酒習慣のある人は肝臓の代謝機能が高まり、アセトアミノフェンなどは速く代謝されて十分な薬効が得られないことがある。カフェインを含む食品（コーヒー等）とカフェイン含有の総合感冒薬を一緒に服用すると、カフェインの過剰摂取になる場合がある。ただし外用薬や注射薬であっても、食品によって医薬品の作用や代謝に影響を受ける可能性があるため、「内服薬以外では影響を受ける可能性はない」とするdは誤りである。","tags":["食品との相互作用","飲み合わせ","アセトアミノフェン"]},{"id":"R4-10","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":10,"stem":"小児への医薬品の使用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"５歳未満の幼児に使用される錠剤やカプセル剤などの医薬品では、服用時に喉につかえやすいので注意するよう添付文書に記載されている。"},{"label":"b","text":"「医療用医薬品の添付文書等の記載要領の留意事項」において、新生児とは、おおよその目安として生後４週未満をいう。"},{"label":"c","text":"小児は腎臓の機能が未発達であるため、医薬品の成分の排泄に要する時間が短く、作用が弱くなることがある。"},{"label":"d","text":"小児は、大人と比べて身体の大きさに対して腸が短いため、服用した医薬品の吸収率が相対的に低く、期待する効果が得られない場合がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"5歳未満の幼児に使われる錠剤・カプセル剤は、服用時に喉につかえやすいため注意するよう添付文書に記載されており、新生児は関連通知上おおよそ生後4週未満とされる。しかし小児は肝臓・腎臓の機能が未発達なため、実際には医薬品成分の代謝・排泄に時間がかかり作用が強く出過ぎることがあるとされ、「排泄に要する時間が短く作用が弱くなる」とするcは事実と逆であり誤りである。また小児は身体の大きさに対して腸が長く吸収率が相対的に高いとされるため、「腸が短く吸収率が低い」とするdも誤りである。","tags":["小児","年齢区分","吸収・排泄"]},{"id":"R4-11","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":11,"stem":"高齢者への医薬品の使用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"高齢者は、持病（基礎疾患）を抱えていることが多いが、一般用医薬品であれば持病の種類によらず、使用可能である。"},{"label":"b","text":"一般に高齢者は生理機能が衰えつつあり、特に腎臓の機能が低下していると医薬品の作用は現れにくい。"},{"label":"c","text":"医薬品の副作用等で口渇が生じた場合、高齢者は誤嚥を誘発しやすくなるので注意が必要である。"},{"label":"d","text":"基礎体力や生理機能の衰えの度合いは個人差が大きく、年齢のみからどの程度副作用を生じるリスクが増大しているかを判断することは難しい。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"高齢者は持病を抱えていることが多く、一般用医薬品でも基礎疾患の症状悪化や治療の妨げとなる場合があるため、「持病の種類によらず使用可能」とするaは誤りである。肝臓・腎臓の機能が低下すると医薬品の作用はむしろ強く現れやすくなるとされるため、「作用は現れにくい」とするbも誤りである。副作用等で口渇が生じると誤嚥を誘発しやすくなるため注意が必要であり、また基礎体力や生理機能の衰えの度合いは個人差が大きく、年齢のみでリスクの程度を判断するのは難しいため、c・dはいずれも正しい。","tags":["高齢者","誤嚥","個人差"]},{"id":"R4-12","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":12,"stem":"妊婦又は妊娠していると思われる女性及び母乳を与える女性（授乳婦）への医薬品の使用等に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"胎盤には、胎児の血液と母体の血液とが混ざらない仕組み（血液－胎盤関門）がある。"},{"label":"b","text":"一般用医薬品では多くの場合、妊婦に対する安全性の評価は確立されているが、配慮が必要であるため、妊婦の使用については「相談すること」としているものが多い。"},{"label":"c","text":"便秘薬は、配合成分やその用量にかかわらず、流産や早産が誘発されることはない。"},{"label":"d","text":"医薬品の種類によっては、授乳婦が使用した医薬品の成分の一部が乳汁中に移行することが知られている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"胎盤には胎児と母体の血液が混ざらない血液-胎盤関門があるが、その防御の程度がどこまで及ぶかは未解明な部分が多く、一般用医薬品でも妊婦に対する安全性の評価は確立していないことが多いため「相談すること」とされる。したがって「安全性の評価は確立されている」とするbは誤りである。便秘薬は配合成分やその用量によっては流産・早産を誘発するおそれがあるとされているため、「誘発されることはない」とするcも誤りである。授乳婦が使用した医薬品の成分の一部は乳汁中に移行することが知られており、dは正しい。","tags":["妊婦","授乳婦","血液-胎盤関門"]},{"id":"R4-13","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":13,"stem":"プラセボ効果に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品を使用したとき、結果的又は偶発的に薬理作用による作用を生じることをプラセボ効果という。"},{"label":"b","text":"プラセボ効果によってもたらされる反応や変化には、望ましいもの（効果）と不都合なもの（副作用）がある。"},{"label":"c","text":"プラセボ効果は、主観的な変化と客観的に測定可能な変化が、確実に現れる。"},{"label":"d","text":"プラセボ効果は、時間経過による自然発生的な変化（自然緩解など）が関与して生じる場合があると考えられる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"プラセボ効果（偽薬効果）とは、医薬品を使用したとき結果的又は偶発的に薬理作用によらずに生じる作用のことであり、「薬理作用による作用」とするaは誤りである。もたらされる反応や変化には望ましいもの（効果）と不都合なもの（副作用）の両方があり、bは正しい。プラセボ効果による変化は主観的にも客観的にも現れ得るが不確実なものであり、「確実に現れる」とするcは誤りである。暗示効果や条件付け、時間経過による自然発生的な変化（自然緩解など）が関与して生じると考えられており、dは正しい。","tags":["プラセボ効果","偽薬効果"]},{"id":"R4-14","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":14,"stem":"医薬品の品質に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品は、適切な保管・陳列がなされたとしても、経時変化による品質の劣化は避けられない。"},{"label":"b","text":"医薬品に配合されている添加物成分は、高温や多湿、光（紫外線）等による品質の劣化（変質・変敗）を起こさない。"},{"label":"c","text":"医薬品の外箱等に記載されている「使用期限」は、未開封状態で保管された場合に、品質が保持される期限である。"},{"label":"d","text":"一般用医薬品は、購入された後、すぐに使用されるとは限らないため、外箱等に記載されている使用期限から十分な余裕をもって販売することが重要である。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"医薬品は適切に保管・陳列しても経時変化による品質の劣化は避けられない。有効成分だけでなく添加物成分も高温・多湿・光（紫外線）等により品質の劣化（変質・変敗）を起こしやすいため、「起こさない」とするbは誤りである。外箱等に記載されている使用期限は未開封状態で保管された場合に品質が保持される期限であり、常備薬として購入されることも多いことから、使用期限から十分な余裕をもって販売することが重要である。","tags":["医薬品の品質","使用期限","添加物"]},{"id":"R4-15","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":15,"stem":"一般用医薬品の選択及びセルフメディケーションに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品は、医療機関での治療を受けるほどではない体調不良や疾病の初期段階、あるいは日常において、生活者が自らの疾病の治療、予防又は生活の質の改善・向上を図ることを目的として用いられる。"},{"label":"b","text":"身近にある一般用医薬品を利用する「セルフメディケーション」の主役は一般の生活者である。"},{"label":"c","text":"一般用医薬品の販売等に従事する専門家は、購入者等に対して常に科学的な根拠に基づいた正確な情報提供を行い、セルフメディケーションを適切に支援していくことが期待されている。"},{"label":"d","text":"一般用医薬品で対処可能な症状等の範囲は、医薬品を使用する人によって変わるものではない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"一般用医薬品は、医療機関での治療を受けるほどではない体調不良や疾病の初期段階等で、生活者自らが治療・予防・生活の質の改善向上を図るために用いられる。セルフメディケーションの主役は一般の生活者自身であり、専門家は常に科学的根拠に基づく正確な情報提供でこれを支援することが期待されている。しかし、一般用医薬品で対処可能な範囲は乳幼児や妊婦等で通常より限られるなど、医薬品を使用する人によって変わってくるとされるため、「変わるものではない」とするdは誤りである。","tags":["セルフメディケーション","一般用医薬品の役割"]},{"id":"R4-16","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":16,"stem":"一般用医薬品の販売時のコミュニケーションに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の販売に従事する専門家からの情報提供は、専門用語を分かりやすい平易な表現で説明するだけでなく、説明した内容が購入者にどう理解されているか、などの実情を把握しながら行うことで、その実効性が高まる。"},{"label":"b","text":"一般用医薬品については、必ずしも情報提供を受けた当人が医薬品を使用するとは限らないことを踏まえ、販売時のコミュニケーションを考える必要がある。"},{"label":"c","text":"一般用医薬品は、すぐに使用する必要に迫られて購入されるとは限らず、家庭における常備薬として購入されることも多いため、販売等に従事する専門家においては、その点も把握に努めることが望ましい。"},{"label":"d","text":"購入者が医薬品を使用する状況が変化する可能性は低いため、販売時のコミュニケーションの機会が継続的に確保されるような配慮は必要ない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"専門用語をわかりやすく説明するだけでなく、購入者の理解度など実情を把握しながら情報提供を行うことでその実効性が高まる。一般用医薬品では情報提供を受けた当人が必ずしも使用するとは限らないことを踏まえてコミュニケーションを考える必要があり、常備薬として購入されることも多い点を把握するよう努めることが望ましい。しかし、購入者が医薬品を使用する状況は随時変化する可能性があるため、販売時のコミュニケーションの機会を継続的に確保する配慮が重要であり、「配慮は必要ない」とするdは誤りである。","tags":["販売時のコミュニケーション"]},{"id":"R4-17","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":17,"stem":"薬害及び薬害の訴訟に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"薬害は、医薬品を十分注意して使用していれば、起こることはない。"},{"label":"b","text":"Ｃ型肝炎訴訟を契機として、医師、薬剤師、法律家、薬害被害者などの委員により構成される医薬品等行政評価・監視委員会が設置された。"},{"label":"c","text":"今まで国内で薬害の原因となったものは医療用医薬品のみである。"},{"label":"d","text":"一般用医薬品の販売等に従事する者は、薬害事件の歴史を十分に理解し、医薬品の副作用等による健康被害の拡大防止に関し、その責務の一端を担っていることに留意しておく必要がある。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、d"},{"n":4,"text":"c、d"}],"answer":3,"explanation":"医薬品の副作用被害は、医薬品が十分注意して使用されたとしても起こり得るものとされているため、「起こることはない」とするaは誤りである。C型肝炎訴訟等を踏まえた薬害再発防止のための最終提言を受けて、医師・薬剤師・法律家・薬害被害者などで構成される医薬品等行政評価・監視委員会が設置されており、bは正しい。サリドマイド製剤やキノホルム製剤は過去に一般用医薬品としても販売されていたことがあり、薬害の原因は医療用医薬品に限られないため「医療用医薬品のみ」とするcは誤りである。一般用医薬品の販売等に従事する者は薬害事件の歴史を理解し、健康被害拡大防止の責務の一端を担っている。正しい組合せはbとdである。","tags":["薬害の歴史","C型肝炎訴訟","医薬品等行政評価・監視委員会"]},{"id":"R4-18","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":18,"stem":"サリドマイド及びサリドマイド訴訟に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"サリドマイド訴訟は、サリドマイド製剤を妊娠している女性が使用したことにより、出生児に四肢欠損、耳の障害等の先天異常（サリドマイド胎芽症）が発生したことに対する損害賠償訴訟である。"},{"label":"b","text":"サリドマイドは、妊娠している女性が摂取した場合、血液－胎盤関門を通過して胎児に移行する。"},{"label":"c","text":"サリドマイドは、催眠鎮静成分として承認・販売されたが、副作用として血管新生を促進する作用がみられた。"},{"label":"d","text":"サリドマイドによる薬害は、その光学異性体のうち、一方の異性体のみが有する作用であることから、もう一方の異性体を分離して製剤化した場合には、避けることができる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"サリドマイド訴訟は、妊娠中の女性がサリドマイド製剤を使用したことで出生児に四肢欠損や耳の障害等の先天異常（サリドマイド胎芽症）が生じたことへの損害賠償訴訟であり、サリドマイドは血液-胎盤関門を通過して胎児に移行する。しかしサリドマイドの副作用は血管新生を促進するのではなく妨げる（阻害する）作用であり、この作用が胎児の器官形成を妨げて先天異常を引き起こすため、「促進する」とするcは誤りである。鎮静作用と血管新生を妨げる作用は光学異性体の一方のみが持つとされるが、両異性体は体内で相互に転換するため、片方を分離して製剤化しても催奇形性を避けることはできず、dも誤りである。","tags":["サリドマイド","血液-胎盤関門","光学異性体"]},{"id":"R4-19","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":19,"stem":"スモン及びスモン訴訟に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"スモン訴訟は、キノホルム製剤を使用したことにより、亜急性脊髄視神経症に罹患したことに対する損害賠償訴訟である。"},{"label":"b","text":"スモンの症状として、初期には腹部の膨満感から激しい腹痛を伴う下痢を生じ、次第に下半身の痺れや脱力、歩行困難等が現れる。"},{"label":"c","text":"キノホルム製剤は、整腸剤として販売されていたが、現在、日本ではアメーバ赤痢にのみ使用されている。"},{"label":"d","text":"スモン患者に対する施策や救済制度として、治療研究施設の整備、重症患者に対する介護事業等が講じられている。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"スモン訴訟は、整腸剤として販売されていたキノホルム製剤を使用したことにより亜急性脊髄視神経症に罹患したことへの損害賠償訴訟であり、症状は初期の腹部膨満感からの激しい下痢に始まり、次第に下半身の痺れや脱力、歩行困難へと進行する。キノホルム製剤は日本では1970年にスモンの原因とされて販売そのものが停止されており、「現在、日本ではアメーバ赤痢にのみ使用」という記述は誤りである（アメーバ赤痢への使用限定は米国での勧告であり、日本の販売実態とは異なる）。スモン患者への施策として治療研究施設の整備や重症患者への介護事業等が講じられており、dは正しい。","tags":["スモン","キノホルム","亜急性脊髄視神経症"]},{"id":"R4-20","chapter":1,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":20,"stem":"クロイツフェルト・ヤコブ病（ＣＪＤ）及びＣＪＤ訴訟に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ヒト乾燥硬膜に対して、十分な化学的処理が行われないまま製品として流通し、脳外科手術で移植された患者にＣＪＤが発生した。"},{"label":"b","text":"ＣＪＤは、ウイルスの一種であるプリオンが脳の組織に感染することが原因とされ、次第に認知症に類似した症状が現れ、死に至る重篤な神経難病である。"},{"label":"c","text":"本訴訟の和解を踏まえて、ＣＪＤ患者に対する入院対策・在宅対策の充実の措置が講じられるようになった。"},{"label":"d","text":"本訴訟を契機として、ヒト乾燥硬膜移植の有無を確認するため、患者診療録を長期保存する等の措置が講じられるようになった。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"プリオン不活化のための十分な化学的処理が行われないままヒト乾燥硬膜が製品として流通し、脳外科手術で移植された患者にCJDが発生した。CJDの原因とされるプリオンは細菌でもウイルスでもないタンパク質の一種であり、脳の組織に感染して次第に認知症に類似した症状が現れ死に至る神経難病であるため、「ウイルスの一種」とするbは誤りである。本訴訟の和解を踏まえてCJD患者への入院対策・在宅対策の充実が図られ、ヒト乾燥硬膜移植の有無を確認するため患者診療録を長期保存する等の措置も講じられるようになった。","tags":["CJD","プリオン","ヒト乾燥硬膜"]},{"id":"R4-61","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":61,"stem":"消化器系に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"消化器系は、飲食物を消化して生命維持に必要な栄養分として吸収し、その残滓を体外に排出する器官系である。"},{"label":"b","text":"消化管は、胃から肛門まで続く管であり、平均的な成人で全長約９ｍある。"},{"label":"c","text":"化学的消化とは、口腔内で咀嚼や消化管の運動によって飲食物を分解することをいう。"},{"label":"d","text":"食道は喉もとから上腹部のみぞおち近くまで続く管状の器官で、括約筋はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"消化器系は、飲食物を消化して生命維持に必要な栄養分として吸収し、残りを体外に排出する器官系であり、aは手引きの定義と一致する。消化管は胃からではなく口腔から肛門まで続く管で、全長約9mという長さの記述は正しいが起点が誤っているため、bは誤り。化学的消化は消化液（消化酵素）による分解を指し、咀嚼や消化管の運動による分解は機械的消化と呼ばれるため、cは両者の説明が入れ替わっている。食道の上端と下端には括約筋があり、胃の内容物が食道や咽頭へ逆流しないようにしているため、dの「括約筋はない」は誤り。以上よりaのみ正しい選択肢5が正答となる。","tags":["消化器系","消化管","食道"]},{"id":"R4-62","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":62,"stem":"小腸に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"十二指腸は、胃から連なるＣ字型に彎曲した部分で、彎曲部には膵管と胆管の開口部があって、それぞれ膵液と胆汁を腸管内へ送り込んでいる。"},{"label":"b","text":"回腸は、十二指腸に続く部分で、小腸上部の約４０％を占め、明確な境目はないが空腸に続く。"},{"label":"c","text":"十二指腸の上部を除き、小腸の内壁は、その粘膜表面が絨毛（柔突起ともいう）に覆われた輪状のひだがあるなど、表面積を大きくする構造を持つ。"},{"label":"d","text":"小腸において、脂質は、ラクターゼ（消化酵素）の作用によって分解を受けるが、小腸粘膜の上皮細胞で吸収されると脂質に再形成され、乳状脂粒となる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"十二指腸は胃から連なる約25cmのC字型に彎曲した部分で、彎曲部に膵管・胆管の開口部があり膵液・胆汁を腸管内へ送り込むため、aは正しい。小腸のうち十二指腸に続く上部約40%を占めるのは空腸であり、回腸はその後に続く残り約60%の部分であるため、bは空腸と回腸の説明が入れ替わっている。十二指腸上部を除く小腸内壁は輪状のひだと絨毛（柔突起）により表面積が広げられているため、cは正しい。小腸で脂質を分解するのはリパーゼであり、ラクターゼは乳糖（糖質）を分解する酵素であるため、dは誤り。","tags":["小腸","十二指腸","絨毛"]},{"id":"R4-63","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":63,"stem":"呼吸器系に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"鼻腔の内壁から分泌される鼻汁には、アミラーゼが多く含まれ、気道の防御機構の一つとなっている。"},{"label":"b","text":"声帯は、喉頭上部にあり、呼気で振動させると声が発せられるが、過度の負担がかかると、声はかすれてくる。"},{"label":"c","text":"気道に細菌等の異物が吸い込まれると、異物は気道粘膜から分泌される粘液にからめ取られ、粘液層の連続した流れによって咽頭へ向けて排出される。"},{"label":"d","text":"肺自体には肺を動かす筋組織がないため、横隔膜や肋間筋によって拡張・収縮して呼吸運動が行われる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"鼻汁に多く含まれ気道の防御に働くのはリゾチームであり、アミラーゼではないため、aは誤り。声帯は喉頭上部にあり呼気で振動させることで発声し、過度の負担で声がかすれるとされ、bは正しい。気道内の異物は気道粘膜から分泌される粘液にからめ取られ、線毛運動による粘液層の連続した流れで咽頭へ向けて排出されるため、cは正しい。肺自体には肺を動かす筋組織がなく、横隔膜や肋間筋の働きによって拡張・収縮し呼吸運動が行われるため、dは正しい。","tags":["呼吸器系","鼻汁","声帯"]},{"id":"R4-64","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":64,"stem":"循環器系に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"心臓の左側部分（左心房、左心室）は、全身から集まってきた血液を肺へ送り出す。"},{"label":"b","text":"四肢を通る静脈では、静脈弁が一定の間隔をおいて発達しており、血液の逆流を防いでいる。"},{"label":"c","text":"毛細血管は、体中の組織に細かく張り巡らされている細い血管で、その薄い血管壁を通して、血液中から酸素と栄養分が組織へ運び込まれる。"},{"label":"d","text":"好中球は、白血球全体の約５％と数は少ないが、大きさは白血球の中で最も大きく、強い食作用を持つ。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"c、d"}],"answer":3,"explanation":"全身から集まった血液を肺へ送り出すのは心臓の右側部分（右心房・右心室）であり、左側部分は肺からの血液を全身へ送り出す側であるため、aは誤り。四肢の静脈には血液の逆流を防ぐ静脈弁が一定間隔で発達しているため、bは正しい。毛細血管は体中に張り巡らされた細い血管で、薄い血管壁を通じて血液中の酸素や栄養分が組織へ運び込まれるため、cは正しい。白血球の約60%を占め最も数が多いのは好中球であり、白血球中最も大きく強い食作用を持つのは単球であるため、dは両者の特徴が入れ替わっており誤り。正しい組合せはb・cである。","tags":["循環器系","心臓","白血球"]},{"id":"R4-65","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":65,"stem":"泌尿器系に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"糸球体の外側を袋状のボウマン嚢が包み込んでおり、これを腎小体という。"},{"label":"b","text":"腎小体では、血液中の老廃物のほか、血球やタンパク質以外の血漿成分も濾過される。"},{"label":"c","text":"腎臓には、心臓から拍出される血液の約７０％が流れており、水分及び電解質（特にナトリウム）の排出調節等が行われる。"},{"label":"d","text":"排尿時には、膀胱の出口にある膀胱括約筋が収縮すると、同時に膀胱壁の排尿筋が弛緩し、尿が尿道へと押し出される。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"c、d"}],"answer":1,"explanation":"糸球体を包む袋状のボウマン嚢と糸球体を合わせて腎小体と呼ぶため、aは正しい。腎小体では血液中の老廃物のほか、血球やタンパク質以外の血漿成分も濾過されるため、bは正しい。腎臓に流れる血液量は心拍出量の約1/5～1/4とされており、約70%という数値は誤り。排尿時は膀胱の出口の膀胱括約筋が緩み（弛緩）、同時に膀胱壁の排尿筋が収縮することで尿が押し出されるため、dは括約筋と排尿筋の動きが逆に記載されており誤り。正しい組合せはa・bである。","tags":["泌尿器系","腎小体","排尿"]},{"id":"R4-66","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":66,"stem":"目に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"水晶体の前にある虹彩が、瞳孔の大きさを変えることによって眼球内に入る光の量を調節している。"},{"label":"b","text":"水晶体は、その周りを囲んでいる毛様体の収縮・弛緩によって、遠くの物を見るときには丸く厚みが増し、近くの物を見るときには扁平になる。"},{"label":"c","text":"網膜に密集している視細胞が光を感じる反応には、ビタミンＣが不可欠であるため、不足すると夜間視力の低下である夜盲症を生じる。"},{"label":"d","text":"眼瞼（まぶた）は、皮下組織が少なく薄くできているため、裂傷や内出血が生じやすく、また、むくみ（浮腫）等の全身的な体調不良（薬の副作用を含む）の症状が現れやすい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"虹彩が瞳孔の大きさを変えて眼球内に入る光量を調節するため、aは正しい。水晶体は毛様体の収縮・弛緩により、近くを見るときに丸く厚みが増し、遠くを見るときに扁平になるとされており、bは記述が逆になっているため誤り。視細胞が光を感じる反応に不可欠なのはビタミンAであり、不足すると夜盲症を生じるため、cのビタミンCは誤り。眼瞼は皮下組織が少なく薄いため裂傷や内出血、むくみ等の全身症状が現れやすいとされ、dは正しい。","tags":["目","水晶体","視細胞"]},{"id":"R4-67","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":67,"stem":"鼻及び耳に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"鼻炎は、鼻腔粘膜に炎症が起きて腫れた状態であり、鼻閉（鼻づまり）や鼻汁過多などの症状が生じる。"},{"label":"b","text":"鼻腔と副鼻腔を連絡する管は非常に狭いため、鼻腔粘膜が腫れると副鼻腔の開口部がふさがりやすくなり、副鼻腔に炎症を生じることがある。"},{"label":"c","text":"鼓膜まで伝導された音は、鼓膜を振動させ、互いに連結した微細な３つの耳小骨が、鼓膜の振動を増幅して、中耳へ音を伝える。"},{"label":"d","text":"小さな子供では、耳管の形状が太く短く、走行が水平に近いため、鼻腔からウイルスや細菌が侵入しやすい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"鼻炎は鼻腔粘膜の炎症により腫れた状態で、鼻閉や鼻汁過多を生じるため、aは正しい。鼻腔と副鼻腔をつなぐ管は狭く、鼻腔粘膜の腫れにより副鼻腔の開口部がふさがり炎症を生じやすいため、bは正しい。3つの耳小骨は鼓膜の振動を増幅して伝えるが、その伝達先は中耳ではなく内耳であるため、cは伝達先が誤っている。小さな子供は耳管が太く短く水平に近いため、鼻腔からウイルスや細菌が侵入しやすいとされ、dは正しい。","tags":["鼻","耳","耳小骨"]},{"id":"R4-68","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":68,"stem":"皮膚に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"外皮系には、皮膚と汗腺、皮脂腺、乳腺等は含まれるが、爪や毛等は含まれない。"},{"label":"b","text":"真皮は、線維芽細胞と線維性のタンパク質からなる皮下組織の層で、皮膚の弾力と強さを与える役割がある。"},{"label":"c","text":"皮脂は、脂分を蓄えて死んだ腺細胞自身が分泌物となったもので、皮膚を潤いのある柔軟な状態に保つ。"},{"label":"d","text":"汗腺には、腋窩（わきのした）などの毛根部に分布するエクリン腺と、手のひらなどの毛根がないところも含め全身に分布するアポクリン腺がある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":5,"explanation":"外皮系には皮膚や汗腺・皮脂腺・乳腺に加え、爪や毛などの角質も含まれるため、aの「爪や毛は含まれない」は誤り。真皮は線維芽細胞とコラーゲン等の線維性タンパク質からなる結合組織の層であり、皮下組織は真皮のさらに下にある別の層であるため、bは誤り。皮脂腺は脂分を蓄えて死んだ腺細胞自身が分泌物（皮脂）となり、皮膚を潤いのある柔軟な状態に保つとされ、cは正しい。腋窩など毛根部に分布するのはアポクリン腺、手のひらなど毛根のない部位も含め全身に分布するのはエクリン腺であり、dは名称が入れ替わっているため誤り。","tags":["皮膚","真皮","汗腺"]},{"id":"R4-69","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":69,"stem":"骨格系及び筋組織に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"骨の機能の一つである造血機能は、主として胸骨、肋骨、脊椎、骨盤、大腿骨などの骨髄が担う。"},{"label":"b","text":"骨組織では、通常、組織を構成するカルシウムが骨から溶け出し、ほぼ同量のカルシウムが骨に沈着することで、骨吸収と骨形成のバランスが取られる。"},{"label":"c","text":"腱は、筋細胞（筋線維）と結合組織からなり、関節を構成する骨に骨格筋をつないでいる。"},{"label":"d","text":"随意筋である骨格筋は、長時間の動作等で疲労した場合でも、運動を続けることで、筋組織の収縮性が回復する。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"造血機能は主として胸骨・肋骨・脊椎・骨盤・大腿骨などの骨髄が担うとされ、aは正しい。骨組織では骨からのカルシウム溶出とほぼ同量の沈着が繰り返されることで骨吸収と骨形成のバランスが保たれるため、bは正しい。腱は結合組織のみでできており伸縮性に乏しく、筋細胞（筋線維）を含むのは筋組織自体であるため、cの「腱は筋細胞と結合組織からなる」は誤り。骨格筋は随意筋だが疲労しやすく、長時間の動作や運動継続によりグリコーゲンの減少や乳酸の蓄積が起きて筋組織の収縮性は低下するのであって回復するわけではないため、dは誤り。","tags":["骨格系","筋組織","腱"]},{"id":"R4-70","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":70,"stem":"交感神経系が活発になった時に生じる効果器とその反応の関係について、誤っているものを一つ選べ。\n効果器 / 交感神経系による効果器の反応","statements":[],"options":[{"n":1,"text":"心臓 / 心拍数増加"},{"n":2,"text":"気管、気管支 / 収縮"},{"n":3,"text":"肝臓 / グリコーゲンの分解"},{"n":4,"text":"腸 / 運動低下"},{"n":5,"text":"目 / 瞳孔散大"}],"answer":2,"explanation":"交感神経系が活発になると、心臓は心拍数が増加し、肝臓ではグリコーゲンの分解が進み、腸は運動が低下し、目は瞳孔が散大するとされており、選択肢1・3・4・5はいずれも正しい。一方、気管・気管支は交感神経系の作用により拡張するのであって収縮するのではないため、選択肢2の「収縮」という記述が誤りである。したがって誤っているものは2の気管・気管支である。","tags":["自律神経系","交感神経","効果器"]},{"id":"R4-71","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":71,"stem":"薬が働く仕組みに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の作用には、全身作用と局所作用とがあり、外用薬は、すべて局所的な効果を目的としたものである。"},{"label":"b","text":"全身作用を目的とする医薬品では、その有効成分が吸収されて、循環血液中に移行することが不可欠である。"},{"label":"c","text":"内服薬のほとんどは、その有効成分が、主として小腸で吸収される。"},{"label":"d","text":"内服薬の有効成分の吸収量や吸収速度は、消化管内容物には影響されないが、他の医薬品の作用により影響を受けることがある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"外用薬には局所作用を目的とするものが多いが、坐剤や経皮吸収製剤のように全身作用を目的として設計されたものもあるため、aの「すべて局所的」は誤り。全身作用を目的とする医薬品では有効成分が吸収され循環血液中に移行することが不可欠であるため、bは正しい。内服薬のほとんどはその有効成分が主に小腸で吸収されるため、cは正しい。内服薬の吸収量や吸収速度は消化管内容物と他の医薬品の作用の両方から影響を受けるとされており、dの「消化管内容物には影響されない」は誤り。","tags":["薬の作用","全身作用","吸収"]},{"id":"R4-72","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":72,"stem":"薬の代謝、排泄に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"経口投与後、消化管で吸収された有効成分は、全身循環に入る前に肝臓を経由して門脈を通過する。"},{"label":"b","text":"循環血液中に移行した多くの有効成分は、血液中で血漿タンパク質と不可逆的に結合して複合体を形成する。"},{"label":"c","text":"循環血液中に存在する有効成分の多くは、未変化体又は代謝物の形で腎臓から尿中に排泄される。"},{"label":"d","text":"腎機能が低下した人では、正常の人よりも有効成分の尿中への排泄が遅れ、医薬品の効き目が過剰に現れたり、副作用が生じやすくなったりする。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":3,"explanation":"経口投与後に吸収された有効成分は、全身循環に入る前に門脈を経由して肝臓を通過するのであり、記述の「肝臓を経由して門脈を通過する」は順序が逆になっているため、aは誤り。血漿タンパク質との結合は速やかかつ可逆的であり、不可逆的に結合するわけではないため、bは誤り。循環血液中の有効成分の多くは未変化体又は代謝物として腎臓から尿中に排泄されるため、cは正しい。腎機能が低下した人では排泄が遅れて血中濃度が下がりにくくなり、効き目が過剰に現れたり副作用が生じやすくなったりするため、dは正しい。","tags":["代謝","排泄","肝初回通過効果"]},{"id":"R4-73","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":73,"stem":"医薬品の剤形及びその一般的な特徴に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"腸溶錠は、腸内での溶解を目的として錠剤表面をコーティングしているものである。"},{"label":"b","text":"散剤を服用するときは、飛散を防ぐため、あらかじめ少量の水（又はぬるま湯）を口に含んだ上で服用するなどの工夫をするとよい。"},{"label":"c","text":"クリーム剤は、有効成分が適用部位に留まりやすく、一般に、患部を水から遮断したい場合に用いられる。"},{"label":"d","text":"貼付剤は、適用部位に有効成分が一定時間留まるため、薬効の持続が期待できる反面、適用部位にかぶれなどを起こす場合もある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"腸溶錠は腸内での溶解を目的として錠剤表面をコーティングしたものであるため、aは正しい。散剤は飛散を防ぐためあらかじめ少量の水を口に含んでから服用するなどの工夫がよいとされ、bは正しい。患部を水から遮断したい場合に用いられるのは油性基剤の軟膏剤であり、クリーム剤はむしろ水で洗い流したい場合に用い、皮膚への刺激が強いため傷などへの使用は避けるとされるため、cは軟膏剤とクリーム剤の説明が入れ替わっており誤り。貼付剤は有効成分が一定時間留まり薬効の持続が期待できる反面、かぶれなどを起こす場合があるため、dは正しい。","tags":["剤形","軟膏","クリーム剤"]},{"id":"R4-74","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":74,"stem":"医薬品の副作用として現れる皮膚粘膜眼症候群と中毒性表皮壊死融解症に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"典型的な症状として、いずれも３８℃以上の高熱、目の充血、口唇のただれ、喉の痛み、広範囲の皮膚の発赤等が現れる。"},{"label":"b","text":"いずれも致命的な転帰をたどることはないが、一旦発症すると、皮膚症状が軽快した後も眼や呼吸器等に障害が残ることがある疾患である。"},{"label":"c","text":"症状が持続したり、又は急激に悪化したりする場合は、原因と考えられる医薬品の使用を中止して、直ちに皮膚科の専門医を受診する必要がある。"},{"label":"d","text":"いずれも原因医薬品の使用開始後、２週間以内に起こることは少なく、１ヶ月以上経過してから発症することが多い。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":5,"explanation":"いずれも38℃以上の高熱、目の充血、口唇のただれ、喉の痛み、広範囲の皮膚の発赤等を典型的な症状とするため、aは正しい。両疾患は多臓器障害等により致命的な転帰をたどることがあり、皮膚症状が軽快した後も眼や呼吸器等に障害が残ることがあるとされるため、bの「致命的な転帰をたどることはない」は誤り。症状が持続または急激に悪化する場合は原因医薬品の使用を中止し、直ちに皮膚科の専門医を受診する必要があるため、cは正しい。いずれも原因医薬品の使用開始後2週間以内に発症することが多く、まれに1ヶ月以上経ってから起こることもあるとされ、dは頻度の記述が逆であるため誤り。","tags":["皮膚粘膜眼症候群","中毒性表皮壊死融解症","副作用"]},{"id":"R4-75","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":75,"stem":"医薬品の副作用として現れる肝機能障害に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品により生じる肝機能障害は、中毒性のものと、アレルギー性のものに大別される。"},{"label":"b","text":"肝機能障害は、軽度であっても倦怠感や皮膚の掻痒感等の自覚症状が顕著に現れることが多い。"},{"label":"c","text":"黄疸は、ビリルビン（黄色色素）が血液中へ排出されず、胆汁中に滞留することにより生じる。"},{"label":"d","text":"副作用による肝機能障害が疑われるにもかかわらず、漫然と原因と考えられる医薬品を使用し続けると、肝不全を生じ、死に至ることもある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"医薬品による肝機能障害は、直接的肝毒性による中毒性のものと、抗原抗体反応によるアレルギー性のものに大別されるため、aは正しい。軽度の肝機能障害では自覚症状がなく、健康診断の血液検査で判明することが多いとされ、bの「自覚症状が顕著に現れることが多い」は誤り。黄疸はビリルビンが胆汁中へ排出されず血液中に滞留することにより生じるとされ、cは血液と胆汁の関係が逆になっているため誤り。副作用による肝機能障害を放置すると肝不全に至り死亡することもあるため、dは正しい。","tags":["肝機能障害","黄疸","副作用"]},{"id":"R4-76","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":76,"stem":"精神神経系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の副作用として現れる精神神経症状は、医薬品の大量服用や長期連用等の不適正な使用がなされた場合に限って発生し、通常の用法・用量の使用で現れることはない。"},{"label":"b","text":"混合性結合組織病、関節リウマチ等の基礎疾患がある人では、医薬品による無菌性髄膜炎の発症リスクが高い。"},{"label":"c","text":"副作用としての無菌性髄膜炎の発症は、多くの場合緩やかで、頭痛、発熱、吐きけ、意識混濁等の症状が徐々に現れる。"},{"label":"d","text":"心臓や血管に作用する医薬品の使用により、頭痛やめまい、浮動感（体がふわふわと宙に浮いたような感じ）の症状が現れることがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"精神神経症状は大量服用や長期連用など不適正な使用に限らず、通常の用法・用量でも発生することがあるため、aは誤り。混合性結合組織病や関節リウマチ等の基礎疾患がある人は、医薬品による無菌性髄膜炎の発症リスクが高いとされ、bは正しい。無菌性髄膜炎の多くは急性に発症し、激しい頭痛や発熱、吐きけ、意識混濁等の症状が現れるとされ、cの「緩やかで徐々に現れる」は誤り。心臓や血管に作用する医薬品では頭痛やめまい、浮動感が現れることがあるため、dは正しい。","tags":["精神神経系","無菌性髄膜炎","副作用"]},{"id":"R4-77","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":77,"stem":"消化器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"副作用による消化性潰瘍になると、胃のもたれ、食欲低下、胸やけ、吐きけ、胃痛、空腹時にみぞおちが痛くなるなどの症状が生じるが、自覚症状が乏しい場合もある。"},{"label":"b","text":"イレウスとは、腸の粘膜組織が傷害されて、その一部が粘膜筋板を超えて欠損する状態をいう。"},{"label":"c","text":"イレウス様症状では、嘔吐がない場合でも、腹痛などの症状のために水分や食物の摂取が抑制され、脱水状態となることがある。"},{"label":"d","text":"浣腸剤や坐剤の使用によって現れる一過性の症状に、肛門部の熱感等の刺激、排便直後の立ちくらみなどがある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"消化性潰瘍では胃のもたれ、食欲低下、胸やけ、吐きけ、胃痛等の症状が生じるが、自覚症状に乏しい場合もあるとされ、aは正しい。イレウスとは腸内容物の通過が阻害された状態を指すのであって、粘膜組織が粘膜筋板を超えて欠損する状態というのは消化性潰瘍の定義であるため、bは説明が入れ替わっており誤り。イレウス様症状では嘔吐がない場合でも腹痛等により水分・食物の摂取が抑制され、脱水状態となることがあるため、cは正しい。浣腸剤や坐剤の使用による一過性の症状として肛門部の熱感や排便直後の立ちくらみなどが挙げられているため、dは正しい。","tags":["消化器系副作用","イレウス","消化性潰瘍"]},{"id":"R4-78","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":78,"stem":"呼吸器系に現れる医薬品の副作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"間質性肺炎を発症すると、体内は低酸素状態となり、息切れ・息苦しさ等の呼吸困難、空咳（痰の出ない咳）、発熱等の症状が現れる。"},{"label":"b","text":"間質性肺炎は、病態が進行すると軽労作時にも息切れが感じられるようになり、その際必ず発熱を伴う。"},{"label":"c","text":"間質性肺炎は、悪化すると肺線維症（肺が線維化を起こして硬くなる状態）に移行することがある。"},{"label":"d","text":"副作用として現れる喘息は、原因となる医薬品の使用後、短時間（１時間以内）で症状が現れ、それらの症状は、時間とともに悪化することがある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"間質性肺炎を発症すると低酸素状態となり、息切れ・息苦しさ等の呼吸困難、空咳、発熱等の症状を呈するため、aは正しい。病態が進行すると軽労作時にも息切れが感じられるようになるが、必ずしも発熱を伴うわけではないため、bの「必ず発熱を伴う」は誤り。間質性肺炎は悪化すると肺線維症に移行することがあるため、cは正しい。副作用としての喘息は原因医薬品の使用後短時間（1時間以内）に症状が現れ、それらの症状は時間とともに悪化するとされ、dは正しい。","tags":["呼吸器系副作用","間質性肺炎","喘息"]},{"id":"R4-79","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":79,"stem":"泌尿器系に現れる医薬品の副作用に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"副交感神経系の機能を亢進する作用がある成分が配合された医薬品を使用すると、膀胱の排尿筋の収縮が抑制され、尿が出にくい等の症状を生じることがある。"},{"label":"b","text":"医薬品を使用して生じる尿閉は、前立腺肥大の基礎疾患がある人に特有に現れることが知られている。"},{"label":"c","text":"医薬品の使用により、尿の回数増加（頻尿）、排尿時の疼痛、残尿感等の膀胱炎様症状が現れることがある。"},{"label":"d","text":"外国から個人的に購入した医薬品（生薬・漢方薬）又はそれらと類似する健康食品（健康茶等）の摂取によって、重篤な腎障害を生じた事例が報告されている。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、d"},{"n":4,"text":"c、d"}],"answer":4,"explanation":"排尿筋の収縮を抑制して尿を出にくくするのは副交感神経系の機能を「抑制」する作用がある成分（抗コリン成分等）であり、機能を「亢進」する成分ではないため、aは誤り。医薬品による尿閉は前立腺肥大等の基礎疾患がない人でも現れることが知られており、男女を問わず報告されているため、bの「特有に現れる」は誤り。医薬品の使用により頻尿、排尿時の疼痛、残尿感等の膀胱炎様症状が現れることがあるため、cは正しい。外国から個人的に購入した医薬品や類似する健康食品の摂取により重篤な腎障害を生じた事例が報告されているため、dは正しい。正しい組合せはc・dである。","tags":["泌尿器系副作用","尿閉","抗コリン"]},{"id":"R4-80","chapter":2,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":80,"stem":"皮膚に現れる医薬品の副作用に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"塗り薬を皮膚に塗布したあと、その薬の配合成分に皮膚が反応して、発赤、腫れ等の激しい炎症症状が生じることがある。"},{"label":"b","text":"接触皮膚炎は、外来性の物質が皮膚に接触することで現れる炎症であるため、同じ医薬品に接触した人のすべてに現れる炎症症状である。"},{"label":"c","text":"接触皮膚炎の症状は、通常１週間程度で治まり、再びその医薬品に触れても再発することはない。"},{"label":"d","text":"薬疹は、過去に薬疹を経験したことがない人であっても、暴飲暴食や肉体疲労が誘因となって現れることがある。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"c、d"}],"answer":2,"explanation":"塗り薬の配合成分に皮膚が反応して、発赤や腫れ等の激しい炎症症状（接触皮膚炎）が生じることがあるため、aは正しい。接触皮膚炎は同じ医薬品に触れても発症するかどうかがその人の体質によって異なり、誰にでも現れるわけではないため、bは誤り。接触皮膚炎の症状は通常1週間程度で治まるが、再びその医薬品に触れると再発するため、cの「再発することはない」は誤り。薬疹は過去に経験がない人でも、暴飲暴食や肉体疲労が誘因となって現れることがあるため、dは正しい。正しい組合せはa・dである。","tags":["皮膚副作用","接触皮膚炎","薬疹"]},{"id":"R4-21","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":21,"stem":"かぜ薬の配合成分に関する記述について、（　）の中に入れるべき字句の正しい組合せを一つ選べ。\nかぜ薬とは、かぜの諸症状の緩和を目的として使用される医薬品の総称である。その中には、鼻粘膜の充血を和らげ、気管・気管支を拡げる成分として（ａ）、咳を抑える成分として（ｂ）、及びくしゃみや鼻汁を抑える成分として（ｃ）が配合されているものがある。","statements":[],"options":[{"n":1,"text":"a グアイフェネシン / b イソプロピルアンチピリン / c エテンザミド"},{"n":2,"text":"a グアイフェネシン / b ノスカピン / c エテンザミド"},{"n":3,"text":"a メチルエフェドリン塩酸塩 / b イソプロピルアンチピリン / c エテンザミド"},{"n":4,"text":"a メチルエフェドリン塩酸塩 / b イソプロピルアンチピリン / c ヨウ化イソプロパミド"},{"n":5,"text":"a メチルエフェドリン塩酸塩 / b ノスカピン / c ヨウ化イソプロパミド"}],"answer":5,"explanation":"かぜ薬には、鼻粘膜の充血を和らげ気管支を拡げるアドレナリン作動成分、咳を鎮める鎮咳成分、くしゃみや鼻汁を抑える抗ヒスタミン成分・抗コリン成分がそれぞれ配合されることがある。手引きでは、メチルエフェドリン塩酸塩は交感神経を刺激して気管支を拡張する成分、ノスカピンは中枢に作用する非麻薬性の鎮咳成分、ヨウ化イソプロパミドは抗コリン作用によってくしゃみや鼻汁を抑える成分として整理されている。設問のａ〜ｃにこの組合せを当てはめると、ａはメチルエフェドリン塩酸塩、ｂはノスカピン、ｃはヨウ化イソプロパミドとなり、選択肢5が正しい。","tags":["かぜ薬","気管支拡張成分","鎮咳成分"]},{"id":"R4-22","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":22,"stem":"かぜ薬に含まれる炎症による腫れを和らげる成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"グリチルリチン酸二カリウムの作用本体であるグリチルリチン酸は、化学構造がステロイド性抗炎症成分に類似していることから、抗炎症作用を示すと考えられている。"},{"label":"b","text":"グリチルリチン酸二カリウムは、血栓を起こすおそれのある人に使用する場合は、医師や薬剤師に相談するなどの対応が必要である。"},{"label":"c","text":"トラネキサム酸は、体内での起炎物質の産生を抑制することで炎症の発生を抑え、腫れを和らげる。"},{"label":"d","text":"トラネキサム酸を大量に摂取すると、偽アルドステロン症を生じるおそれがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"グリチルリチン酸二カリウムはその作用本体であるグリチルリチン酸の化学構造がステロイド性抗炎症成分に類似しており、抗炎症作用を示すと考えられているため、aは正しい。血栓のある人や血栓を起こすおそれのある人への注意が必要とされるのは、凝固した血液を溶解されにくくする働きを持つトラネキサム酸であってグリチルリチン酸二カリウムではないため、bは誤りである。トラネキサム酸は体内での起炎物質の産生を抑制して炎症を抑え腫れを和らげる成分であり、cは正しい。一方、大量摂取で偽アルドステロン症を生じるおそれがあるのはグリチルリチン酸（二カリウム）であってトラネキサム酸ではないため、dは誤りである。","tags":["かぜ薬","抗炎症成分","偽アルドステロン症"]},{"id":"R4-23","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":23,"stem":"体力虚弱のもののかぜの症状緩和に用いることができる漢方処方製剤の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"葛根湯"},{"label":"b","text":"麻黄湯"},{"label":"c","text":"香蘇散"},{"label":"d","text":"小柴胡湯"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":3,"explanation":"葛根湯は体力中等度以上の人向けの処方であり、体の虚弱な人には不向きとされているため、aは誤りである。麻黄湯も体力が充実している人向けで、マオウの含有量が多いため体の虚弱な人には使用を避けるべきとされ、bも誤りである。香蘇散は体力虚弱で神経過敏で気分がすぐれず胃腸の弱いもののかぜの初期等に適すとされており、cは正しい。小柴胡湯は体力中等度の人を対象とし、体の虚弱な人には不向きとされているため、dは誤りである。","tags":["漢方処方製剤","かぜ","体力"]},{"id":"R4-24","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":24,"stem":"鎮痛の目的で用いられる漢方処方製剤に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"芍薬甘草湯は、体力中等度以下で手足が冷えて肩がこり、ときにみぞおちが膨満するものの頭痛、頭痛に伴う吐きけ・嘔吐、しゃっくりに適すとされる。"},{"label":"b","text":"疎経活血湯は、体力中等度で、痛みがあり、ときにしびれがあるものの関節痛、神経痛、腰痛、筋肉痛に適すとされる。"},{"label":"c","text":"麻杏薏甘湯は体力中等度なものの関節痛、神経痛、筋肉痛、いぼ、手足のあれに適すとされる。"},{"label":"d","text":"釣藤散は、体力中等度で、慢性に経過する頭痛、めまい、肩こりなどがあるものの慢性頭痛、神経症、高血圧の傾向のあるものに適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"設問aの『手足が冷えて肩がこり、ときにみぞおちが膨満するものの頭痛、頭痛に伴う吐きけ・嘔吐、しゃっくり』という記述は、芍薬甘草湯ではなく呉茱萸湯の適応にあたる。芍薬甘草湯は体力に関わらず使用でき、筋肉の急激な痙攣を伴うこむらがえりや腹痛、腰痛に適すとされる処方であるため、aは誤りである。疎経活血湯は体力中等度で痛みやしびれを伴う関節痛・神経痛・腰痛・筋肉痛に適すとされ、bは正しい。麻杏薏甘湯は体力中等度の人の関節痛・神経痛・筋肉痛・いぼ・手足のあれに適すとされ、cも正しい。釣藤散は体力中等度で慢性に経過する頭痛やめまい、肩こりを伴い高血圧の傾向のあるものに適すとされ、dも正しい。","tags":["漢方処方製剤","鎮痛","芍薬甘草湯"]},{"id":"R4-25","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":25,"stem":"一般用医薬品の解熱鎮痛薬を購入する際に、受診勧奨が必要と考えられる症状の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"激しい腹痛や下痢などの消化器症状を伴う発熱"},{"label":"b","text":"１週間以上続く発熱"},{"label":"c","text":"年月の経過に伴って次第に増悪していくような月経痛"},{"label":"d","text":"起床時に関節のこわばりを伴う関節痛"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"解熱鎮痛薬は対症療法であり、発熱に激しい腹痛や下痢等の消化器症状を伴う場合や、発熱が1週間以上続く場合は、単なるかぜ以外の重い病気の可能性があるため受診勧奨の対象とされ、a・bは正しい。月経痛が年月の経過とともに次第に増悪していく場合は子宮内膜症等の可能性が考えられるため受診勧奨の対象であり、cも正しい。起床時に関節のこわばりを伴う関節痛は関節リウマチ等の可能性が考えられるため、dも受診勧奨の対象であり正しい。したがって全て正となる。","tags":["解熱鎮痛薬","受診勧奨"]},{"id":"R4-26","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":26,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを一つ選べ。\n体力中等度以下で、心身が疲れ、血色が悪く、ときに熱感を伴うものの貧血、不眠症、精神不安、神経症に適すとされる。","statements":[],"options":[{"n":1,"text":"加味帰脾湯"},{"n":2,"text":"桂枝加竜骨牡蛎湯"},{"n":3,"text":"抑肝散"},{"n":4,"text":"柴胡加竜骨牡蛎湯"},{"n":5,"text":"小建中湯"}],"answer":1,"explanation":"設問の『体力中等度以下で、心身が疲れ、血色が悪く、ときに熱感を伴うものの貧血、不眠症、精神不安、神経症に適す』という記述は、手引きにおける加味帰脾湯の適応そのものであり、選択肢1が正しい。桂枝加竜骨牡蛎湯は体力中等度以下で疲れやすく神経過敏で興奮しやすいものの神経質・不眠症等に適すとされる別の処方である。抑肝散は神経がたかぶり怒りやすい人の神経症・不眠症等に、柴胡加竜骨牡蛎湯は体力中等度以上で精神不安を伴う高血圧の随伴症状等に、小建中湯は虚弱体質の改善などに用いられ、いずれも設問の記述とは適応が異なる。","tags":["漢方処方製剤","加味帰脾湯","貧血"]},{"id":"R4-27","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":27,"stem":"一般用医薬品に含まれる有効成分とアルコールとの相互作用に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"アルコールは、アスピリンによる胃腸障害を減弱する。"},{"label":"b","text":"アルコールは、解熱鎮痛成分の吸収に影響するが、代謝に影響を与えることはない。"},{"label":"c","text":"ジフェンヒドラミン塩酸塩は、アルコールとともに服用すると、薬効や副作用が減弱されるおそれがある。"},{"label":"d","text":"アセトアミノフェンは、アルコールとともに服用すると、肝機能障害が起こりやすくなる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":4,"explanation":"アルコールはアスピリン等の解熱鎮痛成分による胃腸障害を軽減するのではなく、胃粘膜の荒れを介してかえって増強することが知られているため、aは誤りである。アルコールは解熱鎮痛成分の吸収だけでなく肝臓での代謝にも影響を与え、アセトアミノフェンでは通常より代謝が進んで薬効が十分に得られなくなることがあるため、bも誤りである。医薬品の添付文書で服用前後の飲酒を避けることとされているのは、アルコールの摂取により薬効や副作用が減弱ではなくむしろ増強されるおそれがあるためであり、抗ヒスタミン成分であるジフェンヒドラミン塩酸塩についても同様であるため、cは誤りである。アセトアミノフェンはアルコールと一緒に服用すると肝機能障害が起こりやすくなることが知られており、dは正しい。","tags":["相互作用","アルコール","解熱鎮痛薬"]},{"id":"R4-28","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":28,"stem":"一般用医薬品の催眠鎮静薬及びその配合成分等に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"特段の基礎疾患がない人において、ストレス、疲労、時差ぼけ等の睡眠リズムの乱れが原因の一時的な不眠は、一般用医薬品で対処可能である。"},{"label":"b","text":"入眠障害、熟眠障害、中途覚醒、早朝覚醒等の症状が慢性的に続いている不眠は、抗ヒスタミン成分を主薬とする催眠鎮静薬により対処可能である。"},{"label":"c","text":"１５歳未満の小児では、抗ヒスタミン成分により眠気とは反対の中枢興奮などの副作用が起きやすいため、使用は避ける。"},{"label":"d","text":"妊娠中にしばしば生じる睡眠障害は、ホルモンのバランスや体形の変化等が原因であり、睡眠改善薬の適用対象でない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"特段の基礎疾患がない人における、ストレスや疲労、時差ぼけ等の睡眠リズムの乱れが原因の一時的な不眠は一般用医薬品で対処可能とされており、aは正しい。一方、入眠障害や中途覚醒等の症状が慢性的に続く不眠は、抗ヒスタミン成分を主薬とする催眠鎮静薬（睡眠改善薬）の対象ではなく医療機関の受診が必要とされているため、bは誤りである。15歳未満の小児では抗ヒスタミン成分により眠気とは反対の神経過敏や中枢興奮などの副作用が起きやすいため使用を避けるとされており、cは正しい。妊娠中にしばしば生じる睡眠障害はホルモンバランスや体形変化が原因であり睡眠改善薬の適用対象ではないとされているため、dも正しい。","tags":["催眠鎮静薬","睡眠改善薬","抗ヒスタミン成分"]},{"id":"R4-29","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":29,"stem":"眠気防止薬の有効成分として配合されるカフェインに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"脳を興奮させる作用があり、脳が過剰に興奮すると、副作用として振戦（震え）、めまい、不安、頭痛等を生じることがある。"},{"label":"b","text":"心筋を興奮させる作用があり、副作用として、動悸が現れることがある。"},{"label":"c","text":"腎臓におけるナトリウムイオンの再吸収促進作用があり、尿量を減少させる。"},{"label":"d","text":"胃液分泌抑制作用があり、その結果、副作用として胃腸障害（食欲不振・悪心・嘔吐）が現れることがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"カフェインは脳を興奮させる作用があり、脳が過剰に興奮すると振戦やめまい、不安、頭痛等の副作用を生じることがあるため、aは正しい。心筋を興奮させる作用もあり、副作用として動悸が現れることがあるため、bも正しい。カフェインは腎臓におけるナトリウムイオン（水分）の再吸収を促進するのではなく抑制することで尿量を増加させる利尿作用を示すため、cは誤りである。また、胃液の分泌を抑制するのではなく亢進させる作用があり、その結果食欲不振や悪心・嘔吐等の胃腸障害を生じることがあるとされているため、dも誤りである。","tags":["眠気防止薬","カフェイン","利尿作用"]},{"id":"R4-30","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":30,"stem":"乗物酔い防止薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"不安や緊張などの心理的要因による影響を和らげることを目的として、アリルイソプロピルアセチル尿素のような鎮静成分が配合されている場合がある。"},{"label":"b","text":"アミノ安息香酸エチルは、脳に軽い興奮を起こさせて平衡感覚の混乱によるめまいを軽減させることを目的として用いられる。"},{"label":"c","text":"メクリジン塩酸塩は、吐きけの防止・緩和を目的として配合されることがある抗ヒスタミン成分である。"},{"label":"d","text":"ジフェニドール塩酸塩は、胃粘膜への麻酔作用によって嘔吐刺激を和らげる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"乗物酔いには不安や緊張などの心理的要因も関わるため、それを和らげる目的でアリルイソプロピルアセチル尿素のような鎮静成分が配合されることがあり、aは正しい。脳に軽い興奮を起こさせて平衡感覚の混乱によるめまいを軽減する成分はカフェインやジプロフィリン等のキサンチン系成分であり、アミノ安息香酸エチルは胃粘膜への麻酔作用によって嘔吐刺激を和らげる局所麻酔成分であるため、bは誤りである。メクリジン塩酸塩は吐きけの防止・緩和を目的として配合される抗ヒスタミン成分であり、cは正しい。ジフェニドール塩酸塩は内耳の前庭神経の調節作用等による抗めまい成分であり、『胃粘膜への麻酔作用』はアミノ安息香酸エチルの説明にあたるため、dは誤りである。","tags":["乗物酔い防止薬","抗めまい成分","局所麻酔成分"]},{"id":"R4-31","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":31,"stem":"咳止めや痰を出しやすくする目的で用いられる漢方処方製剤及び生薬成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"麻杏甘石湯は、体力中等度以上で、咳が出て、ときにのどが渇くものの咳、小児喘息、気管支喘息、気管支炎、感冒、痔の痛みに適すとされる。"},{"label":"b","text":"半夏厚朴湯は、構成生薬としてカンゾウを含むため、摂取されるグリチルリチン酸の総量が継続して多くならないよう注意を促すことが重要である。"},{"label":"c","text":"キョウニンは、体内で分解されて生じた代謝物の一部が延髄の呼吸中枢、咳嗽中枢を興奮させる作用を示すとされる。"},{"label":"d","text":"麦門冬湯は、体力中等度で、気分がふさいで、咽喉、食道部に異物感があり、かぜをひきやすく、ときに動悸、めまい、嘔気などを伴うものの小児喘息、気管支喘息、気管支炎、咳、不安神経症、虚弱体質に適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":3,"explanation":"麻杏甘石湯は体力中等度以上で咳が出てときにのどが渇くものの咳、小児喘息、気管支喘息、気管支炎、感冒、痔の痛みに適すとされており、aは正しい。半夏厚朴湯は手引き上、構成生薬としてカンゾウを含まない処方として位置づけられているため、グリチルリチン酸の総量に注意が必要という設問bの記述は誤りである。キョウニンは体内で分解されて生じた代謝物の一部が延髄の呼吸中枢・咳嗽中枢を興奮させるのではなく鎮静させる作用を示すとされており、cは誤りである。設問dの記述（気分がふさぎ咽喉・食道部に異物感があるものの小児喘息等に適す）は麦門冬湯ではなく柴朴湯の適応にあたるため、dも誤りである。","tags":["漢方処方製剤","鎮咳去痰薬","キョウニン"]},{"id":"R4-32","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":32,"stem":"胃に作用する薬及びその配合成分に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"消化成分のうち、胆汁分泌促進作用があるものは肝臓病の症状を悪化させるおそれがある。"},{"label":"b","text":"制酸成分を主体とする胃腸薬については、酸度の高い食品と一緒に使用すると胃酸に対する中和作用が低下すると考えられている。"},{"label":"c","text":"健胃薬は、炭水化物、脂質、タンパク質等の分解に働く酵素を補う等により、胃の内容物の消化を助けることを目的とする医薬品である。"},{"label":"d","text":"ピレンゼピン塩酸塩などの胃液分泌抑制成分は、副交感神経の伝達物質であるアセチルコリンの働きを促進する。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"c、d"}],"answer":1,"explanation":"胆汁末や動物胆等の胆汁分泌促進（利胆）作用がある成分は肝臓の働きを高める一方、肝臓病の診断を受けた人ではかえって症状を悪化させるおそれがあるとされており、aは正しい。制酸成分を主体とする胃腸薬は、酸度の高い食品と一緒に使用すると胃酸に対する中和作用が低下すると考えられており、bも正しい。健胃薬は生薬成分の味や香りによって唾液や胃液の分泌を促し弱った胃の働きを高めることを目的とする医薬品であり、炭水化物等の分解酵素を補うのは消化薬の働きであるため、cは誤りである。ピレンゼピン塩酸塩は副交感神経の伝達物質であるアセチルコリンの働きを促進するのではなく抑えることで胃液の分泌を抑制する成分であるため、dも誤りである。よって正しい組合せはaとbとなる。","tags":["胃腸薬","制酸成分","健胃薬"]},{"id":"R4-33","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":33,"stem":"胃の不調を改善する目的で用いられる漢方処方製剤に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"安中散は、体力虚弱で、疲れやすくて手足などが冷えやすいものの胃腸虚弱、下痢、嘔吐、胃痛、腹痛、急・慢性胃炎に適すとされる。"},{"label":"b","text":"六君子湯は、体力中等度以下で、胃腸が弱く、食欲がなく、みぞおちがつかえ、疲れやすく、貧血性で手足が冷えやすいものの胃炎、胃腸虚弱、胃下垂、消化不良、食欲不振、胃痛、嘔吐に適すとされる。"},{"label":"c","text":"平胃散は、体力中等度以上で、胃がもたれて消化が悪く、ときに吐きけ、食後に腹が鳴って下痢の傾向のあるものの食べすぎによる胃のもたれ、急・慢性胃炎、消化不良、食欲不振に適すとされる。"},{"label":"d","text":"人参湯は、体力中等度以下で腹部は力がなくて、胃痛又は腹痛があって、ときに胸やけや、げっぷ、胃もたれ、食欲不振、吐きけ、嘔吐などを伴うものの神経性胃炎、慢性胃炎、胃腸虚弱に適すとされる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"設問aの『体力虚弱で疲れやすく手足が冷えやすいものの胃腸虚弱・下痢・嘔吐・胃痛・腹痛・急慢性胃炎』という記述は、安中散ではなく人参湯（理中丸）の適応にあたるため誤りである。六君子湯は体力中等度以下で胃腸が弱く食欲がなく貧血性で手足が冷えやすいものの胃炎・胃腸虚弱・胃下垂等に適すとされ、bは正しい。平胃散は体力中等度以上で胃がもたれて消化が悪いものの食べすぎによる胃のもたれ・急慢性胃炎等に適すとされ、cも正しい。設問dの『腹部は力がなくて胃痛又は腹痛があり、ときに胸やけやげっぷ、胃もたれ等を伴うものの神経性胃炎・慢性胃炎・胃腸虚弱』という記述は、人参湯ではなく安中散の適応にあたるため誤りである。","tags":["漢方処方製剤","胃腸薬","安中散"]},{"id":"R4-34","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":34,"stem":"整腸薬又は止瀉薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"タンニン酸ベルベリンは、タンニン酸の抗菌作用とベルベリンの収斂作用による止瀉を期待して用いられる。"},{"label":"b","text":"トリメブチンマレイン酸塩は、腸内細菌のバランスを整える作用による整腸を期待して用いられる。"},{"label":"c","text":"ロペラミド塩酸塩は、水あたりや食あたりによる下痢の症状に用いることを目的として配合される。"},{"label":"d","text":"次没食子酸ビスマスは、腸粘膜のタンパク質と結合して不溶性の膜を形成し、腸粘膜を引きしめることにより、腸粘膜を保護する。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"タンニン酸ベルベリンは、タンニン酸の収斂作用とベルベリンの抗菌作用による止瀉を期待して用いられる成分であり、設問aは両者の作用を入れ替えて記述しているため誤りである。トリメブチンマレイン酸塩は腸内細菌のバランスを整える作用ではなく、消化管の平滑筋に直接作用して運動を調整する働きによるものであり、bは誤りである。ロペラミド塩酸塩は食べすぎ・飲みすぎや寝冷えによる下痢に用いる成分であり、食あたりや水あたりによる下痢は適用対象外とされているため、cは誤りである。次没食子酸ビスマスは腸粘膜のタンパク質と結合して不溶性の膜を形成し、腸粘膜を引きしめることで保護する収斂成分であり、dは正しい。","tags":["整腸薬","止瀉薬","ロペラミド塩酸塩"]},{"id":"R4-35","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":35,"stem":"瀉下薬の配合成分に関する記述について、誤っているものを一つ選べ。","statements":[],"options":[{"n":1,"text":"ピコスルファートナトリウムは、腸管内で水分を吸収して腸内容物に浸透し、糞便のかさを増すとともに糞便を柔らかくする。"},{"n":2,"text":"センノシドは、大腸に生息する腸内細菌によって分解され、分解生成物が大腸を刺激することで瀉下作用をもたらすと考えられている。"},{"n":3,"text":"ヒマシ油は、その分解物が小腸を刺激することで瀉下作用をもたらすと考えられている。"},{"n":4,"text":"水酸化マグネシウム等の無機塩類は、腸内容物の浸透圧を高めることで糞便中の水分量を増し、また、大腸を刺激して排便を促す。"},{"n":5,"text":"マルツエキスは、主成分である麦芽糖が腸内細菌によって分解（発酵）して生じるガスによって便通を促すとされている。"}],"answer":1,"explanation":"選択肢1の『腸管内で水分を吸収して腸内容物に浸透し、糞便のかさを増すとともに柔らかくする』という作用は、ピコスルファートナトリウムではなくカルメロース等の膨潤性瀉下成分の説明であるため誤りである。実際のピコスルファートナトリウムは、胃や小腸では分解されず大腸に生息する腸内細菌によって分解されて大腸を刺激する大腸刺激性瀉下成分である。センノシドも同様に大腸の腸内細菌によって分解され、その分解生成物が大腸を刺激して瀉下作用をもたらすとされており選択肢2は正しい。ヒマシ油は小腸でリパーゼにより生じる分解物が小腸を刺激して瀉下作用を示すとされ選択肢3は正しく、無機塩類が浸透圧を高めて水分量を増し大腸を刺激するという選択肢4、マルツエキスの麦芽糖が腸内細菌により発酵してガスを生じ便通を促すという選択肢5もいずれも手引きの記述と一致する。","tags":["瀉下薬","ピコスルファートナトリウム","膨潤性瀉下成分"]},{"id":"R4-36","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":36,"stem":"胃腸鎮痛鎮痙薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ブチルスコポラミン臭化物は、鎮痛鎮痙のほか、胃酸過多や胸やけに対する効果も期待して用いられる。"},{"label":"b","text":"ロートエキスには、縮瞳による目のかすみや排尿困難といった副作用が現れることがある。"},{"label":"c","text":"オキセサゼインは、消化管の粘膜及び平滑筋に対する局所麻酔作用による鎮痛鎮痙効果を期待して用いられる。"},{"label":"d","text":"パパベリン塩酸塩は、胃液分泌を抑える作用もあるため、胃酸過多や胸焼けに対する効果も期待して用いられる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"ブチルスコポラミン臭化物などの抗コリン成分は、胃痛や腹痛を鎮める鎮痛鎮痙作用のほか、胃酸過多や胸やけに対する効果も期待して用いられるため、aは正しい。抗コリン成分は瞳孔が広がる散瞳によって目のかすみや異常なまぶしさ、排尿困難等の副作用を生じることがあるとされ、瞳孔が狭まる『縮瞳』ではないため、bは誤りである。オキセサゼインは消化管の粘膜及び平滑筋に対する局所麻酔作用による鎮痛鎮痙効果を期待して用いられるとされ、cは正しい。パパベリン塩酸塩は消化管の平滑筋に直接働いて痙攣を鎮める成分だが、抗コリン成分とは異なり胃液分泌を抑える作用は見出されていないため、dは誤りである。","tags":["胃腸鎮痛鎮痙薬","抗コリン成分","オキセサゼイン"]},{"id":"R4-37","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":37,"stem":"一般用医薬品の強心薬の配合成分とその配合目的としての作用及び使用の際の注意事項に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"リュウノウは、中枢神経系の刺激による気つけの効果が期待できる強心成分である。"},{"label":"b","text":"ゴオウは、強心作用を示すほか、興奮を静める作用があるとされる。"},{"label":"c","text":"ジャコウは、微量で強い強心作用を示すため、１日用量は５ｍｇ以下に定められている。"},{"label":"d","text":"センソは、強心作用を示すほか、皮膚や粘膜に触れると局所麻酔作用を示すとされる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"手引きでは、強い強心作用を示す生薬成分としてセンソ・ゴオウ・ジャコウ・ロクジョウが位置づけられている一方、リュウノウは強心成分そのものではなく中枢神経系の刺激作用による気つけの効果を期待して配合される補助的な生薬であるため、設問aの『強心成分である』という記述は誤りである。ゴオウは強心作用のほか末梢血管の拡張による血圧降下や興奮を静める作用があるとされ、bは正しい。『微量で強い強心作用を示すため1日用量が5mg以下に定められている』という記述はセンソに関するものであり、ジャコウ（強心作用のほか呼吸中枢を刺激して呼吸機能を高め意識をはっきりさせる作用があるとされる）の説明としては誤りである。センソは強心作用のほか皮膚や粘膜に触れると局所麻酔作用を示すとされており、dは正しい。","tags":["強心薬","生薬成分","センソ"]},{"id":"R4-38","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":38,"stem":"一般用医薬品の高コレステロール改善薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ビタミンＢ６は、酵素によりフラビンアデニンジヌクレオチドへと活性化され、補酵素として働く。"},{"label":"b","text":"ビタミンＥは、コレステロールからの過酸化脂質の生成を抑えるほか、末梢血管の血行促進作用があるとされる。"},{"label":"c","text":"リノール酸は、コレステロールと結合して、代謝されやすいコレステロールエステルを形成するとされ、肝臓におけるコレステロールの代謝を促す効果を期待して用いられる。"},{"label":"d","text":"大豆油不けん化物（ソイステロール）には、低密度リポタンパク質（ＬＤＬ）等の異化排泄を促進し、リポタンパクリパーゼ活性を高めて、高密度リポタンパク質（ＨＤＬ）産生を高める作用があるとされる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":2,"explanation":"『酵素によりフラビンアデニンジヌクレオチドへと活性化され補酵素として働く』という記述はビタミンB6ではなくビタミンB2（リボフラビン）の説明であるため、aは誤りである。ビタミンEはコレステロールからの過酸化脂質の生成を抑えるほか、末梢血管における血行を促進する作用があるとされ、bは正しい。リノール酸はコレステロールと結合して代謝されやすいコレステロールエステルを形成し、肝臓におけるコレステロールの代謝を促す効果を期待して用いられるとされ、cも正しい。『低密度リポタンパク質の異化排泄を促進しリポタンパクリパーゼ活性を高めて高密度リポタンパク質産生を高める』という記述はパンテチンの説明であり、大豆油不けん化物（ソイステロール）は腸管におけるコレステロールの吸収を抑える働きがあるとされる成分であるため、dは誤りである。","tags":["高コレステロール改善薬","ビタミンE","ソイステロール"]},{"id":"R4-39","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":39,"stem":"ダイエット中の２５歳女性が、最近、疲れやすく血色不良があり、次の成分の一般用医薬品の貧血用薬（鉄製剤）を購入する目的で店舗を訪れた。\n１錠中：\n成分 / 分量 / 内訳\n溶性ピロリン酸第二鉄 / ７９．５ ｍｇ （鉄 １０ｍｇ）\nアスコルビン酸 / ５０ｍｇ\nトコフェロール酢酸エステル / １０ｍｇ\nシアノコバラミン / ５０μｇ\n葉酸 / １ｍｇ\nこの貧血用薬（鉄製剤）に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"この医薬品を服用した後に便が黒くなることがあるが、服用前から便が黒い場合は貧血の原因として消化管内で出血している場合もあるため、服用前の便の状況との対比が必要である。"},{"label":"b","text":"鉄分の吸収は空腹時のほうが高いとされ、消化器系への副作用を軽減するためにも、この医薬品は食前に服用することが望ましい。"},{"label":"c","text":"この医薬品は、緑茶や紅茶で服用すると、鉄の吸収が良くなり、効果が高まることが期待できる。"},{"label":"d","text":"この医薬品には、鉄分のほか、正常な赤血球の形成に働くビタミンが配合されている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":5,"explanation":"鉄製剤を服用すると便が黒くなることがあるが、服用前から便が黒い場合は消化管内出血の可能性もあるため服用前の便の状況との対比が必要とされており、aは正しい。鉄分の吸収は空腹時のほうが高いとされる一方、消化器系への副作用を軽減するためには食後に服用することが望ましいとされているため、設問bの『食前に服用することが望ましい』は誤りである。緑茶や紅茶に含まれるタンニン酸は鉄と反応して鉄の吸収を悪くすることが知られており、服用前後はそれらの摂取を控えることとされているため、設問cの『吸収が良くなり効果が高まる』は誤りである。この製剤にはシアノコバラミン（ビタミンB12）や葉酸など正常な赤血球の形成に働くビタミンが配合されており、dは正しい。","tags":["貧血用薬","鉄製剤","相互作用"]},{"id":"R4-40","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":40,"stem":"６５歳男性で排便に伴う切れ痔の痛みと出血の症状があるため、次の成分の一般用医薬品の外用痔疾用薬を購入する目的で店舗を訪れた。\n１個(１.４ｇ)中：\n成分 / 分量\nリドカイン塩酸塩 / ６０ ｍｇ\nメチルエフェドリン塩酸塩 / ５ ｍｇ\nヒドロコルチゾン酢酸エステル / ５ ｍｇ\nイソプロピルメチルフェノール / ２ ｍｇ\nアラントイン / ２０ ｍｇ\n卵黄油 / １００ ｍｇ\nユーカリ油 / ２ ｍｇ\nこの外用痔疾用薬に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"この医薬品に配合されるリドカイン塩酸塩は、まれに重篤な副作用としてショック（アナフィラキシー）を生じることがある。"},{"label":"b","text":"この医薬品には、交感神経系を刺激する成分が配合されているので、高齢者ではその適否を十分考慮し、使用する場合には慎重な使用がなされることが重要である。"},{"label":"c","text":"この医薬品には、血管収縮作用による止血効果を期待して、アラントインが配合されている。"},{"label":"d","text":"この医薬品には、粘膜表面に不溶性の膜を形成することによる、粘膜の保護・止血を目的として、卵黄油が配合されている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"リドカイン塩酸塩などの局所麻酔成分が配合された坐剤・注入軟膏では、まれに重篤な副作用としてショック（アナフィラキシー）を生じることがあるとされており、aは正しい。メチルエフェドリン塩酸塩のようなアドレナリン作動成分（交感神経系を刺激する成分）が配合された坐剤・注入軟膏では、高齢者は心臓病や高血圧、糖尿病の基礎疾患を有することが多いため、その適否を十分考慮し慎重に使用することが重要とされており、bも正しい。血管収縮作用による止血効果を期待して配合されるのはメチルエフェドリン塩酸塩などのアドレナリン作動成分であり、アラントインは肛門部の創傷の治癒を促す組織修復成分であるため、cは誤りである。卵黄油は粘膜表面に不溶性の膜を形成することによる粘膜の保護・止血を目的として配合される収斂保護止血成分であり、dは正しい。","tags":["外用痔疾用薬","局所麻酔成分","アラントイン"]},{"id":"R4-41","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":41,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを一つ選べ。\n体力中等度以下で、冷え症、貧血気味、神経過敏で、動悸、息切れ、ときにねあせ、頭部の発汗、口の渇きがあるものの更年期障害、血の道症、不眠症、神経症、動悸、息切れ、かぜの後期の症状、気管支炎に適すとされる。まれに重篤な副作用として、間質性肺炎、肝機能障害を生じることが知られている。","statements":[],"options":[{"n":1,"text":"温経湯"},{"n":2,"text":"当帰芍薬散"},{"n":3,"text":"桂枝茯苓丸"},{"n":4,"text":"四物湯"},{"n":5,"text":"柴胡桂枝乾姜湯"}],"answer":5,"explanation":"体力中等度以下で冷え症・神経過敏・動悸・息切れがあり、まれに間質性肺炎や肝機能障害を生じる漢方処方製剤は柴胡桂枝乾姜湯である。同じ体質向けでも、当帰芍薬散や四物湯は冷え症・貧血傾向の婦人薬だが神経過敏やねあせの記述は伴わず、桂枝茯苓丸は比較的体力がある人向け、温経湯はひび・あかぎれを伴う血の道症などが目印になり、いずれも本問の記述とは異なる。したがって正答は5である。","tags":["漢方処方製剤","婦人薬","柴胡桂枝乾姜湯"]},{"id":"R4-42","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":42,"stem":"車で通勤する３０歳女性が、仕事中に咳がひどく、周りに迷惑がかからないように咳を鎮めたいため、次の成分の一般用医薬品の鎮咳去痰薬を購入する目的で店舗を訪れた。\n６０ｍＬ中：\n成分 / 分量\nジヒドロコデインリン酸塩 / ３０ ｍｇ\nグアイフェネシン / １７０ ｍｇ\nクロルフェニラミンマレイン酸塩 / １２ ｍｇ\n無水カフェイン / ６２ ｍｇ\nこの女性に対する登録販売者の対応に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"この医薬品は１２歳未満の小児には使用できないことから、本人が使用することを確認した。"},{"label":"b","text":"授乳中の人は、この医薬品を服用しないか、服用する場合は授乳を避ける必要があると購入者に説明した。"},{"label":"c","text":"この医薬品には、鎮咳成分、去痰成分及び抗ヒスタミン成分が含まれることを説明した。"},{"label":"d","text":"この医薬品を服用した後は、乗物又は機械類の運転操作を避けるよう説明した。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"ジヒドロコデインリン酸塩を含む医薬品は呼吸抑制のおそれから12歳未満の小児には使用できず(a正)、コデイン類は母乳に移行し乳児にモルヒネ中毒を起こした報告があるため授乳中は服用を避けるよう説明する必要がある(b正)。成分表からジヒドロコデインリン酸塩(鎮咳)、グアイフェネシン(去痰)、クロルフェニラミンマレイン酸塩(抗ヒスタミン)が含まれることも事実であり(c正)、抗ヒスタミン成分やコデイン類には眠気を生じるおそれがあるため、乗物や機械類の運転操作を避けるよう説明するのも適切である(d正)。よってa~dすべて正しく、正答は1である。","tags":["鎮咳去痰薬","コデイン類","授乳中"]},{"id":"R4-43","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":43,"stem":"一般用医薬品の鼻炎用内服薬に配合されている成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"プソイドエフェドリン塩酸塩が配合されている場合は、長期間にわたって連用した場合、薬物依存につながるおそれがある。"},{"label":"b","text":"鼻腔における副交感神経の働きを抑えることで、鼻汁の分泌やくしゃみを抑えることを目的として、ベラドンナ総アルカロイドが配合されている場合がある。"},{"label":"c","text":"クレマスチンフマル酸塩が配合されている場合は、抗ヒスタミン作用以外にコリン作用（アセチルコリンに類似した作用）も示すため、使用には注意が必要である。"},{"label":"d","text":"鼻粘膜の血管を拡張させることによって鼻粘膜の充血や腫れを和らげることを目的として、フェニレフリン塩酸塩が配合されている場合がある。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"プソイドエフェドリン塩酸塩は他のアドレナリン作動成分に比べて中枢神経系への作用が強く、長期連用で薬物依存につながるおそれがあるとされ(a正)、ベラドンナ総アルカロイドは副交感神経の働きを抑えて鼻汁分泌やくしゃみを抑える抗コリン成分である(b正)。一方クレマスチンフマル酸塩などの抗ヒスタミン成分が示すのは「抗コリン作用」であって、アセチルコリンに類似した働きをする「コリン作用」ではなく、記述は逆になっている(c誤)。またフェニレフリン塩酸塩などのアドレナリン作動成分は血管を収縮させることで鼻粘膜の充血や腫れを和らげるのであり、拡張ではないため(d誤)、正答は3である。","tags":["鼻炎用内服薬","抗コリン作用","アドレナリン作動成分"]},{"id":"R4-44","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":44,"stem":"一般用医薬品のアレルギー用薬及びアレルギー症状の治療に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"鼻炎用内服薬と鼻炎用点鼻薬は、同じ成分または同種の作用を有する成分が重複することもあり、医薬品の販売等に従事する専門家はそれらが併用されることのないよう注意が必要である。"},{"label":"b","text":"アトピー性皮膚炎が疑われる場合やその診断が確定している場合は、医師の受診を勧めることが重要である。"},{"label":"c","text":"皮膚感染症による湿疹の痒み症状に対しては、アレルギー用薬を使用して症状の緩和を図るのではなく、皮膚感染症そのものへの対処を優先する必要がある。"},{"label":"d","text":"医療機関での検査によりアレルゲンを厳密に特定した場合は、医師の指導の下、減感作療法が行われることがある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"鼻炎用内服薬と鼻炎用点鼻薬は抗ヒスタミン成分やアドレナリン作動成分が重複しやすく、過剰摂取を避けるため併用しないよう注意する必要がある(a正)。アトピー性皮膚炎が疑われる、または確定している場合は自己判断せず医師の受診を勧めることが重要であり(b正)、皮膚感染症による痒みはアレルギー用薬では治せないため感染症そのものへの対処を優先すべきである(c正)。また医療機関でアレルゲンを厳密に特定できた場合には、医師の指導の下で減感作療法が行われることがある(d正)。すべて正しい記述であり、正答は3である。","tags":["アレルギー用薬","受診勧奨","減感作療法"]},{"id":"R4-45","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":45,"stem":"一般用医薬品の鼻炎用点鼻薬及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"クロモグリク酸ナトリウムは、肥満細胞からヒスタミンの遊離を抑えることにより、鼻アレルギー症状を緩和することを目的として、配合されている場合がある。"},{"label":"b","text":"クロルフェニラミンマレイン酸塩は、肥満細胞から遊離したヒスタミンとヒスタミン受容体との結合を妨げることにより、鼻アレルギー症状を緩和することを目的として、配合されている場合がある。"},{"label":"c","text":"テトラヒドロゾリン塩酸塩は、鼻粘膜を通っている血管を拡張させる作用を示すため、鼻粘膜症状の緩和を目的として配合されている場合がある。"},{"label":"d","text":"アドレナリン作動成分を含む鼻炎用点鼻薬は、長期連用は避けることとされており、３日間位使用しても症状の改善がみられない場合には、使用を中止して医療機関を受診するなどの対応が必要である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"クロモグリク酸ナトリウムは肥満細胞からのヒスタミン遊離を抑える抗アレルギー成分であり(a正)、クロルフェニラミンマレイン酸塩は遊離したヒスタミンと受容体の結合を妨げる抗ヒスタミン成分である(b正)。一方テトラヒドロゾリン塩酸塩はアドレナリン作動成分であり、鼻粘膜の血管を収縮させることで充血や腫れを鎮めるのであって、拡張ではないため(c誤)、記述は誤りである。アドレナリン作動成分を含む点鼻薬は過度な使用で逆に鼻づまりが悪化することがあるため長期連用を避け、3日ほど使用しても改善しなければ受診を促す必要がある(d正)。したがって正答は1である。","tags":["鼻炎用点鼻薬","抗アレルギー成分","アドレナリン作動成分"]},{"id":"R4-46","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":46,"stem":"眼科用薬に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品の点眼薬には、緑内障の症状を改善できるものはない。"},{"label":"b","text":"点眼薬は、結膜嚢（結膜で覆われた眼瞼の内側と眼球の間の空間）に適用するものであるが、１滴の薬液量は結膜嚢の容積の５０％程度に設定されている。"},{"label":"c","text":"点眼薬は無菌的に製造されるが、法の規定により必ず防腐剤が配合されている。"},{"label":"d","text":"点眼後は、しばらくまばたきを繰り返して、薬液を結膜嚢内に行き渡らせるとよい。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 誤"}],"answer":5,"explanation":"一般用医薬品の点眼薬に緑内障の症状を改善できるものはなく、目のかすみが緑内障による症状であった場合には注意が必要である(a正)。実際には1滴の薬液量は約50μLとされるのに対し結膜嚢の容積は30μL程度であり、1滴で容積を上回るため「容積の50%程度」という記述は誤りである(b誤)。点眼薬は無菌的に製造されるが、1回使い切りタイプなど防腐剤を含まない製品も存在するため「必ず」配合されているわけではない(c誤)。また点眼後はまばたきを繰り返すのではなく、しばらく眼瞼を閉じ、目頭を押さえると薬液が鼻腔内へ流れ込むのを防げて効果的とされる(d誤)。よって正答は5である。","tags":["点眼薬","結膜嚢","緑内障"]},{"id":"R4-47","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":47,"stem":"一般用医薬品の眼科用薬に配合される成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ネオスチグミンメチル硫酸塩は、毛様体におけるアセチルコリンの働きを抑えることで、目の調節機能を改善する効果を目的として用いられる。"},{"label":"b","text":"ヒスタミンの働きを抑えることにより、目の痒みを和らげることを目的として、ケトチフェンフマル酸塩が配合されている場合がある。"},{"label":"c","text":"パンテノールは、結膜の充血を改善するのに必須なビタミン成分である。"},{"label":"d","text":"イプシロン-アミノカプロン酸は、目の乾きを改善する有効成分として眼科用薬に用いられる。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"ネオスチグミンメチル硫酸塩はコリンエステラーゼの働きを抑えることで毛様体においてアセチルコリンの働きを「助け」目の調節機能を改善する成分であり、「抑える」とする記述は逆であるため誤りである(a誤)。ケトチフェンフマル酸塩はヒスタミンの働きを抑えて目の痒みを和らげる抗ヒスタミン成分であり(b正)、パンテノールは自律神経系の伝達物質の産生に関わり目の調節機能の回復を助ける成分であって、結膜充血の改善に必須なビタミンではないため誤りである(c誤)。イプシロン-アミノカプロン酸は炎症の原因物質の生成を抑えて目の炎症を改善する成分であり、目の乾きを改善するものではないため誤りである(d誤)。よって正答は3である。","tags":["眼科用薬成分","ネオスチグミン","パンテノール"]},{"id":"R4-48","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":48,"stem":"次の成分を含む鎮痛消炎貼付剤に関する記述の正誤について、正しい組合せを一つ選べ。\n１００ｇ中：\n成分 / 分量\nサリチル酸グリコール / ２.０ ｇ\nトコフェロール酢酸エステル / １.０ ｇ\nメントール / １.０ ｇ","statements":[{"label":"a","text":"サリチル酸グリコールは、局所刺激により患部の血行を促し、また末梢の知覚神経に軽い麻痺を起こすことにより、鎮痛作用をもたらす。"},{"label":"b","text":"トコフェロール酢酸エステルは、患部局所の血行を促す目的で配合されているが、血液凝固を抑える働きもあるため、血友病などの出血性血液疾患の診断を受けた人では使用を避ける。"},{"label":"c","text":"メントールは、冷感刺激成分であり、患部の血行を促す効果や鎮痛・鎮痒効果を期待して配合されている。"},{"label":"d","text":"本剤は、打撲や捻挫などの急性の腫れや熱感を伴う症状には適さない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"サリチル酸グリコールは局所刺激により血行を促し、末梢の知覚神経に軽い麻痺を起こして鎮痛作用をもたらす成分であり(a正)、トコフェロール酢酸エステル(ビタミンE)は末梢血管の血行を促す目的で配合される成分だが、血液凝固を抑える働きや血友病患者への使用制限は一般的な貼付剤の説明として結び付けられておらず誤りである(b誤)。メントールは冷感刺激成分であり血行促進や鎮痛・鎮痒効果を期待して配合される(c正)。本剤はサリチル酸グリコールやメントールを含む冷感タイプの貼付剤であり、打撲や捻挫など熱感を伴う急性の腫れにはこうした冷感刺激成分配合の外用鎮痛薬が適すとされているため、「適さない」とする記述は誤りである(d誤)。よって正答は4である。","tags":["鎮痛消炎貼付剤","サリチル酸グリコール","冷感刺激成分"]},{"id":"R4-49","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":49,"stem":"外皮用薬及びその配合成分に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"紫雲膏は、ひび、あかぎれ、しもやけ、うおのめ、あせも、ただれ、外傷、火傷、痔核による疼痛、肛門裂傷、湿疹・皮膚炎に適すとされる。"},{"label":"b","text":"ナファゾリン塩酸塩は、創傷面に浸透して、血管を収縮させることによって創傷面からの出血を抑制する効果がある。"},{"label":"c","text":"サリチル酸は、皮膚の角質層を構成するケラチンを変質させることにより、角質軟化作用を示す。"},{"label":"d","text":"イブプロフェンの誘導体であるイブプロフェンピコノールは、吹き出物に伴う皮膚の発赤や腫れを抑えるほか、鎮痛作用も期待して配合される。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、d"},{"n":4,"text":"c、d"}],"answer":1,"explanation":"紫雲膏はひび、あかぎれ、しもやけ、うおのめ、あせも、ただれ、外傷、火傷、痔核による疼痛、肛門裂傷、湿疹・皮膚炎に適すとされており記述どおりで正しい(a正)。ナファゾリン塩酸塩はアドレナリン作動成分で創傷面に浸透して血管を収縮させ止血効果を示すため正しい(b正)。一方、角質層のケラチンを「変質」させて角質軟化作用を示すのはイオウであり、サリチル酸は角質成分を「溶解」することで角質軟化作用を示すため記述は誤りである(c誤)。イブプロフェンピコノールは吹き出物に伴う皮膚の発赤や腫れを抑える局所作用を期待して配合されるが、外用での鎮痛作用はほとんど期待されないため誤りである(d誤)。したがって正しいものの組合せはa、bで、正答は1である。","tags":["外皮用薬","紫雲膏","サリチル酸"]},{"id":"R4-50","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":50,"stem":"外皮用薬及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"貼付剤は、同じ部位に連続して貼付すると、かぶれ等を生じやすくなる。"},{"label":"b","text":"スプレー剤やエアゾール剤は、できるだけ吸入しないよう、口や鼻から遠ざけ、患部の至近距離から噴霧することが望ましい。"},{"label":"c","text":"一般的に、じゅくじゅくと湿潤している患部には、有効成分の浸透性が高い液剤が適している。"},{"label":"d","text":"温感刺激成分が配合された外皮用薬は、貼付部位をコタツ等の保温器具で温めると強い痛みを生じやすくなるほか、いわゆる低温やけどを引き起こすおそれがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":4,"explanation":"貼付剤を同じ部位に連続して貼付するとかぶれ等を生じやすくなるため正しい(a正)。スプレー剤やエアゾール剤は至近距離から噴霧すると凍傷を起こすことがあるため、患部から十分離して噴霧すべきであり、「至近距離が望ましい」とする記述は誤りである(b誤)。じゅくじゅくと湿潤している患部には軟膏が適しており、浸透性が高く刺激が強い液剤はむしろ皮膚が厚く角質化した部分に適するため、記述は誤りである(c誤)。温感刺激成分を主薬とする貼付剤をコタツ等の保温器具で温めると強い痛みやいわゆる低温やけどを起こすおそれがあり正しい(d正)。よって正答は4である。","tags":["外皮用薬","貼付剤","剤形の選択"]},{"id":"R4-51","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":51,"stem":"毛髪用薬の配合成分とその配合目的としての作用に関する記述の正誤について、正しい組合せを一つ選べ。\n配合成分 / 配合目的としての作用","statements":[{"label":"a","text":"カルプロニウム塩化物 / アセチルコリンに類似した作用により、頭皮の血管拡張と毛根への血行を促進する。"},{"label":"b","text":"エストラジオール安息香酸エステル / 女性ホルモンの作用により、脱毛を抑制する。"},{"label":"c","text":"ヒノキチオール / 頭皮の脂質代謝を高め、余分な皮脂を取り除く。"},{"label":"d","text":"カシュウ / 頭皮の血行を促進し、炎症を抑制する。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":1,"explanation":"カルプロニウム塩化物はアセチルコリンに類似した作用(コリン作用)を示し、頭皮の血管を拡張させて毛根への血行を促進する成分であり正しい(a正)。エストラジオール安息香酸エステルは女性ホルモン成分で、脱毛が男性ホルモンの働きの過剰による面もあるため、女性ホルモンにより脱毛を抑制する目的で配合され正しい(b正)。ただしヒノキチオールは抗菌・抗炎症作用を期待して用いられる成分で、「頭皮の脂質代謝を高め余分な皮脂を取り除く」作用は基原植物の異なるカシュウの説明であり、成分と作用が入れ替わっているため誤りである(c誤)。逆にカシュウの実際の作用は脂質代謝を高め皮脂を取り除くことであって、「血行促進・炎症抑制」という記述はヒノキチオールなど他成分の働きと混同されており誤りである(d誤)。よって正答は1である。","tags":["毛髪用薬","カルプロニウム塩化物","ヒノキチオール"]},{"id":"R4-52","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":52,"stem":"歯槽膿漏薬及び口内炎用薬の配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"セチルピリジニウム塩化物は、歯槽膿漏薬において細菌の繁殖を抑えることを目的として配合されている。"},{"label":"b","text":"イソプロピルメチルフェノールは、炎症を起こした歯周組織からの出血を抑える作用を期待して配合されている。"},{"label":"c","text":"グリチルレチン酸は、歯周組織や口腔粘膜の炎症を和らげることを目的として配合されている。"},{"label":"d","text":"アズレンスルホン酸ナトリウム（水溶性アズレン）は、口内炎時の口腔粘膜の組織修復を促す作用を期待して配合される。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"セチルピリジニウム塩化物は歯肉溝での細菌の繁殖を抑えることを目的とした殺菌消毒成分であり正しい(a正)。歯周組織からの出血を抑える止血成分はカルバゾクロムであり、イソプロピルメチルフェノールは殺菌消毒成分であって出血抑制を目的とするものではないため誤りである(b誤)。グリチルレチン酸は歯周組織や口腔粘膜の炎症を和らげる抗炎症成分であり正しい(c正)。アズレンスルホン酸ナトリウム(水溶性アズレン)は炎症を生じた口腔粘膜の組織修復を促す作用を期待して口内炎用薬に配合されており正しい(d正)。よって正答は5である。","tags":["歯槽膿漏薬","口内炎用薬","止血成分"]},{"id":"R4-53","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":53,"stem":"一般用医薬品の禁煙補助剤に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"禁煙補助剤は、鎮咳去痰薬、鼻炎用薬、痔疾用薬等のアドレナリン作動成分が配合された医薬品と併用すると、これら併用された医薬品の作用を増強させるおそれがある。"},{"label":"b","text":"咀嚼剤は、ゆっくりと断続的に噛むことにより口腔内に放出されたニコチンが、主として腸管から吸収されて循環血液中に移行することにより効果を発揮する。"},{"label":"c","text":"咀嚼剤は、口腔内が酸性になるとニコチンの吸収が低下するため、コーヒーや炭酸飲料を摂取した後しばらくは使用を避ける。"},{"label":"d","text":"禁煙補助剤の使用開始から１～２週間の間に、血中ニコチン濃度の上昇によって生じるニコチン離脱症状（イライラ感、集中困難、落ち着かない等）が現れることがある。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、d"},{"n":4,"text":"c、d"}],"answer":2,"explanation":"ニコチンは交感神経系を興奮させる作用を示すため、アドレナリン作動成分が配合された鎮咳去痰薬・鼻炎用薬・痔疾用薬等と併用すると、それらの作用を増強させるおそれがあり正しい(a正)。咀嚼剤は口腔内で放出されたニコチンが主として「口腔粘膜」から吸収されて循環血液中に移行するのであって、「腸管から吸収」とする記述は誤りである(b誤)。咀嚼剤は口腔内が酸性になるとニコチンの吸収が低下するため、コーヒーや炭酸飲料など口腔内を酸性にする飲食物の摂取後しばらくは使用を避けるべきであり正しい(c正)。ニコチン離脱症状は禁煙により血中ニコチン濃度が「低下」することで生じるのであって「上昇」ではなく、記述は誤りである(d誤)。よって正しい組合せはa、cで、正答は2である。","tags":["禁煙補助剤","咀嚼剤","ニコチン離脱症状"]},{"id":"R4-54","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":54,"stem":"ビタミン主薬製剤に配合されるビタミン成分のうち、次の記述にあてはまる最も適切なものを一つ選べ。\n炭水化物からのエネルギー産生に不可欠な栄養素で、神経の正常な働きを維持する作用や、腸管運動を促進する働きがある。その主薬製剤は、神経痛、筋肉痛・関節痛（肩・腰・肘・膝痛、肩こり、五十肩など）、手足のしびれ、便秘、眼精疲労（慢性的な目の疲れ及びそれに伴う目のかすみ・目の奥の痛み）の症状の緩和、脚気症状の緩和に用いられる。","statements":[],"options":[{"n":1,"text":"ビタミンＡ"},{"n":2,"text":"ビタミンＢ１"},{"n":3,"text":"ビタミンＢ２"},{"n":4,"text":"ビタミンＢ６"},{"n":5,"text":"ビタミンＢ１２"}],"answer":2,"explanation":"炭水化物からのエネルギー産生に不可欠で、神経の正常な働きの維持や腸管運動の促進、脚気症状の緩和に用いられるのはビタミンB1(チアミン塩化物塩酸塩等)である。ビタミンAは視力・皮膚粘膜の維持、ビタミンB2は脂質代謝・皮膚粘膜の健康維持、ビタミンB6はタンパク質代謝や皮膚炎予防、ビタミンB12は赤血球の形成や神経機能の維持が中心であり、いずれも本問の記述(炭水化物代謝・脚気症状)には合致しない。したがって正答は2である。","tags":["ビタミン主薬製剤","ビタミンB1","脚気"]},{"id":"R4-55","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":55,"stem":"滋養強壮保健薬の配合成分及び生薬成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ヘスペリジンは、ビタミン様物質のひとつで、骨格筋に溜まった乳酸の分解を促す等の働きを期待して、滋養強壮保健薬に配合されている場合がある。"},{"label":"b","text":"ハンピは、強壮、血行促進、性機能の亢進等の作用を期待して用いられる。"},{"label":"c","text":"グルクロノラクトンは、肝臓の働きを助け、肝血流を促進する働きがあるとされる。"},{"label":"d","text":"アミノエチルスルホン酸（タウリン）は、筋肉にのみ存在し、細胞の機能が正常に働くために重要な物質である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"ヘスペリジンはビタミン様物質のひとつだが、実際の働きはビタミンCの吸収を助けることであり、「骨格筋の乳酸分解を促す」という記述は誤りである(a誤)。ハンピは強壮、血行促進、強精(性機能の亢進)等の作用を期待して用いられる生薬であり正しい(b正)。グルクロノラクトンは肝臓の働きを助け肝血流を促進する働きがあるとされ正しい(c正)。アミノエチルスルホン酸(タウリン)は筋肉だけでなく脳、心臓、目、神経など体のあらゆる部分に存在する物質であり、「筋肉にのみ存在」とする記述は誤りである(d誤)。よって正答は2である。","tags":["滋養強壮保健薬","ヘスペリジン","タウリン"]},{"id":"R4-56","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":56,"stem":"漢方の特徴・漢方薬使用における基本的な考え方に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"漢方薬とは、古来に中国において発展してきた伝統医学で用いる薬剤全体を概念的に広く表現する時に用いる言葉である。"},{"label":"b","text":"現代では、一般用医薬品の漢方処方製剤として、処方に基づく生薬混合物の浸出液を濃縮して調製された乾燥エキス製剤を散剤等に加工したもののみが、市販されている。"},{"label":"c","text":"漢方薬を使用する場合、漢方独自の病態認識である「証」に基づいて用いることが、有効性及び安全性を確保するために重要である。"},{"label":"d","text":"漢方の病態認識には、虚実、陰陽、気血水、五臓などがある。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"漢方医学は古来に中国から伝わり「日本において発展してきた日本の伝統医学」であり、中国の伝統医学そのものを指す言葉ではないため記述は誤りである(a誤)。現代の漢方処方製剤には乾燥エキス製剤を加工したもの以外にも、軟エキス剤や伝統的な煎剤用の刻み生薬の混合物、丸剤なども存在するため、「のみ」市販されているという記述は誤りである(b誤)。漢方薬の使用では漢方独自の病態認識である「証」に基づいて用いることが有効性・安全性の確保に重要であり正しい(c正)。漢方の病態認識には虚実、陰陽、気血水、五臓などがあり正しい(d正)。よって正答は2である。","tags":["漢方の基本","証","漢方処方製剤の剤形"]},{"id":"R4-57","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":57,"stem":"次の記述にあてはまる漢方処方製剤として、最も適切なものを一つ選べ。\n体力中等度以下で、疲れやすく、汗のかきやすい傾向があるものの肥満に伴う関節の腫れや痛み、むくみ、多汗症、肥満症（筋肉にしまりのない、いわゆる水ぶとり）に適すとされる。","statements":[],"options":[{"n":1,"text":"黄連解毒湯"},{"n":2,"text":"清上防風湯"},{"n":3,"text":"防風通聖散"},{"n":4,"text":"大柴胡湯"},{"n":5,"text":"防已黄耆湯"}],"answer":5,"explanation":"体力中等度以下で疲れやすく汗のかきやすい人の、肥満に伴う関節の腫れ・むくみ・多汗症・いわゆる水ぶとりに適すとされる漢方処方製剤は防已黄耆湯である。防風通聖散は体力充実した人向けの肥満症、大柴胡湯は体力が充実し便秘がちな人向け、黄連解毒湯や清上防風湯はのぼせ・湿疹など別の症状を対象としており、体力が虚弱でむくみを伴うという本問の記述とは合致しない。したがって正答は5である。","tags":["漢方処方製剤","防已黄耆湯","肥満症"]},{"id":"R4-58","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":58,"stem":"消毒薬、殺菌消毒成分及びその取扱い上の注意に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"酸性やアルカリ性の消毒薬が目に入った場合は、中和剤を使って早期に十分な時間（１５分間以上）洗眼するのがよい。"},{"label":"b","text":"サラシ粉などの塩素系殺菌消毒成分は、強い酸化力により、一般細菌類、真菌類に対し殺菌消毒作用を示すが、大部分のウイルスに対する作用はない。"},{"label":"c","text":"エタノールは、微生物のタンパク質の変性作用を有し、結核菌を含む一般細菌類のみならず、真菌類に対しても殺菌消毒作用を示す。"},{"label":"d","text":"クレゾール石ケン液の原液は、結核菌を含む一般細菌類、真菌類、大部分のウイルスに対して殺菌消毒作用を示す。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":3,"explanation":"酸性やアルカリ性の消毒薬が目に入った場合、中和剤を用いると発熱等でかえって刺激・損傷を強めるおそれがあるため中和剤は用いず、流水で十分な時間洗い流すべきであり記述は誤りである(a誤)。サラシ粉などの塩素系殺菌消毒成分は強い酸化力により一般細菌類、真菌類だけでなくウイルス全般に対しても殺菌消毒作用を示すため、「ウイルスに対する作用はない」とする記述は誤りである(b誤)。エタノールは微生物のタンパク質を変性させる作用を持ち、結核菌を含む一般細菌類、真菌類、ウイルスに対して殺菌消毒作用を示すため正しい(c正)。クレゾール石ケン液の原液は結核菌を含む一般細菌類・真菌類には比較的広い殺菌消毒作用を示すが、大部分のウイルスに対する殺菌消毒作用はないため、記述は誤りである(d誤)。よって正答は3である。","tags":["消毒薬","塩素系殺菌消毒成分","エタノール"]},{"id":"R4-59","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":59,"stem":"殺虫剤・忌避剤及びその配合成分に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"忌避剤は、衛生害虫が疾病を媒介するのを防止する効果に加え、虫さされによる痒みなどの症状を和らげる効果を有する。"},{"label":"b","text":"野外など医薬部外品の殺虫剤（蚊取り線香など）の効果が十分には期待できない場所では、忌避剤を用いて蚊による吸血の防止を図る。"},{"label":"c","text":"ディートを含有する忌避剤は、生後６ヶ月未満の乳児については、顔面への使用を避け、１日の使用限度（１日１回）を守って使用する必要がある。"},{"label":"d","text":"スプレー剤となっている忌避剤を顔面に使用する場合は、直接顔面に噴霧せず、いったん手のひらに噴霧してから必要な場所に塗布する等の対応が必要である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":4,"explanation":"忌避剤は衛生害虫が吸血したり病原体を媒介するのを防止するものであって、虫さされによる痒みや腫れなどの症状を和らげる効果はないため記述は誤りである(a誤)。野外など医薬部外品の殺虫剤の効果が十分に期待できない場所では、忌避剤を用いて蚊による吸血の防止を図ることになり正しい(b正)。ディートを含有する忌避剤は生後6か月未満の乳児については使用そのものを避けるべきとされており、「顔面への使用を避け1日1回を守れば使用できる」という記述(実際には生後6か月から12歳未満の子どもに適用される内容)は誤りである(c誤)。スプレー剤の忌避剤を顔面に使用する場合は直接噴霧せず、いったん手のひらに噴霧してから塗布する必要があり正しい(d正)。よって正答は4である。","tags":["忌避剤","ディート","虫さされ"]},{"id":"R4-60","chapter":3,"source":"関西広域連合 令和4年度 登録販売者試験 前半","no":60,"stem":"一般用検査薬の妊娠検査薬に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"妊娠検査薬は、通常、実際に妊娠が成立してから４週目前後の尿中のヒトじゅう絨毛性性腺刺激ホルモン濃度を検出感度としている。"},{"label":"b","text":"一般的な妊娠検査薬は、月経予定日を過ぎて概ね１週目以降に検査することが推奨されている。"},{"label":"c","text":"妊娠検査薬の検出反応は、検出対象となる物質と特異的に反応する抗体や酵素を用いたものであるため、検査操作を行う場所の室温が極端に高温の場合には影響を受けるが、室温が極端に低温の場合には影響を受けにくい。"},{"label":"d","text":"経口避妊薬や更年期障害治療薬などのホルモン剤を使用している人では、妊娠していなくても検査結果が陽性となることがある。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":2,"explanation":"妊娠検査薬は通常、妊娠が成立してから4週目前後の尿中ヒト絨毛性性腺刺激ホルモン(hCG)濃度を検出感度としており正しい(a正)。一般的な妊娠検査薬は月経予定日を過ぎて概ね1週目以降の検査が推奨されており正しい(b正)。検出反応は抗体や酵素を用いた反応であるため、室温が極端に高い場合だけでなく極端に低い場合にも正確な結果が得られないことがあり、「低温では影響を受けにくい」とする記述は誤りである(c誤)。経口避妊薬や更年期障害治療薬などのホルモン剤を使用している人は、妊娠していなくても尿中hCGが検出され陽性となることがあり正しい(d正)。よって正答は2である。","tags":["妊娠検査薬","hCG","検査結果に影響する要因"]},{"id":"R4-81","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":81,"stem":"次の記述は、法第１条の条文である。（　　）の中に入れるべき字句の正しい\n組合せを一つ選べ。なお、複数箇所の（ ａ  ）内は、いずれも同じ字句が入る。\nこの法律は、医薬品、医薬部外品、化粧品、医療機器及び再生医療等製品（以下「医薬品等」という。）の品質、有効性及び安全性の確保並びにこれらの使用による（ ａ  ）上の危害の発生及び拡大の防止のために必要な規制を行うとともに、（ ｂ  ）の規制に関する措置を講ずるほか、医療上特にその（ ｃ  ）が高い医薬品、医療機器及び再生医療等製品の研究開発の促進のために必要な措置を講ずることにより、（ ａ  ）の向上を図ることを目的とする。","statements":[],"options":[{"n":1,"text":"a 保健衛生 / b 指定薬物 / c 必要性"},{"n":2,"text":"a 保健衛生 / b 指定薬物 / c 新規性"},{"n":3,"text":"a 保健衛生 / b 麻薬 / c 必要性"},{"n":4,"text":"a 国民生活 / b 麻薬 / c 新規性"},{"n":5,"text":"a 国民生活 / b 大麻 / c 利便性"}],"answer":1,"explanation":"法第１条は医薬品医療機器等法の目的規定であり、医薬品等の品質・有効性・安全性の確保等により生じうる「保健衛生」上の危害の発生・拡大を防止するための規制を行うことを定めている。同条は指定薬物の規制に関する措置にも触れており、（ｂ）には「指定薬物」が入る。さらに医療上特にその必要性が高い医薬品等の研究開発促進のための措置を講ずるとされており、（ｃ）は「必要性」である。したがって正しい組合せは１。","tags":["法の目的","第1条"]},{"id":"R4-82","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":82,"stem":"登録販売者に関する記述について、誤っているものを一つ選べ。","statements":[],"options":[{"n":1,"text":"店舗販売業者は、その店舗において業務に従事する登録販売者に対し、厚生労働大臣に届出を行った研修実施機関が行う研修を毎年度受講させなければならない。"},{"n":2,"text":"販売従事登録を受けようとする者は、法施行規則に基づく申請書を、販売従事登録を受けようとする者の居住地の都道府県知事に提出しなければならない。"},{"n":3,"text":"登録販売者は、第二類医薬品を購入しようとする者に対し、適正な使用に関する事項に関する正確かつ適切な情報の提供に努めなければならない。"},{"n":4,"text":"登録販売者は、法施行規則第１５９条の８第１項の登録事項に変更を生じたときは、３０日以内に、登録を受けた都道府県知事にその旨を届け出なければならない。"},{"n":5,"text":"登録販売者が、偽りその他不正の手段により販売従事登録を受けたことが判明したとき、都道府県知事はその登録を消除しなければならない。"}],"answer":2,"explanation":"販売従事登録は、居住地ではなく、その者が医薬品の販売等の業務に従事する薬局又は店舗等の所在地の都道府県知事に申請書を提出して受けるものであり、選択肢２の「居住地」は誤りである。研修の毎年度受講義務、第二類医薬品購入者への情報提供の努力義務、登録事項変更の３０日以内の届出義務、不正な手段による登録の消除は、いずれも現行の規則・法に沿った内容である。したがって誤っているものは２。","tags":["登録販売者","販売従事登録"]},{"id":"R4-83","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":83,"stem":"医薬品の定義と範囲に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"「やせ薬」を標榜したもの等、人の身体の構造又は機能に影響を及ぼすことが目的とされている「無承認無許可医薬品」は、医薬品に含まれない。"},{"label":"b","text":"人の疾病の診断に使用されることを目的とする検査薬であって、機械器具等でないものは、医薬品に含まれる。"},{"label":"c","text":"日本薬局方に収められている物は医薬品に該当する。"},{"label":"d","text":"医薬品は、法に基づく医薬品の「製造業」の許可を受けた者でなければ製造をしてはならない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"「やせ薬」等を標榜する無承認無許可医薬品は、身体の構造又は機能への影響を目的とする物として法第２条第１項第３号の医薬品の定義に該当するため取締りの対象となるのであり、「医薬品に含まれない」とするａは誤りである。人の疾病の診断に使用される検査薬で機械器具等でないものは同項第２号により医薬品に含まれるためｂは正しい。日局収載物は同項第１号によりそのまま医薬品に該当するためｃは正しい。医薬品は製造業の許可を受けた者でなければ製造できない（法第１３条第１項）ためｄも正しい。よって正しい組合せは３。","tags":["医薬品の定義","無承認無許可医薬品"]},{"id":"R4-84","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":84,"stem":"毒薬・劇薬に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"毒薬は、単に毒性が強いものだけでなく、薬用量と中毒量が接近しており安全域が狭いため、その取扱いに注意を要するもの等が指定される。"},{"label":"b","text":"現在のところ、毒薬に該当する一般用医薬品はないが、劇薬に該当する一般用医薬品はある。"},{"label":"c","text":"劇薬については、それを収める直接の容器又は被包に、黒地に白枠、白字をもって、当該医薬品の品名及び「劇」の文字が記載されていなければならない。"},{"label":"d","text":"劇薬を、１４歳未満の者その他安全な取扱いに不安のある者に交付することは禁止されている。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"c、d"}],"answer":2,"explanation":"毒薬は毒性の強さだけでなく、薬用量と中毒量が接近して安全域が狭いことなどを理由に指定されるため、ａは正しい。毒薬・劇薬はいずれも要指導医薬品に該当することはあるが、現在のところ一般用医薬品に該当するものは毒薬・劇薬とも存在しないため、劇薬に該当する一般用医薬品があるとするｂは誤りである。劇薬の法定表示は白地に赤枠、赤字であり、黒地に白枠、白字は毒薬の表示であるため、ｃは誤り（両者の表示が入れ替わっている）。毒薬又は劇薬を１４歳未満の者その他安全な取扱いに不安のある者に交付することは法第４７条により禁止されているため、ｄは正しい。よって正しい組合せはａ、ｄ。","tags":["毒薬","劇薬"]},{"id":"R4-85","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":85,"stem":"法第５０条の規定に基づき、要指導医薬品の直接の容器又は直接の被包に記載されていなければならない事項の正誤について、正しい組合せを一つ選べ。ただし、厚生労働省令で定める表示の特例に関する規定は考慮しなくてよい。","statements":[{"label":"a","text":"「要指導医薬品」の文字"},{"label":"b","text":"製造販売業者の氏名又は名称及び住所"},{"label":"c","text":"日本薬局方に収載されている医薬品については「日本薬局方」の文字"},{"label":"d","text":"製造番号又は製造記号"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"法第５０条に基づく要指導医薬品の法定表示事項には、「要指導医薬品」の文字、製造販売業者の氏名又は名称及び住所、日局収載品については「日本薬局方」の文字、製造番号又は製造記号などが含まれており、ａ〜ｄはいずれも現行の法定表示事項に含まれる正しい記述である。したがって正しい組合せは５（すべて正）。","tags":["要指導医薬品","法定表示"]},{"id":"R4-86","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":86,"stem":"医薬部外品に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬部外品には、化粧品的な使用目的を有する製品はない。"},{"label":"b","text":"医薬部外品を製造販売する場合には、厚生労働大臣が基準を定めて指定するものを除き、品目ごとに承認を得る必要がある。"},{"label":"c","text":"一般小売店で医薬部外品を販売する場合は、医薬品の販売業の許可が必要である。"},{"label":"d","text":"衛生害虫類の防除のために使用される製品群については、直接の容器又は直接の被包に「指定医薬部外品」と識別表示がなされている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":3,"explanation":"医薬部外品には薬用化粧品・薬用石けん・薬用歯みがき類のように化粧品的な使用目的を有する製品もあるため、「化粧品的な使用目的を有する製品はない」とするａは誤り。医薬部外品は厚生労働大臣が基準を定めて指定するものを除き品目ごとの承認が必要であるためｂは正しい。医薬部外品の販売等には医薬品のような販売業許可は不要で一般小売店でも販売できるため、許可が必要とするｃは誤り。衛生害虫類の防除用製品群には「防除用医薬部外品」の表示がなされるのであり、「指定医薬部外品」はかつて医薬品であったものが医薬部外品に移行した製品群の表示であるため、ｄも誤り。よって正しい組合せは３。","tags":["医薬部外品"]},{"id":"R4-87","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":87,"stem":"化粧品に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"人の身体の構造若しくは機能に影響を及ぼすことを目的としているものは化粧品に含まれない。"},{"label":"b","text":"化粧品は、「人の身体を清潔にし、美化し、魅力を増し、容貌を変え、又は皮膚若しくは毛髪を健やかに保つ」の範囲内においてのみ効能効果を表示・標榜することができる。"},{"label":"c","text":"法第６１条の規定に基づき、化粧品の直接の容器又は直接の被包には、「化粧品」の文字の表示が義務付けられている。"},{"label":"d","text":"化粧品の成分本質（原材料）については、原則として医薬品の成分を配合してはならないこととされており、配合が認められる場合にあっても、添加物として使用されているなど、薬理作用が期待できない量以下に制限されている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"人の身体の構造・機能に影響を及ぼすことを目的とするものは医薬品に該当し化粧品には含まれないため、ａは正しい。化粧品はその定義（人の身体を清潔にし、美化し、魅力を増し、容貌を変え、又は皮膚若しくは毛髪を健やかに保つ）の範囲内でのみ効能効果を表示・標榜できるため、ｂも正しい。法第６１条が定める化粧品の法定表示事項に「化粧品」の文字の表示は含まれていないため、ｃは誤り。化粧品の成分本質については、原則として医薬品的成分の配合が制限され、配合が認められる場合も薬理作用が期待できない量以下に限られるため、ｄは正しい。よって正しい組合せは２。","tags":["化粧品"]},{"id":"R4-88","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":88,"stem":"食品及び「医薬品の範囲に関する基準」（昭和４６年６月１日付け薬発第４７６号厚生省薬務局長通知「無承認無許可医薬品の指導取締りについて」の別紙）に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"食品安全基本法や食品衛生法では、食品とは、医薬品、医薬部外品及び再生医療等製品以外のすべての飲食物をいう。"},{"label":"b","text":"食品として販売されている製品であっても、その成分本質、効能効果の標榜内容等に照らして医薬品とみなされる場合には、無承認無許可医薬品として、法に基づく取締りの対象となる。"},{"label":"c","text":"調理のために使用方法、使用量等を定めている場合を除き、服用時期、服用間隔、服用量等の医薬品的な用法用量の記載は、医薬品に該当するとみなされる要素となる。"},{"label":"d","text":"錠剤、丸剤、カプセル剤、顆粒剤、散剤等の形状については、食品である旨が明示されている場合に限り、当該形状のみをもって医薬品への該当性の判断がなされることはない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 正 / b 正 / c 正 / d 正"}],"answer":5,"explanation":"食品安全基本法・食品衛生法上、食品とは医薬品、医薬部外品及び再生医療等製品以外のすべての飲食物をいうため、ａは正しい。食品として販売されていても成分本質や効能効果の標榜内容等から医薬品とみなされる場合には無承認無許可医薬品として取締りの対象となるため、ｂも正しい。調理のための使用方法等を定めている場合を除き、服用時期・服用間隔・服用量等の医薬品的な用法用量の記載は医薬品該当性の判断要素となるため、ｃも正しい。錠剤等の医薬品的な形状も、食品である旨が明示されていればその形状のみをもって医薬品への該当性が判断されることはないため、ｄも正しい。よって正しい組合せは５。","tags":["食品","無承認無許可医薬品"]},{"id":"R4-89","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":89,"stem":"保健機能食品等の食品に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"栄養機能食品は、栄養成分の機能表示と併せて、当該栄養成分を摂取する上での注意事項を適正に表示することが求められている。"},{"label":"b","text":"機能性表示食品は、事業者の責任において、科学的根拠に基づいた機能性を表示し、販売前に安全性及び機能性の根拠に関する情報などについて、厚生労働大臣へ届け出られたものである。"},{"label":"c","text":"特別用途食品（特定保健用食品を除く。）は、乳児、幼児、妊産婦又は病者の発育又は健康の保持若しくは回復の用に供することが適当な旨を医学的・栄養学的表現で記載し、かつ、用途を限定したものである。"},{"label":"d","text":"保健機能食品は、あくまで食生活を通じた健康の保持増進を目的として摂取されるものであり、食品として販売に供されるものについて、健康の保持増進効果等につき虚偽又は誇大な表示をすることは禁止されている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"栄養機能食品は栄養成分の機能表示に加え、摂取をする上での注意事項も適正に表示することが求められているため、ａは正しい。機能性表示食品は、事業者の責任において科学的根拠に基づく機能性を表示し、販売前に安全性・機能性の根拠情報等を消費者庁長官へ届け出るものであり、厚生労働大臣ではないため、ｂは誤り。特別用途食品（特定保健用食品を除く）は乳児・幼児・妊産婦・病者の発育や健康保持等に適する旨を医学的・栄養学的表現で記載し用途を限定したものであるため、ｃは正しい。保健機能食品を含め食品として販売されるものについて健康の保持増進効果等の虚偽誇大表示は禁止されているため、ｄも正しい。よって正しい組合せは１。","tags":["保健機能食品","機能性表示食品"]},{"id":"R4-90","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":90,"stem":"薬局に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"薬局において、一般の生活者に対して一般用医薬品の販売を行う場合には、薬局の開設許可と併せて、医薬品の店舗販売業の許可を受ける必要がある。"},{"label":"b","text":"薬局で薬事に関する実務に従事する薬剤師を管理者とすることができない場合には、その薬局において一般用医薬品の販売又は授与に関する業務に従事する登録販売者を管理者にすることができる。"},{"label":"c","text":"薬局の管理者は、保健衛生上支障を生ずるおそれがないよう、その薬局に勤務するその他の従業者を監督するなど、薬局の業務につき、必要な注意をしなければならない。"},{"label":"d","text":"健康サポート薬局とは、患者が継続して利用するために必要な機能及び個人の主体的な健康の保持増進への取組を積極的に支援する機能を有する薬局をいう。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"薬局において一般用医薬品を販売する場合、薬局の開設許可のみで足り、別途店舗販売業の許可を受ける必要はないため、ａは誤り。薬局の管理者は法第７条により薬剤師でなければならず、薬剤師が管理者になれない場合に登録販売者を管理者とする規定は存在しないため、ｂも誤り。薬局の管理者は保健衛生上支障が生じないよう他の従業者を監督する等の必要な注意義務を負うため、ｃは正しい。健康サポート薬局は、患者の継続的な利用支援機能と、個人の主体的な健康の保持増進への取組を積極的に支援する機能を有する薬局と定義されているため、ｄも正しい。よって正しい組合せは４。","tags":["薬局","健康サポート薬局"]},{"id":"R4-91","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":91,"stem":"店舗販売業に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"店舗管理者は、その店舗の所在地の都道府県知事（その店舗の所在地が保健所を設置する市又は特別区の区域にある場合においては、市長又は区長。）の許可を受けた場合を除き、その店舗以外の場所で業として店舗の管理その他薬事に関する実務に従事する者であってはならない。"},{"label":"b","text":"店舗販売業では、特定の購入者の求めに応じて、医薬品の包装を開封して分割販売することができる。"},{"label":"c","text":"店舗管理者は、保健衛生上支障を生ずるおそれがないように、その店舗の業務につき、店舗販売業者に対し、必要な意見を書面により述べなければならない。"},{"label":"d","text":"指定第二類医薬品を陳列する陳列設備から１メートルの範囲に、医薬品を購入しようとする者等が侵入することができないよう必要な措置が取られている場合、「情報提供を行うための設備」から７メートル以内の範囲に陳列する必要はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":3,"explanation":"店舗管理者は、都道府県知事等の許可を受けた場合を除き、その店舗以外の場所で薬事に関する実務に従事してはならないため、ａは正しい。店舗販売業では購入者の求めに応じて医薬品の包装を開封して分割販売することが認められているため、ｂも正しい。店舗管理者は保健衛生上必要な意見を書面で店舗販売業者に述べなければならないため、ｃも正しい。指定第二類医薬品の陳列設備からの進入防止措置の距離は現行規則でも１メートルではなく１．２メートル以内とされており、ｄは数値が誤っているため誤り。よって正しい組合せは３。","tags":["店舗販売業","陳列"]},{"id":"R4-92","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":92,"stem":"配置販売業に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"配置販売業者又はその配置員は、医薬品の配置販売に従事しようとするときは、配置販売業者の氏名及び住所、配置販売に従事する者の氏名及び住所並びに区域及びその期間を、あらかじめ、配置販売に従事しようとする区域の都道府県知事に届け出なければならない。"},{"label":"b","text":"配置販売業者は、薬剤師が区域管理者として配置販売に従事していれば、すべての一般用医薬品を販売することができる。"},{"label":"c","text":"配置販売業者は、購入者の求めに応じて医薬品の包装を開封して分割販売することができる。"},{"label":"d","text":"配置販売業者又はその配置員は、その住所地の都道府県知事が発行する身分証明書の交付を受け、かつ、これを携帯しなければ、医薬品の配置販売に従事してはならない。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"配置販売業者・配置員は、配置販売に従事する前に、氏名・住所・区域・期間等をあらかじめ配置する区域の都道府県知事に届け出なければならないため、ａは正しい。配置販売業で扱えるのは経年変化が起こりにくいこと等の配置販売品目基準に適合する医薬品に限られ、区域管理者が薬剤師であってもすべての一般用医薬品を販売できるわけではないため、ｂは誤り。配置販売業では医薬品を開封して分割販売することは法第３７条により禁止されているため、ｃも誤り。配置販売業者・配置員は住所地の都道府県知事発行の身分証明書の交付を受け携帯しなければならないため、ｄは正しい。よって正しい組合せは２。","tags":["配置販売業"]},{"id":"R4-93","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":93,"stem":"薬局開設者が行う、要指導医薬品及び一般用医薬品のリスク区分に応じた情報提供に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"要指導医薬品を使用しようとする者が、薬剤服用歴その他の情報を一元的かつ経時的に管理できる手帳（以下「お薬手帳」という。）を所持しない場合はその所持を勧奨し、所持する場合は、必要に応じてお薬手帳を活用した情報の提供及び指導を行わせることとされている。"},{"label":"b","text":"第一類医薬品を購入しようとする者から説明不要の意思表明があり、その医薬品が適正に使用されると薬剤師が判断した場合であっても、情報を提供せずに販売することはできない。"},{"label":"c","text":"指定第二類医薬品を販売する場合には、その医薬品を購入しようとする者が、禁忌事項を確認すること及び当該医薬品の使用について薬剤師又は登録販売者に相談することを勧める旨を、確実に認識できるようにするために必要な措置を講じなければならない。"},{"label":"d","text":"第三類医薬品を購入した者から質問等がない場合であっても、薬剤師又は登録販売者に必要な情報を提供させることが望ましいが、法律上の規定ではない。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"要指導医薬品を使用しようとする者に対しては、お薬手帳を所持しない場合はその所持を勧め、所持する場合は必要に応じてお薬手帳を活用した情報提供・指導を行わせることとされており、ａは正しい。第一類医薬品は、購入者から説明不要の意思表明があり、薬剤師がその適正使用を確認できると判断した場合には情報提供義務の規定（法第３６条の１０第１項）が適用されないため、「情報を提供せずに販売することはできない」とするｂは誤り。指定第二類医薬品については、禁忌事項の確認や薬剤師・登録販売者への相談を勧める旨を購入者が確実に認識できるようにする措置が義務付けられているため、ｃは正しい。第三類医薬品については、質問がなくても情報提供を行うことが望ましいとされているが、法律上の提供義務ではないため、ｄも正しい。よって正しい組合せは２。","tags":["情報提供","リスク区分"]},{"id":"R4-95","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":95,"stem":"店舗販売業者が、卸売販売業者から初めて医薬品を購入したときに、法施行規則第１４６条の規定に基づき書面に記載しなければならない事項について、誤っているものを一つ選べ。","statements":[],"options":[{"n":1,"text":"品名"},{"n":2,"text":"数量"},{"n":3,"text":"購入の年月日"},{"n":4,"text":"医薬品のリスク区分"},{"n":5,"text":"卸売販売業者の氏名又は名称、住所又は所在地及び電話番号その他の連絡先"}],"answer":4,"explanation":"店舗販売業者が卸売販売業者から初めて医薬品を購入した際に施行規則第１４６条に基づき書面に記載すべき事項は、品名、数量、購入等の年月日、相手方（卸売販売業者）の氏名又は名称・住所又は所在地及び電話番号その他の連絡先等であり、「医薬品のリスク区分」はこの記載事項には含まれていない。したがって誤っているものは４。","tags":["医薬品の購入記録","施行規則146条"]},{"id":"R4-97","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":97,"stem":"医薬品の広告に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"医師は未承認の医薬品の名称に関する広告を行うことが禁止されていない。"},{"label":"b","text":"一般用医薬品の販売広告には、店舗販売業において販売促進のため用いられるチラシ、ダイレクトメール（電子メールを含む）も含まれる。"},{"label":"c","text":"医薬品の承認されていない効果を広告する場合、明示的でない限り、虚偽又は誇大広告には該当しない。"},{"label":"d","text":"医薬品の広告に該当するか否かについては、(１)顧客を誘引する意図が明確であること、(２)特定の医薬品の商品名が明らかにされていること、(３)一般人が認知できる状態であること、のいずれも満たす場合には、広告に該当するものと判断されている。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、d"},{"n":4,"text":"c、d"}],"answer":3,"explanation":"医薬品の広告規制（法第６６条・第６８条）は依頼主だけでなくそれに関与するすべての者が対象となるため、医師であっても未承認医薬品の名称に関する広告は禁止されており、ａは誤り。一般用医薬品の販売広告には、店舗販売業で販売促進に用いられるチラシやダイレクトメール（電子メールを含む）も含まれるため、ｂは正しい。虚偽誇大広告の禁止（法第６６条）は明示的・暗示的を問わず適用されるため、「明示的でない限り該当しない」とするｃは誤り。広告に該当するか否かは、顧客誘引の意図が明確であること、特定医薬品の商品名が明らかにされていること、一般人が認知できる状態であることの３要件をいずれも満たす場合に広告と判断されるため、ｄは正しい。よって正しいものの組合せはｂ、ｄ。","tags":["医薬品の広告"]},{"id":"R4-98","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":98,"stem":"医薬品等適正広告基準に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"一般用医薬品について、同じ有効成分を含有する医療用医薬品の効能効果をそのまま標榜する広告は、承認されている内容を正確に反映した広告とはいえない。"},{"label":"b","text":"チラシやパンフレット等の同一紙面に、医薬品と、食品、化粧品、雑貨類等の医薬品ではない製品を併せて掲載することは認められていない。"},{"label":"c","text":"医療機関が推薦している旨の広告を行うことは、仮に事実であったとしても、原則として不適当とされている。"},{"label":"d","text":"医薬品の広告については、生命関連製品としての信用や品位が損なわれることのないよう、節度ある適切な内容や表現が求められる。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"一般用医薬品について同じ有効成分の医療用医薬品の効能効果をそのまま標榜する広告は、承認内容を正確に反映したものとはいえないため、ａは正しい。チラシ等の同一紙面に医薬品と食品・化粧品・雑貨類等を併せて掲載すること自体は問題なく、誤認を与える場合に規制対象となるにすぎないため、「認められていない」とするｂは誤り。医療機関等が推薦している旨の広告は、仮に事実であっても生活者への影響の大きさから原則として不適当とされるため、ｃは正しい。医薬品の広告は生命関連製品としての信用・品位を損なわないよう節度ある内容・表現が求められるため、ｄも正しい。よって正しい組合せは１。","tags":["医薬品等適正広告基準"]},{"id":"R4-99","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":99,"stem":"医薬品の販売方法に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の過度の消費や乱用を助長するおそれがある販売方法については、保健衛生上の観点から必要な監視指導が行われている。"},{"label":"b","text":"購入者の利便性のため医薬品と他の物品を組み合わせて販売又は授与する場合は、体温計、ガーゼ、包帯、脱脂綿等、組み合わせる医薬品の用途に対して補助的な目的を果たす範囲においてのみ認められる。"},{"label":"c","text":"薬局及び店舗販売業においては、許可を受けた薬局又は店舗以外の場所に医薬品を貯蔵し、そこを拠点として販売等に供することも認められている。"},{"label":"d","text":"医薬品の販売等に従事する専門家は、医薬品を多量に購入する者等に対して、積極的に事情を尋ねるなど慎重に対処し、状況によっては販売を差し控えるべきである。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"医薬品の過度の消費や乱用を助長するおそれのある販売方法には保健衛生上の観点から必要な監視指導が行われているため、ａは正しい。医薬品と他の物品を組み合わせて販売する場合は、体温計・ガーゼ・包帯・脱脂綿等、組み合わせる医薬品の用途に対して補助的な目的を果たす範囲内でのみ認められているため、ｂも正しい。許可を受けた薬局・店舗以外の場所に医薬品を貯蔵し、そこを拠点として販売等に供することは店舗による販売等に当たらず認められていないため、「認められている」とするｃは誤り。医薬品を多量に購入しようとする者等に対しては、積極的に事情を尋ねるなど慎重に対処し、状況によっては販売を差し控えるべきとされているため、ｄは正しい。よって正しい組合せは５。","tags":["販売方法"]},{"id":"R4-100","chapter":4,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":100,"stem":"法に基づく行政庁の監視指導及び処分に関する記述の正誤について、正しい組合せを一つ選べ。なお、本問において「都道府県知事」とは、「都道府県知事（薬局又は店舗販売業にあっては、その薬局又は店舗の所在地が保健所設置市又は特別区の区域にある場合においては、市長又は区長。）」とする。","statements":[{"label":"a","text":"都道府県知事は、薬事監視員に、薬局開設者又は医薬品の販売業者が医薬品を業務上取り扱う場所に立ち入り、無承認無許可医薬品の疑いのある物品を、試験のために必要な最少分量に限り、収去させることができる。"},{"label":"b","text":"薬局又は店舗において従事する薬剤師及び登録販売者が、薬事監視員の質問に対して正当な理由なく答弁しなかった場合には、罰則の規定が設けられているが、薬剤師及び登録販売者ではない従業員には罰則の規定は適用されない。"},{"label":"c","text":"都道府県知事は、店舗管理者が管理者として不適当であると認めるときは、その店舗販売業者に対して、その変更を命ずることができる。"},{"label":"d","text":"都道府県知事は、緊急の必要があるときは、薬事監視員に、不正表示医薬品、不良医薬品、無承認無許可医薬品等を廃棄させることができる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":5,"explanation":"都道府県知事等は薬事監視員に、無承認無許可医薬品の疑いのある物品を試験に必要な最少分量に限り収去させることができる（法第６９条第２項）ため、ａは正しい。薬事監視員の質問に対し正当な理由なく答弁しない場合等の罰則（法第８７条第１３号）は、薬剤師や登録販売者を含む従業員全般に適用されるものであり、それ以外の従業員が除外されるわけではないため、ｂは誤り。都道府県知事等は店舗管理者が管理者として不適当であると認めるときは店舗販売業者にその変更を命ずることができる（法第７３条）ため、ｃは正しい。都道府県知事等は緊急の必要があるときは薬事監視員に不正表示医薬品・不良医薬品・無承認無許可医薬品等を廃棄させることができる（法第７０条第３項）ため、ｄも正しい。よって正しい組合せは５。","tags":["行政処分","監視指導"]},{"id":"R4-101","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":101,"stem":"医薬品の適正使用情報に関する記述について、正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"要指導医薬品は、医薬関係者の判断に従い、一般の生活者が使用するものである。"},{"label":"b","text":"添付文書等の適正使用情報は、一般の生活者に理解しやすい平易な表現でなされているが、その内容は一般的・網羅的なものとならざるをえない。"},{"label":"c","text":"一般用検査薬では確定診断ができるので、検査結果が陽性である場合の医師の診断を受ける必要性については、添付文書等に記載されていない。"},{"label":"d","text":"一般用医薬品の中には、添付文書の形ではなく、法第５２条第２項に基づく「用法、用量その他使用及び取扱い上の必要な注意」等の記載を、外部の容器若しくは被包に行っている場合がある。"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、c"},{"n":3,"text":"b、d"},{"n":4,"text":"c、d"}],"answer":3,"explanation":"要指導医薬品・一般用医薬品は、薬剤師その他の医薬関係者から提供された情報に基づき、需要者自身の判断で選択・使用するものと定義されており、aのように「医薬関係者の判断に従い」使用するという説明は誤りです。添付文書等の適正使用情報は、多様な使用者に対応できるよう平易な表現で書かれる一方、内容は一般的・網羅的にならざるを得ず、bは正しい記述です。一般用検査薬は検査結果のみで確定診断はできないため、陽性の場合には医師の受診を促す記載が添付文書等に必要であり、cは誤りです。一般用医薬品の中には添付文書という形をとらず、法第52条第2項に基づく必要な注意事項を外箱等に記載しているものがあるため、dは正しく、正しい組合せはbとdです。","tags":["添付文書","適正使用情報","要指導医薬品"]},{"id":"R4-102","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":102,"stem":"一般用医薬品（一般用検査薬を除く）の添付文書等に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"添付文書は、開封時だけではなく、使用する人やその時の状態等によって留意されるべき事項が異なってくるため、必要なときにいつでも取り出して読むことができるように保管される必要がある。"},{"label":"b","text":"販売時に専門家から直接情報提供を受けた購入者以外の家族がその医薬品を使用する際には、添付文書に目を通す必要はない。"},{"label":"c","text":"販売名の上部に、「使用にあたって、この説明文書を必ず読むこと。また、必要なときに読めるよう大切に保存すること。」等の文言が記載されている。"},{"label":"d","text":"製造販売業者において購入者等からの相談に応じるため、窓口担当部門の名称、電話番号、受付時間等が記載されている。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"添付文書は開封時に一度目を通せば十分というものではなく、使用者や状態によって留意点が変わるため、必要なときにいつでも取り出して読めるよう保管する必要があり、aは正しい記述です。専門家から直接説明を受けた購入者以外の家族が使用する場合こそ添付文書で注意事項を確認することが特に重要であり、bの「目を通す必要はない」という記述は誤りです。販売名の上部には「使用にあたって…必ず読むこと」等の文言が実際に記載されており、cは正しい記述です。製造販売業者が相談に応じるための窓口担当部門の名称・電話番号・受付時間等も記載されるため、dも正しく、正しい組合せは正・誤・正・正です。","tags":["添付文書","保管"]},{"id":"R4-103","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":103,"stem":"一般用医薬品の添付文書等の「使用上の注意」に関する記述について、誤っているものを一つ選べ。","statements":[],"options":[{"n":1,"text":"使用上の注意は、「してはいけないこと」、「相談すること」及び「その他の注意」から構成され、適正使用のために重要と考えられる項目が前段に記載されている。"},{"n":2,"text":"漢方処方製剤では、ある程度の期間継続して使用されることにより効果が得られるとされているものが多いが、長期連用する場合には、専門家に相談する旨が記載されている（本記載がない漢方処方製剤は、短期の使用に限られるもの）。"},{"n":3,"text":"局所に適用する医薬品は、患部の状態によっては症状を悪化させたり、誤った部位に使用すると副作用を生じたりするおそれがあるので、「次の部位には使用しないこと」として、使用を避けるべき患部の状態や適用部位等が簡潔に記載されている。"},{"n":4,"text":"医療用医薬品と併用すると、作用の増強、副作用等のリスクの増大が予測されるため、「医師（又は歯科医師）の治療を受けている人」は、「次の人は使用（服用）しないこと」の項に記載されている。"},{"n":5,"text":"眠気や異常なまぶしさ等を引き起こす成分が配合されている内服用医薬品では、服用すると重大な事故につながるおそれがあるため、「服用後、乗物又は機械類の運転操作をしないこと」と記載されている。"}],"answer":4,"explanation":"使用上の注意は「してはいけないこと」「相談すること」「その他の注意」の順で構成され、重要度の高い項目が前段に記載されるため、1は正しい説明です。漢方処方製剤は長期連用時に専門家への相談を促す記載があり、その記載がないものは短期使用に限られるとする説明も手引きの記述どおりで、2は正しい記述です。局所適用医薬品について使用を避けるべき患部の状態や部位を「次の部位には使用しないこと」として簡潔に記載する点も正しく、3は誤りではありません。医療用医薬品との併用により作用増強等が予測される「医師（又は歯科医師）の治療を受けている人」は、実際には「次の人は使用（服用）しないこと」ではなく「相談すること」の項目に記載されるため、4が誤った説明であり、これが正答です。","tags":["使用上の注意","相談すること"]},{"id":"R4-104","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":104,"stem":"一般用医薬品の保管及び取扱い上の注意に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品は、適切な保管がなされないと化学変化や雑菌の繁殖等を生じることがあるため、特に開封後の散剤は、冷蔵庫内に保管されるのが望ましい。"},{"label":"b","text":"医薬品は、容器を移し替えると、誤用の原因になったり、品質が変わったりすることがあるので、旅行等で携行する場合であっても、他の容器に入れ替えることは適当ではない。"},{"label":"c","text":"点眼薬は、開封後長期間保存すると変質するおそれがあるため、家族間で共用し、できる限り早目に使い切ることが望ましい。"},{"label":"d","text":"購入後すぐ開封しない場合等に、添付文書を見なくても適切な保管がなされるよう、その医薬品の容器や包装にも、保管に関する注意事項が記載されている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"散剤は他の剤形と異なり、冷蔵庫から取り出す際の室温との温度差で湿気を帯びて品質が劣化しやすいため、冷蔵庫内保管はむしろ不適当とされ、aは誤りです。医薬品を旅行等に携行する際に別容器へ移し替えると、誤用や品質劣化の原因になるため避けるべきであり、bは正しい記述です。点眼薬は複数人で使い回すと薬液の細菌汚染により感染が広がるおそれがあるため、家族間であっても共用は避けるべきとされ、cの「共用が望ましい」は誤りです。購入後すぐに開封しない場合等に備え、添付文書を見なくても適切に保管できるよう容器や包装にも保管上の注意事項が記載されており、dは正しく、正しい組合せは誤・正・誤・正です。","tags":["保管","取扱い上の注意"]},{"id":"R4-105","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":105,"stem":"安全性速報に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"対象となるのは医薬品のみであり、医療機器や再生医療等製品は対象にならない。"},{"label":"b","text":"一般的な使用上の注意の改訂情報よりも迅速な注意喚起や、適正使用のための対応の注意喚起が必要な場合に作成される。"},{"label":"c","text":"厚生労働省からの命令、指示、製造販売業者の自主決定等に基づいて作成される。"},{"label":"d","text":"Ａ４サイズの黄色地の印刷物で、イエローレターとも呼ばれる。"}],"options":[{"n":1,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 正"}],"answer":1,"explanation":"安全性速報は医薬品だけでなく医療機器や再生医療等製品も対象となるため、aの「医薬品のみ」という説明は誤りです。一般的な使用上の注意の改訂情報よりも迅速な注意喚起が必要な場合に作成される点はbの記述のとおりで正しい内容です。厚生労働省からの命令・指示や製造販売業者の自主決定等に基づいて作成される点もcの記述と一致します。安全性速報はA4サイズの青色地の印刷物で「ブルーレター」と呼ばれ、黄色地で「イエローレター」と呼ばれるのは緊急安全性情報であるため、dは誤りで、正しい組合せは誤・正・正・誤です。","tags":["安全性速報","ブルーレター"]},{"id":"R4-106","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":106,"stem":"医薬品等の安全性情報等に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品・医療機器等安全性情報の対象となる医薬品は、医療用医薬品のほかに、一般用医薬品も含む。"},{"label":"b","text":"医薬品・医療機器等安全性情報の内容として、重要な副作用等に関する使用上の注意を改訂した場合は、改訂の根拠となった症例の概要も紹介されている。"},{"label":"c","text":"（独）医薬品医療機器総合機構ホームページには、緊急安全性情報は掲載されていない。"},{"label":"d","text":"（独）医薬品医療機器総合機構が配信する医薬品医療機器情報配信サービス（ＰＭＤＡメディナビ）は、医薬関係者のみが利用可能である。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 誤 / b 正 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"医薬品・医療機器等安全性情報は医療用医薬品だけでなく一般用医薬品も対象としており、aは正しい記述です。重要な副作用等に関する使用上の注意の改訂があった場合には、改訂の根拠となった症例の概要も紹介されるため、bも正しい内容です。総合機構（PMDA）のホームページには、厚生労働省が製造販売業者等に指示した緊急安全性情報も掲載されているため、cの「掲載されていない」は誤りです。PMDAメディナビは医薬関係者に限らず誰でも登録・利用できる配信サービスであるため、dの「医薬関係者のみ利用可能」も誤りで、正しい組合せは正・正・誤・誤です。","tags":["医薬品医療機器等安全性情報","PMDAメディナビ"]},{"id":"R4-107","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":107,"stem":"企業からの副作用等の報告制度に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"企業からの法第６８条の１０第１項の規定に基づく副作用等の報告は、義務ではなく自主的な報告である。"},{"label":"b","text":"医療用医薬品で使用されていた有効成分を一般用医薬品で初めて配合したものについては、承認条件として承認後の一定期間（概ね８年）、安全性に関する調査及び調査結果の報告が求められている。"},{"label":"c","text":"登録販売者を含む医薬関係者は、製造販売業者等が行う情報収集に協力するよう努めなければならない。"},{"label":"d","text":"製造販売業者は、医薬品によるものと疑われる副作用症例のうち、使用上の注意から予測できないものでも、非重篤の国内事例であれば、法第６８条の１０第１項の規定に基づく報告義務はない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":2,"explanation":"製造販売業者による副作用等の報告は法第68条の10第1項に基づく法的な義務であり、任意の自主的な報告ではないため、aは誤りです。医療用医薬品で使用されていた有効成分を一般用医薬品（スイッチOTC）で初めて配合した医薬品は、承認条件として承認後概ね3年間の安全性調査・報告が求められるものであり、「概ね8年」とする年数のbは誤りです（概ね8年は既存の医薬品と明らかに異なる有効成分を配合した医薬品の再審査期間です）。登録販売者を含む医薬関係者が製造販売業者等の情報収集に協力するよう努めることは法律上の努力義務として定められており、cは正しい記述です。使用上の注意から予測できない副作用は、非重篤な国内事例であっても定期報告の対象となり報告義務が免除されるわけではないため、dも誤りで、正しい組合せは誤・誤・正・誤です。","tags":["副作用等報告制度","再審査"]},{"id":"R4-108","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":108,"stem":"「医薬品・医療機器等安全性情報報告制度」に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"本制度は、医薬品の使用、販売等に携わり、副作用等が疑われる事例に直接に接する医薬関係者からの情報を広く収集することによって、医薬品の安全対策のより着実な実施を図ることを目的としている。"},{"label":"b","text":"医薬品等によるものと疑われる、身体の変調・不調、日常生活に支障を来す程度の健康被害（死亡を含む。）について報告が求められている。"},{"label":"c","text":"健康被害と医薬品との因果関係が必ずしも明確でない場合であっても、報告の対象となり得る。"},{"label":"d","text":"医薬品による副作用が疑われる場合、報告の必要性を認めた日から起算して３０日以内に報告することが定められている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":3,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":4,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":1,"explanation":"本制度は、副作用等が疑われる事例に直接接する医薬関係者から情報を広く収集し、医薬品の安全対策の実施につなげることを目的としており、aは正しい記述です。報告対象は医薬品等によるものと疑われる身体の変調・不調や、日常生活に支障を来す程度の健康被害（死亡を含む）とされており、bも正しい内容です。健康被害と医薬品との因果関係が必ずしも明確でない場合であっても報告の対象となり得るとされているため、cも正しい記述です。一方、この医薬関係者による報告制度には「30日以内」のような具体的な報告期限は定められておらず、必要性を認めたときに報告することとされているため、dは誤りで、正しい組合せは正・正・正・誤です。","tags":["医薬品医療機器等安全性情報報告制度"]},{"id":"R4-109","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":109,"stem":"医薬品の副作用等による健康被害の救済に関する記述について、（　　）の中\nに入れるべき字句の正しい組合せを一つ選べ。\nサリドマイド事件、（ ａ  ）等を踏まえ、１９７９年に薬事法が改正され、医薬品の市販後の安全対策の強化を図るため、（ ｂ  ）制度の創設、副作用等報告制度の整備、保健衛生上の危害の発生又は拡大を防止するための（ ｃ  ）、廃棄・回収命令に関する法整備等がなされたが、それらと併せて、医薬品副作用被害救済基金法（現「（独）医薬品医療機器総合機構法」）による救済制度が創設された。","statements":[],"options":[{"n":1,"text":"a スモン事件 / b 承認 / c 業務停止命令"},{"n":2,"text":"a スモン事件 / b 承認 / c 緊急命令"},{"n":3,"text":"a スモン事件 / b 再審査・再評価 / c 緊急命令"},{"n":4,"text":"a 薬害エイズ事件 / b 再審査・再評価 / c 業務停止命令"},{"n":5,"text":"a 薬害エイズ事件 / b 承認 / c 業務停止命令"}],"answer":3,"explanation":"サリドマイド事件やスモン事件等の薬害を踏まえ、1979年の薬事法改正では、市販後の安全対策強化のため再審査・再評価制度の創設や副作用等報告制度の整備、保健衛生上の危害拡大を防止するための緊急命令・廃棄回収命令に関する規定が整備されました。これと併せて医薬品副作用被害救済基金法（現・独立行政法人医薬品医療機器総合機構法）に基づく副作用被害救済制度も創設されています。したがって空欄には、a＝スモン事件、b＝再審査・再評価、c＝緊急命令が入り、正答は選択肢3です。","tags":["薬害の歴史","再審査・再評価制度"]},{"id":"R4-110","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":110,"stem":"医薬品副作用被害救済制度等に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品又は健康食品を適正に使用したにもかかわらず発生した副作用に対し、被害者の迅速な救済を図るため、製薬企業の社会的責任に基づく公的制度として運営が開始された。"},{"label":"b","text":"救済給付業務に必要な費用のうち、給付費については、（独）医薬品医療機器総合機構法第１９条の規定に基づいて、製造販売業者から年度ごとに納付される拠出金が充てられる。"},{"label":"c","text":"医薬品を適正に使用して生じた健康被害の場合は、医療機関での治療を要さずに寛解したような軽度なものであっても、救済給付の対象となる。"},{"label":"d","text":"一部の日本薬局方収載医薬品（精製水、ワセリン等）は、救済制度の対象とならない。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 誤 / b 正 / c 正 / d 正"},{"n":4,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"医薬品副作用被害救済制度は、医薬品を適正に使用したにもかかわらず生じた副作用による健康被害を対象とする公的制度であり、健康食品による健康被害は対象に含まれないため、aは誤りです。救済給付業務に必要な費用のうち給付費は、独立行政法人医薬品医療機器総合機構法第19条に基づき製造販売業者が年度ごとに納付する拠出金で賄われており、bは正しい記述です。救済給付のうち医療費・医療手当は入院治療を要する程度の健康被害を対象としており、医療機関での治療を要さずに軽快したような軽度な健康被害は対象とならないため、cは誤りです。精製水やワセリンなど一部の日本薬局方収載医薬品は、そもそも救済制度の対象品目から除外されているため、dは正しく、正しい組合せは誤・正・誤・正です。","tags":["医薬品副作用被害救済制度"]},{"id":"R4-111","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":111,"stem":"医薬品ＰＬセンターに関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品副作用被害救済制度の対象とならないケースのうち、製品不良など、製薬企業に損害賠償責任がある場合には、「医薬品ＰＬセンター」への相談が推奨される。"},{"label":"b","text":"本センターは、平成７年７月の製造物責任法（ＰＬ法）の施行と同時に開設された。"},{"label":"c","text":"本センターは、製造販売元の企業と交渉するに当たって、消費者側の立場に立って交渉の仲介や調整・あっせんを行い、裁判によらず迅速な解決に導くことを目的としている。"},{"label":"d","text":"本センターでは、医薬品、医薬部外品及び医療機器に関する苦情の相談を受け付けている。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":4,"explanation":"医薬品副作用被害救済制度の対象とならないケースのうち、製品不良など製薬企業に損害賠償責任がある場合には、医薬品PLセンターへの相談が推奨されるため、aは正しい記述です。同センターは平成7年7月の製造物責任法（PL法）の施行と同時に日本製薬団体連合会によって開設されており、bも正しい内容です。ただし同センターは、消費者側に立って交渉するのではなく、公平・中立な立場で交渉の仲介や調整・あっせんを行う機関であるため、cの「消費者側の立場に立って」という説明は誤りです。相談対象も医薬品と医薬部外品に関する苦情に限られ、医療機器は対象に含まれないため、dも誤りで、正しい組合せは正・正・誤・誤です。","tags":["医薬品PLセンター","PL法"]},{"id":"R4-112","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":112,"stem":"一般用医薬品の安全対策に関する記述について、（　　）の中に入れるべき\n字句の正しい組合せを一つ選べ。なお、複数箇所の（ ｂ  ）には、いずれも同じ字句が入る。\n（ ａ  ）等が配合されたアンプル入り（ ｂ  ）の使用による重篤な副作用（ショック）で１９５９年から１９６５年までの間に計３８名の死亡例が発生した。アンプル剤は錠剤や散剤等、他の剤形に比べて、血中濃度が（ ｃ  ）高値に達するため、通常用量でも副作用を生じやすいことが確認されたことから、１９６５年、厚生省（当時）より関係製薬企業に対し、アンプル入り（ ｂ  ）製品の回収が要請された。","statements":[],"options":[{"n":1,"text":"a プソイドエフェドリン塩酸塩 / b 胃腸薬 / c 緩やかに"},{"n":2,"text":"a プソイドエフェドリン塩酸塩 / b かぜ薬 / c 急速に"},{"n":3,"text":"a アミノピリン / b かぜ薬 / c 緩やかに"},{"n":4,"text":"a アミノピリン / b かぜ薬 / c 急速に"},{"n":5,"text":"a アミノピリン / b 胃腸薬 / c 急速に"}],"answer":4,"explanation":"解熱鎮痛成分としてアミノピリンやスルピリンが配合されたアンプル入りかぜ薬の使用により、1959年から1965年の間に重篤なショックによる死亡例が計38名発生しました。アンプル剤は錠剤や散剤等に比べて吸収が速く血中濃度が急速に高値に達するため、通常用量でも副作用を生じやすいことが確認され、1965年に厚生省（当時）が関係製薬企業にアンプル入りかぜ薬製品の回収を要請しました。したがって空欄には、a＝アミノピリン、b＝かぜ薬、c＝急速に、が入り、正答は選択肢4です。","tags":["薬害の歴史","アンプル入りかぜ薬"]},{"id":"R4-113","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":113,"stem":"医薬品の適正使用のための啓発活動に関する記述の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"医薬品の持つ特質及びその使用・取扱い等について正しい知識を広く生活者に浸透させることにより、保健衛生の維持向上に貢献することを目的とし、毎年１０月１７日～２３日の１週間を「薬と健康の週間」としている。"},{"label":"b","text":"「６・２６国際麻薬乱用撲滅デー」を広く普及し、薬物乱用防止を一層推進するため、毎年６月２６日～７月２日の１週間、世界保健機構(ＷＨＯ)を中心とした、「ダメ。ゼッタイ。」普及運動が実施されている。"},{"label":"c","text":"薬物乱用や薬物依存は、一般用医薬品では生じることはなく、違法薬物（麻薬、覚醒剤、大麻等）や医療用医薬品によって生じる。"},{"label":"d","text":"青少年では薬物乱用の危険性に関する認識や理解が必ずしも十分でなく、好奇心から身近に入手できる薬物を興味本位で乱用することがあるため、医薬品の適正使用の重要性等について、小中学生のうちから啓発することが重要である。"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":2,"explanation":"「薬と健康の週間」は、医薬品の特質や取扱い等の正しい知識を広く生活者に浸透させることを目的として毎年10月17日から23日に実施されており、aは正しい記述です。一方「ダメ。ゼッタイ。」普及運動は、世界保健機関（WHO）ではなく国・自治体・関係団体等が中心となって、毎年6月20日から7月19日までの1か月間実施されているため、bは実施主体・期間ともに誤っています。薬物乱用や薬物依存は違法薬物や医療用医薬品に限らず、一般用医薬品によっても生じ得るとされているため、cの「一般用医薬品では生じない」という説明は誤りです。青少年は薬物乱用の危険性への認識が不十分なまま好奇心から乱用に至ることがあるため、小中学生のうちからの啓発が重要であり、dは正しく、正しい組合せは正・誤・誤・正です。","tags":["啓発活動","薬物乱用防止"]},{"id":"R4-114","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":114,"stem":"次の表は、ある一般用医薬品の制酸薬に含まれている有効成分の一覧である。\n１２錠中：\n成分 / 分量\n銅クロロフィリンカリウム / １２０ ｍｇ\n無水リン酸水素カルシウム / １０２０ ｍｇ\n沈降炭酸カルシウム / １０２０ ｍｇ\n水酸化マグネシウム / ９６０ ｍｇ\nロートエキス / ３０ ｍｇ\nこの制酸薬の添付文書等の「相談すること」の項目において、「次の診断を受けた人」と記載されている基礎疾患の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"心臓病"},{"label":"b","text":"てんかん"},{"label":"c","text":"緑内障"},{"label":"d","text":"糖尿病"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":5,"explanation":"設問の制酸薬にはロートエキスという抗コリン成分が含まれており、抗コリン成分は心臓に負担をかけるおそれがあるため「心臓病」の診断を受けた人は相談することとされ、aは正しい組合せです。てんかんとの関連が手引きに示されているのはジプロフィリンのような中枢神経興奮作用を持つ成分であり、本剤の成分には該当がないため、bは誤った組合せです。ロートエキスなどの抗コリン成分は眼圧を上昇させ緑内障を悪化させるおそれがあるため「緑内障」は相談することの対象であり、cは正しい組合せです。糖尿病との関連が示されているのはアドレナリン作動成分などであり、本剤に含まれるカルシウム・マグネシウム系の制酸成分やロートエキスには該当しないため、dは誤った組合せで、正しい組合せは正・誤・正・誤です。","tags":["制酸薬","相談すること","ロートエキス"]},{"id":"R4-115","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":115,"stem":"一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に、「本剤又は本剤の成分、牛乳によるアレルギー症状を起こしたことがある人」と記載することとされている成分を一つ選べ。","statements":[],"options":[{"n":1,"text":"ケトプロフェン"},{"n":2,"text":"ブチルスコポラミン臭化物"},{"n":3,"text":"プソイドエフェドリン塩酸塩"},{"n":4,"text":"タンニン酸アルブミン"},{"n":5,"text":"チペピジンヒベンズ酸塩"}],"answer":4,"explanation":"タンニン酸アルブミンに含まれるアルブミンは、牛乳のタンパク質であるカゼインから精製された成分であるため、牛乳や乳製品にアレルギーのある人が使用すると、まれに重篤なショック（アナフィラキシー）等のアレルギー症状を起こすおそれがあります。そのため添付文書の「次の人は使用（服用）しないこと」の項目には「本剤又は本剤の成分、牛乳によるアレルギー症状を起こしたことがある人」と記載することとされています。他の選択肢の成分（ケトプロフェン、ブチルスコポラミン臭化物、プソイドエフェドリン塩酸塩、チペピジンヒベンズ酸塩）にはこのような牛乳アレルギーとの関連はなく、正答は選択肢4のタンニン酸アルブミンです。","tags":["タンニン酸アルブミン","牛乳アレルギー"]},{"id":"R4-116","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":116,"stem":"乗り物酔い防止薬として用いられる配合成分のうち、メトヘモグロビン血症を起こすおそれがあるため、一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に、「６歳未満の小児」と記載することとされている成分の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"ジプロフィリン"},{"label":"b","text":"メクリジン塩酸塩"},{"label":"c","text":"アミノ安息香酸エチル"},{"label":"d","text":"ピリドキシン塩酸塩"}],"options":[{"n":1,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":2,"text":"a 正 / b 誤 / c 誤 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 誤 / b 誤 / c 誤 / d 正"}],"answer":3,"explanation":"乗物酔い防止薬の成分のうちメトヘモグロビン血症を起こすおそれがあるとして6歳未満の小児への使用を避けることとされているのはアミノ安息香酸エチルのみであり、cが正しい記述です。ジプロフィリンは中枢神経系の興奮作用によりてんかんの発作を誘発するおそれがある成分として扱われますが、6歳未満禁忌の対象ではないためaは誤りです。メクリジン塩酸塩やピリドキシン塩酸塩についても、手引きにメトヘモグロビン血症や6歳未満禁忌との関連の記載はなく、b・dも誤りで、正しい組合せは誤・誤・正・誤です。","tags":["メトヘモグロビン血症","乗物酔い防止薬"]},{"id":"R4-117","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":117,"stem":"一般用医薬品の添付文書等において、「次の人は使用（服用）しないこと」の項目中に、「妊婦又は妊娠していると思われる人」（出産予定日１２週以内の妊婦も含む。）と記載されている主な成分と、その理由の正誤について、正しい組合せを一つ選べ。\n主な成分 / 理 由","statements":[{"label":"a","text":"ヒマシ油類 / 子宮収縮が抑制されるため。"},{"label":"b","text":"エチニルエストラジオール / 妊娠中の女性ホルモン成分の摂取によって、胎児の先天性異常の発生が報告されているため。"},{"label":"c","text":"イブプロフェン / 腸の急激な動きに刺激されて流産・早産を誘発するおそれがあるため。"},{"label":"d","text":"オキセサゼイン / 妊娠中における安全性は確立されていないため。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 誤 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 誤"},{"n":3,"text":"a 正 / b 正 / c 正 / d 誤"},{"n":4,"text":"a 正 / b 誤 / c 正 / d 誤"},{"n":5,"text":"a 誤 / b 正 / c 誤 / d 正"}],"answer":5,"explanation":"ヒマシ油類は、腸の急激な動きが刺激となって流産・早産を誘発するおそれがあるために妊婦への使用を避けることとされていますが、設問の理由欄には「子宮収縮が抑制されるため」という誤った理由が示されており、aは誤った組合せです。エチニルエストラジオールのような女性ホルモン成分は、妊娠中に摂取されると胎児の先天性異常の発生が報告されていることを理由に妊婦への使用を避けることとされており、bは正しい組合せです。イブプロフェンについては、妊娠期間の延長や胎児の動脈管の収縮・早期閉鎖、分娩時出血の増加等のおそれが理由とされていますが、設問では実際にはヒマシ油類の理由である「流産・早産を誘発するおそれ」が誤って示されているため、cも誤った組合せです。オキセサゼインは妊娠中における安全性が確立されていないことを理由に使用を避けることとされ、dの記載と一致するため正しい組合せであり、全体として正しい組合せは誤・正・誤・正です。","tags":["妊婦","使用しないこと"]},{"id":"R4-118","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":118,"stem":"内服用の一般用医薬品の添付文書等において、「相談すること」の項目中に「次の診断を受けた人」として記載することとされている基礎疾患等と医薬品成分との関係について、正しいものの組合せを一つ選べ。\n基礎疾患等 / 医薬品成分","statements":[{"label":"a","text":"胃・十二指腸潰瘍 / エテンザミド"},{"label":"b","text":"高血圧 / フェニレフリン塩酸塩"},{"label":"c","text":"腎臓病 / メチルエフェドリン塩酸塩"},{"label":"d","text":"糖尿病 / ジプロフィリン"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"c、d"}],"answer":1,"explanation":"胃・十二指腸潰瘍の診断を受けた人は、胃・十二指腸潰瘍を悪化させるおそれがあるエテンザミドなどの解熱鎮痛成分について相談することとされており、aは正しい組合せです。高血圧の診断を受けた人は、交感神経興奮作用により血圧を上昇させるおそれがあるフェニレフリン塩酸塩などのアドレナリン作動成分について相談することとされており、bも正しい組合せです。腎臓病との関連で相談することとされているのはアスピリン等やマグネシウム・アルミニウム系の成分などであり、メチルエフェドリン塩酸塩は該当しないためcは誤った組合せです。糖尿病との関連で相談することとされているのはアドレナリン作動成分等であり、ジプロフィリンは主にてんかんとの関連で扱われる成分のためdも誤った組合せで、正しい組合せはaとbです。","tags":["相談すること","基礎疾患"]},{"id":"R4-119","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":119,"stem":"ジヒドロコデインリン酸塩が配合された一般用医薬品の鎮咳去痰薬（内服液剤）の添付文書等において、「使用上の注意」の項目中に「過量服用・長期連用しないこと」と記載することとされている理由の正誤について、正しい組合せを一つ選べ。","statements":[{"label":"a","text":"副腎皮質の機能低下を生じるおそれがあるため。"},{"label":"b","text":"激しい腹痛を伴う下痢等の副作用が現れやすくなるため。"},{"label":"c","text":"倦怠感や虚脱感等が現れることがあるため。"},{"label":"d","text":"依存性・習慣性がある成分が配合されており、乱用事例が報告されているため。"}],"options":[{"n":1,"text":"a 正 / b 正 / c 正 / d 正"},{"n":2,"text":"a 誤 / b 誤 / c 正 / d 正"},{"n":3,"text":"a 誤 / b 誤 / c 誤 / d 正"},{"n":4,"text":"a 正 / b 正 / c 誤 / d 誤"},{"n":5,"text":"a 正 / b 誤 / c 正 / d 誤"}],"answer":2,"explanation":"ジヒドロコデインリン酸塩が配合された鎮咳去痰薬（内服液剤）を過量服用・長期連用しないこととされているのは、倦怠感や虚脱感等が現れることがあるためであり、cは正しい記述です。この注意はコデイン類が依存性・習慣性のある成分であり、乱用事例が報告されていることも理由とされているため、dも正しい記述です。副腎皮質の機能低下は主に甘草（グリチルリチン酸等）に関連する副作用であり、この注意記載の理由として手引きに記載がないためaは誤りです。激しい腹痛を伴う下痢等の副作用は、この注意記載の理由として手引きに示されておらず、bも誤りで、正しい組合せは誤・誤・正・正です。","tags":["ジヒドロコデインリン酸塩","過量服用・長期連用"]},{"id":"R4-120","chapter":5,"source":"関西広域連合 令和4年度 登録販売者試験 後半","no":120,"stem":"一般用医薬品の添付文書等の「使用上の注意」の項目中に、「服用後、乗物又は機械類の運転操作をしないこと」と記載することとされている成分の正しいものの組合せを一つ選べ。","statements":[{"label":"a","text":"合成ヒドロタルサイト"},{"label":"b","text":"ジフェンヒドラミン塩酸塩"},{"label":"c","text":"ブロモバレリル尿素"},{"label":"d","text":"テオフィリン"}],"options":[{"n":1,"text":"a、b"},{"n":2,"text":"a、d"},{"n":3,"text":"b、c"},{"n":4,"text":"c、d"}],"answer":3,"explanation":"ジフェンヒドラミン塩酸塩などの抗ヒスタミン成分は眠気を生じさせるおそれがあるため、「服用後、乗物又は機械類の運転操作をしないこと」の対象成分とされており、bは正しい記述です。ブロモバレリル尿素も催眠鎮静作用により眠気を生じるため、同様に運転操作をしないことの対象とされており、cも正しい記述です。合成ヒドロタルサイトは制酸成分であり眠気との関連はなく、テオフィリンも中枢神経刺激作用を持つ成分であり、いずれも本注意事項の対象には含まれないため、aとdは誤りです。したがって正しい組合せはbとcです。","tags":["眠気","運転操作"]}];
